import { useEffect } from 'react';
import { Select, Tag } from 'antd';
import { useDictStore } from '@/store/dict';

interface Props {
  typeCode: string;
  value?: any;
  onChange?: (value: any) => void;
  mode?: 'multiple' | 'tags';
  allowClear?: boolean;
  disabled?: boolean;
  placeholder?: string;
  extValue?: string; // 联动过滤（如 material_type 按 material_category 过滤）
  /** 不展示的选项值（如发票编辑表单排除「作废/红冲」终态，强制走专用操作） */
  excludeValues?: string[];
  style?: React.CSSProperties;
}

/** 统一字典下拉组件：所有下拉选项均从字典表动态读取 */
export default function DictSelect({
  typeCode,
  value,
  onChange,
  mode,
  allowClear = true,
  disabled,
  placeholder,
  extValue,
  excludeValues,
  style,
}: Props) {
  const ensure = useDictStore((s) => s.ensure);
  const options = useDictStore((s) => s.options(typeCode, extValue));

  useEffect(() => {
    ensure(typeCode);
  }, [typeCode]);

  return (
    <Select
      style={{ minWidth: 160, ...style }}
      value={value || undefined}
      onChange={onChange}
      mode={mode}
      allowClear={allowClear}
      disabled={disabled}
      placeholder={placeholder || '请选择'}
      options={options
        .filter((o) => !excludeValues?.includes(o.value))
        .map((o) => ({ value: o.value, label: o.label }))}
      showSearch
      optionFilterProp="label"
    />
  );
}

/** 字典值渲染为彩色标签 */
export function DictTag({ typeCode, value }: { typeCode: string; value?: string }) {
  const ensure = useDictStore((s) => s.ensure);
  const options = useDictStore((s) => s.cache[typeCode] || []);
  useEffect(() => {
    ensure(typeCode);
  }, [typeCode]);
  if (!value) return <span>-</span>;
  const hit = options.find((o) => o.value === value);
  return <Tag color={hit?.color || 'default'}>{hit?.label || value}</Tag>;
}

/** 字典值渲染为纯文本 */
export function DictText({ typeCode, value }: { typeCode: string; value?: string }) {
  const ensure = useDictStore((s) => s.ensure);
  const label = useDictStore((s) => s.label(typeCode, value));
  useEffect(() => {
    ensure(typeCode);
  }, [typeCode]);
  return <span>{label}</span>;
}

import type { ReactNode } from 'react';
import { Empty, Button } from 'antd';

/**
 * 统一空状态（列表、卡片、图表容器的空态都走它）。
 *
 * 为什么要有它：改造前各处的空态是裸 `<Empty description="…" />`，
 * 描述文案、插画尺寸、是否给"下一步动作"各写各的 —— 同一屏里两种空态能长得不一样。
 *
 * 取舍：**不做自定义 SVG 插画**。本仓没有插画设计资源，而 [DESIGN.md] §0 已明确
 * "不搬外部设计文档里的摄影与插画规范"，凭空造一套插画只会与既有视觉体系打架。
 * 统一到 AntD 的 `PRESENTED_IMAGE_SIMPLE`（比默认插画小、更克制）+ 可选的行动按钮，
 * 已经能解决"空态太大、没有出口"这两个真实问题。
 */
export interface EmptyStateProps {
  /** 空态文案；默认「暂无数据」 */
  description?: ReactNode;
  /** 行动按钮文案（如「新增台账」「查看全部」）。给了它就渲染一个主色文字链按钮 */
  actionText?: string;
  /** 行动按钮回调 */
  onAction?: () => void;
  /** 自定义行动区（优先于 actionText）；如放多个按钮 */
  action?: ReactNode;
  /**
   * 紧凑态：用于表格 `locale.emptyText`、下拉列表、卡片内的小空态。
   * 去掉插画、缩小内边距 —— 表格空态用大插画会把整页撑开（这正是改造前的问题之一）。
   */
  compact?: boolean;
  /** 容器高度（如图表卡的 300px，避免空态时卡片塌陷） */
  height?: number | string;
}

export default function EmptyState({
  description = '暂无数据',
  actionText,
  onAction,
  action,
  compact,
  height,
}: EmptyStateProps) {
  const actionNode =
    action ??
    (actionText ? (
      <Button type="link" size="small" style={{ padding: 0 }} onClick={onAction}>
        {actionText}
      </Button>
    ) : undefined);

  return (
    <Empty
      image={compact ? Empty.PRESENTED_IMAGE_SIMPLE : undefined}
      styles={{ image: compact ? { height: 40, marginBottom: 8 } : undefined }}
      style={{
        margin: compact ? 0 : '24px 0',
        padding: compact ? '12px 0' : undefined,
        height,
        display: height ? 'flex' : undefined,
        flexDirection: height ? 'column' : undefined,
        justifyContent: height ? 'center' : undefined,
      }}
      description={
        <span className={compact ? 'cms-hint' : undefined}>
          {description}
          {actionNode ? <>　{actionNode}</> : null}
        </span>
      }
    />
  );
}

import { sanitizeHtml } from '@/utils/sanitizeHtml';

/**
 * 采购模块预览与发布统一流程（批次四 · 任务 4.2）
 *
 * 各业务模块（采前会会议纪要 / 采购公告 / 采购文件 / 成交报告 / 框架协议事前说明 /
 * 采购价格对比表）复用本组件：
 * - mode='publish'：发布前确认 —— 预览最终 Word 效果，提供「返回修改」与「确认发布」
 * - mode='preview'：纯预览（发布后主界面「预览」入口复用同一渲染管线）
 *
 * 内部走统一 Word 导出管线（procurementExport）：采购模板优先 → 变量替换 → 图片内联，
 * 保证预览与导出所见即所得。发布动作由各页面通过 onPublish 回调实现（任务子模块走
 * POST /procurement-tasks/:id/publish，独立模块走各自 publish 接口）。
 */
import { useEffect, useMemo, useState } from 'react';
import { Alert, Button, Modal, Popconfirm, Spin, message } from 'antd';
import { DownloadOutlined, SendOutlined } from '@ant-design/icons';
import { highlightPlaceholders } from '@/utils/docExport';
import {
  buildProcurementDoc,
  exportProcurementWord,
  procurementExportFilename,
  type ProcurementExportInput,
} from '@/utils/procurementExport';
import { procurementModuleLabel } from '@/constants/procurementVariables';

export interface PreviewPublishModalProps {
  open: boolean;
  /** 采购模块类型（决定模板匹配与变量集合） */
  moduleType: string;
  /** 关联采购任务 id */
  taskId?: string;
  /** 显式模板 id；缺省按 moduleType 自动匹配采购模板 */
  templateId?: string;
  /** 模块内置文档 HTML（含 {{占位符}}，未替换） */
  docHtml: string;
  /** 变量取值（文本 / 表格 HTML / 富文本 HTML） */
  values: Record<string, string>;
  /** publish=发布前确认；preview=仅预览（发布后主界面预览）。默认 publish */
  mode?: 'publish' | 'preview';
  /** 弹窗标题；缺省「{模块名} · 发布前确认 / 预览」 */
  title?: string;
  /** 导出文件名；缺省 {项目简称}-{采购内容}-{模块名称}.docx */
  filename?: string;
  /** 项目简称 / 采购内容（缺省文件名生成用） */
  projectAbbr?: string;
  content?: string;
  /** 确认发布按钮 loading */
  publishing?: boolean;
  /** 发布确认气泡文案 */
  confirmTitle?: string;
  confirmDescription?: string;
  /** 顶部提示文案 */
  tipMessage?: string;
  /** 确认发布回调（仅 mode='publish' 时展示按钮） */
  onPublish?: () => Promise<void> | void;
  /** 关闭弹窗（返回修改） */
  onClose: () => void;
  /** 自定义导出（特殊命名）；缺省走统一导出接口 */
  onExport?: () => void | Promise<void>;
}

export default function PreviewPublishModal({
  open,
  moduleType,
  taskId,
  templateId,
  docHtml,
  values,
  mode = 'publish',
  title,
  filename,
  projectAbbr,
  content,
  publishing,
  confirmTitle = '确认发布？',
  confirmDescription = '发布后状态变更为「已完成」。',
  tipMessage,
  onPublish,
  onClose,
  onExport,
}: PreviewPublishModalProps) {
  const [building, setBuilding] = useState(false);
  const [html, setHtml] = useState('');
  /** 是否使用了采购模板（提示用户底稿来源） */
  const [tplName, setTplName] = useState<string>('');

  const modalTitle = useMemo(
    () => title ?? `${moduleType ? '' : ''}${mode === 'publish' ? '发布前确认' : '预览'}`,
    [title, mode],
  );

  useEffect(() => {
    if (!open) return;
    let alive = true;
    setBuilding(true);
    buildProcurementDoc(
      { moduleType, taskId, templateId, docHtml, values, filename },
      { inlineImages: false },
    )
      .then((r) => {
        if (!alive) return;
        setHtml(r.html);
        setTplName(r.templateUsed ? r.templateName || '' : '');
      })
      .catch(() => {
        if (alive) setHtml(docHtml || '');
      })
      .finally(() => {
        if (alive) setBuilding(false);
      });
    return () => {
      alive = false;
    };
    // values / docHtml 由调用方 useMemo 保证引用稳定
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, moduleType, templateId, docHtml, values]);

  const handleExport = async () => {
    if (onExport) {
      await onExport();
      return;
    }
    const name =
      filename || procurementExportFilename(projectAbbr, content, moduleType);
    await exportProcurementWord({ moduleType, taskId, templateId, docHtml, values, filename: name });
    message.success(`已导出：${name}`);
  };

  return (
    <Modal
      title={modalTitle}
      open={open}
      width={1000}
      footer={[
        <Button key="back" onClick={onClose}>
          返回修改
        </Button>,
        <Button key="export" icon={<DownloadOutlined />} onClick={handleExport}>
          导出 Word
        </Button>,
        ...(mode === 'publish' && onPublish
          ? [
              <Popconfirm
                key="publish"
                title={confirmTitle}
                description={confirmDescription}
                onConfirm={onPublish}
              >
                <Button type="primary" icon={<SendOutlined />} loading={publishing}>
                  确认发布
                </Button>
              </Popconfirm>,
            ]
          : [
              <Button key="close" type="primary" onClick={onClose}>
                关闭
              </Button>,
            ]),
      ]}
      onCancel={onClose}
    >
      {/* 容器标记：预览区按**弹窗自身宽度**降级（DESIGN.md §10.2）——
          桌面视口 + 窄弹窗时 `.doc-preview` 也会收敛，这是 V1 的视口判断做不到的 */}
      <div className="cq">
        {tipMessage && mode === 'publish' && (
          <Alert type="info" showIcon style={{ marginBottom: 12 }} message={tipMessage} />
        )}
        {tplName && (
          <Alert
            type="info"
            showIcon
            style={{ marginBottom: 12 }}
            message={`本模块已配置采购模板「${tplName}」，以下内容以模板为底稿生成。`}
          />
        )}
        <Spin spinning={building} tip="正在生成预览…">
          <div
            className="doc-preview"
            style={{
              maxHeight: '58vh',
              minHeight: 120,
              overflow: 'auto',
              border: '1px solid var(--cms-hairline-soft)',
              // padding 交由 .doc-preview 做容器级收敛（DESIGN.md §10.2）
            }}
            dangerouslySetInnerHTML={{
              __html: sanitizeHtml(highlightPlaceholders(html)) || '<p style="color:var(--cms-muted-soft)">暂无内容</p>',
            }}
          />
        </Spin>
      </div>
    </Modal>
  );
}

import { useEffect, useMemo, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import {
  BoldOutlined,
  ItalicOutlined,
  UnderlineOutlined,
  StrikethroughOutlined,
  AlignLeftOutlined,
  AlignCenterOutlined,
  AlignRightOutlined,
  UnorderedListOutlined,
  OrderedListOutlined,
  UndoOutlined,
  RedoOutlined,
  ClearOutlined,
  FontSizeOutlined,
  BranchesOutlined,
  TableOutlined,
  FontColorsOutlined,
  BgColorsOutlined,
  VerticalAlignMiddleOutlined,
  LineOutlined,
  FullscreenOutlined,
  FullscreenExitOutlined,
  SearchOutlined,
  PictureOutlined,
  MoreOutlined,
} from '@ant-design/icons';
import { Button, Select, Space, Tooltip, Modal, Input, Tag, Divider, Collapse, Popover } from 'antd';
import type { VarGroup } from '@/pages/Clauses';
import { useContainerWidth } from '@/hooks/useContainerWidth';
import { sanitizeHtml } from '@/utils/sanitizeHtml';

export interface RichTextEditorProps {
  /** 编辑器内容（HTML 字符串） */
  value?: string;
  onChange?: (html: string) => void;
  /** 扁平变量名列表（兼容旧用法） */
  variables?: string[];
  /** 分类变量（优先于 variables），用于「插入变量」面板 */
  variableGroups?: VarGroup[];
  /**
   * 变量所属体系：面板顶部会据此显示提示。
   *
   * ⚠️ **三套变量体系互不相通**（采购模板 / 合同模板 / 单据模板）：同名 `{{项目名称}}` 由
   * **不同代码**替换、规则也不同。面板不标明体系时，作者很容易在合同正文里插入采购变量——那会
   * **静默不替换**（正文里留着占位符，预览才高亮）。凡传了 `variables`/`variableGroups` 的调用点
   * 都应传本属性，由 `server/test/procurementVariables.spec.mts` 的源码扫描锁定。
   */
  variableScope?: 'contract' | 'procurement';
  placeholder?: string;
  minHeight?: number;
  disabled?: boolean;
}

/** 中文字号（pt） */
const CN_SIZES = [
  { label: '初号', value: 42 },
  { label: '小初', value: 36 },
  { label: '一号', value: 26 },
  { label: '小一', value: 24 },
  { label: '二号', value: 22 },
  { label: '小二', value: 18 },
  { label: '三号', value: 16 },
  { label: '小三', value: 15 },
  { label: '四号', value: 14 },
  { label: '小四', value: 12 },
  { label: '五号', value: 10.5 },
  { label: '小五', value: 9 },
];

/** 常用中文字体 */
const CN_FONTS = [
  { label: '宋体', value: '宋体' },
  { label: '仿宋', value: '仿宋' },
  { label: '黑体', value: '黑体' },
  { label: '微软雅黑', value: '微软雅黑' },
  { label: '楷体', value: '楷体' },
];

/** 预置样式（通过 formatBlock 套用块级标签） */
const BLOCK_STYLES = [
  { label: '标题1', tag: 'H1' },
  { label: '标题2', tag: 'H2' },
  { label: '标题3', tag: 'H3' },
  { label: '正文', tag: 'P' },
  { label: '引用', tag: 'BLOCKQUOTE' },
];

/**
 * 零依赖富文本编辑器（contentEditable + execCommand）。
 * 用于合同模板正文、条款内容等需要排版 + 变量占位符的场景。
 * 已支持：加粗/斜体/下划线/删除线、对齐（含两端对齐）、有序/无序列表、
 * 字体/字号、字体颜色/背景色、预置样式、表格、分页符、撤销/重做、清除格式、
 * 插入变量（分类+搜索）、查找替换、全屏。
 */
export default function RichTextEditor({
  value,
  onChange,
  variables = [],
  variableGroups,
  variableScope,
  placeholder = '请输入内容…',
  minHeight = 320,
  disabled = false,
}: RichTextEditorProps) {
  /**
   * **容器**级响应式（DESIGN.md §10.2）：工具栏折行按**编辑器自身宽度**决定，不再看视口。
   * 同一个编辑器在整页表单里和 900px 弹窗里宽度差很多，视口判断会给出错误答案。
   *
   * 这里**不用** `.cq` + `@container`：折行本身要读 JS 状态（`toolsOpen`），
   * 且本组件的根元素在全屏模式下就是那个 `position: fixed; inset: 0` 的层
   * （它已 portal 到 body，见 `frame` 注释）——给可查自身的元素挂容器标记既无意义也会踩
   * containment 的包含块问题。故走 `useContainerWidth()`。
   */
  const { ref: cqRef, size: containerSize } = useContainerWidth<HTMLDivElement>();
  const isNarrow = containerSize.isNarrow;
  const ref = useRef<HTMLDivElement>(null);
  const [focused, setFocused] = useState(false);
  const [fontSize, setFontSize] = useState(12);
  const [fontFamily, setFontFamily] = useState('宋体');
  const [fullscreen, setFullscreen] = useState(false);
  const [varOpen, setVarOpen] = useState(false);
  const [varSearch, setVarSearch] = useState('');

  /** 进入全屏会重建 DOM 节点（portal 切换），主动 focus 一次让人能接着打字 */
  useEffect(() => {
    if (fullscreen) ref.current?.focus();
  }, [fullscreen]);

  // 查找替换弹窗
  const [frOpen, setFrOpen] = useState(false);
  const [findText, setFindText] = useState('');
  const [replaceText, setReplaceText] = useState('');

  const groups: VarGroup[] = useMemo(() => {
    if (variableGroups && variableGroups.length) return variableGroups;
    if (variables.length) return [{ label: '变量', items: variables.map((v) => ({ key: v })) }];
    return [];
  }, [variableGroups, variables]);

  const flatVars = useMemo(
    () => groups.flatMap((g) => g.items.map((i) => ({ ...i, group: g.label }))),
    [groups],
  );
  const filteredVars = useMemo(() => {
    const kw = varSearch.trim();
    if (!kw) return flatVars;
    return flatVars.filter((v) => v.key.includes(kw) || (v.tip && v.tip.includes(kw)));
  }, [flatVars, varSearch]);

  /**
   * 外部 value 变化（如切换编辑记录）时同步到编辑区。
   *
   * ⚠️ 依赖里必须带 `fullscreen`：切换全屏时**组件本身不会重挂载**（只是它的 DOM 子树
   * 从弹窗里挪到了 body 下），新渲染出来的 `contentEditable` 节点是空的，而 `[value]`
   * 这个依赖没变 → 这个 effect 不会重跑 → 编辑区内容**静默丢失**。
   * （2026-10-15 真渲染验收抓到：输入 15 次 `input` 事件后点全屏，内容变空，而表单校验
   * 证明 Form 里其实存着值 —— 丢的只是 DOM。）
   */
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    // 回填前净化（2026-10-18 审计）：渲染侧都过了 sanitizeHtml，但编辑入口曾漏——
    // 经 API/导入写入的恶意 HTML 会在打开编辑时执行。净化只清脚本/事件属性，
    // 富文本结构（表格/加粗/列表等）不受影响。
    const next = sanitizeHtml(value || '');
    if (next !== el.innerHTML) el.innerHTML = next;
  }, [value, fullscreen]);

  const emit = () => {
    const html = ref.current?.innerHTML || '';
    onChange?.(html);
  };

  const exec = (cmd: string, arg?: string) => {
    if (disabled) return;
    ref.current?.focus();
    document.execCommand(cmd, false, arg);
    emit();
  };

  /** 将选区（或光标处）用指定 inline style 的 span 包裹 */
  const surroundStyle = (style: string) => {
    if (disabled) return;
    const el = ref.current;
    if (!el) return;
    el.focus();
    const sel = window.getSelection();
    if (!sel || sel.rangeCount === 0) {
      document.execCommand('insertHTML', false, `<span style="${style}"></span>`);
      emit();
      return;
    }
    const range = sel.getRangeAt(0);
    if (!el.contains(range.commonAncestorContainer)) {
      range.selectNodeContents(el);
      range.collapse(false);
    }
    const span = document.createElement('span');
    span.setAttribute('style', style);
    try {
      range.surroundContents(span);
    } catch {
      span.appendChild(range.extractContents());
      range.insertNode(span);
    }
    sel.removeAllRanges();
    const r = document.createRange();
    r.selectNodeContents(span);
    sel.addRange(r);
    emit();
  };

  const formatBlock = (tag: string) => {
    if (disabled) return;
    ref.current?.focus();
    document.execCommand('formatBlock', false, tag);
    emit();
  };

  /**
   * 在光标处插入变量占位符。
   *
   * ⚠️ 默认插**双花括号** `{{变量名}}`：渲染器（`template-render.ts`）只认双花括号，
   * 单花括号的兼容分支早已按业务要求移除 —— 插成 `{变量名}` 会**静默不替换**
   * （正文里留着占位符、只有预览才高亮），作者几乎发现不了。
   * `raw` 仍可覆盖（表格类占位符等非变量文本）。
   */
  const insertVariable = (item: { key: string; raw?: string }) => {
    if (disabled) return;
    const text = item.raw || `{{${item.key}}}`;
    ref.current?.focus();
    const el = ref.current;
    const sel = window.getSelection();
    if (!el || !sel || sel.rangeCount === 0) {
      document.execCommand('insertText', false, text);
      emit();
      return;
    }
    const range = sel.getRangeAt(0);
    if (!el.contains(range.commonAncestorContainer)) {
      range.selectNodeContents(el);
      range.collapse(false);
    }
    range.deleteContents();
    const node = document.createTextNode(text);
    range.insertNode(node);
    range.setStartAfter(node);
    range.collapse(true);
    sel.removeAllRanges();
    sel.addRange(range);
    setVarOpen(false);
    emit();
  };

  const insertTable = () => {
    if (disabled) return;
    const html =
      '<table border="1" cellspacing="0" cellpadding="6" style="border-collapse:collapse;width:100%">' +
      '<tr><td>项目</td><td>内容</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td></tr>' +
      '<tr><td>&nbsp;</td><td>&nbsp;</td></tr></table><p><br/></p>';
    ref.current?.focus();
    document.execCommand('insertHTML', false, html);
    emit();
  };

  // ==================== 表格编辑（2026-10-17：行列增删 / 合并单元格） ====================
  // execCommand 不支持表格结构操作，直接对 DOM 做 insertRow/insertCell 等，完成后 emit()。
  const [activeCell, setActiveCell] = useState<{ cell: HTMLTableCellElement; table: HTMLTableElement } | null>(null);

  /** 从选区向上找光标所在单元格与其表格 */
  const trackCell = () => {
    const el = ref.current;
    const sel = window.getSelection();
    if (!el || !sel || sel.rangeCount === 0) return setActiveCell(null);
    let node: Node | null = sel.getRangeAt(0).startContainer;
    while (node && node !== el) {
      if (node instanceof HTMLTableCellElement) {
        // td 的直接父元素是 tr，表格要用 closest 向上找
        const table = node.closest('table');
        if (table && el.contains(table)) {
          setActiveCell({ cell: node, table });
          return;
        }
      }
      node = node.parentNode;
    }
    setActiveCell(null);
  };

  /** 表格编辑统一入口：mutate 后必须 emit 同步表单值；占位符在文本节点里不受结构操作影响 */
  const mutateTable = (fn: (table: HTMLTableElement, cell: HTMLTableCellElement) => void) => {
    if (disabled || !activeCell) return;
    try {
      fn(activeCell.table, activeCell.cell);
      emit();
    } catch {
      /* 结构异常（如合并后的边缘 case）时静默失败，避免把编辑区搞崩 */
    }
  };

  const findCellIndex = (row: HTMLTableRowElement, cell: HTMLTableCellElement) =>
    Array.from(row.cells).indexOf(cell);

  const insertRowAbove = () =>
    mutateTable((table, cell) => {
      const row = cell.parentElement as HTMLTableRowElement;
      const newRow = table.insertRow(row.rowIndex);
      for (let i = 0; i < row.cells.length; i++) newRow.insertCell(i).innerHTML = '&nbsp;';
    });

  const insertRowBelow = () =>
    mutateTable((table, cell) => {
      const row = cell.parentElement as HTMLTableRowElement;
      const newRow = table.insertRow(row.rowIndex + 1);
      for (let i = 0; i < row.cells.length; i++) newRow.insertCell(i).innerHTML = '&nbsp;';
    });

  /** 在目标行参照列插一列（保持同列 index，容忍 colSpan 造成的列数不齐） */
  const insertColumnAt = (after: boolean) =>
    mutateTable((_table, cell) => {
      const row = cell.parentElement as HTMLTableRowElement;
      const idx = findCellIndex(row, cell) + (after ? 1 : 0);
      const tbody = row.parentElement as HTMLTableSectionElement;
      Array.from(tbody.rows).forEach((r) => {
        const refCell = r.cells[Math.min(idx, r.cells.length - 1)];
        const newCell = r.insertCell(Math.min(idx, r.cells.length));
        if (refCell) newCell.style.cssText = refCell.style.cssText;
        newCell.innerHTML = '&nbsp;';
      });
    });

  const deleteRow = () =>
    mutateTable((table, cell) => {
      const row = cell.parentElement as HTMLTableRowElement;
      if (table.rows.length <= 1) return; // 防呆：只剩一行不删
      table.deleteRow(row.rowIndex);
    });

  const deleteColumn = () =>
    mutateTable((_table, cell) => {
      const row = cell.parentElement as HTMLTableRowElement;
      const tbody = row.parentElement as HTMLTableSectionElement;
      if (row.cells.length <= 1) return; // 防呆：只剩一列不删
      const idx = findCellIndex(row, cell);
      Array.from(tbody.rows).forEach((r) => {
        if (r.cells.length > 1) r.deleteCell(Math.min(idx, r.cells.length - 1));
      });
    });

  /**
   * 合并单元格：选区跨多个单元格时支持（同行相邻 → colSpan；同列 → rowSpan）；
   * 无多选时把光标所在格与其右侧/下方格合并。被并格内容**追加**进目标格（保留 {{占位符}}）。
   */
  const mergeCells = () =>
    mutateTable((table, cell) => {
      const sel = window.getSelection();
      let targets: HTMLTableCellElement[] = [];
      if (sel && sel.rangeCount > 0) {
        const range = sel.getRangeAt(0);
        if (!range.collapsed) {
          const nodes: HTMLTableCellElement[] = [];
          const walker = document.createTreeWalker(range.commonAncestorContainer, NodeFilter.SHOW_ELEMENT);
          while (walker.nextNode()) {
            const n = walker.currentNode;
            if (n instanceof HTMLTableCellElement && range.intersectsNode(n) && table.contains(n)) nodes.push(n);
          }
          targets = nodes;
        }
      }
      if (targets.length < 2) {
        const row = cell.parentElement as HTMLTableRowElement;
        const next = row.cells[findCellIndex(row, cell) + 1];
        targets = next ? [cell, next] : [];
      }
      if (targets.length < 2) return;
      const first = targets[0];
      const last = targets[targets.length - 1];
      const firstRow = first.parentElement as HTMLTableRowElement;
      const lastRow = last.parentElement as HTMLTableRowElement;
      const rowSpan = firstRow === lastRow ? 1 : lastRow.rowIndex - firstRow.rowIndex + 1;
      const colSpan = firstRow === lastRow
        ? findCellIndex(lastRow, last) - findCellIndex(firstRow, first) + 1
        : 1;
      // 追加内容后移除被并格
      for (let i = 1; i < targets.length; i++) {
        first.innerHTML += targets[i].innerHTML;
        targets[i].remove();
      }
      if (rowSpan > 1) first.rowSpan = rowSpan;
      if (colSpan > 1) first.colSpan = colSpan;
    });

  const deleteTable = () =>
    mutateTable((table) => {
      table.remove();
      setActiveCell(null);
    });

  const tableToolbar = activeCell ? (
    <div
      style={{
        display: 'flex',
        flexWrap: 'wrap',
        alignItems: 'center',
        gap: 2,
        padding: '2px 8px',
        borderBottom: '1px solid var(--cms-hairline-soft)',
        background: 'var(--cms-surface-soft)',
      }}
    >
      <span style={{ fontSize: 12, color: 'var(--cms-muted)', marginRight: 4 }}>表格：</span>
      <Button size="small" type="text" disabled={disabled} onMouseDown={(e) => e.preventDefault()} onClick={insertRowAbove}>上方插行</Button>
      <Button size="small" type="text" disabled={disabled} onMouseDown={(e) => e.preventDefault()} onClick={insertRowBelow}>下方插行</Button>
      <Button size="small" type="text" disabled={disabled} onMouseDown={(e) => e.preventDefault()} onClick={() => insertColumnAt(false)}>左插列</Button>
      <Button size="small" type="text" disabled={disabled} onMouseDown={(e) => e.preventDefault()} onClick={() => insertColumnAt(true)}>右插列</Button>
      <Button size="small" type="text" disabled={disabled} onMouseDown={(e) => e.preventDefault()} onClick={deleteRow}>删行</Button>
      <Button size="small" type="text" disabled={disabled} onMouseDown={(e) => e.preventDefault()} onClick={deleteColumn}>删列</Button>
      <Button size="small" type="text" disabled={disabled} onMouseDown={(e) => e.preventDefault()} onClick={mergeCells}>合并单元格</Button>
      <Button size="small" type="text" danger disabled={disabled} onMouseDown={(e) => e.preventDefault()} onClick={deleteTable}>删除表格</Button>
    </div>
  ) : null;

  const insertPageBreak = () => {
    if (disabled) return;
    ref.current?.focus();
    document.execCommand(
      'insertHTML',
      false,
      '<div style="page-break-before:always;height:0;border-top:1px dashed #d48806;margin:8px 0;" contenteditable="false">（分页符）</div><p><br/></p>',
    );
    emit();
  };

  const applyFontFamily = (f: string) => {
    setFontFamily(f);
    exec('fontName', f);
  };

  const applyFontSize = (pt: number) => {
    setFontSize(pt);
    surroundStyle(`font-size:${pt}pt`);
  };

  const applyColor = (cmd: 'foreColor' | 'hiliteColor', color: string) => {
    if (disabled) return;
    ref.current?.focus();
    document.execCommand('styleWithCSS', false, 'true');
    document.execCommand(cmd, false, color);
    emit();
  };

  const doFind = () => {
    if (!findText) return;
    const el = ref.current;
    if (el) {
      el.focus();
      (window as any).find?.(findText, false, false, true);
    }
  };

  const doReplaceAll = () => {
    const el = ref.current;
    if (!el || !findText) return;
    const html = el.innerHTML;
    // 仅替换可见文本节点中的匹配（避免破坏标签）
    const escaped = findText.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const re = new RegExp(escaped, 'g');
    const walk = (node: Node) => {
      if (node.nodeType === Node.TEXT_NODE) {
        if (node.textContent && re.test(node.textContent)) {
          const span = document.createElement('span');
          span.innerHTML = node.textContent.replace(re, replaceText);
          node.parentNode?.replaceChild(span, node);
        }
      } else {
        node.childNodes.forEach((c) => walk(c));
      }
    };
    walk(el);
    emit();
    setFrOpen(false);
  };

  const btn = (title: string, icon: React.ReactNode, cmd: string, arg?: string) => (
    <Tooltip title={title} key={title}>
      <Button size="small" type="text" icon={icon} disabled={disabled} onMouseDown={(e) => e.preventDefault()} onClick={() => exec(cmd, arg)} />
    </Tooltip>
  );

  const variableModal = (
    // 宽度不能写死 380：弹窗在手机上会被全局 `max-width: calc(100vw - 16px)` 兜到 ~359px，
    // 写死会把内容顶出弹窗（V2 阶段 2 顺手修掉的容器适配问题）
    <div style={{ width: '100%', maxWidth: 380, maxHeight: 420, overflow: 'auto' }}>
      {variableScope ? (
        <div
          className="cms-hint"
          style={{ marginBottom: 8, lineHeight: 1.6, color: 'var(--cms-muted)' }}
        >
          {variableScope === 'procurement'
            ? '采购模板变量 · 只在采购文档里生效；合同正文请改用合同模板变量'
            : '合同模板变量 · 只在合同正文/条款里生效；采购文档请改用采购模板变量'}
        </div>
      ) : null}
      <Input
        allowClear
        prefix={<SearchOutlined />}
        placeholder="搜索变量名称"
        value={varSearch}
        onChange={(e) => setVarSearch(e.target.value)}
        style={{ marginBottom: 8 }}
      />
      <Collapse
        size="small"
        defaultActiveKey={groups.map((_, i) => String(i))}
        items={groups.map((g, i) => ({
          key: String(i),
          label: `${g.label}（${g.items.length}）`,
          children: (
            <Space size={[4, 6]} wrap>
              {(kwFilter(g, varSearch).length ? kwFilter(g, varSearch) : g.items).map((it) => (
                <Tooltip title={it.tip || it.raw || `{{${it.key}}}`} key={it.key}>
                  <Tag style={{ cursor: 'pointer' }} onClick={() => insertVariable(it)}>
                    {it.raw || `{{${it.key}}}`}
                  </Tag>
                </Tooltip>
              ))}
            </Space>
          ),
        }))}
      />
    </div>
  );

  const fileRef = useRef<HTMLInputElement>(null);
  const insertImage = () => fileRef.current?.click();
  const onImagePicked = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => exec('insertImage', String(reader.result));
    reader.readAsDataURL(file);
    e.target.value = '';
  };

  /** 窄容器工具栏：「更多」展开/收起低频项（按**编辑器自身宽度**判断，见 DESIGN.md §10.2） */
  const [toolsOpen, setToolsOpen] = useState(false);

  /** 高频工具项：宽容器与窄容器都显示 */
  const primaryTools = (
    <>
      <Tooltip title="字体">
        <Select
          size="small"
          value={fontFamily}
          disabled={disabled}
          style={{ width: 96, marginRight: 4 }}
          options={CN_FONTS}
          onMouseDown={(e) => e.preventDefault()}
          onChange={applyFontFamily}
        />
      </Tooltip>
      <Tooltip title="字号">
        <Select
          size="small"
          value={fontSize}
          disabled={disabled}
          style={{ width: 84, marginRight: 4 }}
          options={CN_SIZES.map((s) => ({ label: s.label, value: s.value }))}
          onMouseDown={(e) => e.preventDefault()}
          onChange={(v) => applyFontSize(Number(v))}
          suffixIcon={<FontSizeOutlined />}
        />
      </Tooltip>
      {btn('加粗', <BoldOutlined />, 'bold')}
      {btn('斜体', <ItalicOutlined />, 'italic')}
      {btn('下划线', <UnderlineOutlined />, 'underline')}
      {isNarrow && (
        <Tooltip title={toolsOpen ? '收起更多工具' : '更多工具'}>
          <Button
            size="small"
            type="text"
            icon={<MoreOutlined />}
            disabled={disabled}
            onMouseDown={(e) => e.preventDefault()}
            onClick={() => setToolsOpen((v) => !v)}
          />
        </Tooltip>
      )}
    </>
  );

  /** 低频工具项：窄屏默认收进「更多」，宽屏平铺显示 */
  const moreTools = (
    <>
      {btn('删除线', <StrikethroughOutlined />, 'strikeThrough')}
      <Tooltip title="字体颜色">
        <Popover
          trigger="click"
          content={
            <Space wrap style={{ maxWidth: 200 }}>
              {['#000000', '#d4380d', '#389e0d', '#096dd9', '#722ed1', '#ad6800'].map((c) => (
                <span
                  key={c}
                  onClick={() => applyColor('foreColor', c)}
                  style={{ width: 22, height: 22, background: c, display: 'inline-block', cursor: 'pointer', borderRadius: 3, border: '1px solid var(--cms-hairline)' }}
                />
              ))}
            </Space>
          }
        >
          <Button size="small" type="text" icon={<FontColorsOutlined />} disabled={disabled} onMouseDown={(e) => e.preventDefault()} />
        </Popover>
      </Tooltip>
      <Tooltip title="背景颜色">
        <Popover
          trigger="click"
          content={
            <Space wrap style={{ maxWidth: 200 }}>
              {['#fff1b8', '#ffccc7', '#b7eb8f', '#bae0ff', '#efdbff', '#fff'].map((c) => (
                <span
                  key={c}
                  onClick={() => applyColor('hiliteColor', c)}
                  style={{ width: 22, height: 22, background: c, display: 'inline-block', cursor: 'pointer', borderRadius: 3, border: '1px solid var(--cms-hairline)' }}
                />
              ))}
            </Space>
          }
        >
          <Button size="small" type="text" icon={<BgColorsOutlined />} disabled={disabled} onMouseDown={(e) => e.preventDefault()} />
        </Popover>
      </Tooltip>
      <Divider type="vertical" style={{ margin: '0 4px' }} />
      {btn('左对齐', <AlignLeftOutlined />, 'justifyLeft')}
      {btn('居中', <AlignCenterOutlined />, 'justifyCenter')}
      {btn('右对齐', <AlignRightOutlined />, 'justifyRight')}
      <Tooltip title="两端对齐">
        <Button size="small" type="text" disabled={disabled} onMouseDown={(e) => e.preventDefault()} onClick={() => exec('justifyFull')}>
          两端
        </Button>
      </Tooltip>
      <Divider type="vertical" style={{ margin: '0 4px' }} />
      {btn('无序列表', <UnorderedListOutlined />, 'insertUnorderedList')}
      {btn('有序列表', <OrderedListOutlined />, 'insertOrderedList')}
      <Tooltip title="预置样式">
        <Select
          size="small"
          value=""
          disabled={disabled}
          style={{ width: 92, marginRight: 4 }}
          placeholder="样式"
          options={BLOCK_STYLES.map((s) => ({ label: s.label, value: s.tag }))}
          onMouseDown={(e) => e.preventDefault()}
          onChange={(v) => formatBlock(String(v))}
          suffixIcon={<VerticalAlignMiddleOutlined />}
        />
      </Tooltip>
      <Tooltip title="插入表格">
        <Button size="small" type="text" icon={<TableOutlined />} disabled={disabled} onMouseDown={(e) => e.preventDefault()} onClick={insertTable} />
      </Tooltip>
      <Tooltip title="插入图片">
        <Button size="small" type="text" icon={<PictureOutlined />} disabled={disabled} onMouseDown={(e) => e.preventDefault()} onClick={insertImage} />
      </Tooltip>
      <Tooltip title="插入分页符">
        <Button size="small" type="text" icon={<LineOutlined />} disabled={disabled} onMouseDown={(e) => e.preventDefault()} onClick={insertPageBreak} />
      </Tooltip>
      <Divider type="vertical" style={{ margin: '0 4px' }} />
      {btn('撤销', <UndoOutlined />, 'undo')}
      {btn('重做', <RedoOutlined />, 'redo')}
      {btn('清除格式', <ClearOutlined />, 'removeFormat')}
      <Tooltip title="查找/替换">
        <Button size="small" type="text" icon={<SearchOutlined />} disabled={disabled} onMouseDown={(e) => e.preventDefault()} onClick={() => setFrOpen(true)} />
      </Tooltip>
      <Tooltip title="插入变量">
        <Button size="small" type="text" icon={<BranchesOutlined />} disabled={disabled} onMouseDown={(e) => e.preventDefault()} onClick={() => setVarOpen(true)}>
          插入变量
        </Button>
      </Tooltip>
      <Tooltip title={fullscreen ? '退出全屏' : '全屏'}>
        <Button
          size="small"
          type="text"
          icon={fullscreen ? <FullscreenExitOutlined /> : <FullscreenOutlined />}
          disabled={disabled}
          onMouseDown={(e) => e.preventDefault()}
          onClick={() => setFullscreen((f) => !f)}
        />
      </Tooltip>
    </>
  );

  const toolbar = (
    <div
      style={{
        display: 'flex',
        flexWrap: 'wrap',
        alignItems: 'center',
        gap: 2,
        padding: '4px 8px',
        borderBottom: '1px solid var(--cms-hairline-soft)',
        background: 'var(--cms-surface-soft)',
      }}
    >
      {primaryTools}
      {/* 窄容器：低频项默认收起，点「更多」展开；宽容器：始终平铺 */}
      {(!isNarrow || toolsOpen) && moreTools}
    </div>
  );

  const containerStyle: React.CSSProperties = fullscreen
    ? {
        position: 'fixed',
        inset: 0,
        zIndex: 1000,
        // 编辑区按「纸张」呈现（与 Word 导出对应），故用 paper 而非主题底
        background: 'var(--cms-paper)',
        display: 'flex',
        flexDirection: 'column',
      }
    : {
        border: `1px solid ${focused ? 'var(--cms-primary)' : 'var(--cms-hairline)'}`,
        borderRadius: 6,
        background: disabled ? 'var(--cms-surface-soft)' : 'var(--cms-paper)',
        overflow: 'hidden',
      };

  /**
   * 编辑器外框。
   *
   * ⚠️ **全屏时整块 portal 到 `document.body`**（而不是就地 `position: fixed`）：
   * 全屏层是 `position: fixed; inset: 0`，一旦它的某个祖先带了
   * `container-type`（containment 的 `contain: layout` 会把该祖先变成 fixed 元素的**包含块**），
   * 全屏就只会铺满那个祖先而不是视口。而本组件绝大多数使用点是**弹窗正文**，
   * 弹窗正文自 V2 阶段 5 起统一是容器（`styles/containers.css` 的 `.ant-modal-body`），
   * 曾经的"就地 fixed"必然被限制住。portal 后全屏层直接挂在 body 下，与任何容器无关。
   *
   * 副作用（可接受）：切换全屏会重建 DOM 节点 → 由 `useEffect([value])` 在挂载时回填内容，
   * 且**所有使用点都是受控的**（显式 `value`/`onChange`，或由 `Form.Item` 注入）→ 内容不丢；
   * 光标位置会重置，故进入全屏时主动 focus 一次（见下方 effect）。
   */
  const frame = (
    <div ref={cqRef} style={containerStyle}>
      {toolbar}
      {tableToolbar}
      <div
        ref={ref}
        contentEditable={!disabled}
        suppressContentEditableWarning
        onInput={emit}
        onKeyUp={trackCell}
        onMouseUp={trackCell}
        onBlur={() => {
          setFocused(false);
          emit();
        }}
        onFocus={() => setFocused(true)}
        data-placeholder={placeholder}
        style={{
          minHeight: fullscreen ? 'calc(100vh - 44px)' : minHeight,
          maxHeight: fullscreen ? undefined : 560,
          overflowY: 'auto',
          padding: 12,
          outline: 'none',
          lineHeight: 1.8,
          fontSize: 14,
        }}
        className="cms-rich-text"
      />
      <input ref={fileRef} type="file" accept="image/*" style={{ display: 'none' }} onChange={onImagePicked} />
      <style>{`
        .cms-rich-text:empty::before {
          content: attr(data-placeholder);
          color: var(--cms-muted-soft);
        }
        .cms-rich-text table { border-collapse: collapse; width: 100%; margin: 8px 0; }
        .cms-rich-text td { border: 1px solid #d9d9d9; padding: 6px; }
        .cms-rich-text p { margin: 0 0 8px; }
        .cms-rich-text ol, .cms-rich-text ul { padding-left: 24px; margin: 4px 0; }
        .cms-rich-text h1 { font-size: 18pt; text-align: center; font-family: "黑体", SimHei, sans-serif; }
        .cms-rich-text h2 { font-size: 14pt; font-family: "黑体", SimHei, sans-serif; }
        .cms-rich-text blockquote { border-left: 3px solid #d9d9d9; padding-left: 12px; color: #595959; margin: 8px 0; }
      `}</style>

      <Modal title="插入变量" open={varOpen} footer={null} onCancel={() => setVarOpen(false)} width={440} destroyOnHidden>
        {variableModal}
      </Modal>

      <Modal
        title="查找 / 替换"
        open={frOpen}
        onCancel={() => setFrOpen(false)}
        onOk={doReplaceAll}
        okText="替换全部"
        okButtonProps={{ disabled: !findText }}
      >
        <Space direction="vertical" style={{ width: '100%' }}>
          <Input
            prefix={<SearchOutlined />}
            placeholder="查找内容"
            value={findText}
            onChange={(e) => setFindText(e.target.value)}
            onPressEnter={doFind}
          />
          <Button block onClick={doFind} disabled={!findText}>
            查找下一个
          </Button>
          <Input placeholder="替换为" value={replaceText} onChange={(e) => setReplaceText(e.target.value)} />
        </Space>
      </Modal>
    </div>
  );

  // 全屏时整块挂到 body 之下（见 `frame` 上方注释）；非全屏就地渲染
  return fullscreen ? createPortal(frame, document.body) : frame;
}

/** 按关键词过滤某组的变量 */
function kwFilter(g: VarGroup, kw: string): VarGroup['items'] {
  const t = (kw || '').trim();
  if (!t) return g.items;
  return g.items.filter((it) => it.key.includes(t) || (it.tip && it.tip.includes(t)));
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  Alert,
  Button,
  Card,
  DatePicker,
  Empty,
  Segmented,
  Select,
  Space,
  Spin,
  Table,
  Tabs,
  Tag,
  Tooltip,
  Typography,
  Upload,
  message,
} from 'antd';
import { DownloadOutlined, InboxOutlined, ReloadOutlined, ThunderboltOutlined } from '@ant-design/icons';
import type { Dayjs } from 'dayjs';
import { aiApi, type AiInspectCandidate, type AiInspectResult } from '@/api/modules';
import { contractApi, projectApi, supplierApi } from '@/api/business';
import { MIME_XLSX, downloadBlob, fileNameFromDisposition } from '@/utils/reportExport';

const { Dragger } = Upload;
const { Text, Paragraph } = Typography;

interface Option {
  id: string;
  name?: string;
  code?: string;
}

/** 单元格唯一键：同一份表里可能有多张工作表，必须带 sheet 才不会串行 */
const keyOf = (c: { sheet: string; cellRef: string }) => `${c.sheet}!${c.cellRef}`;

/** 本页用的是「表单核验」用途；下面这张表只为提示文案服务，不参与任何业务判断 */
const PURPOSE_LABEL: Record<string, string> = {
  form_inspect: '表单核验',
  register: '文件登记',
  report: '汇报材料',
  anomaly: '异常预警',
  intent: '意图解析',
};

/**
 * 「已启用」标签旁的模型提示：把五个用途各自实际生效的模型摊开。
 *
 * 为什么要摊开：`/api/ai/status` 的 `model` 只是**全局默认**，各用途可能在设置页单独
 * 指定过、也可能被 `AI_MODEL_<用途>` 覆盖，光看全局名会误判成本页用的是哪个模型。
 */
function modelTip(status: { model: string; models?: Record<string, string> }): string {
  return Object.keys(PURPOSE_LABEL)
    .map((code) => `${PURPOSE_LABEL[code]}：${status.models?.[code] || status.model || '（未配置）'}`)
    .join('\n');
}

/**
 * AI 助手（一期：模板智能填报）。
 *
 * 交互刻意做成「先看建议、再手动改、最后才生成文件」三步：
 * 1. 上传 xlsx → 后端扫描出所有「标签: 空格子」候选位置，并让模型给出字段建议；
 * 2. 用户逐行确认/修改字段（模型只做建议，不做决定）；
 * 3. 生成回填文件下载 —— **系统里的数据一个字段都不会写回本页**，
 *    页面上只显示「有值/无值」，避免把合同金额、银行账号等敏感信息直接摊在浏览器与操作日志里。
 */
function FillPanel() {
  const [status, setStatus] = useState<{
    enabled: boolean;
    model: string;
    /** 各用途实际生效的模型（后端按 页面登记 > AI_MODEL_<用途> > 全局 算好） */
    models?: Record<string, string>;
  } | null>(null);
  const [contracts, setContracts] = useState<Option[]>([]);
  const [suppliers, setSuppliers] = useState<Option[]>([]);
  const [contractId, setContractId] = useState<string>();
  const [supplierId, setSupplierId] = useState<string>();
  /** 填报范围（2026-11-12）：跨项目时填入的是汇总值，需「统计报表-查看」权限与期间 */
  const [scopeMode, setScopeMode] = useState<'current' | 'selected' | 'all'>('current');
  const [projectIds, setProjectIds] = useState<string[]>([]);
  const [projects, setProjects] = useState<Option[]>([]);
  const [periodRange, setPeriodRange] = useState<[Dayjs, Dayjs] | null>(null);

  const [file, setFile] = useState<File | null>(null);
  const [inspecting, setInspecting] = useState(false);
  const [result, setResult] = useState<AiInspectResult | null>(null);
  const [picked, setPicked] = useState<Record<string, string | undefined>>({});
  const [filling, setFilling] = useState(false);
  /** 行级表格填充：选表区 → 选数据集 → 列映射 */
  const [tableIndex, setTableIndex] = useState(0);
  const [tableDatasetKey, setTableDatasetKey] = useState<string>();
  const [tableMapping, setTableMapping] = useState<Record<number, string | undefined>>({});
  const [tableFilling, setTableFilling] = useState(false);

  useEffect(() => {
    aiApi
      .status()
      .then(setStatus)
      .catch(() => setStatus({ enabled: false, model: '' }));
    contractApi.options().then((list: Option[]) => setContracts(list || [])).catch(() => undefined);
    supplierApi.options().then((list: Option[]) => setSuppliers(list || [])).catch(() => undefined);
    projectApi
      .list({ page: 1, pageSize: 200 })
      .then((res: any) => setProjects(res?.list || res?.items || []))
      .catch(() => undefined);
  }, []);

  const fieldOptions = useMemo(
    () =>
      (result?.availableFields || []).map((f) => ({
        value: f.key,
        label: `${f.label}（${f.key}）`,
        sensitive: f.sensitive,
      })),
    [result],
  );

  /** 上传/回填共用上下文：跨项目时只传 range（表单里是汇总值） */
  const formCtx = useMemo(
    () => ({
      contractId,
      supplierId,
      scopeMode: scopeMode === 'current' ? undefined : scopeMode,
      projectIds: scopeMode === 'selected' ? projectIds : undefined,
      from: scopeMode === 'current' ? undefined : periodRange?.[0]?.format('YYYY-MM-DD'),
      to: scopeMode === 'current' ? undefined : periodRange?.[1]?.format('YYYY-MM-DD'),
    }),
    [contractId, supplierId, scopeMode, projectIds, periodRange],
  );

  /** 上传即扫描：省掉「上传 + 点扫描」两步，失败时保留文件方便重试 */
  const inspect = useCallback(
    async (f: File) => {
      setInspecting(true);
      setResult(null);
      setPicked({});
      setTableIndex(0);
      setTableDatasetKey(undefined);
      setTableMapping({});
      try {
        const res = await aiApi.inspect(f, formCtx);
        setResult(res);
        // 初始映射 = 模型建议（只采纳高置信度，低置信度留给用户判断）
        const initial: Record<string, string | undefined> = {};
        for (const c of res.candidates) {
          if (c.fieldKey && (c.confidence ?? 0) >= 0.6) initial[keyOf(c)] = c.fieldKey;
        }
        setPicked(initial);
        if (!res.candidates.length) message.warning('没找到可填的空白单元格，确认模板里是「标签 + 空值格」的布局');
        else message.success(`找到 ${res.candidates.length} 个候选位置`);
      } catch {
        // http 拦截器已弹错，这里只负责收尾
      } finally {
        setInspecting(false);
      }
    },
    [formCtx],
  );

  /**
   * 切换「填报范围 / 关联合同 / 关联供应商」后可用字段会变，必须重扫一遍：
   * 否则用户先传文件、后改范围，下拉里还是旧字段集，汇总字段根本选不到。
   * 首次挂载跳过（此时还没上传文件，重扫没有意义）。
   */
  const firstCtx = useRef(true);
  useEffect(() => {
    if (firstCtx.current) {
      firstCtx.current = false;
      return;
    }
    if (file) void inspect(file);
    // 只跟随填报上下文变化；file 变化本身由 onPick 触发扫描
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [formCtx]);

  const onPick = (f: File) => {
    if (!/\.xlsx$/i.test(f.name)) {
      message.error('只支持 .xlsx（.xls / .xlsm 会丢格式或宏，请先另存为 xlsx）');
      return false;
    }
    setFile(f);
    void inspect(f);
    return false;
  };

  const mapped = useMemo(
    () =>
      Object.entries(picked)
        .filter(([, fieldKey]) => !!fieldKey)
        .map(([k, fieldKey]) => {
          const [sheet, cellRef] = k.split('!');
          return { sheet, cellRef, fieldKey: fieldKey as string };
        }),
    [picked],
  );

  const fill = async () => {
    if (!file) return;
    if (!mapped.length) {
      message.warning('还没有选择任何字段');
      return;
    }
    setFilling(true);
    try {
      const res = await aiApi.fill(file, mapped, formCtx);
      const blob = res.data as Blob;
      const filled = Number(res.headers?.['x-ai-filled'] ?? 0);
      const skipped = Number(res.headers?.['x-ai-skipped'] ?? 0);
      downloadBlob(new Blob([blob], { type: MIME_XLSX }), fileNameFromDisposition(res.headers, 'ai-filled.xlsx'));
      message.success(`已回填 ${filled} 处${skipped ? `，跳过 ${skipped} 处（公式/合并格）` : ''}`);
    } catch {
      // 拦截器已提示
    } finally {
      setFilling(false);
    }
  };

  const tableRegion = result?.tables?.[tableIndex];
  const tableDataset = result?.tableDatasets?.find((d) => d.key === tableDatasetKey);

  /** 选数据集时按表头文字自动预填列映射（用户仍可逐列改） */
  const applyTableDataset = (key?: string) => {
    setTableDatasetKey(key);
    const ds = result?.tableDatasets?.find((d) => d.key === key);
    const map: Record<number, string | undefined> = {};
    if (ds && tableRegion) {
      for (const c of tableRegion.columns) {
        const hit =
          ds.columns.find((col) => col === c.label) ??
          ds.columns.find((col) => c.label.includes(col) || col.includes(c.label));
        if (hit) map[c.col] = hit;
      }
    }
    setTableMapping(map);
  };

  const fillTable = async () => {
    if (!file || !tableRegion || !tableDatasetKey) return;
    const columns = Object.entries(tableMapping)
      .filter(([, source]) => !!source)
      .map(([col, source]) => ({ col: Number(col), source: source as string }));
    if (!columns.length) {
      message.warning('至少映射一列');
      return;
    }
    setTableFilling(true);
    try {
      const res = await aiApi.fillTable(file, {
        datasetKey: tableDatasetKey,
        sheet: tableRegion.sheet,
        headerRow: tableRegion.headerRow,
        startRow: tableRegion.startRow,
        columns,
        ...formCtx,
      });
      const filledRows = Number(res.headers?.['x-ai-filled-rows'] ?? 0);
      const skipped = Number(res.headers?.['x-ai-skipped'] ?? 0);
      const truncated = String(res.headers?.['x-ai-truncated'] ?? '') === '1';
      downloadBlob(
        new Blob([res.data as Blob], { type: MIME_XLSX }),
        fileNameFromDisposition(res.headers, 'ai-filled-table.xlsx'),
      );
      message.success(`已写入 ${filledRows} 行${skipped ? `，跳过 ${skipped} 空值/合并格` : ''}${truncated ? '（超出 2000 行已截断）' : ''}`);
    } catch {
      // 拦截器已提示
    } finally {
      setTableFilling(false);
    }
  };

  const columns = [
    { title: '工作表', dataIndex: 'sheet', width: 140, ellipsis: true },    { title: '单元格', dataIndex: 'cellRef', width: 90 },
    {
      title: '表单标签',
      dataIndex: 'label',
      width: 220,
      ellipsis: true,
      render: (v: string) => (
        <Tooltip title={v}>
          <Text>{v || '-'}</Text>
        </Tooltip>
      ),
    },
    {
      title: '当前',
      dataIndex: 'hasValue',
      width: 80,
      render: (v: boolean) => (v ? <Tag color="orange">已有值</Tag> : <Tag>空白</Tag>),
    },
    {
      title: '取系统字段',
      width: 280,
      render: (_: unknown, row: AiInspectCandidate) => (
        <Select
          allowClear
          showSearch
          style={{ width: '100%' }}
          placeholder="选择要填入的字段"
          value={picked[keyOf(row)]}
          onChange={(v?: string) => setPicked((prev) => ({ ...prev, [keyOf(row)]: v }))}
          optionFilterProp="label"
          options={fieldOptions}
        />
      ),
    },
    {
      title: '置信度',
      width: 100,
      render: (_: unknown, row: AiInspectCandidate) => {
        const c = row.confidence;
        if (c === null || c === undefined) return <Text type="secondary">-</Text>;
        const color = c >= 0.8 ? 'green' : c >= 0.6 ? 'blue' : 'default';
        return <Tag color={color}>{Math.round(c * 100)}%</Tag>;
      },
    },
  ];

  const disabled = status ? !status.enabled : false;

  return (
    <Card
      title={
        <Space>
          <ThunderboltOutlined />
          <span>AI 助手 · 模板智能填报</span>
          {status?.enabled ? (
            <Tooltip title={<div style={{ whiteSpace: 'pre-line', maxWidth: 320 }}>{modelTip(status)}</div>}>
              <Tag color="green" style={{ cursor: 'help' }}>
                已启用 {status.models?.form_inspect || status.model}
              </Tag>
            </Tooltip>
          ) : (
            <Tag>未启用</Tag>
          )}
        </Space>
      }
      extra={
        <Space>
          <Button icon={<ReloadOutlined />} disabled={!file || disabled} onClick={() => file && inspect(file)}>
            重新扫描
          </Button>
          <Button
            type="primary"
            icon={<DownloadOutlined />}
            loading={filling}
            disabled={!file || !mapped.length || disabled}
            onClick={fill}
          >
            生成回填文件（{mapped.length}）
          </Button>
        </Space>
      }
    >
      <Alert
        type="info"
        showIcon
        style={{ marginBottom: 12 }}
        message="一期能力：上传 Excel 表单 → 识别空白字段 → 自动取系统里的项目/合同/供应商/统计数据填入 → 下载回填后的文件"
        description="系统里的数据只会写进你下载的文件，不会在页面上展示金额、账号等敏感值；请下载后自行核对再提交。"
      />
      {disabled && (
        <Alert
          type="warning"
          showIcon
          style={{ marginBottom: 12 }}
          message="AI 未启用"
          description="还没有登记可用的 AI 服务（接口地址 / API Key / 模型名）。请管理员到「系统管理 → AI 信息登记」填写并保存，保存即生效、无需重启；未启用时仍可手动按模板填写。"
        />
      )}

      <Space wrap style={{ marginBottom: 12 }}>
        <Segmented
          value={scopeMode}
          onChange={(v) => setScopeMode(v as 'current' | 'selected' | 'all')}
          options={[
            { value: 'current', label: '当前项目' },
            { value: 'selected', label: '多选项目' },
            { value: 'all', label: '全部项目' },
          ]}
        />
        {scopeMode === 'selected' && (
          <Select
            mode="multiple"
            allowClear
            showSearch
            optionFilterProp="label"
            style={{ minWidth: 240, maxWidth: 420 }}
            maxTagCount="responsive"
            placeholder="选择要汇总的项目"
            value={projectIds}
            onChange={setProjectIds}
            options={projects.map((p) => ({ value: p.id, label: `${p.name || p.id}${p.code ? `（${p.code}）` : ''}` }))}
          />
        )}
        {scopeMode !== 'current' && (
          <DatePicker.RangePicker value={periodRange} onChange={(v) => setPeriodRange(v as [Dayjs, Dayjs] | null)} />
        )}
        {scopeMode !== 'current' && (
          <Text type="secondary">跨项目填报：填入的是汇总值，需要「统计报表-查看」权限与期间</Text>
        )}
      </Space>

      <Space wrap style={{ marginBottom: 12 }}>
        <Select
          allowClear
          showSearch
          optionFilterProp="label"
          style={{ width: 320 }}
          placeholder="关联合同（可选，决定能用哪些合同字段）"
          value={contractId}
          onChange={setContractId}
          options={contracts.map((c) => ({ value: c.id, label: `${c.code} ${c.name}` }))}
        />
        <Select
          allowClear
          showSearch
          optionFilterProp="label"
          style={{ width: 260 }}
          placeholder="关联供应商（可选）"
          value={supplierId}
          onChange={setSupplierId}
          options={suppliers.map((s) => ({ value: s.id, label: s.name || s.id }))}
        />
        <Text type="secondary">选好关联对象再上传，字段列表会随之变化</Text>
      </Space>

      {!file && (
        <Dragger accept=".xlsx" maxCount={1} beforeUpload={onPick} showUploadList={false} disabled={disabled}>
          <p className="ant-upload-drag-icon">
            <InboxOutlined />
          </p>
          <p className="ant-upload-text">点击或拖拽 Excel 表单到此区域</p>
          <p className="ant-upload-hint">仅支持 .xlsx；表单需是「标签在左、值在右」或「标签在上、值在下」的常规布局</p>
        </Dragger>
      )}

      {inspecting && (
        <div style={{ padding: 40, textAlign: 'center' }}>
          <Spin tip="正在识别表单结构并匹配字段…" size="large">
            <div style={{ height: 60 }} />
          </Spin>
        </div>
      )}

      {!inspecting && file && (
        <>
          <Paragraph type="secondary" style={{ marginTop: 12 }}>
            文件：{file.name}
            {result ? `　工作表：${result.sheetNames.join('、') || '-'}` : ''}
            {result && result.truncated > 0 ? `　（候选过多，已丢弃 ${result.truncated} 个，请精简表单后重试）` : ''}
          </Paragraph>
          {result && !result.aiEnabled && (
            <Alert
              type="info"
              showIcon
              style={{ marginBottom: 12 }}
              message="未启用 AI 建议，下面只按关键词规则匹配"
              description={result.aiMessage}
            />
          )}
          <Table
            rowKey={(r) => keyOf(r)}
            dataSource={result?.candidates || []}
            columns={columns as any}
            pagination={{ pageSize: 20, showSizeChanger: false }}
            locale={{ emptyText: <Empty description="没有找到可填的空白单元格" /> }}
            scroll={{ x: 980 }}
          />

          {!!result?.tables?.length && !!result.tableDatasets?.length && (
            <Card size="small" style={{ marginTop: 16 }} title="表格区行级填充">
              <Space wrap>
                <Select
                  style={{ minWidth: 300 }}
                  value={tableIndex}
                  onChange={(i) => {
                    setTableIndex(i);
                    setTableDatasetKey(undefined);
                    setTableMapping({});
                  }}
                  options={result.tables.map((t, i) => ({
                    value: i,
                    label: `${t.sheet} · 第 ${t.headerRow} 行表头（${t.columns.length} 列 / ${t.emptyRows} 空行）`,
                  }))}
                />
                <Select
                  allowClear
                  style={{ minWidth: 220 }}
                  placeholder="选择数据集"
                  value={tableDatasetKey}
                  onChange={applyTableDataset}
                  options={result.tableDatasets.map((d) => ({ value: d.key, label: d.label }))}
                />
                <Button
                  type="primary"
                  loading={tableFilling}
                  disabled={!tableRegion || !tableDatasetKey}
                  onClick={fillTable}
                >
                  生成行级填充文件
                </Button>
              </Space>
              {tableRegion && tableDataset && (
                <Table
                  style={{ marginTop: 12 }}
                  rowKey="col"
                  size="small"
                  pagination={false}
                  dataSource={tableRegion.columns}
                  columns={[
                    { title: '列', dataIndex: 'letter', width: 70 },
                    { title: '模板表头', dataIndex: 'label' },
                    {
                      title: '数据列',
                      key: 'source',
                      render: (_: unknown, r: { col: number }) => (
                        <Select
                          allowClear
                          style={{ width: '100%' }}
                          value={tableMapping[r.col]}
                          onChange={(v) => setTableMapping((m) => ({ ...m, [r.col]: v }))}
                          options={tableDataset.columns.map((c) => ({ value: c, label: c }))}
                        />
                      ),
                    },
                  ]}
                />
              )}
              {tableRegion && !tableDataset && (
                <Text type="secondary" style={{ display: 'block', marginTop: 8 }}>
                  选择数据集后按表头自动预填列映射；跨项目时需先在页首选择期间。
                </Text>
              )}
            </Card>
          )}
        </>
      )}
    </Card>
  );
}

/**
 * 页面外壳：一期「模板智能填报」与二期「文件登记」「汇报材料」各占一个页签，菜单只有一个入口。
 *
 * 注：「结算异常预警」是**独立页面**（`AnomalyPanel`，路径 `/ai/anomaly`，侧边栏平级入口），
 * 不放在这里的页签里 —— 它是财务核对的常驻动作，藏进页签会找不到入口。
 * 页签不写进 URL——两个面板都是「上传即用」的临时状态，刷新后重来更符合预期。
 *
 * 注意：「系统管理 → AI 信息登记」是**另一个页面**（`AiSettings`，登记上游地址/密钥/模型），
 * 与本页无关，别再把它当成这里的某个页签。
 */

export default FillPanel;

import { useMemo, useState } from 'react';
import {
  Alert,
  Button,
  Card,
  Checkbox,
  Col,
  Collapse,
  DatePicker,
  Descriptions,
  Divider,
  Empty,
  Form,
  Input,
  Radio,
  Row,
  Segmented,
  Select,
  Space,
  Switch,
  Tag,
  Typography,
  message,
} from 'antd';
import { DownloadOutlined, FileTextOutlined, ThunderboltOutlined } from '@ant-design/icons';
import dayjs, { type Dayjs } from 'dayjs';
import {
  aiApi,
  type AiAnalyticsDatasetMeta,
  type AiAnalyticsPlanResult,
  type AiAnalyticsReportResult,
  type AiCompareMode,
  type AiPeriodPreset,
  type AiScopeMode,
} from '@/api/modules';
import ReportMarkdown from '@/components/ReportMarkdown';
import { MIME_DOCX, MIME_PDF, MIME_XLSX, downloadBlob, fileNameFromDisposition } from '@/utils/reportExport';
import { DEFAULT_MAX_DATASETS, KIND_OPTIONS, PRESET_OPTIONS, SCOPE_LABEL } from './constants';

const { Text, Paragraph } = Typography;


export interface GeneratePanelProps {
  datasets: AiAnalyticsDatasetMeta[];
  defaultKeys: string[];
  projects: Array<{ id: string; code: string; name: string }>;
  crossProjectAllowed: boolean;
  /** 后端注册表返回的最大可选数据集数（默认 8） */
  maxDatasets?: number;
  /** 生成成功后通知历史页签刷新 */
  onSaved: () => void;
}

/**
 * 生成页签（Phase 2）：范围/期间/数据集/自然语言 → 意图预览 → 确定性报告。
 * 数由程序算、排版由程序生成；本阶段不调用模型（`source='template'`）。
 */
export default function GeneratePanel({
  datasets,
  defaultKeys,
  projects,
  crossProjectAllowed,
  maxDatasets = DEFAULT_MAX_DATASETS,
  onSaved,
}: GeneratePanelProps) {
  const [scopeMode, setScopeMode] = useState<AiScopeMode>('current');
  const [projectIds, setProjectIds] = useState<string[]>([]);
  const [preset, setPreset] = useState<AiPeriodPreset>('this_month');
  const [customRange, setCustomRange] = useState<[Dayjs, Dayjs] | null>(null);
  const [compare, setCompare] = useState<AiCompareMode>('mom');
  const [selectedKeys, setSelectedKeys] = useState<string[]>(defaultKeys);
  const [text, setText] = useState('');
  const [reportKind, setReportKind] = useState<string | undefined>();
  const [detail, setDetail] = useState<string | undefined>();
  const [notes, setNotes] = useState('');
  const [title, setTitle] = useState('');
  const [narrative, setNarrative] = useState(true);
  const [withWorkbook, setWithWorkbook] = useState(false);
  const [workbookInfo, setWorkbookInfo] = useState<{ fileName: string } | null>(null);
  const [planning, setPlanning] = useState(false);
  const [generating, setGenerating] = useState(false);
  const [exporting, setExporting] = useState<'docx' | 'pdf' | null>(null);
  const [plan, setPlan] = useState<AiAnalyticsPlanResult | null>(null);
  const [result, setResult] = useState<AiAnalyticsReportResult | null>(null);
  /** 只有用户真正动过的字段才发给后端，未动的留给自然语言解析（计划 §2.2 逐字段覆盖） */
  const [touched, setTouched] = useState({ scope: false, period: false, compare: false, datasets: false });
  const mark = (key: keyof typeof touched) => setTouched((t) => ({ ...t, [key]: true }));

  const labelByKey = useMemo(() => new Map(datasets.map((d) => [d.key, d.label])), [datasets]);

  const body = (): Record<string, unknown> => {
    const b: Record<string, unknown> = {
      text: text.trim() || undefined,
      notes: notes.trim() || undefined,
      reportKind,
      detail,
      narrative,
    };
    if (touched.scope || scopeMode === 'selected') {
      b.scope = { mode: scopeMode, projectIds: scopeMode === 'selected' ? projectIds : undefined };
    }
    if (touched.period) {
      b.period =
        preset === 'custom'
          ? customRange
            ? { preset: 'custom', from: customRange[0].format('YYYY-MM-DD'), to: customRange[1].format('YYYY-MM-DD') }
            : { preset }
          : { preset };
    }
    if (touched.datasets && selectedKeys.length) b.datasets = selectedKeys;
    if (touched.compare) b.compare = compare;
    return b;
  };

  const doPlan = async () => {
    setPlanning(true);
    try {
      setPlan(await aiApi.analyticsPlan(body()));
    } catch {
      // 拦截器已弹错
    } finally {
      setPlanning(false);
    }
  };

  const doGenerate = async () => {
    if (scopeMode === 'selected' && !projectIds.length) {
      message.warning('多选项目里还没有选择项目');
      return;
    }
    if (preset === 'custom' && !customRange) {
      message.warning('自定义期间需要选择开始与结束日期');
      return;
    }
    setGenerating(true);
    try {
      const res = await aiApi.analyticsReport({ ...body(), title: title.trim() || undefined, outputs: { report: true, workbook: false } });
      setResult(res);
      setPlan(null);
      setWorkbookInfo(null);
      if (res.id && withWorkbook) {
        try {
          const wb = await aiApi.analyticsWorkbook({ ...body(), title: title.trim() || undefined, reportId: res.id });
          setWorkbookInfo({ fileName: wb.fileName });
          message.success(`报告已保存，表格已生成（${wb.sheets.length} 个 sheet）`);
        } catch {
          message.warning('报告已生成，但表格生成失败（历史里可稍后重试）');
        }
      } else if (res.persisted) {
        message.success('报告已生成并保存到历史');
      }
      onSaved();
    } catch {
      // 拦截器已弹错
    } finally {
      setGenerating(false);
    }
  };

  const doExport = async (format: 'docx' | 'pdf') => {
    if (!result?.id) return;
    setExporting(format);
    try {
      const res = await aiApi.analyticsExport(result.id, format);
      const blob = new Blob([res.data], { type: format === 'pdf' ? MIME_PDF : MIME_DOCX });
      downloadBlob(blob, fileNameFromDisposition(res.headers, `${result.title}.${format}`));
    } catch {
      // 拦截器已弹错
    } finally {
      setExporting(null);
    }
  };

  const doDownloadWorkbook = async () => {
    if (!result?.id) return;
    try {
      const res = await aiApi.analyticsWorkbookDownload(result.id);
      const blob = new Blob([res.data], { type: MIME_XLSX });
      downloadBlob(blob, fileNameFromDisposition(res.headers, workbookInfo?.fileName || `${result.title}.xlsx`));
    } catch {
      // 拦截器已弹错
    }
  };

  const datasetLabels = (keys: string[]) => keys.map((k) => labelByKey.get(k) ?? k);

  return (
    <Space direction="vertical" size={16} style={{ width: '100%' }}>
      <Card title="生成经营数据报告">
        <Form layout="vertical">
          <Row gutter={[16, 0]}>
            <Col xs={24} lg={12} xl={8}>
              <Form.Item label="范围">
                <Segmented
                  block
                  value={scopeMode}
                  onChange={(v) => {
                    setScopeMode(v as AiScopeMode);
                    mark('scope');
                  }}
                  options={[
                    { value: 'current', label: '当前项目' },
                    { value: 'selected', label: '多选项目', disabled: !crossProjectAllowed },
                    { value: 'all', label: '全部项目', disabled: !crossProjectAllowed },
                  ]}
                />
                {!crossProjectAllowed && (
                  <Text type="secondary" style={{ fontSize: 12 }}>
                    跨项目汇总需要「统计报表-查看」权限
                  </Text>
                )}
              </Form.Item>
            </Col>
            {scopeMode === 'selected' && (
              <Col xs={24} lg={12} xl={8}>
                <Form.Item label="选择项目">
                  <Select
                    mode="multiple"
                    allowClear
                    showSearch
                    maxTagCount="responsive"
                    placeholder="选择要汇总的项目"
                    value={projectIds}
                    onChange={(v) => {
                      setProjectIds(v);
                      mark('scope');
                    }}
                    options={projects.map((p) => ({ value: p.id, label: `${p.name}（${p.code}）` }))}
                  />
                </Form.Item>
              </Col>
            )}
            <Col xs={24} lg={12} xl={8}>
              <Form.Item label="期间">
                <Space wrap>
                  <Select
                    style={{ width: 140 }}
                    value={preset}
                    onChange={(v) => {
                      setPreset(v);
                      mark('period');
                    }}
                    options={PRESET_OPTIONS}
                  />
                  {preset === 'custom' && (
                    <DatePicker.RangePicker
                      value={customRange}
                      onChange={(v) => {
                        setCustomRange(v as [Dayjs, Dayjs] | null);
                        mark('period');
                      }}
                    />
                  )}
                </Space>
              </Form.Item>
            </Col>
            <Col xs={24} lg={12} xl={8}>
              <Form.Item label="对比">
                <Radio.Group
                  value={compare}
                  onChange={(e) => {
                    setCompare(e.target.value);
                    mark('compare');
                  }}
                >
                  <Radio.Button value="mom">环比</Radio.Button>
                  <Radio.Button value="yoy">同比</Radio.Button>
                  <Radio.Button value="none">不对比</Radio.Button>
                </Radio.Group>
              </Form.Item>
            </Col>
          </Row>

          <Form.Item label={`数据集（最多 ${maxDatasets} 个，已选 ${selectedKeys.length}）`}>
            <Checkbox.Group
              value={selectedKeys}
              onChange={(v) => {
                setSelectedKeys(v as string[]);
                mark('datasets');
              }}
              options={datasets.map((d) => ({
                value: d.key,
                label: (
                  <span title={d.desc}>
                    {d.label}
                    <Text type="secondary" style={{ fontSize: 12, marginLeft: 4 }}>
                      {d.desc}
                    </Text>
                  </span>
                ),
              }))}
            />
          </Form.Item>

          <Form.Item label="自然语言描述（可选）" extra="模型只用于理解意图：不会产生项目 ID、日期或数字。">
            <Input.TextArea
              rows={3}
              maxLength={2000}
              showCount
              value={text}
              onChange={(e) => setText(e.target.value)}
              placeholder="例：汇总全部项目今年合同、结算、付款和发票，出一份给领导的简报"
            />
          </Form.Item>

          <Collapse
            ghost
            items={[
              {
                key: 'advanced',
                label: '高级选项',
                children: (
                  <Row gutter={[16, 0]}>
                    <Col xs={24} md={8}>
                      <Form.Item label="报告类型">
                        <Select allowClear placeholder="按描述自动判断" value={reportKind} onChange={setReportKind} options={KIND_OPTIONS} />
                      </Form.Item>
                    </Col>
                    <Col xs={24} md={8}>
                      <Form.Item label="明细程度">
                        <Select
                          allowClear
                          placeholder="默认汇总"
                          value={detail}
                          onChange={setDetail}
                          options={[
                            { value: 'summary', label: '汇总' },
                            { value: 'detail', label: '明细' },
                            { value: 'both', label: '汇总 + 明细' },
                          ]}
                        />
                      </Form.Item>
                    </Col>
                    <Col xs={24} md={8}>
                      <Form.Item label="标题（留空自动生成）">
                        <Input maxLength={60} value={title} onChange={(e) => setTitle(e.target.value)} />
                      </Form.Item>
                    </Col>
                    <Col xs={24} md={8}>
                      <Form.Item label="AI 撰写分析段落" extra="关闭则只出确定性表格与汇总">
                        <Switch checked={narrative} onChange={setNarrative} />
                      </Form.Item>
                    </Col>
                    <Col span={24}>
                      <Form.Item label="补充说明（只影响写作，不影响取数）">
                        <Input maxLength={300} value={notes} onChange={(e) => setNotes(e.target.value)} />
                      </Form.Item>
                    </Col>
                  </Row>
                ),
              },
            ]}
          />

          <Space wrap>
            <Button icon={<ThunderboltOutlined />} loading={planning} onClick={doPlan}>
              解析意图
            </Button>
            <Button type="primary" icon={<FileTextOutlined />} loading={generating} onClick={doGenerate}>
              生成报告
            </Button>
            <Checkbox checked={withWorkbook} onChange={(e) => setWithWorkbook(e.target.checked)}>
              同时生成表格（xlsx）
            </Checkbox>
          </Space>
        </Form>
      </Card>

      {plan && (
        <Card title="意图预览" extra={<Text type="secondary">来源：{plan.source === 'rules' ? '规则解析' : '模型'}</Text>}>
          <Descriptions column={{ xs: 1, md: 2, xl: 3 }} size="small">
            <Descriptions.Item label="范围">{SCOPE_LABEL[plan.intent.scope.mode] ?? plan.intent.scope.mode}</Descriptions.Item>
            <Descriptions.Item label="期间">
              {PRESET_OPTIONS.find((p) => p.value === plan.intent.period.preset)?.label ?? plan.intent.period.preset}
              {plan.intent.period.preset === 'custom' ? `（${plan.intent.period.from} ~ ${plan.intent.period.to}）` : ''}
            </Descriptions.Item>
            <Descriptions.Item label="对比">
              {plan.intent.compare === 'yoy' ? '同比' : plan.intent.compare === 'mom' ? '环比' : '不对比'}
            </Descriptions.Item>
            <Descriptions.Item label="报告类型">
              {KIND_OPTIONS.find((k) => k.value === plan.intent.reportKind)?.label ?? plan.intent.reportKind}
            </Descriptions.Item>
            <Descriptions.Item label="项目数">{plan.projects.length}</Descriptions.Item>
            <Descriptions.Item label="数据集">{plan.intent.datasets.length}</Descriptions.Item>
          </Descriptions>
          <div style={{ marginTop: 8 }}>
            {datasetLabels(plan.intent.datasets).map((label) => (
              <Tag key={label} color="blue">
                {label}
              </Tag>
            ))}
          </div>
          {!!plan.warnings.length && (
            <Alert
              style={{ marginTop: 12 }}
              type="warning"
              showIcon
              message="解析提醒"
              description={
                <ul style={{ margin: 0, paddingLeft: 18 }}>
                  {plan.warnings.map((w) => (
                    <li key={w}>{w}</li>
                  ))}
                </ul>
              }
            />
          )}
        </Card>
      )}

      {result && (
        <Card
          title={result.title}
          extra={
            <Space wrap>
              {workbookInfo && (
                <Button icon={<DownloadOutlined />} onClick={doDownloadWorkbook}>
                  表格
                </Button>
              )}
              <Button icon={<DownloadOutlined />} loading={exporting === 'docx'} disabled={!result.id} onClick={() => doExport('docx')}>
                Word
              </Button>
              <Button icon={<DownloadOutlined />} loading={exporting === 'pdf'} disabled={!result.id} onClick={() => doExport('pdf')}>
                PDF
              </Button>
            </Space>
          }
        >
          {!result.persisted && (
            <Alert
              style={{ marginBottom: 12 }}
              type="warning"
              showIcon
              message="历史记录保存失败：本次结果仍可查看，但刷新后不可找回。"
            />
          )}
          {!!result.discardedNumbers.length && (
            <Alert
              style={{ marginBottom: 12 }}
              type="error"
              showIcon
              message="模型叙述包含无法对账的数字，已整段丢弃，报告改用确定性结果"
              description={result.discardedNumbers.join('、')}
            />
          )}
          {!!result.warnings.length && (
            <Alert
              style={{ marginBottom: 12 }}
              type="warning"
              showIcon
              message="生成提醒"
              description={
                <ul style={{ margin: 0, paddingLeft: 18 }}>
                  {result.warnings.map((w) => (
                    <li key={w}>{w}</li>
                  ))}
                </ul>
              }
            />
          )}
          <Space wrap style={{ marginBottom: 8 }}>
            {result.sections.map((s) => (
              <Tag key={s.id}>{s.title}</Tag>
            ))}
            <Tag color={result.source === 'template' ? 'default' : 'green'}>
              {result.source === 'template' ? '确定性模板' : '模型叙述'}
            </Tag>
          </Space>
          <Divider style={{ margin: '8px 0 12px' }} />
          {result.markdown ? <ReportMarkdown text={result.markdown} /> : <Empty description="没有生成内容" />}
          <Paragraph type="secondary" style={{ fontSize: 12, marginTop: 12 }}>
            口径：业务发生日归期；合同金额按合同链（主合同 + Σ 补充协议增量）；发票排除作废/红冲；未填金额按未知处理。
          </Paragraph>
        </Card>
      )}
    </Space>
  );
}

import { useEffect, useState } from 'react';
import {
  Button,
  DatePicker,
  Descriptions,
  Empty,
  Form,
  Input,
  Modal,
  Space,
  Spin,
  Table,
  Tabs,
  Tag,
  message,
} from 'antd';
import { contractApi } from '@/api/business';
import Can from '@/components/Can';
import DictSelect, { DictTag } from '@/components/DictSelect';
import { usePermission } from '@/hooks/usePermission';
import { useContainerWidth } from '@/hooks/useContainerWidth';

/**
 * 合同详情弹窗（只读 + 变更记录 + 新增补充协议向导）。
 *
 * 由原 `pages/Contracts.tsx` 的列表弹窗迁入（业务 2026-11-14 合并「合同台账」与「合同台账维护」）。
 * 列表页只管"打开哪一份"，取数与弹窗状态都在这里，避免列表再持有 detail/changes。
 */

const money = (v: number) => (v == null ? '-' : `¥${Number(v).toLocaleString('zh-CN', { maximumFractionDigits: 2 })}`);

export interface ContractDetailModalProps {
  /** 要查看的合同 id；为 null 时弹窗关闭（打开状态由它派生，避免两个状态各说各话） */
  contractId?: string | null;
  onClose: () => void;
  /** 新增补充协议成功后的回调（列表需要重新取数） */
  onChanged?: () => void;
}

export default function ContractDetailModal({ contractId, onClose, onChanged }: ContractDetailModalProps) {
  const open = !!contractId;
  const [detail, setDetail] = useState<any>(null);
  const [changes, setChanges] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(false);
  const [supOpen, setSupOpen] = useState(false);
  const [supForm] = Form.useForm();
  /** 写入口门禁：只读用户与已归档合同不得发起「新增补充协议」（后端仍有 `contract:edit` 403 兜底） */
  const canEdit = usePermission('contract:edit');
  const canWrite = canEdit && !!detail && !detail.archivedAt;

  useEffect(() => {
    // 关详情 / 换合同时，内层的「新增补充协议」弹窗必须一起收起（否则会挂在已清空的上文上）。
    // 表单值不用手动清：补充协议 Modal 带 `destroyOnHidden`，关闭即卸载。
    setSupOpen(false);
    if (!contractId) {
      setDetail(null);
      setChanges([]);
      setError(false);
      setLoading(false);
      return;
    }
    let alive = true;
    setError(false);
    setLoading(true);
    Promise.all([contractApi.detail(contractId), contractApi.changes(contractId)])
      .then(([d, ch]: any[]) => {
        if (!alive) return;
        setDetail(d);
        setChanges(ch || []);
      })
      .catch(() => {
        // 取不到 ≠ 没有：失败要显示失败，不能渲染成「暂无合同数据」
        if (alive) setError(true);
      })
      .finally(() => {
        if (alive) setLoading(false);
      });
    return () => {
      alive = false;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [contractId]);

  const openSupplement = async () => {
    if (!detail || !canWrite) return;
    const res: any = await contractApi.nextSupplementCode(detail.id);
    supForm.setFieldsValue({
      code: res.code,
      name: `${res.parentName}补充协议`,
      supplementTypeCode: undefined,
    });
    setSupOpen(true);
  };

  const createSupplement = async () => {
    if (!detail) {
      message.warning('合同详情已关闭，请重新打开后再新增补充协议');
      return;
    }
    if (!canWrite) {
      message.warning('合同已归档或无编辑权限，不能新增补充协议');
      return;
    }
    const v = await supForm.validateFields();
    await contractApi.create({
      ...v,
      signDate: v.signDate ? v.signDate.format('YYYY-MM-DD') : null,
      isSupplement: 'Y',
      parentContractId: detail.id,
      typeCode: detail.typeCode,
      supplierId: detail.supplierId,
    });
    message.success('补充协议已创建');
    setSupOpen(false);
    supForm.resetFields();
    const res: any = await contractApi.detail(detail.id);
    setDetail(res);
    onChanged?.();
  };

  return (
    <>
      <Modal
        title="合同详情"
        width={720}
        centered
        open={open}
        onCancel={onClose}
        footer={null}
        styles={{ body: { maxHeight: 'calc(100vh - 220px)', overflowY: 'auto' } }}
      >
        {loading ? (
          <Spin />
        ) : detail ? (
          <>
            <Tabs
              items={[
                {
                  key: 'info',
                  label: '合同信息',
                  children: <ContractDetailInfo detail={detail} />,
                },
                {
                  key: 'changes',
                  label: `变更记录（${changes.length}）`,
                  children: (
                    <Table
                      scroll={{ x: 'max-content' }}
                      rowKey="id"
                      size="small"
                      dataSource={changes}
                      pagination={false}
                      columns={[
                        { title: '字段', dataIndex: 'fieldLabel' },
                        { title: '变更前', dataIndex: 'beforeValue' },
                        { title: '变更后', dataIndex: 'afterValue' },
                        // 窄容器收起次要列（见 styles/containers.css §2）
                        { title: '操作人', dataIndex: 'operator', className: 'col-secondary' },
                        { title: '时间', dataIndex: 'createdAt', className: 'col-secondary', render: (v) => v?.slice(0, 19).replace('T', ' ') },
                      ]}
                    />
                  ),
                },
              ]}
            />
            {detail.isSupplement !== 'Y' && (
              <div style={{ marginTop: 16 }}>
                <Space wrap>
                  {detail.supplements?.map((s: any) => (
                    <Tag key={s.id} color="blue">{s.code}</Tag>
                  ))}
                </Space>
                <Can code="contract:edit">
                  <Button
                    type="primary"
                    size="small"
                    style={{ marginLeft: 8 }}
                    disabled={!!detail.archivedAt}
                    title={detail.archivedAt ? '合同已归档，不能新增补充协议' : undefined}
                    onClick={openSupplement}
                  >
                    新增补充协议
                  </Button>
                </Can>
              </div>
            )}
          </>
        ) : (
          <Empty description={error ? '合同详情加载失败，请稍后重试' : '暂无合同数据'} />
        )}
      </Modal>

      {/* 新增补充协议：详情弹窗内发起的向导型动作（创建草稿），保留弹窗形态（业务 2026-10-17） */}
      <Modal
        title="新增补充协议"
        open={supOpen}
        onOk={createSupplement}
        onCancel={() => setSupOpen(false)}
        destroyOnHidden
      >
        <Form form={supForm} layout="vertical">
          <Form.Item name="code" label="补充协议编号（自动生成，可微调）" rules={[{ required: true }]}>
            <Input />
          </Form.Item>
          <Form.Item name="name" label="协议名称" rules={[{ required: true }]}><Input /></Form.Item>
          <Form.Item name="supplementTypeCode" label="补充协议类型" rules={[{ required: true, message: '请选择补充协议类型' }]}>
            <DictSelect typeCode="supplement_agreement_type" />
          </Form.Item>
          <Form.Item name="signDate" label="签订日期"><DatePicker format="YYYY-MM-DD" style={{ width: '100%' }} /></Form.Item>
          <Form.Item name="remark" label="备注"><Input.TextArea rows={2} /></Form.Item>
        </Form>
      </Modal>
    </>
  );
}

/** 合同详情弹窗正文：列数按弹窗容器宽度降级（DESIGN.md §10.2） */
function ContractDetailInfo({ detail }: { detail: any }) {
  const { ref, size } = useContainerWidth<HTMLDivElement>();
  return (
    <div ref={ref} className="cq">
      <Descriptions column={size.isNarrow ? 1 : 2} size="small" bordered>
        <Descriptions.Item label="合同编号">{detail.code}</Descriptions.Item>
        <Descriptions.Item label="合同名称">{detail.name}</Descriptions.Item>
        <Descriptions.Item label="合同类型"><DictTag typeCode="contract_type" value={detail.typeCode} /></Descriptions.Item>
        <Descriptions.Item label="合同子类型"><DictTag typeCode="contract_sub_type" value={detail.subTypeCode} /></Descriptions.Item>
        {detail.codeAbbrUsed && <Descriptions.Item label="编号项目简称">{detail.codeAbbrUsed}</Descriptions.Item>}
        {detail.parentContractId && (
          <Descriptions.Item label="父合同" span={size.isNarrow ? 1 : 2}>
            {detail.parentContract ? `${detail.parentContract.code} ${detail.parentContract.name}` : '-'}
          </Descriptions.Item>
        )}
        <Descriptions.Item label="供应商">{detail.supplier?.name || '-'}</Descriptions.Item>
        <Descriptions.Item label="法人">{detail.supplier?.legalPerson || '-'}</Descriptions.Item>
        <Descriptions.Item label="授权人">{detail.supplier?.contractAuthPerson || '-'}</Descriptions.Item>
        <Descriptions.Item label="联系人">{detail.supplier?.contactName || '-'}</Descriptions.Item>
        <Descriptions.Item label="联系人电话">{detail.supplier?.contactPhone || '-'}</Descriptions.Item>
        <Descriptions.Item label="合同额">{money(detail.amount)}</Descriptions.Item>
        <Descriptions.Item label="税率">{detail.taxRatePct != null ? `${Number(detail.taxRatePct).toFixed(2)}%` : '-'}</Descriptions.Item>
        <Descriptions.Item label="签订日期">{detail.signDate?.slice(0, 10)}</Descriptions.Item>
        <Descriptions.Item label="执行情况"><DictTag typeCode="contract_execution_status" value={detail.execStatus} /></Descriptions.Item>
        <Descriptions.Item label="备注" span={size.isNarrow ? 1 : 2}>{detail.remark || '-'}</Descriptions.Item>
        {detail.attachments?.length ? (
          <Descriptions.Item label="附件" span={size.isNarrow ? 1 : 2}>
            {detail.attachments.map((a: any) => (
              <Tag key={a.id}><a href={a.url} target="_blank" rel="noreferrer">{a.fileName}</a></Tag>
            ))}
          </Descriptions.Item>
        ) : null}
      </Descriptions>
    </div>
  );
}

import { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Button,
  Card,
  Col,
  DatePicker,
  Descriptions,
  Form,
  Input,
  InputNumber,
  Modal,
  Row,
  Select,
  Space,
  Tabs,
  Typography,
  message,
} from 'antd';
import dayjs from 'dayjs';
import { contractApi, materialApi, projectApi, supplierApi, templateApi } from '@/api/business';
import EditorTabPage from '@/components/editor/EditorTabPage';
import DictSelect from '@/components/DictSelect';
import Uploader, { UploadFile } from '@/components/Uploader';
import { PAYMENT_MODE_OPTIONS, CUSTOM_PAYMENT_MODE } from '@/constants/paymentModes';
import { LIST_PATHS } from '@/constants/listPaths';
import { useEditorTab } from '@/hooks/useTabs';
import { useContainerWidth } from '@/hooks/useContainerWidth';
import { useAuthStore } from '@/store/auth';
import { sanitizeHtml } from '@/utils/sanitizeHtml';
import { CLAUSE_TYPE_LABEL } from '@/constants/clauseTypes';

/**
 * 合同编辑器（列表 + 编辑器是同一路由的两种形态：`?editor=new|<id>`）。
 *
 * 由原 `pages/Contracts.tsx` 迁入（业务 2026-11-14 合并「合同台账」与「合同台账维护」）：
 * 台账列表与编辑器共用 `/contract/list`，编辑器页签与列表刷新令牌都用 `LIST_PATHS.contractLedger`。
 */

/** 需求 2.3：四种条款类型对应的合同表单字段 */
const CLAUSE_FIELDS: { type: string; field: string }[] = [
  { type: 'technical', field: 'technicalClauseId' },
  { type: 'quality', field: 'qualityClauseId' },
  { type: 'payment', field: 'paymentClauseId' },
  { type: 'acceptance', field: 'acceptanceClauseId' },
];

export default function ContractEditor({ seed }: { seed: unknown }) {
  const editorTab = useEditorTab(LIST_PATHS.contractLedger);
  const [form] = Form.useForm();
  const [extForm] = Form.useForm();
  const [saving, setSaving] = useState(false);
  const [dirty, setDirty] = useState(false);
  const editing = seed as any | undefined;
  const [suppliers, setSuppliers] = useState<any[]>([]);
  const [materials, setMaterials] = useState<any[]>([]);
  const [supplier, setSupplier] = useState<any>(null);
  const [attachments, setAttachments] = useState<UploadFile[]>([]);
  const [codeStatus, setCodeStatus] = useState<'' | 'error' | 'success'>('');
  const [codeMsg, setCodeMsg] = useState('');
  const [codeTimer, setCodeTimer] = useState<any>(null);
  const [currentProject, setCurrentProject] = useState<any>(null);

  // 需求 2.3：合同条款（四种类型）选择
  const [clauseList, setClauseList] = useState<any[]>([]);
  const [clausePreview, setClausePreview] = useState<any[] | null>(null); // 预览全部条款
  const [clauseView, setClauseView] = useState<{ label: string; content: string } | null>(null); // 查看单条内容
  useEffect(() => {
    templateApi.clauses().then((res: any) => setClauseList(res?.list || res || []));
  }, []);
  const clausesByType = useCallback(
    (type: string) => clauseList.filter((c: any) => c.type === type),
    [clauseList],
  );

  useEffect(() => {
    supplierApi.options().then((res: any) => setSuppliers(res || []));
    materialApi.options().then((res: any) => setMaterials(res || []));
  }, []);

  // 当前项目（用于编号第3段字母简称）
  const currentProjectId = useAuthStore((s) => s.currentProjectId);
  useEffect(() => {
    if (currentProjectId) projectApi.detail(currentProjectId).then((res: any) => setCurrentProject(res));
  }, [currentProjectId]);

  // 编辑态：整行（含 ext）回填；新建：默认值
  useEffect(() => {
    form.resetFields();
    extForm.resetFields();
    if (editing) {
      form.setFieldsValue({
        ...editing,
        signDate: editing.signDate ? dayjs(editing.signDate) : null,
      });
      extForm.setFieldsValue({
        ...(editing.ext || {}),
        // 付款安排在主表上，但和 ext 的比例并排显示、一起保存（见 submit 里的归位说明）
        paymentMode: editing.paymentMode ?? undefined,
        bidStartDate: editing.ext?.bidStartDate ? dayjs(editing.ext.bidStartDate) : null,
        bidWinDate: editing.ext?.bidWinDate ? dayjs(editing.ext.bidWinDate) : null,
        disclosureDate: editing.ext?.disclosureDate ? dayjs(editing.ext.disclosureDate) : null,
      });
      setSupplier(editing.supplier || null);
      setAttachments(editing.attachments || []);
    }
    setDirty(false);
  }, [editing]);

  // 自动生成合同编号（类型/子类型/项目变化时刷新）
  const genCode = async (typeCode?: string, subTypeCode?: string) => {
    if (editing) return; // 编辑态编号不可变更
    try {
      const res: any = await contractApi.nextCode({
        typeCode: typeCode ?? form.getFieldValue('typeCode'),
        subTypeCode: subTypeCode ?? form.getFieldValue('subTypeCode'),
        projectId: currentProjectId,
      });
      if (res?.code) {
        form.setFieldsValue({ code: res.code });
        setCodeStatus('success');
        setCodeMsg('已自动生成（可手动微调，保存后不可变更）');
        if (res.missing?.length) setCodeMsg(`已生成，但缺少：${res.missing.join('；')}`);
      }
    } catch {
      /* 映射缺失时静默，由用户手填 */
    }
  };

  // 监听类型/子类型变化自动刷新编号预览
  const watchedType = Form.useWatch('typeCode', form);
  // 需求 2.1：合同发布后（待签章/已签章）合同类型固化；历史空状态在 UI 上按「待签章」展示，同样锁定
  const typeLocked = !!editing && editing.status !== 'DRAFT';
  const watchedSubType = Form.useWatch('subTypeCode', form);
  /** 付款安排：决定「月度结算办理比例」是否可填（标准安排自带比例，自定义才要填） */
  const watchedPayMode = Form.useWatch('paymentMode', extForm);
  useEffect(() => {
    if (!editing) genCode(watchedType, watchedSubType);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [watchedType, watchedSubType, editing]);

  // 合同编号实时查重
  const checkCode = (code: string) => {
    if (!code) {
      setCodeStatus('');
      setCodeMsg('');
      return;
    }
    if (codeTimer) clearTimeout(codeTimer);
    setCodeTimer(
      setTimeout(async () => {
        if (editing && editing.code === code) {
          setCodeStatus('success');
          setCodeMsg('当前编号');
          return;
        }
        const res: any = await contractApi.checkCode(code, editing?.id);
        if (res?.exists) {
          setCodeStatus('error');
          setCodeMsg(`合同编号已存在（${res.scope === 'GLOBAL' ? '全局唯一' : '项目内唯一'}）`);
        } else {
          setCodeStatus('success');
          setCodeMsg('编号可用');
        }
      }, 400),
    );
  };

  const onSupplierChange = (id: string) => {
    const hit = suppliers.find((s) => s.id === id);
    setSupplier(hit || null);
  };

  const submit = async () => {
    if (editing?.archivedAt) {
      message.error('合同已归档（单向归档），不能修改');
      return;
    }
    const values = await form.validateFields();
    if (codeStatus === 'error') {
      message.error('合同编号已存在，请修改');
      return;
    }
    const materialIds = values.materialIds;
    delete values.materialIds;
    /**
     * 「付款安排」是**合同主表**字段（`Contract.paymentMode`），却和 ext 的「月度结算办理比例」并排显示
     * —— 故在这里拆开归位：主表字段提到 payload 顶层，比例留在 `ext` 里。
     * （两个都塞进 ext 会**静默丢失**：后端 `saveExt` 只认 `EXT_FIELDS` 白名单。）
     */
    const extValues = extForm.getFieldsValue();
    // `currentPayRatio` 由服务端派生（见后端 `contract.service.syncPayRatio`），前端只展示、不回传
    const { paymentMode, settlementPayRatio, currentPayRatio: _derivedRatio, ...extRest } = extValues;
    const payload = {
      ...values,
      paymentMode,
      signDate: values.signDate ? values.signDate.format('YYYY-MM-DD') : null,
      attachments,
      ext: { ...extRest, settlementPayRatio },
      materialIds: editing ? undefined : materialIds, // 仅创建时派生清单
      // 乐观锁：编辑态必须回传 version，否则后端 assertVersion 抛 409
      version: editing ? (editing as any).version : undefined,
    };
    setSaving(true);
    try {
      if (editing) await contractApi.update(editing.id, payload);
      else await contractApi.create(payload);
      message.success(editing ? '保存成功' : '保存成功，已按所选物资生成合同物资清单');
      editorTab.closeEditor();
    } finally {
      setSaving(false);
    }
  };

  return (
    <EditorTabPage
      listPath={LIST_PATHS.contractLedger}
      title={editing ? '编辑合同' : '新建合同'}
      saving={saving}
      dirty={dirty}
      onSave={submit}
    >
      <Form form={form} component={false} onValuesChange={() => setDirty(true)}>
        {editing?.archivedAt && (
          <Alert
            type="warning"
            showIcon
            style={{ marginBottom: 12 }}
            message={`该合同已归档（${editing.archivedBy || '—'} · ${String(editing.archivedAt).slice(0, 10)}），仅可查看，不能修改`}
          />
        )}
        <Tabs
          items={[
            {
              key: 'base',
              label: '基础信息',
              children: (
                <>
                  <Row gutter={16}>
                    <Col xs={24} md={12}>
                      <Form.Item
                        name="code"
                        label="合同编号"
                        rules={[{ required: true }]}
                        validateStatus={codeStatus}
                        help={codeMsg}
                        hasFeedback
                      >
                        <Input onChange={(e) => checkCode(e.target.value)} placeholder="如 HT-2026-0001" />
                      </Form.Item>
                    </Col>
                    <Col xs={24} md={12}>
                      <Form.Item name="name" label="合同名称" rules={[{ required: true }]}><Input /></Form.Item>
                    </Col>
                    <Col xs={24} md={12}>
                      {/* 需求 2.1：发布后（待签章/已签章）合同类型只读，后端同步校验 */}
                      <Form.Item
                        name="typeCode"
                        label={typeLocked ? '合同类型（发布后不可修改）' : '合同类型'}
                        rules={[{ required: true }]}
                      >
                        <DictSelect typeCode="contract_type" disabled={typeLocked} />
                      </Form.Item>
                    </Col>
                    <Col xs={24} md={12}>
                      <Form.Item name="subTypeCode" label="合同子类型" rules={[{ required: true }]}>
                        <DictSelect typeCode="contract_sub_type" />
                      </Form.Item>
                    </Col>
                    <Col xs={24} md={12}>
                      <Form.Item name="supplierId" label="供应商" rules={[{ required: true }]}>
                        <Select
                          showSearch
                          optionFilterProp="label"
                          placeholder="请选择供应商（选择后自动带出法人/授权人/银行等信息）"
                          onChange={onSupplierChange}
                          options={suppliers.map((s) => ({ value: s.id, label: s.name }))}
                        />
                      </Form.Item>
                    </Col>
                    <Col xs={24} md={8}>
                      <Form.Item name="signDate" label="签订日期"><DatePicker format="YYYY-MM-DD" style={{ width: '100%' }} /></Form.Item>
                    </Col>
                    {!editing && (
                      <Col xs={24} md={16}>
                        <Form.Item
                          name="materialIds"
                          label="初始物资（从项目物资清单派生合同清单，可多选）"
                          extra="创建合同后将按所选物资自动生成合同物资清单（唯一数据源），也可之后在「合同物资清单」页面派生或导入。"
                        >
                          <Select
                            mode="multiple"
                            showSearch
                            optionFilterProp="label"
                            allowClear
                            maxTagCount={4}
                            placeholder="选择物资（可留空，稍后在合同物资清单中派生）"
                            options={materials.map((m) => ({ value: m.id, label: `${m.name} / ${m.spec}` }))}
                          />
                        </Form.Item>
                      </Col>
                    )}
                    <Col xs={24} md={8}>
                      <Form.Item name="amount" label="合同额"><InputNumber style={{ width: '100%' }} min={0} precision={2} /></Form.Item>
                    </Col>
                    <Col xs={24} md={8}>
                      <Form.Item name="taxRatePct" label="税率(%)"><InputNumber style={{ width: '100%' }} min={0} max={100} step={0.01} precision={2} /></Form.Item>
                    </Col>
                    <Col xs={24} md={8}>
                      <Form.Item name="paymentMethodCode" label="合同约定付款方式"><DictSelect typeCode="payment_method" /></Form.Item>
                    </Col>
                    <Col xs={24} md={8}>
                      <Form.Item name="isFramework" label="是否框架协议"><DictSelect typeCode="yes_no" /></Form.Item>
                    </Col>
                    <Col xs={24} md={8}>
                      <Form.Item name="isSupplement" label="是否补充协议"><DictSelect typeCode="yes_no" /></Form.Item>
                    </Col>
                    <Col xs={24} md={12}>
                      <Form.Item
                        noStyle
                        shouldUpdate={(prev, cur) => prev.isSupplement !== cur.isSupplement}
                      >
                        {({ getFieldValue }) =>
                          getFieldValue('isSupplement') === 'Y' ? (
                            <Form.Item name="supplementTypeCode" label="补充协议类型" rules={[{ required: true, message: '请选择补充协议类型' }]}>
                              <DictSelect typeCode="supplement_agreement_type" />
                            </Form.Item>
                          ) : null
                        }
                      </Form.Item>
                    </Col>
                    <Col xs={24} md={12}>
                      <Form.Item name="execStatus" label="合同执行情况"><DictSelect typeCode="contract_execution_status" /></Form.Item>
                    </Col>
                    <Col xs={24}>
                      <Form.Item name="remark" label="备注"><Input.TextArea rows={2} /></Form.Item>
                    </Col>
                    <Col xs={24}>
                      <Form.Item label="附件"><Uploader value={attachments} onChange={setAttachments} /></Form.Item>
                    </Col>
                    {/* 需求 2.3：合同条款 —— 四种类型分别下拉选择已维护的条款 */}
                    <Col xs={24}>
                      <Card
                        type="inner"
                        title="合同条款"
                        extra={
                          <Button
                            onClick={() => {
                              const rows = CLAUSE_FIELDS.map(({ type, field }) => {
                                const id = form.getFieldValue(field);
                                return { type, clause: clauseList.find((c: any) => c.id === id) || null };
                              });
                              setClausePreview(rows);
                            }}
                          >
                            预览全部条款
                          </Button>
                        }
                      >
                        <Row gutter={16}>
                          {CLAUSE_FIELDS.map(({ type, field }) => (
                            <Col xs={24} md={12} key={field}>
                              <Form.Item label={CLAUSE_TYPE_LABEL[type]}>
                                <Space.Compact style={{ width: '100%' }}>
                                  <Form.Item noStyle name={field}>
                                    <Select
                                      allowClear
                                      showSearch
                                      optionFilterProp="label"
                                      placeholder={`选择${CLAUSE_TYPE_LABEL[type]}`}
                                      options={clausesByType(type).map((c: any) => ({ value: c.id, label: c.title }))}
                                    />
                                  </Form.Item>
                                  <Button
                                    onClick={() => {
                                      const id = form.getFieldValue(field);
                                      const clause = clauseList.find((c: any) => c.id === id);
                                      if (!clause) return message.warning(`请先选择${CLAUSE_TYPE_LABEL[type]}`);
                                      setClauseView({ label: `${CLAUSE_TYPE_LABEL[type]}：${clause.title}`, content: clause.content });
                                    }}
                                  >
                                    查看内容
                                  </Button>
                                </Space.Compact>
                              </Form.Item>
                            </Col>
                          ))}
                        </Row>
                        <Alert
                          type="info"
                          showIcon
                          message="条款内容在「基础信息管理 → 合同条款」中维护；此处选择后随合同一起保存。"
                        />
                      </Card>
                    </Col>
                  </Row>

                  {supplier && (
                    <>
                      <Alert
                        type="info"
                        showIcon
                        style={{ marginBottom: 12 }}
                        message="以下信息由供应商库自动带出，只读展示；修改请在【供应商库】维护"
                      />
                      <SupplierInfoDescriptions supplier={supplier} />
                    </>
                  )}
                </>
              ),
            },
            {
              key: 'ext',
              label: '台账补充信息',
              children: (
                // 两个独立 Form（form + extForm），外层 component={false} 只做 dirty 汇总
                <Form form={extForm} layout="vertical" onValuesChange={() => setDirty(true)}>
                  <Row gutter={16}>
                    <Col xs={24} md={12}>
                      <Form.Item name="financeCode" label="财务一体化合同编号"><Input /></Form.Item>
                    </Col>
                    <Col xs={24} md={12}>
                      <Form.Item name="bidName" label="招标名称"><Input /></Form.Item>
                    </Col>
                    <Col xs={24} md={12}>
                      <Form.Item name="procurementSrc" label="采购来源"><DictSelect typeCode="procurement_source" /></Form.Item>
                    </Col>
                    <Col xs={24} md={12}>
                      <Form.Item name="isDirectPurchase" label="是否厂家直采"><DictSelect typeCode="is_direct_purchase" /></Form.Item>
                    </Col>
                    <Col xs={24} md={12}>
                      <Form.Item name="supplierCategory" label="分供方类别"><DictSelect typeCode="supplier_category" /></Form.Item>
                    </Col>
                    <Col xs={24} md={12}>
                      <Form.Item
                        name="paymentMode"
                        label="付款安排"
                        extra="月度结算办理的付款节点；总结算办理完成后按 100%（当前生效比例由服务端派生）"
                      >
                        <Select allowClear placeholder="请选择付款安排" options={PAYMENT_MODE_OPTIONS} />
                      </Form.Item>
                    </Col>
                    <Col xs={24} md={12}>
                      <Form.Item
                        name="settlementPayRatio"
                        label="月度结算办理比例"
                        extra={
                          watchedPayMode === CUSTOM_PAYMENT_MODE
                            ? '自定义付款安排时必填（如 0.65 表示 65%）'
                            : '标准付款安排的比例由安排本身决定，无需填写'
                        }
                      >
                        <InputNumber
                          style={{ width: '100%' }}
                          min={0}
                          max={1}
                          step={0.01}
                          precision={4}
                          disabled={watchedPayMode !== CUSTOM_PAYMENT_MODE}
                        />
                      </Form.Item>
                    </Col>
                    <Col xs={24} md={12}>
                      <Form.Item
                        name="currentPayRatio"
                        label="当前合同付款比例"
                        extra="只读：由服务端按「付款安排 / 已完已结」派生，保存后自动更新"
                      >
                        <Input readOnly placeholder="保存后自动计算" />
                      </Form.Item>
                    </Col>
                    <Col xs={24} md={8}>
                      <Form.Item name="bidStartDate" label="开始招标时间"><DatePicker format="YYYY-MM-DD" style={{ width: '100%' }} /></Form.Item>
                    </Col>
                    <Col xs={24} md={8}>
                      <Form.Item name="bidWinDate" label="定标时间"><DatePicker format="YYYY-MM-DD" style={{ width: '100%' }} /></Form.Item>
                    </Col>
                    <Col xs={24} md={8}>
                      <Form.Item name="disclosureDate" label="合同交底时间"><DatePicker format="YYYY-MM-DD" style={{ width: '100%' }} /></Form.Item>
                    </Col>
                    <Col xs={24}>
                      <Form.Item name="complaint" label="投诉情况"><Input.TextArea rows={2} /></Form.Item>
                    </Col>
                  </Row>
                </Form>
              ),
            },
          ]}
        />
      </Form>

      {/* 需求 2.3：查看单条条款内容 */}
      <Modal
        title={clauseView?.label || '条款内容'}
        open={!!clauseView}
        onCancel={() => setClauseView(null)}
        footer={<Button type="primary" onClick={() => setClauseView(null)}>关闭</Button>}
        width={680}
      >
        <div
          style={{ maxHeight: 480, overflow: 'auto', border: '1px solid var(--cms-hairline-soft)', borderRadius: 6, padding: 16, background: 'var(--cms-paper)' }}
          dangerouslySetInnerHTML={{ __html: sanitizeHtml(clauseView?.content) }}
        />
      </Modal>

