import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Alert, AutoComplete, Button, Input, InputNumber, Popconfirm, Space, Table, Tag, message } from 'antd';
import { DeleteOutlined, SaveOutlined, PlusOutlined } from '@ant-design/icons';
import { contractApi } from '@/api/business';
import { dictApi } from '@/api/dict';
import {
  calcPriceWithTax,
  calcTotalWithTax as calcTotal,
} from '../../../../server/src/common/calc/amounts.ts';

/** 含税单价/含税合价统一走共享原语（4 位精度），不再本地复制公式 */

/**
 * 合同起草 · Tab2：合同清单（交易明细 / 执行池）
 * - 独立维护，可通过「从物料编码清单添加」手动从 Tab1 同步（不自动派生）
 * - 数量、税前单价可编辑
 * - 税率为只读，实时绑定合同基本信息中的「合同税率」（需求修正2）：
 *   合同税率变化时所有行立即同步并重算，无需保存；后端保存时同样以合同税率为准
 * - 含税单价与暂定含税合价实时自动计算
 */
export default function ContractItemTab({
  contractId,
  contractTaxPct,
  onDirty,
}: {
  contractId: string;
  contractTaxPct?: number | null;
  onDirty?: () => void;
}) {
  const [rows, setRows] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [poolIds, setPoolIds] = useState<any[]>([]); // 物料编码清单（用于派生勾选）
  const [selectedRowKeys, setSelectedRowKeys] = useState<string[]>([]); // 派生勾选项
  const [deriveOpen, setDeriveOpen] = useState(false);
  // 需求 2.3.2：计量单位下拉选项统一来自字典「measurement_unit」
  const [unitOptions, setUnitOptions] = useState<string[]>([]);
  const dirtyRef = useRef(false);

  useEffect(() => {
    dictApi
      .options('measurement_unit')
      .then((res: any) => setUnitOptions((res || []).map((u: any) => u.label).filter(Boolean)))
      .catch(() => undefined);
  }, []);

  /** 生效税率：优先取合同基本信息中实时填写的合同税率 */
  const effectiveTax = contractTaxPct ?? null;

  const load = useCallback(async () => {
    if (!contractId) return;
    setLoading(true);
    try {
      const [list, pool]: any[] = await Promise.all([
        contractApi.draftList(contractId),
        contractApi.poolList(contractId),
      ]);
      setRows(Array.isArray(list) ? list : list?.list || []);
      setPoolIds(Array.isArray(pool) ? pool : pool?.list || []);
    } finally {
      setLoading(false);
    }
  }, [contractId]);

  useEffect(() => {
    load();
  }, [load]);

  /** 合同税率实时变化 → 所有行税率立即同步并重算（需求修正2，无需保存） */
  useEffect(() => {
    setRows((prev) =>
      prev.map((r) => {
        const priceWithTax = calcPriceWithTax(r.priceBeforeTax, effectiveTax);
        return {
          ...r,
          taxRatePct: effectiveTax,
          priceWithTax,
          totalWithTax: calcTotal(priceWithTax, r.qty),
        };
      }),
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [effectiveTax]);

  /** 本地改值：同步更新当前行并重算派生列（前端实时计算，保存时服务端二次校验） */
  const patch = (id: string, key: string, value: any) => {
    dirtyRef.current = true;
    onDirty?.();
    setRows((prev) =>
      prev.map((r) => {
        if (r.id !== id) return r;
        const next = { ...r, [key]: value };
        const priceWithTax = calcPriceWithTax(next.priceBeforeTax, effectiveTax);
        next.priceWithTax = priceWithTax;
        next.totalWithTax = calcTotal(priceWithTax, next.qty);
        return next;
      }),
    );
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      const res: any = await contractApi.draftSave(contractId, rows);
      message.success(`已保存 ${res?.saved ?? rows.length} 行`);
      dirtyRef.current = false;
      load();
    } finally {
      setSaving(false);
    }
  };

  const handleDerive = async () => {
    if (!selectedRowKeys.length) return message.warning('请勾选要添加的物料');
    const res: any = await contractApi.draftDerive(contractId, selectedRowKeys);
    message.success(`已添加 ${res?.added ?? 0} 行${res?.skipped ? `，跳过已存在 ${res.skipped} 行` : ''}`);
    setDeriveOpen(false);
    setSelectedRowKeys([]);
    load();
  };

  const handleRemove = async (id: string) => {
    await contractApi.draftRemove(contractId, id);
    message.success('已删除');
    onDirty?.();
    load();
  };

  const totalAmount = useMemo(
    () => rows.reduce((s, r) => s + (Number(r.totalWithTax) || 0), 0),
    [rows],
  );

  /** 需求修正2：合同税率未填写时给出红色提示 */
  const missingTax = effectiveTax == null && rows.length > 0;

  return (
    <Space direction="vertical" size={12} style={{ width: '100%' }}>
      {missingTax && (
        <Alert
          type="error"
          showIcon
          message="请先在物资基础信息中维护税率"
          description="请在上方的「基础信息」中填写合同税率，填写后所有物料税率将实时自动填充。"
        />
      )}
      <Space wrap>
        <Button icon={<PlusOutlined />} onClick={() => setDeriveOpen((v) => !v)}>
          {deriveOpen ? '收起物料列表' : '从物料编码清单添加'}
        </Button>
        <Button type="primary" icon={<SaveOutlined />} loading={saving} onClick={handleSave}>
          保存清单
        </Button>
        <span style={{ color: 'var(--cms-muted)' }}>
          合计（暂定含税）：<b style={{ color: 'var(--cms-error)' }}>¥{totalAmount.toLocaleString('zh-CN', { maximumFractionDigits: 2 })}</b>
        </span>
      </Space>

      {deriveOpen && (
        <Table
          rowKey="materialBaseId"
          size="small"
          dataSource={poolIds}
          scroll={{ x: 'max-content' }}
          pagination={false}
          rowSelection={{ selectedRowKeys, onChange: (keys: any) => setSelectedRowKeys(keys) }}
          columns={[
            { title: '物资名称', dataIndex: 'name' },
            { title: '规格型号', dataIndex: 'spec', width: 180 },
          ]}
          footer={() => (
            <Space>
              <Button
                size="small"
                onClick={() =>
                  setSelectedRowKeys(poolIds.map((p: any) => p.materialBaseId))
                }
              >
                全选
              </Button>
              <Button size="small" type="primary" onClick={handleDerive}>
                确认添加到合同清单
              </Button>
            </Space>
          )}
        />
      )}

      <Table
        rowKey="id"
        size="small"
        loading={loading}
        dataSource={rows}
        pagination={false}
        scroll={{ x: 1200 }}
        columns={[
          { title: '序号', dataIndex: 'seqNo', width: 70, render: (_, __, i) => i + 1 },
          { title: '物资名称', dataIndex: 'name', width: 160 },
          { title: '规格型号', dataIndex: 'spec', width: 150 },
          {
            title: '计量单位',
            dataIndex: 'unit',
            width: 130,
            // 需求 2.3.2：默认从物资基础库带出，可手动输入，但必须存在于字典「计量单位」
            render: (v, row) => (
              <AutoComplete
                value={v || ''}
                options={unitOptions.map((u) => ({ value: u }))}
                placeholder="如 吨(t)"
                style={{ width: '100%' }}
                filterOption={(input, option) => String(option?.value || '').includes(input)}
                onChange={(val) => patch(row.id, 'unit', val ?? '')}
                onBlur={() => {
                  const cur = String(row.unit || '').trim();
                  if (cur && unitOptions.length && !unitOptions.includes(cur)) {
                    message.error(`计量单位「${cur}」不在字典范围内，请先在字典管理中添加`);
                    patch(row.id, 'unit', '');
                  }
                }}
              />
            ),
          },
          {
            title: '暂定数量',
            dataIndex: 'qty',
            width: 120,
            render: (v, row) => (
              <InputNumber
                defaultValue={v}
                min={0}
                precision={4}
                style={{ width: '100%' }}
                onChange={(val) => patch(row.id, 'qty', val)}
              />
            ),
          },
          {
            title: '税前单价',
            dataIndex: 'priceBeforeTax',
            width: 120,
            render: (v, row) => (
              <InputNumber
                defaultValue={v}
                min={0}
                precision={4}
                style={{ width: '100%' }}
                onChange={(val) => patch(row.id, 'priceBeforeTax', val)}
              />
            ),
          },
          {
            title: '税率(%)',
            dataIndex: 'taxRatePct',
            width: 100,
            // 需求修正2：税率只读，实时绑定合同基本信息中的「合同税率」
            render: () =>
              effectiveTax == null ? (
                <Tag color="red">未维护</Tag>
              ) : (
                <Tag color="green">{Number(effectiveTax).toFixed(2)}</Tag>
              ),
          },
          {
            title: '含税单价（自动）',
            dataIndex: 'priceWithTax',
            width: 130,
            render: (v) => (v == null ? '-' : <Tag color="blue">{Number(v).toFixed(4)}</Tag>),
          },
          {
            title: '暂定含税合价（自动）',
            dataIndex: 'totalWithTax',
            width: 150,
            render: (v) => (v == null ? '-' : <Tag color="blue">{Number(v).toFixed(4)}</Tag>),
          },
          {
            title: '备注',
            dataIndex: 'remark',
            width: 160,
            render: (v, row) => (
              <Input defaultValue={v || ''} onBlur={(e) => patch(row.id, 'remark', e.target.value)} />
            ),
          },
          {
            title: '操作',
            width: 80,
            fixed: 'right',
            render: (_, row) => (
              <Popconfirm title="确认删除该清单行？" onConfirm={() => handleRemove(row.id)}>
                <Button type="link" size="small" danger icon={<DeleteOutlined />}>
                  删除
                </Button>
              </Popconfirm>
            ),
          },
        ]}
      />
    </Space>
  );
}

import { useEffect, useMemo, useState } from 'react';
import { Button, Form, Input, Modal, Table, Space, Alert, message } from 'antd';
import { PlusOutlined, SearchOutlined } from '@ant-design/icons';
import { materialApi } from '@/api/business';

/**
 * 物料选择弹窗（合同起草「物料编码清单」·「添加物料」用，需求修正1）
 * - 支持按名称 / 规格 / MDM 编码 / DSC 编码检索物资基础库
 * - 支持单条勾选与全选（全选作用于当前检索结果）
 * - 已添加（存在于 excludeIds）的物资灰显禁选，避免重复
 * - 支持手动新增物料：填写名称/规格等创建到物资基础库后自动勾选
 */
export default function MaterialPickerModal({
  open,
  excludeIds = [],
  onCancel,
  onOk,
}: {
  open: boolean;
  excludeIds?: string[];
  onCancel: () => void;
  onOk: (ids: string[]) => void;
}) {
  const [rows, setRows] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [keyword, setKeyword] = useState('');
  const [selected, setSelected] = useState<string[]>([]);
  const [createOpen, setCreateOpen] = useState(false);
  const [creating, setCreating] = useState(false);
  const [createForm] = Form.useForm();

  const load = async (kw?: string) => {
    setLoading(true);
    try {
      const res: any = await materialApi.list({ keyword: kw || undefined, pageSize: 500, page: 1 });
      setRows(res?.list || res?.data?.list || (Array.isArray(res) ? res : []));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (open) {
      setKeyword('');
      setSelected([]);
      setCreateOpen(false);
      load();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  const excludeSet = useMemo(() => new Set(excludeIds), [excludeIds]);
  const selectable = useMemo(() => rows.filter((r) => !excludeSet.has(r.id)), [rows, excludeSet]);
  const allChecked = selectable.length > 0 && selectable.every((r) => selected.includes(r.id));

  const toggleAll = (checked: boolean) => {
    if (checked) setSelected(Array.from(new Set([...selected, ...selectable.map((r) => r.id)])));
    else setSelected(selected.filter((id) => !selectable.some((r) => r.id === id)));
  };

  const toggleOne = (id: string, checked: boolean) => {
    setSelected((prev) => (checked ? Array.from(new Set([...prev, id])) : prev.filter((x) => x !== id)));
  };

  /** 手动新增物料：创建到物资基础库后自动勾选（需求修正1） */
  const handleCreate = async () => {
    const values = await createForm.validateFields();
    setCreating(true);
    try {
      const created: any = await materialApi.create(values);
      const id = created?.id || created?.data?.id;
      message.success('物料已创建到物资基础库');
      setCreateOpen(false);
      createForm.resetFields();
      await load(keyword);
      if (id) setSelected((prev) => Array.from(new Set([...prev, id])));
    } finally {
      setCreating(false);
    }
  };

  return (
    <Modal
      title="添加物料"
      open={open}
      onCancel={onCancel}
      onOk={() => onOk(selected)}
      okText={`确认添加${selected.length ? `（${selected.length}）` : ''}`}
      cancelText="取消"
      width={900}
      destroyOnHidden
    >
      <Space direction="vertical" size={12} style={{ width: '100%' }}>
        <Space>
          <Input
            allowClear
            prefix={<SearchOutlined />}
            style={{ width: 320 }}
            placeholder="物资名称 / 规格型号 / MDM编码 / DSC编码"
            value={keyword}
            onChange={(e) => setKeyword(e.target.value)}
            onPressEnter={() => load(keyword)}
          />
          <a onClick={() => load(keyword)}>检索</a>
          <Button type="primary" ghost icon={<PlusOutlined />} onClick={() => setCreateOpen(true)}>
            手动新增物料
          </Button>
        </Space>
        {excludeSet.size > 0 && (
          <Alert type="info" showIcon message="灰显且不可勾选的物料为已添加至本合同的物料，避免重复。" />
        )}
        <Table
          rowKey="id"
          size="small"
          loading={loading}
          dataSource={rows}
          scroll={{ x: 'max-content' }}
          pagination={{ pageSize: 8, showTotal: (t: number) => `共 ${t} 条` }}
          rowSelection={{
            selectedRowKeys: selected,
            onSelect: (row, checked) => toggleOne(row.id, checked),
            onSelectAll: (checked) => toggleAll(checked),
            getCheckboxProps: (row: any) => ({ disabled: excludeSet.has(row.id) }),
          }}
          columns={[
            {
              title: '物资名称',
              dataIndex: 'name',
              render: (v, row) => (excludeSet.has(row.id) ? <span style={{ color: 'var(--cms-muted-soft)' }}>{v}</span> : v),
            },
            { title: '规格型号', dataIndex: 'spec', width: 180 },
            { title: 'MDM编码', dataIndex: 'mdmCode', width: 160, render: (v) => v || '-' },
            { title: 'DSC编码', dataIndex: 'dscCode', width: 160, render: (v) => v || '-' },
          ]}
        />
      </Space>

      {/* 手动新增物料弹窗 */}
      <Modal
        title="手动新增物料"
        open={createOpen}
        onCancel={() => setCreateOpen(false)}
        onOk={handleCreate}
        confirmLoading={creating}
        okText="创建并勾选"
        width={480}
        destroyOnHidden
      >
        <Form form={createForm} layout="vertical">
          <Form.Item name="name" label="物资名称" rules={[{ required: true, message: '请输入物资名称' }]}>
            <Input placeholder="如：PE管" />
          </Form.Item>
          <Form.Item name="spec" label="规格型号" rules={[{ required: true, message: '请输入规格型号' }]}>
            <Input placeholder="如：DN300 PN1.0" />
          </Form.Item>
          <Space size={16}>
            <Form.Item name="mdmCode" label="MDM编码（选填）" style={{ width: 200 }}>
              <Input />
            </Form.Item>
            <Form.Item name="dscCode" label="DSC编码（选填）" style={{ width: 200 }}>
              <Input />
            </Form.Item>
          </Space>
          <Alert type="info" showIcon={false} message="新物料将同步保存到「物资基础库」，供其他合同复用。" />
        </Form>
      </Modal>
    </Modal>
  );
}

import { sanitizeHtml } from '@/utils/sanitizeHtml';

import { useEffect, useState } from 'react';
import {
  Alert, Button, Card, Form, Input, InputNumber, Select, Space, Table, Typography, message, Modal,
} from 'antd';
import type { ColumnsType } from 'antd/es/table';
import { DeleteOutlined, PlusOutlined, EyeOutlined, SendOutlined, SaveOutlined } from '@ant-design/icons';
import { contractApi, templateApi } from '@/api/business';
import { dailyApi } from '@/api/modules';
import RichTextEditor from '@/components/RichTextEditor';
import { amountToChineseCapital } from '../../../../server/src/common/calc/money.ts';
import { calcPriceWithTax, calcTotalWithTax } from '../../../../server/src/common/calc/amounts.ts';
import { DictTag } from '@/components/DictSelect';

const SUPP_TYPES = [
  { value: 'PRICE_UP', label: '涨价补充协议' },
  { value: 'PRICE_DOWN', label: '降价补充协议' },
  { value: 'QTY_ADD', label: '增量补充协议' },
  { value: 'ITEM_ADD', label: '增项补充协议' },
  { value: 'OTHER', label: '其他类补充协议' },
] as const;

type SuppType = (typeof SUPP_TYPES)[number]['value'];

const suppName = (code: string): string =>
  SUPP_TYPES.find((t) => t.value === code)?.label ?? code;

const num = (v: unknown): number => {
  if (v === '' || v == null) return 0;
  const n = Number(v);
  return Number.isNaN(n) ? 0 : n;
};
const fmt = (v: unknown): string =>
  num(v) === 0 ? '0.00' : num(v).toLocaleString('zh-CN', { maximumFractionDigits: 2 });
const fmtPct = (v: unknown): string => `${(num(v) * 100).toFixed(2)}%`;

/** 构造与后端 buildTableHtml 一致的表格 HTML（用于 {{补充协议表}} 占位符） */
function buildTableHtml(headers: readonly string[], rows: readonly (string | number)[][]): string {
  const esc = (v: unknown): string =>
    String(v ?? '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');
  const thead = `<tr>${headers
    .map((h) => `<th style="border:1px solid var(--cms-ink);padding:4px 6px;background:var(--cms-paper-head);">${esc(h)}</th>`)
    .join('')}</tr>`;
  const tbody = rows.length
    ? rows
        .map(
          (r) =>
            `<tr>${r
              .map((c) => `<td style="border:1px solid var(--cms-ink);padding:4px 6px;text-align:center;">${esc(c)}</td>`)
              .join('')}</tr>`,
        )
        .join('')
    : `<tr><td style="border:1px solid var(--cms-ink);padding:4px 6px;text-align:center;" colspan="${headers.length}">暂无数据</td></tr>`;
  return `<table style="border-collapse:collapse;width:100%;">${thead}${tbody}</table>`;
}

/** 原合同（父合同）最小结构：所有字段均可能缺失，访问时必须使用可选链 */
interface SuppParent {
  id?: string | null;
  code?: string | null;
  name?: string | null;
  typeCode?: string | null;
  supplierId?: string | null;
  templateId?: string | null;
  amount?: number | string | null;
}

/**
 * 涨价/降价/增量协议行：由原合同清单自动带出（materialBaseId 非空时只读字段锁定），
 * 或手动添加（materialBaseId 为空，全部字段可编辑）。
 */
interface SuppRow {
  materialBaseId: string;
  name: string;
  spec: string;
  unit: string;
  origQty: number; // 原合同数量（清单「暂定数量」）
  origPrice: number; // 原合同含税单价（清单「含税单价」）
  settledQty: number; // 日报已发生数量（结算数量合计）
  newPrice: number; // 涨价/降价：补充协议含税单价（可编辑）
  addQty: number; // 增量：暂定新增数量（可编辑）
  remark: string;
}

/** 原合同清单导入行（来自 contractApi.draftList，字段可能缺失） */
interface OrigRow {
  materialBaseId?: string | null;
  name?: string | null;
  spec?: string | null;
  unit?: string | null;
  qty?: number | string | null;
  priceWithTax?: number | string | null;
  totalWithTax?: number | string | null;
}

interface ItemRow {
  name: string;
  spec: string;
  unit: string;
  priceBeforeTax: number;
  taxRate: number;
  addQty: number;
  remark: string;
}

interface Props {
  /** 父组件可能尚未选中合同（null），组件内部必须兜底 */
  parent: SuppParent | null;
  open: boolean;
  onClose: () => void;
  onDone: () => void;
}

const blankSupp = (): SuppRow => ({
  materialBaseId: '', name: '', spec: '', unit: '',
  origQty: 0, origPrice: 0, settledQty: 0, newPrice: 0, addQty: 0, remark: '',
});
const blankItem = (): ItemRow => ({ name: '', spec: '', unit: '', priceBeforeTax: 0, taxRate: 13, addQty: 0, remark: '' });

/** 原合同剩余数量 = 原合同数量 − 日报已发生数量（允许负数显示，计算金额时按 0） */
const remainOf = (r: SuppRow): number => num(r.origQty) - num(r.settledQty);
/** 计算用剩余数量：负数按 0 处理，避免出现负金额 */
const remainForCalc = (r: SuppRow): number => Math.max(0, remainOf(r));

/** 更新数组第 i 项指定字段（泛型，类型安全） */
function update<T, K extends keyof T>(rows: T[], setter: (v: T[]) => void, i: number, field: K, value: T[K]): void {
  const next = rows.slice();
  next[i] = { ...next[i], [field]: value };
  setter(next);
}

export default function SupplementDraft({ parent, open, onClose, onDone }: Props) {
  const [loading, setLoading] = useState(false);
  const [creating, setCreating] = useState(false);
  const [contractId, setContractId] = useState<string | null>(null);
  const [code, setCode] = useState('');
  const [seq, setSeq] = useState(1);
  const [suppType, setSuppType] = useState<SuppType>('PRICE_UP');
  const [saved, setSaved] = useState(false);

  // 各类型表数据
  const [priceRows, setPriceRows] = useState<SuppRow[]>([]);
  const [qtyRows, setQtyRows] = useState<SuppRow[]>([]);
  const [itemOrig, setItemOrig] = useState<OrigRow[]>([]);
  const [itemNew, setItemNew] = useState<ItemRow[]>([blankItem()]);
  const [otherHtml, setOtherHtml] = useState('');

  const [previewOpen, setPreviewOpen] = useState(false);
  const [previewHtml, setPreviewHtml] = useState('');
  const [previewing, setPreviewing] = useState(false);
  const [publishing, setPublishing] = useState(false);

  /** 原合同清单行 → 补充协议行（只读字段自动带出，剩余数量 = 数量 − 日报结算合计） */
  const toSuppRows = (orig: OrigRow[], settledMap: Map<string, number>): SuppRow[] =>
    orig
      .filter((r) => r?.materialBaseId || r?.name)
      .map((r) => {
        const materialBaseId = r?.materialBaseId ?? '';
        const row: SuppRow = {
          materialBaseId,
          name: r?.name ?? '',
          spec: r?.spec ?? '',
          unit: r?.unit ?? '',
          origQty: num(r?.qty),
          origPrice: num(r?.priceWithTax),
          settledQty: settledMap.get(materialBaseId) ?? 0,
          newPrice: 0,
          addQty: 0,
          remark: '',
        };
        return row;
      });

  // 打开时初始化：拉取补充协议编号 + 原合同清单 + 日报结算数量合计
  useEffect(() => {
    if (!open || !parent?.id) return;
    setContractId(null);
    setSuppType('PRICE_UP');
    setSaved(false);
    setOtherHtml('');
    setItemNew([blankItem()]);
    setLoading(true);
    (async () => {
      try {
        const nc = (await contractApi.nextSupplementCode(parent.id as string)) as
          | { code?: string; seq?: number }
          | undefined;
        setCode(nc?.code ?? '');
        setSeq(nc?.seq ?? 1);
        // 并行拉取：原合同清单 + 日报结算数量合计
        const [m, sq] = await Promise.all([
          contractApi
            .draftList(parent.id as string)
            .catch(() => undefined as unknown),
          dailyApi
            .contractSettledQty(parent.id as string)
            .catch(() => undefined as unknown),
        ]);
        const orig: OrigRow[] = Array.isArray(m)
          ? (m as OrigRow[])
          : ((m as { list?: OrigRow[] } | undefined)?.list ?? []);
        setItemOrig(orig);
        const settledEntries = Array.isArray(sq)
          ? (sq as { materialBaseId: string; settleQty: number }[])
          : [];
        const settledMap = new Map<string, number>(
          settledEntries.map((x) => [x.materialBaseId, num(x.settleQty)]),
        );
        // 涨价/降价/增量：自动带出原合同清单（含剩余数量），支持删除行
        setPriceRows(toSuppRows(orig, settledMap));
        setQtyRows(toSuppRows(orig, settledMap));
      } catch {
        message.error('获取补充协议编号失败');
      } finally {
        setLoading(false);
      }
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, parent?.id]);

  /** 创建补充协议草稿（仅首次），返回 id */
  const ensureContract = async (): Promise<string | null> => {
    if (contractId) return contractId;
    if (!code || !parent?.id) return null;
    setCreating(true);
    try {
      const created = (await contractApi.create({
        code,
        name: `${parent?.name ?? parent?.code ?? ''}之补充协议（${seq}）`,
        typeCode: parent?.typeCode ?? undefined,
        supplierId: parent?.supplierId ?? undefined,
        templateId: parent?.templateId ?? undefined,
        isSupplement: 'Y',
        parentContractId: parent.id,
        supplementTypeCode: suppType,
        status: 'DRAFT',
      })) as { id?: string } | undefined;
      const id = created?.id ?? null;
      setContractId(id);
      return id;
    } finally {
      setCreating(false);
    }
  };

  /** 计算并组装 formData.supplement（已解析好的占位符值） */
  const buildSupplementData = (): Record<string, string> => {
    const parentAmount = num(parent?.amount);
    const base: Record<string, string> = {
      补充协议编号: code,
      补充协议类型: suppName(suppType),
      原合同编号: parent?.code ?? '',
      原合同名称: parent?.name ?? '',
    };
    if (suppType === 'PRICE_UP' || suppType === 'PRICE_DOWN') {
      // 原合同剩余数量：显示允许负数；计算金额时负数按 0（避免负金额）
      const rows = priceRows.map((r, i) => {
        const origAmount = num(r.origQty) * num(r.origPrice);
        const diff = num(r.newPrice) - num(r.origPrice);
        const newAmount = remainForCalc(r) * diff;
        return { ...r, origAmount, diff, newAmount, i };
      });
      const newTotal = rows.reduce((s, r) => s + r.newAmount, 0);
      const qtyTotal = rows.reduce((s, r) => s + remainOf(r), 0);
      base['补充协议表'] = buildTableHtml(
        ['序号', '物资名称', '规格型号', '计量单位', '原合同数量', '原合同剩余数量', '原合同含税单价', '原合同金额',
          '补充协议含税单价', '原合同与补充协议价差', '新增合同金额', '累计占原合同金额比例', '备注'],
        rows.map((r) => [r.i + 1, r.name, r.spec, r.unit, fmt(r.origQty), fmt(remainOf(r)), fmt(r.origPrice), fmt(r.origAmount),
          fmt(r.newPrice), fmt(r.diff), fmt(r.newAmount), fmtPct(parentAmount ? r.newAmount / parentAmount : 0), r.remark || '']),
      );
      base['原合同金额总价大写'] = amountToChineseCapital(parentAmount);
      base['新增合同金额总价大写'] = amountToChineseCapital(newTotal);
      base['数量汇总'] = fmt(qtyTotal);
      base['累计补充协议占比'] = fmtPct(parentAmount ? newTotal / parentAmount : 0);
    } else if (suppType === 'QTY_ADD') {
      const rows = qtyRows.map((r, i) => {
        const origAmount = num(r.origQty) * num(r.origPrice);
        const addAmount = num(r.addQty) * num(r.origPrice);
        return { ...r, origAmount, addAmount, i };
      });
      const addTotal = rows.reduce((s, r) => s + r.addAmount, 0);
      const qtyTotal = rows.reduce((s, r) => s + num(r.addQty), 0);
      base['补充协议表'] = buildTableHtml(
        ['序号', '物资名称', '规格型号', '计量单位', '原合同含税单价', '原合同数量', '原合同剩余数量', '暂定新增数量', '原合同金额', '暂定新增金额', '累计占原合同金额比例', '备注'],
        rows.map((r) => [r.i + 1, r.name, r.spec, r.unit, fmt(r.origPrice), fmt(r.origQty), fmt(remainOf(r)), fmt(r.addQty), fmt(r.origAmount),
          fmt(r.addAmount), fmtPct(parentAmount ? r.addAmount / parentAmount : 0), r.remark || '']),
      );
      base['原合同金额总价大写'] = amountToChineseCapital(parentAmount);
      base['新增合同金额总价大写'] = amountToChineseCapital(addTotal);
      base['数量汇总'] = fmt(qtyTotal);
      base['累计补充协议占比'] = fmtPct(parentAmount ? addTotal / parentAmount : 0);
    } else if (suppType === 'ITEM_ADD') {
      const newRows = itemNew.map((r, i) => {
        // 统一引擎：与服务端 contract.service 的含税公式同口径（含税单价 4 位、合价 4 位）
        const priceWithTax = calcPriceWithTax(num(r.priceBeforeTax), num(r.taxRate)) ?? 0;
        const amount = calcTotalWithTax(priceWithTax, num(r.addQty)) ?? 0;
        return { ...r, priceWithTax, amount, i };
      });
      const addTotal = newRows.reduce((s, r) => s + r.amount, 0);
      const qtyTotal = newRows.reduce((s, r) => s + num(r.addQty), 0);
      base['补充协议表'] = buildTableHtml(
        ['序号', '物资名称', '规格型号', '计量单位', '税前单价', '税率(%)', '含税单价', '暂定新增数量', '暂定新增含税金额', '累计占原合同金额比例', '备注'],
        newRows.map((r) => [r.i + 1, r.name, r.spec, r.unit, fmt(r.priceBeforeTax), fmt(r.taxRate), fmt(r.priceWithTax),
          fmt(r.addQty), fmt(r.amount), fmtPct(parentAmount ? r.amount / parentAmount : 0), r.remark || '']),
      );
      base['原合同金额总价大写'] = amountToChineseCapital(parentAmount);
      base['新增合同金额总价大写'] = amountToChineseCapital(addTotal);
      base['数量汇总'] = fmt(qtyTotal);
      base['累计补充协议占比'] = fmtPct(parentAmount ? addTotal / parentAmount : 0);
      // 原合同清单作为正文前导说明（可选），此处仅存入原合同清单表
      if (itemOrig.length) {
        base['补充协议表'] =
          buildTableHtml(['序号', '物资名称', '规格型号', '计量单位', '原合同含税单价', '原合同数量', '原合同金额'],
            itemOrig.map((r, i) => [i + 1, r?.name ?? '', r?.spec ?? '',
              r?.unit ?? '', fmt(r?.priceWithTax), fmt(r?.qty), fmt(r?.totalWithTax)])) + base['补充协议表'];
      }
    } else {
      // OTHER：富文本正文
      base['其他补充协议内容'] = otherHtml;
      base['补充协议表'] = '';
    }
    return base;
  };

  const persistFormData = async (id: string): Promise<void> => {
    const supplement = buildSupplementData();
    // 乐观锁：本组件可能对同一份补充协议连续保存多次（保存→预览→发布），
    // 每次保存前取一次最新 version，否则第二次必被后端 assertVersion 拦成 409
    const detail: any = await contractApi.detail(id).catch(() => undefined);
    await contractApi.update(id, {
      supplementTypeCode: suppType,
      formData: { supplement },
      ...(detail?.version !== undefined ? { version: detail.version } : {}),
    });
    setSaved(true);
  };

  const handleSave = async (): Promise<void> => {
    const id = await ensureContract();
    if (!id) { message.error('补充协议创建失败'); return; }
    await persistFormData(id);
    message.success('已保存补充协议内容');
  };

  const handlePreview = async (): Promise<void> => {
    const id = await ensureContract();
    if (!id) { message.error('补充协议创建失败'); return; }
    await persistFormData(id);
    if (!parent?.templateId) { message.warning('原合同未关联模板，无法预览'); return; }
    setPreviewing(true);
    try {
      const res = (await templateApi.generate({ templateId: parent.templateId, contractId: id })) as
        | { html?: string }
        | undefined;
      setPreviewHtml(res?.html ?? '');
      setPreviewOpen(true);
    } finally {
      setPreviewing(false);
    }
  };

  const handlePublish = async (): Promise<void> => {
    const id = await ensureContract();
    if (!id) { message.error('补充协议创建失败'); return; }
    await persistFormData(id);
    Modal.confirm({
      title: '发布补充协议',
      content: '发布后该补充协议将进入「合同查询」列表，状态为待签章，合同类型与内容不可再修改。',
      okText: '确认发布',
      cancelText: '再检查一下',
      onOk: async () => {
        setPublishing(true);
        try {
          await contractApi.publish(id);
          message.success('补充协议已发布');
          onDone();
        } finally {
          setPublishing(false);
        }
      },
    });
  };

  // ---- 空值守卫：parent 为 null（父组件初始状态）时不渲染任何依赖其字段的内容 ----
  if (!parent?.id) {
    return (
      <Modal title="新增补充协议" width={1040} centered open={open} onCancel={onClose} footer={null}>
        <Alert
          type="warning"
          showIcon
          message="未选择原合同"
          description="请从「合同查询」列表的操作列点击「新增补充协议」进入。"
        />
      </Modal>
    );
  }

  const isPrice = suppType === 'PRICE_UP' || suppType === 'PRICE_DOWN';
  const isQty = suppType === 'QTY_ADD';
  const isItem = suppType === 'ITEM_ADD';
  const isOther = suppType === 'OTHER';

  /** 只读文本（带出字段），负数红色提示 */
  const readonlyText = (v: string | number): JSX.Element =>
    num(v) < 0 ? <Typography.Text type="danger">{fmt(v)}</Typography.Text> : <span>{fmt(v)}</span>;

  /** 带出行显示只读文本；手动添加行（materialBaseId 为空）允许编辑 */
  const origCell = (
    r: SuppRow,
    key: 'name' | 'spec' | 'unit',
    rows: SuppRow[],
    setter: (v: SuppRow[]) => void,
    i: number,
  ): JSX.Element =>
    r.materialBaseId ? (
      <span>{r[key] || '-'}</span>
    ) : (
      <Input value={r[key]} onChange={(e) => update(rows, setter, i, key, e.target.value)} />
    );

  const priceColumns: ColumnsType<SuppRow> = [
    { title: '序号', width: 50, render: (_, __, i) => i + 1 },
    { title: '物资名称', render: (_, r, i) => origCell(r, 'name', priceRows, setPriceRows, i) },
    { title: '规格型号', render: (_, r, i) => origCell(r, 'spec', priceRows, setPriceRows, i) },
    { title: '计量单位', render: (_, r, i) => origCell(r, 'unit', priceRows, setPriceRows, i) },
    { title: '原合同数量', render: (_, r, i) =>
      r.materialBaseId ? readonlyText(r.origQty)
        : <InputNumber value={r.origQty} onChange={(v) => update(priceRows, setPriceRows, i, 'origQty', num(v))} /> },
    { title: '原合同剩余数量', render: (_, r) => readonlyText(remainOf(r)) },
    { title: '原合同含税单价', render: (_, r, i) =>
      r.materialBaseId ? readonlyText(r.origPrice)
        : <InputNumber value={r.origPrice} onChange={(v) => update(priceRows, setPriceRows, i, 'origPrice', num(v))} /> },
    { title: '原合同金额', render: (_, r) => fmt(num(r.origQty) * num(r.origPrice)) },
    { title: '补充协议含税单价', render: (_, r, i) => <InputNumber value={r.newPrice} onChange={(v) => update(priceRows, setPriceRows, i, 'newPrice', num(v))} /> },
    { title: '价差', render: (_, r) => fmt(num(r.newPrice) - num(r.origPrice)) },
    { title: '新增合同金额', render: (_, r) => fmt(remainForCalc(r) * (num(r.newPrice) - num(r.origPrice))) },
    { title: '备注', render: (_, r, i) => <Input value={r.remark} onChange={(e) => update(priceRows, setPriceRows, i, 'remark', e.target.value)} /> },
  ];

  const qtyColumns: ColumnsType<SuppRow> = [
    { title: '序号', width: 50, render: (_, __, i) => i + 1 },
    { title: '物资名称', render: (_, r, i) => origCell(r, 'name', qtyRows, setQtyRows, i) },
    { title: '规格型号', render: (_, r, i) => origCell(r, 'spec', qtyRows, setQtyRows, i) },
    { title: '计量单位', render: (_, r, i) => origCell(r, 'unit', qtyRows, setQtyRows, i) },
    { title: '原合同含税单价', render: (_, r, i) =>
      r.materialBaseId ? readonlyText(r.origPrice)
        : <InputNumber value={r.origPrice} onChange={(v) => update(qtyRows, setQtyRows, i, 'origPrice', num(v))} /> },
    { title: '原合同数量', render: (_, r, i) =>
      r.materialBaseId ? readonlyText(r.origQty)
        : <InputNumber value={r.origQty} onChange={(v) => update(qtyRows, setQtyRows, i, 'origQty', num(v))} /> },
    { title: '原合同剩余数量', render: (_, r) => readonlyText(remainOf(r)) },
    { title: '暂定新增数量', render: (_, r, i) => <InputNumber value={r.addQty} onChange={(v) => update(qtyRows, setQtyRows, i, 'addQty', num(v))} /> },
    { title: '原合同金额', render: (_, r) => fmt(num(r.origQty) * num(r.origPrice)) },
    { title: '暂定新增金额', render: (_, r) => fmt(num(r.addQty) * num(r.origPrice)) },
    { title: '备注', render: (_, r, i) => <Input value={r.remark} onChange={(e) => update(qtyRows, setQtyRows, i, 'remark', e.target.value)} /> },
  ];

  const itemColumns: ColumnsType<ItemRow> = [
    { title: '序号', width: 50, render: (_, __, i) => i + 1 },
    { title: '物资名称', render: (_, r, i) => <Input value={r.name} onChange={(e) => update(itemNew, setItemNew, i, 'name', e.target.value)} /> },
    { title: '规格型号', render: (_, r, i) => <Input value={r.spec} onChange={(e) => update(itemNew, setItemNew, i, 'spec', e.target.value)} /> },
    { title: '计量单位', render: (_, r, i) => <Input value={r.unit} onChange={(e) => update(itemNew, setItemNew, i, 'unit', e.target.value)} /> },
    { title: '税前单价', render: (_, r, i) => <InputNumber value={r.priceBeforeTax} onChange={(v) => update(itemNew, setItemNew, i, 'priceBeforeTax', num(v))} /> },
    { title: '税率(%)', render: (_, r, i) => <InputNumber value={r.taxRate} onChange={(v) => update(itemNew, setItemNew, i, 'taxRate', num(v))} /> },
    { title: '含税单价', render: (_, r) => fmt(calcPriceWithTax(num(r.priceBeforeTax), num(r.taxRate)) ?? 0) },
    { title: '暂定新增数量', render: (_, r, i) => <InputNumber value={r.addQty} onChange={(v) => update(itemNew, setItemNew, i, 'addQty', num(v))} /> },
    { title: '暂定新增含税金额', render: (_, r) => fmt(calcTotalWithTax(calcPriceWithTax(num(r.priceBeforeTax), num(r.taxRate)), num(r.addQty)) ?? 0) },
    { title: '备注', render: (_, r, i) => <Input value={r.remark} onChange={(e) => update(itemNew, setItemNew, i, 'remark', e.target.value)} /> },
  ];

  const origColumns: ColumnsType<OrigRow> = [
    { title: '序号', width: 50, render: (_, __, i) => i + 1 },
    { title: '物资名称', render: (_, r) => r?.name ?? '' },
    { title: '规格型号', render: (_, r) => r?.spec ?? '' },
    { title: '计量单位', render: (_, r) => r?.unit ?? '' },
    { title: '原合同含税单价', render: (_, r) => fmt(r?.priceWithTax) },
    { title: '原合同数量', render: (_, r) => fmt(r?.qty) },
    { title: '原合同金额', render: (_, r) => fmt(num(r?.totalWithTax)) },
  ];

  const deleteBtn = (rows: SuppRow[], setter: (v: SuppRow[]) => void, i: number): JSX.Element => (
    <Button type="link" danger size="small" icon={<DeleteOutlined />} onClick={() => setter(rows.filter((_, j) => j !== i))} />
  );

  return (
    <Modal
      title={<Space>新增补充协议<DictTag typeCode="supplement_agreement_type" value={suppType} /></Space>}
      width={1160}
      centered
      open={open}
      onCancel={onClose}
      styles={{ body: { maxHeight: 'calc(100vh - 240px)', overflowY: 'auto' } }}
      footer={
        <Space style={{ float: 'right' }}>
          <Button icon={<SaveOutlined />} loading={creating} onClick={handleSave}>保存</Button>
          <Button icon={<EyeOutlined />} loading={previewing} onClick={handlePreview}>预览</Button>
