      {loading ? <Alert type="info" message="加载中…" /> : (
        <Space direction="vertical" size={16} style={{ width: '100%' }}>
          <Card size="small" title="基础信息">
            <Form layout="vertical">
              <Form.Item label="补充协议编号（自动生成）"><Input value={code} disabled /></Form.Item>
              <Form.Item label="原合同（只读）">
                <Input value={`${parent?.code ?? ''} ${parent?.name ?? ''}`.trim()} disabled />
              </Form.Item>
              <Form.Item label="补充协议类型" required>
                <Select<SuppType> value={suppType} onChange={(v) => { setSuppType(v); setSaved(false); }} options={SUPP_TYPES.map((t) => ({ value: t.value, label: t.label }))} />
              </Form.Item>
            </Form>
          </Card>

          {isPrice && (
            <Card
              size="small"
              title={`${suppName(suppType)} · 价格调整明细（清单自动带出，仅可填补充协议含税单价）`}
              extra={priceRows.length === 0 && (
                <Button size="small" icon={<PlusOutlined />} onClick={() => setPriceRows([...priceRows, blankSupp()])}>手动加一行</Button>
              )}
            >
              {priceRows.length === 0 && (
                <Alert type="info" showIcon style={{ marginBottom: 8 }} message="原合同暂无合同清单，可手动添加物资行" />
              )}
              <Table<SuppRow> size="small" rowKey={(_, i) => String(i ?? 0)} dataSource={priceRows} pagination={false}
                scroll={{ x: 1560 }}
                columns={[...priceColumns, { title: '操作', width: 60, fixed: 'right', render: (_, __, i) => deleteBtn(priceRows, setPriceRows, i) }]} />
            </Card>
          )}

          {isQty && (
            <Card
              size="small"
              title="增量补充协议 · 数量增加明细（清单自动带出，仅可填暂定新增数量）"
              extra={qtyRows.length === 0 && (
                <Button size="small" icon={<PlusOutlined />} onClick={() => setQtyRows([...qtyRows, blankSupp()])}>手动加一行</Button>
              )}
            >
              {qtyRows.length === 0 && (
                <Alert type="info" showIcon style={{ marginBottom: 8 }} message="原合同暂无合同清单，可手动添加物资行" />
              )}
              <Table<SuppRow> size="small" rowKey={(_, i) => String(i ?? 0)} dataSource={qtyRows} pagination={false}
                scroll={{ x: 1500 }}
                columns={[...qtyColumns, { title: '操作', width: 60, fixed: 'right', render: (_, __, i) => deleteBtn(qtyRows, setQtyRows, i) }]} />
            </Card>
          )}

          {isItem && (
            <>
              <Card size="small" title="原合同清单（自动导入，只读）">
                <Table<OrigRow> size="small" rowKey={(_, i) => String(i ?? 0)} dataSource={itemOrig} pagination={false} scroll={{ x: 900 }} columns={origColumns} />
              </Card>
              <Card size="small" title="新增合同清单（增项）" extra={<Button size="small" icon={<PlusOutlined />} onClick={() => setItemNew([...itemNew, blankItem()])}>加一行</Button>}>
                <Table<ItemRow> size="small" rowKey={(_, i) => String(i ?? 0)} dataSource={itemNew} pagination={false} scroll={{ x: 1200 }}
                  columns={[...itemColumns, { title: '操作', width: 60, fixed: 'right', render: (_, __, i) => <Button type="link" danger size="small" icon={<DeleteOutlined />} onClick={() => setItemNew(itemNew.filter((_, j) => j !== i))} /> }]} />
              </Card>
            </>
          )}

          {isOther && (
            <Card size="small" title="其他类补充协议 · 正文（富文本，支持文字 / 图片 / 表格）">
              <RichTextEditor value={otherHtml} onChange={setOtherHtml} minHeight={360} placeholder="请输入补充协议正文，可插入图片与表格" />
            </Card>
          )}

          {isPrice && (
            <Alert
              type="info"
              showIcon
              message="计算规则：原合同剩余数量 = 原合同数量 − 日报已发生数量（结算数量合计）；剩余数量允许为负数显示，但计算新增合同金额时按 0 处理"
            />
          )}

          <Alert type="info" showIcon message={saved ? '已保存，可预览或发布' : '填写完成后请先「保存」，再「预览 / 发布」'} />
        </Space>
      )}

      <Modal title="补充协议预览" open={previewOpen} onCancel={() => setPreviewOpen(false)} width={900} footer={null} destroyOnHidden>
        <div style={{ maxHeight: 560, overflow: 'auto', border: '1px solid var(--cms-hairline-soft)', padding: 16, background: 'var(--cms-paper)' }} dangerouslySetInnerHTML={{ __html: sanitizeHtml(previewHtml) }} />
      </Modal>
    </Modal>
  );
}

import { Suspense, useEffect, useMemo, useRef, useState, type ReactElement } from 'react';
import { Layout, Dropdown, Space, Badge, Button, Avatar, Spin, Tooltip, Typography } from 'antd';
import {
  MenuFoldOutlined,
  MenuUnfoldOutlined,
  BellOutlined,
  UserOutlined,
  LogoutOutlined,
} from '@ant-design/icons';
import { Outlet, useLocation, useNavigate, useOutlet } from 'react-router-dom';
import { useAuthStore } from '@/store/auth';
import ProjectSwitch from '@/components/ProjectSwitch';
import AppSider, { BreadcrumbNav } from '@/components/Sider';
import { STORAGE_KEYS, readLocal } from '@/components/Sider/utils/storage';
import { useMenuData } from '@/components/Sider/hooks/useMenuData';
import { findMenuChain } from '@/components/Sider/utils/menuHelper';
import { useResponsive } from '@/hooks/useResponsive';
import { notificationApi } from '@/api/modules';
import { useTabsStore } from '@/store/tabs';
import { cacheKeyOf, editorIdOf, tabKeyOf, HOME_TAB_KEY } from '@/utils/tabs';
import { TabScopeProvider, type TabScope } from './tabScope';
import TagsView from './TagsView';

const { Header, Content } = Layout;

/** 标签被激活时重测量的兜底：等一帧再派发，元素从 display:none 切回来后才测得到尺寸 */
function useRemindChartsOnActivate(activeToken: number) {
  useEffect(() => {
    if (!activeToken) return;
    const id = window.requestAnimationFrame(() => window.dispatchEvent(new Event('resize')));
    return () => window.cancelAnimationFrame(id);
  }, [activeToken]);
}

/**
 * 主布局（DESIGN.md §10.1：布局层响应式）
 *
 * - 左侧导航：`AppSider`——≥768px 固定侧栏，<768px 自动改为覆盖式抽屉
 * - 折叠状态：桌面端沿用本地持久化值；进入手机宽度自动收起（抽屉默认关闭），
 *   回到桌面时恢复进入前的桌面偏好
 * - 内容区：**多页签导航条 + 面包屑 + 路由出口**；窄屏边距 16 → 8
 * - Header：保留项目切换 / 消息提醒 / 用户菜单，窄屏精简（项目切换限宽、隐藏用户名文字）
 *
 * ## 多页签的页面状态缓存（keep-alive）
 *
 * React Router 6 **没有** keep-alive，这里用 `useOutlet()` + 元素缓存在布局层自建：
 *
 * 1. 当前路由的元素（`useOutlet()`）在**渲染期**写入 `Map<标签键, ReactElement>`；
 * 2. 按**标签顺序**渲染全部已缓存元素，非活动的包一层 `display: none`——
 *    React 按 keyed 位置复用 fiber，于是组件实例与 state（筛选条件、表格、图表、表单草稿）都留着；
 * 3. 缓存项的 `key` 是 `标签键#version`：**右键"刷新"递增 version 就相当于重挂载**（重新取数）；
 * 4. 每个缓存项外面包一层 `TabScopeProvider`，让页面知道自己属于**哪个**标签——
 *    被缓存的列表标签与编辑器标签会同时在 DOM 上，靠 URL 判断形态会把列表也变成编辑器
 *    （见 `tabScope.ts` 的注释）。
 *
 * ⚠️ 页面被藏起来时容器宽度是 0，`useContainerWidth()` 会把它当"未测量 → 按宽处理"，
 * 重新显示时 `ResizeObserver` 会再报一次真实宽度；ECharts 与 rc-table 靠本组件激活时
 * 派发的一次 `resize` 兜底（`useRemindChartsOnActivate`）。**改动这里务必真渲染核验**
 * 「台账大宽表 / 工作台两张图」隐藏再显示后的渲染。
 *
 * 断点唯一来源：`@/hooks/useResponsive`（勿用 window.innerWidth）。
 */
export default function BasicLayout() {
  const { isMobile } = useResponsive();
  // 初始值取侧栏持久化偏好（此前固定 false，使 Sider 的 localStorage 持久化形同虚设）
  const [collapsed, setCollapsed] = useState<boolean>(() => readLocal<boolean>(STORAGE_KEYS.collapsed, false));
  /** 进入手机宽度前的桌面折叠偏好，供回到桌面时恢复 */
  const desktopCollapsedRef = useRef(collapsed);
  const [unread, setUnread] = useState(0);
  const navigate = useNavigate();
  const location = useLocation();
  const { user, logout } = useAuthStore();
  const { menu } = useMenuData();

  const tabs = useTabsStore((s) => s.tabs);
  const activeToken = useTabsStore((s) => s.activeToken);
  const syncRoute = useTabsStore((s) => s.syncRoute);

  /* ---------------- 多页签：登记 + 缓存 ---------------- */

  const tabKey = tabKeyOf(location.pathname, location.search);
  const editorId = editorIdOf(tabKey);
  /** 菜单里能找到的才建标签 —— 旧扁平路径的 `<Navigate>` 与未知路径自然被排除 */
  const menuChain = useMemo(() => findMenuChain(menu, location.pathname), [menu, location.pathname]);
  const menuLabel = menuChain?.slice(-1)[0]?.label ?? '';
  /** 标签图标 = 菜单项的 icon 名（TagsView 仅激活态渲染） */
  const menuIcon = menuChain?.slice(-1)[0]?.icon as string | undefined;

  useEffect(() => {
    if (!menuLabel) return; // 菜单尚未加载完；加载完会再跑一次
    syncRoute({
      key: tabKey,
      path: location.pathname,
      href: tabKey,
      title: editorId ? `${menuLabel} · ${editorId === 'new' ? '新增' : '编辑'}` : menuLabel,
      icon: editorId ? undefined : menuIcon,
      closable: tabKey !== HOME_TAB_KEY,
    });
  }, [tabKey, menuLabel, menuIcon, editorId, location.pathname, syncRoute]);

  const outlet = useOutlet();
  /** 标签键 → 该标签对应的路由元素。渲染期写入是幂等的（同一路由永远是同一元素） */
  const cacheRef = useRef<Map<string, ReactElement>>(new Map());
  if (outlet && menuLabel) cacheRef.current.set(tabKey, outlet);

  // 标签被关掉/淘汰后同步释放缓存，避免长期使用后 Map 无限增长
  useEffect(() => {
    const alive = new Set(tabs.map((t) => t.key));
    for (const key of [...cacheRef.current.keys()]) {
      if (!alive.has(key)) cacheRef.current.delete(key);
    }
  }, [tabs]);

  /** 每个标签的作用域（缓存键 → scope）；`key` 上用缓存键，故刷新标签会连带重建 scope */
  const scopes = useMemo(() => {
    const map: Record<string, TabScope> = {};
    for (const t of tabs) {
      map[cacheKeyOf(t)] = { tabKey: t.key, path: t.path, href: t.href, editorId: editorIdOf(t.key) };
    }
    return map;
  }, [tabs]);

  useRemindChartsOnActivate(activeToken);

  useEffect(() => {
    notificationApi.unreadCount().then((res: any) => setUnread(res?.count || 0)).catch(() => undefined);
  }, [location.pathname]);

  // 断点变化时调整侧栏：手机 → 收起（抽屉关闭）；桌面 → 恢复进入前的偏好
  useEffect(() => {
    if (isMobile) {
      desktopCollapsedRef.current = collapsed;
      setCollapsed(true);
    } else {
      setCollapsed(desktopCollapsedRef.current);
    }
    // 仅在断点变化时执行；collapsed 故意不入依赖，避免用户手动折叠时被覆盖
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isMobile]);

  /**
   * 渲染一个「标签面板」。抽成函数是为了让「标签项」与「无标签兜底」两支产出**结构完全一致**的
   * 元素 —— 结构一致时，标签真正建出来的那一刻 React 才会复用同一个 fiber（不重挂载、不丢状态）。
   */
  const renderPane = (cacheKey: string, scope: TabScope, element: ReactElement, active: boolean) => (
    <TabScopeProvider key={cacheKey} value={scope}>
      <div className="cms-tab-pane" style={active ? undefined : { display: 'none' }}>
        {/* 每个标签自己的 Suspense：某个标签在加载分包时不会把别的标签一起清空 */}
        <Suspense fallback={<Spin size="large" style={{ display: 'block', margin: '80px auto' }} />}>
          {element}
        </Suspense>
      </div>
    </TabScopeProvider>
  );

  return (
    <Layout style={{ minHeight: '100vh' }}>
      {/* 左侧导航：窄屏自动切换为抽屉式（内部由 useResponsive 决定） */}
      <AppSider collapsed={collapsed} onCollapsedChange={setCollapsed} />
      <Layout>
        <Header
          className="cms-header"
          style={{
            padding: isMobile ? '0 8px' : '0 16px',
            // 深墨面：与侧栏同族，内容区奶油底——页面骨架即设计文档的「深墨 ↔ 奶油」节奏
            background: 'var(--cms-surface-dark)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
          }}
        >
          <Space size={isMobile ? 4 : 8}>
            <Button
              type="text"
              aria-label={collapsed ? '展开菜单' : '收起菜单'}
              icon={collapsed ? <MenuUnfoldOutlined /> : <MenuFoldOutlined />}
              onClick={() => setCollapsed(!collapsed)}
            />
            <ProjectSwitch />
          </Space>
          <Space size={isMobile ? 8 : 16}>
            {/* ⚠️ Tooltip 必须放在 **Badge/Dropdown 的内侧**：这两者都会 clone 自己的 child 挂事件，
                若把它们套在 Tooltip 外面，事件会挂在 Tooltip 上而不落到按钮，点击将静默失效。 */}
            <Badge count={unread}>
              <Tooltip title="消息中心">
                <Button type="text" aria-label="消息中心" icon={<BellOutlined />} onClick={() => navigate('/message')} />
              </Tooltip>
            </Badge>
            <Dropdown
              menu={{
                items: [
                  { key: 'profile', icon: <UserOutlined />, label: user?.realName || user?.username },
                  { type: 'divider' },
                  { key: 'logout', icon: <LogoutOutlined />, label: '退出登录' },
                ],
                onClick: ({ key }) => {
                  if (key === 'logout') {
                    // 标签属于"上一个账号"，先清掉再登出（顺手清掉其 localStorage）
                    useTabsStore.getState().reset();
                    logout();
                    navigate('/login');
                  }
                },
              }}
            >
              <Space style={{ cursor: 'pointer' }}>
                <Tooltip title={user?.realName || '账号'}>
                  <Avatar style={{ backgroundColor: 'var(--cms-primary)', color: 'var(--cms-on-primary)' }}>
                    {user?.realName?.[0] || 'U'}
                  </Avatar>
                </Tooltip>
                {/* 窄屏只留头像，名字放进下拉菜单（Header 精简，DESIGN.md §10.1） */}
                {!isMobile && <Typography.Text>{user?.realName}</Typography.Text>}
              </Space>
            </Dropdown>
          </Space>
        </Header>
        {/* 多页签通栏工具条（对标 XHan Admin：顶栏正下方、面包屑之上、全宽）——
            位置与样式口径见 DESIGN.md §10.1；sticky 使滚动时钉在顶栏下 */}
        <TagsView />
        <Content style={{ margin: isMobile ? 8 : 16 }}>
          <BreadcrumbNav />
          {tabs.map((t) => {
            const element = cacheRef.current.get(t.key);
            // 恢复自 localStorage 的标签**不预挂载**：只挂活动页，其余点开时才建实例。
            // 否则会在 0×0 的容器里初始化 ECharts / rc-table，量到的宽高全是 0。
            if (!element) return null;
            const cacheKey = cacheKeyOf(t);
            return renderPane(cacheKey, scopes[cacheKey], element, t.key === tabKey);
          })}

          {/*
            当前路由**没有对应标签**时的兜底渲染。
            两条真实场景：
            ① 旧扁平路径（`/ledger`、`/projects`…）——它们在路由表里是 `<Navigate>` 重定向，
               不建标签；**不渲染就等于重定向不执行**，内容区会空着（2026-10-17 实测踩到）；
            ② 菜单还没加载完（冷启动）——此时 `menuLabel` 为空、标签尚未创建，先把页面显示出来。
            ⚠️ 这一支与上面的标签项用的是**同一个缓存键与同一层结构**（见 renderPane），
            所以菜单加载完、标签真正建出来时，React 会复用同一个 fiber，**不会重挂载**。
          */}
          {outlet && !tabs.some((t) => t.key === tabKey) &&
            renderPane(`${tabKey}#0`, { tabKey, path: location.pathname, href: tabKey, editorId }, outlet, true)}
        </Content>
      </Layout>
    </Layout>
  );
}

import { useMemo } from 'react';
import { Dropdown, Modal } from 'antd';
import { CloseOutlined, EditOutlined, MenuOutlined } from '@ant-design/icons';
import { useNavigate } from 'react-router-dom';
import { useTabsStore } from '@/store/tabs';
import { isEditorKey } from '@/utils/tabs';
import { useResponsive } from '@/hooks/useResponsive';
import { renderIcon } from '@/components/Sider/utils/iconHelper';

/**
 * 多页签导航条（主内容区顶部、顶栏与内容区之间）。
 *
 * 分工：**本组件只管"展示 + 交互"**，标签的增删改查全在 `@/store/tabs`（纯逻辑在 `@/utils/tabs`），
 * 页面实例的缓存与挂载在 `BasicLayout`（那里的 `useOutlet()` 才是缓存的数据来源）。
 *
 * 关于响应式：标签栏是**页面外壳**的一部分（它的容器就是视口），故按 DESIGN.md §10.1
 * 用 `useResponsive()`；组件内部的宽度收敛（标签变窄、横向滚动）用纯 CSS。
 *
 * ⚠️ 已知限制（有意接受，不额外处理）：
 * - AntD `Modal` 默认带全屏遮罩 → 打开弹窗时点不到标签栏，"隐藏页面的弹窗滞留"场景不成立；
 * - `Popconfirm` / `Dropdown` 等浮层在切页前会因失焦自行关闭；
 * - `RichTextEditor` 的全屏层已 portal 到 `body`（`containerQuery.spec.mts` 有锁），全屏时同样遮住标签栏。
 */
export default function TagsView() {
  const navigate = useNavigate();
  const { isMobile } = useResponsive();
  const tabs = useTabsStore((s) => s.tabs);
  const activeKey = useTabsStore((s) => s.activeKey);
  const closeTab = useTabsStore((s) => s.closeTab);
  const closeOthers = useTabsStore((s) => s.closeOthers);
  const closeAll = useTabsStore((s) => s.closeAll);
  const closeSide = useTabsStore((s) => s.closeSide);
  const refresh = useTabsStore((s) => s.refresh);
  const dirtyKeys = useTabsStore((s) => s.dirtyKeys);

  const index = useMemo(() => tabs.findIndex((t) => t.key === activeKey), [tabs, activeKey]);
  const closableCount = useMemo(() => tabs.filter((t) => t.closable).length, [tabs]);

  /** 关闭后落到 `activate` 指定的标签；为 null 表示当前标签没被关掉 */
  const go = (activate: string | null) => {
    if (activate) navigate(activate);
  };

  /** 关闭前拦一下：有未保存内容的标签必须先确认（脏状态由编辑器页上报） */
  const requestClose = (key: string, run: () => void) => {
    if (!dirtyKeys.includes(key)) {
      run();
      return;
    }
    Modal.confirm({
      title: '该页有未保存的内容',
      content: '关闭后未保存的内容将丢失，确定关闭吗？',
      okText: '仍然关闭',
      okType: 'danger',
      cancelText: '返回',
      onOk: run,
    });
  };

  // 关闭类操作可能一次关掉多个脏标签；只要其中任何一个脏就统一确认一次
  const requestBatchClose = (scopeKeys: string[], run: () => void) => {
    const hit = scopeKeys.filter((k) => dirtyKeys.includes(k));
    if (!hit.length) {
      run();
      return;
    }
    Modal.confirm({
      title: `有 ${hit.length} 个标签存在未保存的内容`,
      content: '关闭后这些标签里未保存的内容将丢失，确定继续吗？',
      okText: '仍然关闭',
      okType: 'danger',
      cancelText: '返回',
      onOk: run,
    });
  };

  const contextItems = (key: string) => {
    const i = tabs.findIndex((t) => t.key === key);
    return [
      { key: 'refresh', label: '刷新当前页' },
      { type: 'divider' as const },
      { key: 'others', label: '关闭其他标签', disabled: closableCount === 0 },
      { key: 'left', label: '关闭左侧标签', disabled: !tabs.slice(0, i).some((t) => t.closable) },
      { key: 'right', label: '关闭右侧标签', disabled: !tabs.slice(i + 1).some((t) => t.closable) },
      { key: 'all', label: '关闭全部标签', disabled: closableCount === 0 },
    ];
  };

  const onContextClick = (key: string, action: string) => {
    if (action === 'refresh') {
      // 递增 version → 缓存键变化 → 该标签内的页面重挂载并重新取数。
      // 脏标签必须先确认：重挂载等于把未保存的编辑直接扔掉（第 17~20 轮审计）。
      if (!dirtyKeys.includes(key)) {
        refresh(key);
        return;
      }
      Modal.confirm({
        title: '该页有未保存的内容',
        content: '刷新会重新加载页面，未保存的内容将丢失，确定刷新吗？',
        okText: '仍然刷新',
        okType: 'danger',
        cancelText: '取消',
        onOk: () => refresh(key),
      });
      return;
    }
    if (action === 'others') {
      requestBatchClose(tabs.filter((t) => t.closable && t.key !== key).map((t) => t.key), () => go(closeOthers(key)));
      return;
    }
    if (action === 'all') {
      requestBatchClose(tabs.filter((t) => t.closable).map((t) => t.key), () => go(closeAll()));
      return;
    }
    const i = tabs.findIndex((t) => t.key === key);
    const scope = action === 'left' ? tabs.slice(0, i) : tabs.slice(i + 1);
    requestBatchClose(scope.filter((t) => t.closable).map((t) => t.key), () =>
      go(closeSide(key, action === 'left' ? 'left' : 'right')),
    );
  };

  /** 单个标签：桌面平铺与手机端（只渲染当前一个）共用同一份渲染逻辑 */
  const renderTab = (t: (typeof tabs)[number]) => {
    const active = t.key === activeKey;
    const dirty = dirtyKeys.includes(t.key);
    const editor = isEditorKey(t.key);
    return (
      <Dropdown
        key={t.key}
        trigger={['contextMenu']}
        menu={{
          items: contextItems(t.key),
          onClick: ({ key: action }) => onContextClick(t.key, action),
        }}
      >
        <div
          role="tab"
          aria-selected={active}
          className={`cms-tags-view__item${active ? ' is-active' : ''}${dirty ? ' is-dirty' : ''}${
            editor ? ' is-editor' : ''
          }`}
          onClick={() => {
            if (!active) navigate(t.href);
          }}
        >
          {/* 图标仅激活态显示（一排小图标过吵；参考图 3 也是仅激活标签带图标） */}
          {active && (
            <span className="cms-tags-view__icon">
              {editor ? <EditOutlined /> : t.icon ? renderIcon(t.icon) : null}
            </span>
          )}
          <span className="cms-tags-view__label" title={t.title}>
            {t.title}
          </span>
          {t.closable && (
            <button
              type="button"
              className="cms-tags-view__close"
              aria-label={`关闭 ${t.title}`}
              onClick={(e) => {
                e.stopPropagation();
                requestClose(t.key, () => go(closeTab(t.key)));
              }}
            >
              <CloseOutlined />
            </button>
          )}
        </div>
      </Dropdown>
    );
  };

  /**
   * 手机端：只显示**当前标签** + 一个下拉（切换 / 批量关闭）。
   * 平铺在 375px 下必然横向滚动（实测要滑 0.6k px 才能点到当前页签的关闭按钮），
   * 且与抽屉导航功能重复。当前标签始终可见后，"关掉当前页"不再需要先找它。
   * 下拉里的批量关闭复用桌面右键菜单的确认逻辑（脏标签照样先确认）。
   */
  if (isMobile) {
    const activeTab = tabs.find((t) => t.key === activeKey);
    const others = tabs.filter((t) => t.key !== activeKey);
    // 刷新也在下拉里：触摸屏上的长按右键菜单不可发现，桌面能做的事手机不能缺
    const mobileItems: any[] = [
      { key: 'refresh', label: '刷新当前页', disabled: !activeTab },
      { type: 'divider' as const },
      ...others.map((t) => ({
        key: `switch:${t.key}`,
        label: `${t.title}${dirtyKeys.includes(t.key) ? ' •' : ''}`,
      })),
      ...(others.length ? [{ type: 'divider' as const }] : []),
      // 没有可关闭的标签、或 activeKey 尚未登记（路由切换的首帧）时置灰，
      // 避免出现「菜单项可点、点了什么都不发生」
      { key: 'others', label: '关闭其他标签', disabled: closableCount === 0 || !activeTab },
      { key: 'all', label: '关闭全部标签', disabled: closableCount === 0 || !activeTab },
    ];
    return (
      <div className="cms-tags-view is-compact is-mobile" role="tablist" aria-label="已打开的页面">
        {activeTab && renderTab(activeTab)}
        <Dropdown
          trigger={['click']}
          menu={{
            items: mobileItems,
            onClick: ({ key }) => {
              if (key.startsWith('switch:')) {
                const target = tabs.find((t) => t.key === key.slice('switch:'.length));
                if (target && target.key !== activeKey) navigate(target.href);
                return;
              }
              if (activeTab) onContextClick(activeTab.key, key);
            },
          }}
        >
          <button type="button" className="cms-tags-view__mobile-more" aria-label="切换或关闭页签">
            <MenuOutlined />
            <span>{tabs.length}</span>
          </button>
        </Dropdown>
      </div>
    );
  }

  return (
    <div className="cms-tags-view" role="tablist" aria-label="已打开的页面">
      {tabs.map(renderTab)}
    </div>
  );
}

import { Fragment, useState, type ReactNode } from 'react';
import {
  Alert,
  Button,
  Card,
  Collapse,
  DatePicker,
  Empty,
  Form,
  Input,
  Segmented,
  Space,
  Spin,
  Tag,
  Typography,
  message,
} from 'antd';
import { DownloadOutlined, FilePdfOutlined, FileTextOutlined, ThunderboltOutlined } from '@ant-design/icons';
import dayjs, { type Dayjs } from 'dayjs';
import { aiApi, type AiReportDelta, type AiReportResult } from '@/api/modules';
import ReportMarkdown from '@/components/ReportMarkdown';
import { MIME_DOCX, MIME_PDF, downloadBlob, fileNameFromDisposition } from '@/utils/reportExport';

const { Text, Paragraph, Title } = Typography;

/** 环比文案：上期为 0 时后端给的是 null，这里如实写「上期为 0」，不编百分比 */
function pctText(d: AiReportDelta): string {
  return d.pct === null
    ? `上期为 0（本期 ${d.now}）`
    : `${d.pct > 0 ? '+' : ''}${d.pct.toFixed(2)}%（上期 ${d.prev} → 本期 ${d.now}）`;
}

const { RangePicker } = DatePicker;
const { TextArea } = Input;

type ReportKind = 'monthly' | 'project' | 'brief';

const KIND_OPTIONS: { label: string; value: ReportKind }[] = [
  { label: '月度经营汇报', value: 'monthly' },
  { label: '项目履约汇报', value: 'project' },
  { label: '领导汇报摘要', value: 'brief' },
];

/**
 * AI 助手 · 汇报材料（三期）。
 *
 * 分工：**程序给事实、模型给文字**。页面上的数字全部来自后端聚合的事实清单，
 * 生成后会把材料里对不上的数字单独列出来（`unknownNumbers`）——
 * 汇报材料是给领导看的，编一个数字比写得平淡严重得多，所以宁可把风险摆到明面上。
 */
export default function AiReportPanel() {
  const [kind, setKind] = useState<ReportKind>('monthly');
  const [range, setRange] = useState<[Dayjs, Dayjs]>([dayjs().startOf('month'), dayjs()]);
  const [extra, setExtra] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<AiReportResult | null>(null);
  const [exporting, setExporting] = useState<'docx' | 'pdf' | null>(null);
  const [header, setHeader] = useState('');
  const [footer, setFooter] = useState('');

  const generate = async () => {
    setLoading(true);
    try {
      const res = await aiApi.reportGenerate({
        kind,
        from: range?.[0]?.format('YYYY-MM-DD'),
        to: range?.[1]?.format('YYYY-MM-DD'),
        extra: extra.trim() || undefined,
      });
      setResult(res);
      if (res.unknownNumbers.length) message.warning('材料里有数字未在系统数据中找到，请复核');
      else message.success('已生成，请核对后导出');
    } catch {
      // 拦截器已弹错
    } finally {
      setLoading(false);
    }
  };

  const exportFile = async (format: 'docx' | 'pdf') => {
    if (!result) return;
    setExporting(format);
    try {
      const res = await aiApi.reportExport({
        markdown: result.markdown,
        title: `${result.facts.project.name}${result.label}`,
        header: header.trim() || undefined,
        footer: footer.trim() || undefined,
        format,
      });
      const blob = new Blob([res.data], { type: format === 'pdf' ? MIME_PDF : MIME_DOCX });
      downloadBlob(blob, fileNameFromDisposition(res.headers, `汇报材料.${format}`));
    } catch {
      // 拦截器已弹错
    } finally {
      setExporting(null);
    }
  };

  return (
    <Card
      title={
        <Space>
          <FileTextOutlined />
          <span>AI 助手 · 汇报材料</span>
          {result ? <Tag color="green">{result.label}</Tag> : null}
        </Space>
      }
      extra={
        <Space>
          <Button icon={<DownloadOutlined />} loading={exporting === 'docx'} disabled={!result} onClick={() => exportFile('docx')}>
            导出 Word
          </Button>
          <Button icon={<FilePdfOutlined />} loading={exporting === 'pdf'} disabled={!result} onClick={() => exportFile('pdf')}>
            导出 PDF
          </Button>
        </Space>
      }
    >
      <Alert
        type="info"
        showIcon
        style={{ marginBottom: 12 }}
        message="用系统里的真实数据生成汇报材料：数字由程序汇总，AI 只负责组织语言"
        description="生成后请核对；材料里出现但系统数据对不上的数字会被单独列出来提示你。"
      />

      <Form layout="vertical">
        <Space wrap size={16} align="end" style={{ width: '100%' }}>
          <Form.Item label="材料类型" style={{ marginBottom: 8 }}>
            <Segmented
              options={KIND_OPTIONS}
              value={kind}
              onChange={(v) => setKind(v as ReportKind)}
            />
          </Form.Item>
          <Form.Item label="统计区间" style={{ marginBottom: 8 }}>
            <RangePicker
              value={range}
              allowClear={false}
              onChange={(v) => v && v[0] && v[1] && setRange([v[0], v[1]])}
            />
          </Form.Item>
          <Form.Item style={{ marginBottom: 8 }}>
            <Button type="primary" icon={<ThunderboltOutlined />} loading={loading} onClick={generate}>
              生成材料
            </Button>
          </Form.Item>
        </Space>
        <Space wrap size={16} align="end" style={{ width: '100%' }}>
          <Form.Item label="页眉（留空用标题）" style={{ marginBottom: 8 }}>
            <Input value={header} onChange={(e) => setHeader(e.target.value)} placeholder="例如：XX 项目月度情况报告" style={{ width: 260 }} />
          </Form.Item>
          <Form.Item label="页脚（留空用默认说明）" style={{ marginBottom: 8 }}>
            <Input value={footer} onChange={(e) => setFooter(e.target.value)} placeholder="例如：工程管理部　2026 年 10 月" style={{ width: 260 }} />
          </Form.Item>
        </Space>
        <Form.Item label="补充要求（可选）" style={{ marginBottom: 8 }}>
          <TextArea
            rows={2}
            value={extra}
            maxLength={200}
            placeholder="例如：重点写付款风险；面向集团领导，控制在一页以内"
            onChange={(e) => setExtra(e.target.value)}
          />
        </Form.Item>
      </Form>

      {loading && (
        <div style={{ padding: 32, textAlign: 'center' }}>
          <Spin tip="正在汇总数据并生成材料…" size="large">
            <div style={{ height: 48 }} />
          </Spin>
        </div>
      )}

      {!loading && result && (
        <>
          {result.warnings.length > 0 && (
            <Alert
              type="warning"
              showIcon
              style={{ marginBottom: 12 }}
              message="数据侧提醒"
              description={
                <ul style={{ margin: 0, paddingLeft: 18 }}>
                  {result.warnings.map((w) => (
                    <li key={w}>{w}</li>
                  ))}
                </ul>
              }
            />
          )}

          {result.unknownNumbers.length > 0 && (
            <Alert
              type="error"
              showIcon
              style={{ marginBottom: 12 }}
              message="以下数字未在系统数据中找到，请核对后再使用"
              description={result.unknownNumbers.join('、')}
            />
          )}

          <div
            style={{
              border: '1px solid var(--cms-hairline)',
              borderRadius: 8,
              padding: 16,
              background: 'var(--cms-canvas)',
              maxHeight: 620,
              overflow: 'auto',
            }}
          >
            <ReportMarkdown text={result.markdown} />
          </div>

          {result.missingSections.length > 0 && (
            <Alert
              type="warning"
              showIcon
              style={{ marginBottom: 12 }}
              message="材料缺少以下小节（模板骨架与 prompt 一致，模型偶尔会漏）"
              description={result.missingSections.join('、')}
            />
          )}

          <Collapse
            style={{ marginTop: 12 }}
            items={[
              {
                key: 'facts',
                label: '数据来源（事实清单，材料里的数字都来自这里）',
                children: (
                  <Paragraph style={{ whiteSpace: 'pre-wrap', marginBottom: 0 }} type="secondary">
                    {[
                      `公文骨架：${result.sections.join(' / ')}`,
                      `本期区间：${result.period.label}`,
                      `对比区间：${result.comparePeriod.label}`,
                      `项目累计：合同 ${result.facts.totals.contracts} 份（执行中 ${result.facts.totals.executing}），累计金额 ${result.facts.totals.contractAmount} 元，累计结算 ${result.facts.totals.settlementAmount} 元，累计付款 ${result.facts.totals.paymentAmount} 元，累计开票 ${result.facts.totals.invoiceAmount} 元，应付未付 ${result.facts.totals.unpaid} 元`,
                      `本期发生额：新签 ${result.facts.current.contractsSigned} 份 / ${result.facts.current.contractsSignedAmount} 元，结算 ${result.facts.current.settlementAmount} 元，付款 ${result.facts.current.paymentAmount} 元，开票 ${result.facts.current.invoiceAmount} 元，日报 ${result.facts.current.dailyReports} 条`,
                      `环比（上期 ${result.facts.compare.period.label}）：新签金额 ${pctText(result.facts.deltas.contractsSignedAmount)}，结算金额 ${pctText(result.facts.deltas.settlementAmount)}，付款金额 ${pctText(result.facts.deltas.paymentAmount)}，日报 ${pctText(result.facts.deltas.dailyReports)}`,
                      `系统识别风险：${result.facts.risks.length ? result.facts.risks.join('；') : '无'}`,
                    ].join('\n')}
                  </Paragraph>
                ),
              },
            ]}
          />
        </>
      )}

      {!loading && !result && (
        <Empty description="还没有生成材料：选好类型与区间后点「生成材料」" style={{ marginTop: 32 }} />
      )}

      <Paragraph type="secondary" style={{ marginTop: 12, marginBottom: 0 }}>
        <Text type="secondary">
          口径：合同金额按合同链（主合同 + 补充协议）累计；结算排除草稿；付款排除失败/退款；
          应付未付 = 累计结算 − 累计付款（可为负，负值说明付超了）。
        </Text>
      </Paragraph>
    </Card>
  );
}

import { useEffect, useState } from 'react';
import { Card, Table, Button, Space, Spin, Tree } from 'antd';
import { DownloadOutlined } from '@ant-design/icons';
import { withToken } from '../utils/download';
import { archiveApi } from '@/api/modules';

/**
 * 项目资料归档（附件需求 2026-10-17）：按需求目录树一键打包 ZIP 或按目录下载。
 *
 * 目录结构 = 业务确认的 13 类（`server/src/constants/archiveCategories.ts` 的镜像）；
 * 文件数来自 `GET /archive/entries`；空目录在 ZIP 里有 `_说明.txt` 占位（目录看得见）。
 * 命名口径：真实附件按业务字段重命名、图片转单页 PDF、台账 Excel 实时导出（见 archive-naming.ts）。
 */
export default function Archive() {
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [detailKey, setDetailKey] = useState<string | null>(null);
  const [detail, setDetail] = useState<any[] | null>(null);
  const [detailLoading, setDetailLoading] = useState(false);

  const load = () => {
    setLoading(true);
    archiveApi
      .entries()
      .then((res: any) => setData(res))
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    load();
  }, []);

  const groups: any[] = data?.groups ?? [];

  const treeData = groups.map((g) => ({
    key: g.key,
    title: (
      <Space size={8}>
        <span>{g.dir}</span>
        <span className="cms-hint">{g.count} 个文件</span>
      </Space>
    ),
    children: [
      {
        key: `${g.key}::items`,
        title: (
          <Space size={8} wrap>
            <Button
              size="small"
              type="link"
              icon={<DownloadOutlined />}
              style={{ padding: 0 }}
              onClick={(e: any) => {
                e?.stopPropagation?.();
                window.open(withToken(archiveApi.downloadUrl(g.key)));
              }}
            >
              下载本目录（ZIP）
            </Button>
            <Button
              size="small"
              type="link"
              style={{ padding: 0 }}
              onClick={(e: any) => {
                e?.stopPropagation?.();
                setDetailKey(g.key);
                setDetailLoading(true);
                // entries 已带明细（items）；直接取
                const hit = groups.find((x) => x.key === g.key);
                setDetail(hit?.items ?? []);
                setDetailLoading(false);
              }}
            >
              查看文件清单
            </Button>
            {g.count === 0 && (
              <span className="cms-hint">该目录由「{g.sourceModule}」提供数据，当前暂无文件</span>
            )}
          </Space>
        ),
        selectable: false,
      },
    ],
  }));

  const detailItems = detailKey ? (groups.find((g) => g.key === detailKey)?.items ?? []) : null;

  return (
    <Card
      title="项目资料归档"
      extra={
        <Button
          type="primary"
          icon={<DownloadOutlined />}
          loading={loading}
          onClick={() => window.open(withToken(archiveApi.downloadUrl('all')))}
        >
          一键下载全部（ZIP）
        </Button>
      }
    >
      {loading ? (
        <Spin style={{ display: 'block', margin: '60px auto' }} />
      ) : (
        <>
          <div className="cms-hint" style={{ marginBottom: 12 }}>
            共 {data?.total ?? 0} 个文件 · 目录结构与需求归档格式一致（项目简称/业务类型/附件名称.扩展名）；
            台账 Excel 为导出时的最新数据，扫描件图片自动转为 PDF。
          </div>
          <Tree
            treeData={treeData}
            defaultExpandParent
            blockNode
            style={{ background: 'transparent' }}
          />
          {detailKey && (
            <Table
              style={{ marginTop: 16 }}
              size="small"
              // 表格必须声明 scroll（DESIGN.md §10.1 第 2 条）：窄屏下让表格内部横滑，不压扁「目录」列
              scroll={{ x: 760 }}
              rowKey="zipPath"
              loading={detailLoading}
              dataSource={detailItems ?? []}
              pagination={{ pageSize: 10, showTotal: (t) => `共 ${t} 个文件` }}
              columns={[
                { title: '目录', dataIndex: 'zipPath', width: 420, ellipsis: true },
                { title: '文件名', dataIndex: 'fileName', ellipsis: true },
              ]}
              locale={{ emptyText: '该目录暂无文件' }}
            />
          )}
        </>
      )}
    </Card>
  );
}

