/** 草稿超时阈值（需求 2.1.3：新增后 2 小时内未完成即视为超时） */
const OVERDUE_HOURS = 2;

const money = (v: number) =>
  v == null ? '-' : `¥${Number(v).toLocaleString('zh-CN', { maximumFractionDigits: 2 })}`;

/** 计算草稿超时剩余/超出分钟数：正数为剩余，负数为已超时 */
function overdueMinutes(createTime: string): number {
  return OVERDUE_HOURS * 60 - dayjs().diff(dayjs(createTime), 'minute');
}

/** 列表 / 新增 / 起草 是同一路由的三种形态（`?editor=new|<id>`），见 `useEditorTab` 的注释 */
const LIST_PATH = '/contract/draft';

/**
 * 合同起草页面（需求 2.1 / 2.4；问题四：列表区统一标准列表页规约）
 * - 草稿列表：仅展示当前用户「未完成」（status=DRAFT 或空）的草稿（需求 2.3），
 *   发布后的合同自动流转至「合同查询」菜单，不再出现在本列表
 * - 列表行「更多 → 编辑」打起草编辑器页签，「更多 → 删除」删除草稿
 * - 新增合同：先填 类型/供应商/物资描述/模板 → 创建草稿 → 换成该草稿的编辑器标签
 * - 起草编辑器：基础信息 + Tab1 物料编码清单 + Tab2 合同清单（税率为只读自动带出）
 * - 状态流转：保存（存草稿）→ 预览确认（模板变量替换 HTML）→ 发布（完成，清单推送至合同物资）
 */
export default function ContractDraft() {
  const editorTab = useEditorTab(LIST_PATH);
  const canEdit = usePermission('contract:edit');
  const isCreate = editorTab.editorId === 'new';
  const recordId = editorTab.editorId && editorTab.editorId !== 'new' ? editorTab.editorId : null;

  const currentProjectId = useAuthStore((s) => s.currentProjectId);
  const [listRefresh, setListRefresh] = useState(0);
  const refreshList = useCallback(() => setListRefresh((k) => k + 1), []);
  /** 列表原始数据（用于顶部超时提醒统计） */
  const [allRows, setAllRows] = useState<any[]>([]);
  /** 编辑器保存/发布后 bump → 被缓存的列表标签重新取数 */
  const tabRefresh = useTabRefresh(LIST_PATH);
  useEffect(() => {
    if (tabRefresh) refreshList();
  }, [tabRefresh]);

  // ===== 新增合同（编辑器页签的 "new" 形态） =====
  const [createForm] = Form.useForm();
  const [suppliers, setSuppliers] = useState<any[]>([]);
  const [templates, setTemplates] = useState<any[]>([]);
  const [creating, setCreating] = useState(false);

  // ===== 起草编辑器 =====
  const [editing, setEditing] = useState<any>(null); // 当前草稿合同
  const [basicForm] = Form.useForm();
  const [saving, setSaving] = useState(false);
  const [publishing, setPublishing] = useState(false);
  const [activeTab, setActiveTab] = useState('pool');
  // 需求修正3：发布前必须预览确认；内容变更后重新禁用
  const [previewed, setPreviewed] = useState(false);
  /** 起草编辑器里的未保存改动（关闭页签时确认） */
  const [dirty, setDirty] = useState(false);
  // 需求修正2：合同税率实时值（状态提升，Tab2 物料税率实时绑定）
  const watchTaxRate = Form.useWatch('taxRatePct', basicForm);
  const contractTaxPct =
    watchTaxRate == null || watchTaxRate === '' ? null : Number(watchTaxRate);

  // ===== 预览 =====
  const [previewOpen, setPreviewOpen] = useState(false);
  const [previewLoading, setPreviewLoading] = useState(false);
  const [preview, setPreview] = useState<{ templateName: string; html: string } | null>(null);

  /** 标准列表数据源：草稿接口返回全量数组，此处做关键词过滤 + 前端分页 */
  const fetcher = useCallback(async (params: Record<string, any>) => {
    const res: any = await contractApi.drafts();
    let list: any[] = Array.isArray(res) ? res : res?.list || [];
    setAllRows(list);
    const kw = String(params.keyword || '').trim();
    if (kw) {
      list = list.filter(
        (r) => (r.code || '').includes(kw) || (r.name || '').includes(kw),
      );
    }
    const total = list.length;
    const page = params.page || 1;
    const pageSize = params.pageSize || 10;
    return { list: list.slice((page - 1) * pageSize, page * pageSize), total };
  }, []);

  useEffect(() => {
    supplierApi.options().then((res: any) => setSuppliers(res || []));
    templateApi.list({ pageSize: 200, page: 1 }).then((res: any) => setTemplates(res?.list || res || []));
  }, []);

  // ==================== 新增草稿 ====================
  const handleCreate = async () => {
    const values = await createForm.validateFields();
    setCreating(true);
    try {
      // 编号自动生成：CSCEC-WZCG-项目字母简称-层级-日期顺序码
      let code = '';
      try {
        const nc: any = await contractApi.nextCode({
          typeCode: values.typeCode,
          projectId: currentProjectId,
        });
        code = nc?.code || '';
      } catch {
        /* 映射缺失时由用户稍后在台账页补填 */
      }
      if (!code) {
        message.error('合同编号自动生成失败，请检查系统参数 contract.code 配置');
        return;
      }
      const created: any = await contractApi.create({ ...values, code, status: 'DRAFT' });
      message.success('草稿已创建，请完善清单后发布');
      createForm.resetFields();
      refreshList();
      // 换成本草稿的编辑器标签（关掉 "new" 标签，但**不要**导航回列表——否则会闪一下列表）
      const newId = created?.id || created?.data?.id;
      useTabsStore.getState().closeTab(editorTab.tabKey);
      editorTab.openEdit(newId, {});
    } finally {
      setCreating(false);
    }
  };

  // ==================== 起草编辑器：进入时拉详情 ====================
  useEffect(() => {
    if (!recordId) return;
    setPreviewed(false); // 需求修正3：打开/切换草稿时重置预览确认状态
    setActiveTab('pool');
    setDirty(false);
    // 需求修正3：编辑器与列表是两个实例，故按 id 自己拉一次详情
    contractApi
      .detail(recordId)
      .then((detail: any) => {
        setEditing(detail);
        basicForm.setFieldsValue({
          code: detail.code,
          name: detail.name,
          typeCode: detail.typeCode,
          subTypeCode: detail.subTypeCode,
          supplierId: detail.supplierId,
          materialDescription: detail.materialDescription,
          templateId: detail.templateId,
          signDate: detail.signDate ? dayjs(detail.signDate) : null,
          // 合同级税率：全站单轨百分数（13 = 13%），直接回填
          taxRatePct: detail.taxRatePct != null ? Number(detail.taxRatePct) : null,
          // 条款选择回显（业务口径 2026-10-16）
          technicalClauseId: detail.technicalClauseId,
          qualityClauseId: detail.qualityClauseId,
          acceptanceClauseId: detail.acceptanceClauseId,
          paymentClauseId: detail.paymentClauseId,
        });
        editorTab.setTitle(`合同起草 · ${detail.code || ''}`.trim());
      })
      .catch(() => undefined);
    // recordId 是种子之外的唯一依赖（详情只按它拉一次）
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [recordId]);

  /** 保存基础信息（自动触发名称重建：后端按 TMHB-XX-项目-物资-类型-供应商 规则生成） */
  const saveBasic = async (silent = false): Promise<boolean> => {
    if (!editing) return false;
    const values = await basicForm.validateFields();
    setSaving(true);
    try {
      await contractApi.update(editing.id, {
        typeCode: values.typeCode,
        subTypeCode: values.subTypeCode,
        supplierId: values.supplierId,
        materialDescription: values.materialDescription,
        templateId: values.templateId,
        signDate: values.signDate ? values.signDate.format('YYYY-MM-DD') : null,
        // 合同级税率：单轨百分数，用户填 13 → 存 13；保存后 Tab2 所有物料税率自动同步
        taxRatePct: values.taxRatePct != null && values.taxRatePct !== '' ? Number(values.taxRatePct) : null,
        // 条款选择（业务口径 2026-10-16）：Contract 的 4 个条款外键
        technicalClauseId: values.technicalClauseId || null,
        qualityClauseId: values.qualityClauseId || null,
        acceptanceClauseId: values.acceptanceClauseId || null,
        paymentClauseId: values.paymentClauseId || null,
        // 乐观锁：后端 assertVersion 强制要求回传（缺失=409）
        version: (editing as any).version,
      });
      const detail: any = await contractApi.detail(editing.id);
      setEditing(detail);
      basicForm.setFieldsValue({
        code: detail.code,
        name: detail.name,
        signDate: detail.signDate ? dayjs(detail.signDate) : null,
        taxRatePct: detail.taxRatePct != null ? Number(detail.taxRatePct) : null,
      });
      if (!silent) message.success('已保存');
      // 需求修正3：基础信息变更后需重新预览确认，发布按钮重新禁用
      setPreviewed(false);
      setDirty(false);
      return true;
    } finally {
      setSaving(false);
    }
  };

  // ==================== 预览确认（需求 2.4 / 需求修正3：发布前必须预览） ====================
  const handlePreview = async () => {
    const ok = await saveBasic(true);
    if (!ok) return;
    const templateId = basicForm.getFieldValue('templateId');
    if (!templateId) {
      message.warning('请先在基础信息中选择合同模板');
      return;
    }
    setPreviewLoading(true);
    try {
      const res: any = await templateApi.generate({ templateId, contractId: editing.id });
      setPreview({ templateName: res?.templateName || '合同预览', html: highlightPlaceholders(res?.html || '') });
      setPreviewOpen(true);
    } finally {
      setPreviewLoading(false);
    }
  };

  /** 预览「确认无误」后发布按钮才可用（需求修正3） */
  const handlePreviewConfirm = () => {
    setPreviewed(true);
    setPreviewOpen(false);
    message.success('预览确认完成，现在可以发布合同');
  };

  // ==================== 发布（完成） ====================
  const handlePublish = async () => {
    // 需求修正3：必须先预览确认才能发布
    if (!previewed) {
      message.warning('请先点击「预览合同」并在预览中确认无误后，再发布');
      return;
    }
    if (!basicForm.getFieldValue('templateId')) {
      message.warning('发布前请先选择合同模板并保存');
      setActiveTab('basic');
      return;
    }
    Modal.confirm({
      title: '发布确认',
      width: 520,
      content: (
        <div>
          <p>发布后将执行以下动作，确认继续？</p>
          <ol style={{ paddingLeft: 20, margin: 0 }}>
            <li>合同清单推送至「合同物资」，作为正式执行数据；</li>
            <li>合同状态置为「待签章」，从草稿列表移除并进入「合同查询」；</li>
            <li>按所选模板生成合同正文（可先点击「预览合同」确认）；</li>
            <li>发布后合同类型不可再修改，可在「合同查询」中上传签章。</li>
          </ol>
        </div>
      ),
      okText: '确认发布',
      cancelText: '再检查一下',
      onOk: async () => {
        const ok = await saveBasic(true);
        if (!ok) return;
        setPublishing(true);
        try {
          await contractApi.publish(editing.id);
          message.success('合同已发布，状态：待签章');
          setDirty(false);
          editorTab.closeEditor();
        } finally {
          setPublishing(false);
        }
      },
    });
  };

  // ==================== 删除草稿 ====================
  const handleRemove = (row: ModuleListRow) => {
    const r = row as any;
    Modal.confirm({
      title: '删除草稿',
      content: `确认删除草稿「${r.name || r.code}」？删除后不可恢复。`,
      okText: '删除',
      okType: 'danger',
      cancelText: '取消',
      onOk: async () => {
        await contractApi.removeDraft(row.id);
        message.success('草稿已删除');
        refreshList();
      },
    });
  };

  const overdueCount = useMemo(
    () => allRows.filter((r) => overdueMinutes(r.createdAt) <= 0).length,
    [allRows],
  );

  /** 筛选项（问题四：标准筛选区） */
  const extraFilters: ModuleListFilterField[] = [
    { key: 'keyword', label: '合同编号 / 名称', control: 'input', placeholder: '请输入关键词' },
  ];

  /** 表格列（问题四：generic 模式完整列定义） */
  const extraColumns: any[] = [
    { title: '合同编号', dataIndex: 'code', width: 200, fixed: 'left' },
    { title: '合同名称', dataIndex: 'name', width: 220, ellipsis: true },
    { title: '供应商名称', dataIndex: ['supplier', 'name'], width: 200, ellipsis: true, render: (v: any) => v || '-' },
    { title: '合同类型', dataIndex: 'typeCode', width: 140, render: (v: any) => (v ? <DictTag typeCode="contract_type" value={v} /> : '-') },
    { title: '合同额', dataIndex: 'amount', width: 140, align: 'right' as const, render: money },
    {
      title: '状态',
      dataIndex: 'status',
      width: 100,
      render: () => <Tag color="default">草稿中</Tag>,
    },
    {
      title: '超时提醒',
      key: 'draftStatus',
      width: 160,
      render: (_: any, row: any) => {
        const mins = overdueMinutes(row.createdAt);
        return mins > 0 ? (
          <Tag>剩余 {Math.floor(mins / 60)} 小时 {mins % 60} 分</Tag>
        ) : (
          <Tag color="orange">已超时 {-mins} 分钟</Tag>
        );
      },
    },
    {
      title: '最后编辑时间',
      dataIndex: 'updatedAt',
      width: 170,
      render: (v: any) => v?.slice(0, 19).replace('T', ' '),
    },
  ];

  return (
    <>
      {!isCreate && !recordId && (
        <Space direction="vertical" size={16} style={{ width: '100%' }}>
      {overdueCount > 0 && (
        <Alert
          type="warning"
          showIcon
          message={`您有 ${overdueCount} 份合同草稿已超过 ${OVERDUE_HOURS} 小时未完成，请及时处理`}
        />
      )}

      <ModuleListPage
        mode="generic"
        columnConfigKey="contract.draft"
        fetcher={fetcher}
        extraFilters={extraFilters}
        extraColumns={extraColumns}
        emptyText="暂无合同草稿"
        refreshKey={listRefresh + tabRefresh}
        editPermission="contract:edit"
        onEdit={(row) => editorTab.openEdit(row.id, {})}
        onDelete={handleRemove}
        toolbarLeft={
          canEdit ? (
            <Button type="primary" icon={<PlusOutlined />} onClick={() => editorTab.openCreate()}>
              新增合同
            </Button>
          ) : null
        }
      />

        </Space>
      )}

      {/* ==================== 新增合同（编辑器页签的 "new" 形态） ==================== */}
      {isCreate && (
        <EditorTabPage
          listPath={LIST_PATH}
          title="新增合同草稿"
          saving={creating}
          saveText="创建草稿"
          onSave={handleCreate}
          // 「创建草稿」只建单据、不关标签（随后换成该草稿的编辑器标签）
          closeOnSave={false}
          dirty={dirty}
        >
          <Form form={createForm} layout="vertical" onValuesChange={() => setDirty(true)}>
          <Form.Item name="typeCode" label="合同类型" rules={[{ required: true, message: '请选择合同类型' }]}>
            <DictSelect typeCode="contract_type" placeholder="请选择合同类型" />
          </Form.Item>
          <Form.Item name="supplierId" label="供应商" rules={[{ required: true, message: '请选择供应商' }]}>
            <Select
              showSearch
              optionFilterProp="label"
              placeholder="请选择供应商"
              options={suppliers.map((s: any) => ({ value: s.id, label: s.name }))}
            />
          </Form.Item>
          <Form.Item
            name="materialDescription"
            label="物资名称描述"
            rules={[{ required: true, message: '请输入物资名称描述（用于合同名称自动生成）' }]}
            extra="示例：步道砖、盲道砖 —— 将用于合同名称 TMHB-CG-项目-物资描述-类型-供应商"
          >
            <Input placeholder="如：步道砖、盲道砖" />
          </Form.Item>
          <Form.Item
            name="templateId"
            label="合同模板"
            rules={[{ required: true, message: '请选择合同模板' }]}
            extra="发布时按模板自动生成合同正文，可在起草过程中随时更换"
          >
            <Select
              showSearch
              optionFilterProp="label"
              placeholder="请选择合同模板"
              options={templates.map((t: any) => ({ value: t.id, label: t.name }))}
            />
          </Form.Item>
          </Form>
        </EditorTabPage>
      )}

      {/* ==================== 起草弹窗（问题三：居中弹窗） ==================== */}
      {/* ==================== 起草编辑器（记录形态） ==================== */}
      {recordId && (
        <EditorTabPage
          listPath={LIST_PATH}
          title="合同起草"
          titleExtra={
            <Space>
              {editing?.code && <Tag color="geekblue">{editing.code}</Tag>}
              {editing?.status === 'SIGNED' ? (
                <Tag color="green">已签章</Tag>
              ) : editing?.status === 'APPROVING' ? (
                <Tag color="blue">待签章</Tag>
              ) : (
                <Tag color="default">草稿中</Tag>
              )}
            </Space>
          }
          saving={saving}
          saveText="保存（草稿）"
          onSave={() => saveBasic()}
          // 起草是多步的（基础信息 → 清单 → 预览 → 发布）；「保存」不关标签，只有「发布」才关
          closeOnSave={false}
          dirty={dirty}
          footerLeft={
            <Space wrap size={8}>
              <Button icon={<EyeOutlined />} loading={previewLoading} onClick={handlePreview}>
                预览合同
              </Button>
            </Space>
          }
          footerExtra={
            /* 需求修正3：预览确认无误后发布按钮才可用（禁用态也要能问出原因，故包一层 span 给 Tooltip） */
            <Tooltip title={previewed ? '发布合同' : '请先点击「预览合同」并确认无误'}>
              <span>
                <Button
                  type="primary"
                  icon={<SendOutlined />}
                  loading={publishing}
                  disabled={!previewed}
                  onClick={handlePublish}
                >
                  发布（完成）
                </Button>
              </span>
            </Tooltip>
          }
        >
        {editing ? (
          <Space direction="vertical" size={16} style={{ width: '100%' }}>
            <Card size="small" title="基础信息">
              <Form form={basicForm} layout="vertical" onValuesChange={() => setDirty(true)}>
                <Row gutter={16}>
                  <Col xs={24} md={12}>
                    <Form.Item label="合同编号（自动生成，保存后不可变更）">
                      <Input value={basicForm.getFieldValue('code')} disabled />
                    </Form.Item>
                  </Col>
                  <Col xs={24} md={12}>
                    <Form.Item label="合同名称（自动生成：TMHB-XX-项目-物资-类型-供应商）">
                      <Input value={basicForm.getFieldValue('name')} disabled />
                    </Form.Item>
                  </Col>
                </Row>
                <Row gutter={16}>
                  <Col xs={24} md={8}>
                    {/* 需求 2.1：合同发布后（待签章/已签章）合同类型固化不可修改 */}
                    <Form.Item name="typeCode" label="合同类型" rules={[{ required: true }]}>
                      <DictSelect
                        typeCode="contract_type"
                        disabled={!!editing.status && editing.status !== 'DRAFT'}
                      />
                    </Form.Item>
                  </Col>
                  <Col xs={24} md={8}>
                    <Form.Item name="supplierId" label="供应商" rules={[{ required: true }]}>
                      <Select
                        showSearch
                        optionFilterProp="label"
                        options={suppliers.map((s: any) => ({ value: s.id, label: s.name }))}
                      />
                    </Form.Item>
                  </Col>
                  <Col xs={24} md={8}>
                    <Form.Item
                      name="materialDescription"
                      label="物资名称描述"
                      rules={[{ required: true }]}
                    >
                      <Input placeholder="如：步道砖、盲道砖" />
                    </Form.Item>
                  </Col>
                </Row>
                <Row gutter={16}>
                  <Col xs={24} md={8}>
                    <Form.Item
                      name="templateId"
                      label="合同模板"
                      rules={[{ required: true, message: '发布前必须选择模板' }]}
                    >
                      <Select
                        showSearch
                        optionFilterProp="label"
                        placeholder="请选择合同模板"
                        options={templates.map((t: any) => ({ value: t.id, label: t.name }))}
                      />
                    </Form.Item>
                  </Col>
                  <Col xs={24} md={8}>
                    <Form.Item
                      name="signDate"
                      label="签订日期"
                      extra="支持日期选择器或按 YYYY-MM-DD 手动输入"
                    >
                      <DatePicker format="YYYY-MM-DD" style={{ width: '100%' }} placeholder="yyyy-mm-dd" />
                    </Form.Item>
                  </Col>
                  <Col xs={24} md={8}>
                    <Form.Item
                      name="taxRatePct"
                      label="合同税率(%)"
                      extra="整个合同的统一税率（如 13 表示 13%）。保存后 Tab2 合同清单所有物料税率自动同步为该值（只读）"
                    >
                      <InputNumber style={{ width: '100%' }} min={0} max={100} precision={2} placeholder="如 13" />
                    </Form.Item>
                  </Col>
                </Row>
                {/* 条款选择（业务口径 2026-10-16）：Contract 本就有 4 个条款外键，
                    旧合同编辑页会填，新起草页此前没有入口 —— 不补的话合同模板里的
                    {{技术条款}} 等变量恒为空。同样"只选不录"，条款库维护在 /base/clause。 */}
                <ClauseSelectRow form={basicForm} />
              </Form>
            </Card>

            <Card size="small" title="物资清单">
              <Tabs
                activeKey={activeTab}
                onChange={setActiveTab}
                items={[
                  {
                    key: 'pool',
                    label: 'Tab1 · 物料编码清单',
                    children: (
                      <MaterialPoolTab
                        contractId={editing.id}
                        onChanged={() => setPreviewed(false)}
                      />
                    ),
                  },
                  {
                    key: 'items',
                    label: 'Tab2 · 合同清单',
                    children: (
                      <ContractItemTab
                        contractId={editing.id}
                        contractTaxPct={contractTaxPct}
                        onDirty={() => setPreviewed(false)}
                      />
                    ),
                  },
                ]}
              />
            </Card>
          </Space>
        ) : (
          <Spin />
        )}
        </EditorTabPage>
      )}

      {/* ==================== 合同正文预览（需求修正3：确认无误后发布才可用） ==================== */}
      <Modal
        title={`预览确认 · ${preview?.templateName || ''}`}
        open={previewOpen}
        onCancel={() => setPreviewOpen(false)}
        footer={[
          <Button key="back" onClick={() => setPreviewOpen(false)}>
            返回修改
          </Button>,
          <Button key="confirm" type="primary" icon={<CheckOutlined />} onClick={handlePreviewConfirm}>
            确认无误
          </Button>,
        ]}
        width={900}
        destroyOnHidden
      >
        <Alert
          type="info"
          showIcon
          style={{ marginBottom: 12 }}
          message="请核对合同完整内容；点击「确认无误」后「发布」按钮才可用。若返回修改合同内容，需重新预览确认。"
        />
        <div
          style={{ maxHeight: 520, overflow: 'auto', border: '1px solid var(--cms-hairline-soft)', padding: 16, background: 'var(--cms-paper)' }}
          dangerouslySetInnerHTML={{ __html: sanitizeHtml(preview?.html) }}
        />
      </Modal>
    </>
  );
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { withToken } from '../utils/download';
import {
  Button, Form, Input, Space, Modal, message, InputNumber, Select, Descriptions, Alert, Table, Tag,
} from 'antd';
import { PlusOutlined, ExportOutlined, SwapOutlined, ArrowUpOutlined, ArrowDownOutlined } from '@ant-design/icons';
import { contractMaterialApi, materialApi } from '@/api/modules';
import { contractApi, supplierApi } from '@/api/business';
import ImportButton from '@/components/ImportButton';
import Can from '@/components/Can';
import ModuleListPage, { type ModuleListFilterField, type ModuleListRow } from '@/components/procurement/ModuleListPage';
import { useEditorTab, useTabRefresh } from '@/hooks/useTabs';
import { usePermission } from '@/hooks/usePermission';
import EditorTabPage from '@/components/editor/EditorTabPage';
import { LIST_PATHS } from '@/constants/listPaths';
import { calcPriceWithTax, calcTotalWithTax } from '../../../server/src/common/calc/amounts.ts';

/** 列表与「添加/编辑清单行」是同一路由的两种形态（`?editor=new|<id>`） */
const LIST_PATH = LIST_PATHS.contractMaterial;

/** 前端实时计算（与服务端共用同一份 4 位舍入实现） */
const fmtNum = (v: any, digits = 4) =>
  v == null || v === '' ? '-' : Number(v).toLocaleString('zh-CN', { maximumFractionDigits: digits });

/**
 * 合同物资清单（需求修正3；问题四：统一标准列表页规约）
 * - 默认展示当前项目下**所有合同**的物资清单（按行平铺）
 * - 筛选区：供应商名称 / 合同物资名称 / 合同编号 多条件组合筛选（查询/重置）
 * - 工具栏：按合同查看/维护切换 + 导入/导出/派生/添加（单合同维度操作需先选中合同）
 * - 行操作：更多 → 上移/下移/编辑/删除（单合同视图可用）
 */
export default function ContractMaterials() {
  const editorTab = useEditorTab(LIST_PATH);
  if (editorTab.isEditor) {
    return <MaterialRowEditor seed={editorTab.seed} />;
  }
  return <ContractMaterialsList />;
}

function ContractMaterialsList() {
  const editorTab = useEditorTab(LIST_PATH);
  const canEdit = usePermission('material:edit');
  const [contracts, setContracts] = useState<any[]>([]);
  const [suppliers, setSuppliers] = useState<any[]>([]);
  const [contractId, setContractId] = useState<string>();
  const [header, setHeader] = useState<any>(null);

  // 列表刷新键（合同切换/保存/删除后 +1 触发重查）
  const [listRefresh, setListRefresh] = useState(0);
  const refreshList = useCallback(() => setListRefresh((k) => k + 1), []);
  /** 当前列表数据副本（用于上移/下移定位行序） */
  const listRef = useRef<any[]>([]);

  // 选料弹窗（单个，选择器非表单，保留弹窗形态）
  const [pickerOpen, setPickerOpen] = useState(false);
  const [baseList, setBaseList] = useState<any[]>([]);
  const [baseLoading, setBaseLoading] = useState(false);

  // 派生弹窗（多选，动作类，保留弹窗形态）
  const [deriveOpen, setDeriveOpen] = useState(false);
  const [deriveIds, setDeriveIds] = useState<string[]>([]);
  const [deriveSubmitting, setDeriveSubmitting] = useState(false);

  // 编辑器标签保存后 bump 令牌 → 本（被缓存的）列表标签重新取数
  const tabRefresh = useTabRefresh(LIST_PATH);
  useEffect(() => {
    if (tabRefresh) refreshList();
  }, [tabRefresh, refreshList]);

  const contractMap = useMemo(
    () => Object.fromEntries((contracts || []).map((c: any) => [c.id, c])),
    [contracts],
  );

  /** 行数据补齐合同维度字段（单合同视图下从 header/合同下拉补齐） */
  const enrich = useCallback(
    (list: any[]) =>
      (list || []).map((r: any) => ({
        ...r,
        contractCode: r.contract?.code || header?.code || contractMap[r.contractId]?.code || '-',
        contractName: r.contract?.name || header?.name || contractMap[r.contractId]?.name || '-',
        supplierName:
          r.contract?.supplier?.name || header?.supplierName || contractMap[r.contractId]?.supplierName || '-',
      })),
    [header, contractMap],
  );

  /** 标准列表数据源：选中合同时按合同查全量（前端分页关闭由返回 total 控制），否则全项目分页查询 */
  const fetcher = useCallback(
    async (params: Record<string, any>) => {
      if (contractId) {
        const res: any = await contractMaterialApi.list(contractId);
        setHeader(res?.contract || null);
        const list = enrich(res?.list || []);
        listRef.current = list;
        return { list, total: list.length };
      }
      setHeader(null);
      const res: any = await contractMaterialApi.listAll({
        supplierName: params.supplierName,
        materialName: params.materialName,
        contractCode: params.contractCode,
        page: params.page,
        pageSize: params.pageSize,
      });
      const data = res?.data ?? res;
      const list = enrich(data?.list || []);
      listRef.current = list;
      return { list, total: data?.total ?? list.length };
    },
    [contractId, enrich],
  );

  useEffect(() => {
    contractApi.options().then((res: any) => setContracts(res || []));
    supplierApi.options().then((res: any) => setSuppliers(res || []));
  }, []);

  const loadBases = (keyword: string) => {
    setBaseLoading(true);
    materialApi.options(keyword)
      .then((res: any) => setBaseList(res || []))
      .finally(() => setBaseLoading(false));
  };

  // ---------- 行新增/编辑（编辑器页签） ----------
  const openEdit = (row?: any) => {
    if (!contractId) return message.warning('请先在工具栏选择合同，再维护该合同的物资清单');
    editorTab.openEdit(row?.id ?? 'new', { contractId, editing: row || null, picked: row?.materialBase || null });
  };

  // 选料弹窗的选择回调（重复校验按当前列表副本）；pickMaterial 已随行编辑迁入编辑器页签
  const pickMaterial = (m: any) => {
    if (listRef.current.some((r) => r.materialBaseId === m.id)) {
      message.warning(`「${m.name} / ${m.spec}」已在当前合同清单中，同一物资只能出现一次`);
      return;
    }
    editorTab.openEdit('new', { contractId, editing: null, picked: m });
  };

  const removeRow = (row: ModuleListRow) => {
    Modal.confirm({
      title: '删除该清单行？',
      content: '删除该行不影响物资基础库。',
      okText: '确认删除',
      okType: 'danger',
      onOk: async () => {
        await contractMaterialApi.remove(row.id);
        message.success('已删除');
        refreshList();
      },
    });
  };

  const moveRow = async (row: ModuleListRow, dir: -1 | 1) => {
    const rows = listRef.current;
    const index = rows.findIndex((r) => r.id === row.id);
    const target = index + dir;
    if (index < 0 || target < 0 || target >= rows.length) return;
    const a = rows[index];
    const b = rows[target];
    await contractMaterialApi.sort([
      { id: a.id, sortOrder: b.sortOrder },
      { id: b.id, sortOrder: a.sortOrder },
    ]);
    refreshList();
  };

  const doDerive = async () => {
    if (!contractId) return message.warning('请先选择合同');
    if (!deriveIds.length) return message.warning('请选择要派生的物资');
    setDeriveSubmitting(true);
    try {
      const res: any = await contractMaterialApi.derive(contractId, deriveIds);
      message.success(`派生完成：已按所选物资重新生成 ${res?.created || 0} 行清单（请补录数量/单价，税率将自动继承合同税率）`);
      setDeriveOpen(false);
      setDeriveIds([]);
      refreshList();
    } finally {
      setDeriveSubmitting(false);
    }
  };

  /** 筛选项（问题四：标准筛选区） */
  const extraFilters: ModuleListFilterField[] = [
    {
      key: 'supplierName',
      label: '供应商名称',
      control: 'select',
      options: suppliers.map((s: any) => ({ value: s.name, label: s.name })),
      placeholder: '选择或输入关键词',
    },
    { key: 'materialName', label: '合同物资名称', control: 'input', placeholder: '物资名称关键词' },
    { key: 'contractCode', label: '合同编号', control: 'input', placeholder: '合同编号关键词' },
  ];

  /** 表格列（问题四：generic 模式完整列定义） */
  const extraColumns: any[] = [
    { title: '合同编号', dataIndex: 'contractCode', width: 200, fixed: 'left', render: (v: any) => v || '-' },
    { title: '合同名称', dataIndex: 'contractName', width: 200, ellipsis: true, render: (v: any) => v || '-' },
    { title: '供应商名称', dataIndex: 'supplierName', width: 170, ellipsis: true, render: (v: any) => v || '-' },
    { title: '物资名称', key: 'materialName', width: 180, render: (_: any, r: any) => r.materialBase?.name || '-' },
    { title: '规格型号', key: 'spec', width: 150, render: (_: any, r: any) => r.materialBase?.spec || '-' },
    { title: '计量单位', dataIndex: 'unit', width: 100 },
    { title: '暂定数量', dataIndex: 'qty', width: 120, align: 'right' as const, render: (v: any) => fmtNum(v) },
    { title: '税前单价', dataIndex: 'priceBeforeTax', width: 130, align: 'right' as const, render: (v: any) => fmtNum(v, 2) },
    { title: '税率(%)', dataIndex: 'taxRatePct', width: 100, align: 'right' as const, render: (v: any) => (v == null ? '-' : `${Number(v).toFixed(2)}`) },
    { title: '含税单价（自动）', dataIndex: 'priceWithTax', width: 150, align: 'right' as const, render: (v: any) => <Tag color="geekblue">{fmtNum(v, 2)}</Tag> },
    { title: '暂定含税合价（自动）', dataIndex: 'totalWithTax', width: 170, align: 'right' as const, render: (v: any) => <Tag color="geekblue">{fmtNum(v, 2)}</Tag> },
    { title: '备注', dataIndex: 'remark', width: 160, ellipsis: true, render: (v: any) => v || '-' },
  ];

  return (
    <Space direction="vertical" size={16} style={{ width: '100%' }}>
      {/* 选中合同时展示合同头信息 */}
      {header && (
        <Descriptions
          size="small"
          bordered
          column={3}
          style={{ marginBottom: 0 }}
          items={[
            { key: 'code', label: '合同编号', children: header.code || '-' },
            { key: 'project', label: '项目名称', children: header.projectName || '-' },
            { key: 'supplier', label: '供应商名称', children: header.supplierName || '-' },
          ]}
        />
      )}

      {!contractId && (
        <Alert
          type="info"
          showIcon
          style={{ marginBottom: 0 }}
          message="当前展示项目下所有合同的物资清单；可按供应商名称 / 合同物资名称 / 合同编号组合筛选。选择具体合同后可维护该合同清单（上移/下移/编辑/删除/添加/派生/导入）。"
        />
      )}

      <ModuleListPage
        mode="generic"
        columnConfigKey="contract.materials"
        fetcher={fetcher}
        extraFilters={extraFilters}
        extraColumns={extraColumns}
        refreshKey={listRefresh}
        mobileDefaultKeys={['contractCode', 'contractName', 'materialName', 'qty', 'totalWithTax']}
        emptyText={contractId ? '当前合同暂无物资清单，可「从物资库派生」或「添加物资」' : '暂无合同物资清单数据'}
        rowEditable={() => !!contractId}
        rowDeletable={() => !!contractId}
        editPermission="material:edit"
        onEdit={(row) => openEdit(row)}
        onDelete={removeRow}
        rowMenuItems={(row) => {
          if (!canEdit) return [];
          const rows = listRef.current;
          const index = rows.findIndex((r) => r.id === row.id);
          return [
            {
              key: 'moveUp',
              label: (
                <span>
                  <ArrowUpOutlined /> 上移
                </span>
              ),
              disabled: !contractId || index <= 0,
              onClick: () => moveRow(row, -1),
            },
            {
              key: 'moveDown',
              label: (
                <span>
                  <ArrowDownOutlined /> 下移
                </span>
              ),
              disabled: !contractId || index < 0 || index >= rows.length - 1,
              onClick: () => moveRow(row, 1),
            },
          ];
        }}
        toolbarLeft={
          <Space wrap size={8}>
            <Select
              showSearch
              optionFilterProp="label"
              placeholder="按合同查看 / 维护（可留空查看全部）"
              allowClear
              style={{ minWidth: 320 }}
              value={contractId}
              onChange={(v) => { setContractId(v); refreshList(); }}
              options={contracts.map((c) => ({ value: c.id, label: `${c.code || ''} ${c.name || ''}`.trim() }))}
            />
            <Can code="material:edit">
              <ImportButton
                moduleName="合同物资清单"
                templateUrl={contractMaterialApi.templateUrl()}
                uploadUrl={contractId ? contractMaterialApi.importUrl(contractId) : ''}
                validateUrl={contractId ? contractMaterialApi.validateUrl(contractId) : ''}
                disabled={!contractId}
                onDone={refreshList}
                extraHint="物资名称 + 规格型号须与物资基础库一致。"
              />
            </Can>
            <Button
              icon={<ExportOutlined />}
              disabled={!contractId}
              onClick={() => window.open(withToken(contractMaterialApi.exportUrl(contractId!, 'xlsx')))}
            >
              导出 Excel
            </Button>
            <Button
              icon={<ExportOutlined />}
              disabled={!contractId}
              onClick={() => window.open(withToken(contractMaterialApi.exportUrl(contractId!, 'csv')))}
            >
              导出 CSV
            </Button>
            <Can code="material:edit">
              <>
                <Button
                  icon={<SwapOutlined />}
                  disabled={!contractId}
                  onClick={() => { setDeriveIds([]); loadBases(''); setDeriveOpen(true); }}
                >
                  从物资库派生
                </Button>
                <Button type="primary" icon={<PlusOutlined />} disabled={!contractId} onClick={() => openEdit()}>
                  添加物资
                </Button>
              </>
            </Can>
          </Space>
        }
      />

      {/* 行新增/编辑已改为编辑器页签（MaterialRowEditor）；选料弹窗为选择器、派生弹窗为动作类，保留弹窗 */}

      {/* 选料弹窗（单个） */}
      <Modal
        title="从物资基础库选择物资"
        open={pickerOpen}
        onCancel={() => setPickerOpen(false)}
        footer={null}
        width={760}
        destroyOnHidden
      >
        <Input.Search
          placeholder="搜索物资名称/规格/MDM/DSC编码"
          allowClear
          enterButton
          onSearch={(v) => loadBases(v)}
          onChange={(e) => { if (e.target.value) return; loadBases(''); }}
          style={{ marginBottom: 12 }}
        />
        <Space direction="vertical" style={{ width: '100%' }}>
          <TableInline baseList={baseList} baseLoading={baseLoading} onPick={pickMaterial} />
          {baseList.length === 0 && !baseLoading && (
            <Alert type="warning" showIcon message="基础库中未找到匹配物资，请先到「物资基础库」页面维护。" />
          )}
        </Space>
      </Modal>

      {/* 派生弹窗（多选） */}
      <Modal
        title="从物资基础库派生合同清单"
        open={deriveOpen}
        onOk={doDerive}
        confirmLoading={deriveSubmitting}
        onCancel={() => setDeriveOpen(false)}
        width={620}
        destroyOnHidden
      >
        <Alert
          type="warning"
          showIcon
          style={{ marginBottom: 12 }}
          message="派生将清空当前合同已有清单行，并按所选物资重新编号生成（序号从 1 开始）。税率自动继承合同税率，生成后请补录数量与单价，含税金额将自动计算。"
        />
        <Select
          mode="multiple"
          showSearch
          optionFilterProp="label"
          placeholder="选择要派生的物资（可多选）"
          style={{ width: '100%' }}
          value={deriveIds}
          onChange={setDeriveIds}
          options={baseList.map((m) => ({ value: m.id, label: `${m.name} / ${m.spec}` }))}
        />
      </Modal>
    </Space>
  );
}

/** 选料弹窗内嵌表格（局部组件，避免与外层标准列表混淆） */
function TableInline({ baseList, baseLoading, onPick }: { baseList: any[]; baseLoading: boolean; onPick: (m: any) => void }) {
  return (
    <Table
      rowKey="id"
      size="small"
      loading={baseLoading}
      dataSource={baseList}
      scroll={{ x: 'max-content' }}
      pagination={{ pageSize: 8 }}
      onRow={(record: any) => ({ onClick: () => onPick(record), style: { cursor: 'pointer' } })}
      columns={[
        { title: '物资名称', dataIndex: 'name', width: 200 },
        { title: '规格型号', dataIndex: 'spec', width: 160 },
        { title: 'MDM编码', dataIndex: 'mdmCode', width: 140, render: (v: any) => v || '-' },
        { title: 'DSC编码', dataIndex: 'dscCode', width: 140, render: (v: any) => v || '-' },
      ]}
    />
  );
}

/**
 * 编辑器页签：添加/编辑合同清单行（原「行编辑弹窗」迁入；业务 2026-10-17 新增必须进编辑界面）。
 * seed = { contractId, editing: 行对象|null, picked: 基础物资|null }；保存后 closeEditor 刷新列表。
 */
function MaterialRowEditor({ seed }: { seed: unknown }) {
  const editorTab = useEditorTab(LIST_PATH);
  const s = (seed ?? {}) as { contractId?: string; editing?: any; picked?: any };
  const editing = s.editing ?? null;
  const [saving, setSaving] = useState(false);
  const [dirty, setDirty] = useState(false);
  const [picked, setPicked] = useState<any>(s.picked ?? null);
  const [form] = Form.useForm();

  // 选料弹窗（选择器，非表单，保留弹窗）
  const [pickerOpen, setPickerOpen] = useState(false);
  const [baseList, setBaseList] = useState<any[]>([]);
  const [baseLoading, setBaseLoading] = useState(false);
  const loadBases = (keyword: string) => {
    setBaseLoading(true);
    materialApi.options(keyword)
      .then((res: any) => setBaseList(res || []))
      .finally(() => setBaseLoading(false));
  };

  useEffect(() => {
    form.resetFields();
    if (editing) {
      form.setFieldsValue({
        unit: editing.unit, qty: editing.qty, priceBeforeTax: editing.priceBeforeTax,
        taxRatePct: editing.taxRatePct, remark: editing.remark, sortOrder: editing.sortOrder,
      });
    }
    setDirty(false);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [editing]);

  // 实时计算预览（与服务端同口径：4 位小数）
  const watched: any = Form.useWatch((values: any) => values, form) || {};
  const preview = useMemo(() => {
    const qty = watched.qty;
    const p = watched.priceBeforeTax;
    const pct = watched.taxRatePct;
    // 统一引擎：与服务端 material.service 的 calcPriceWithTax/calcTotalWithTax 同口径
    const withTax = p != null ? calcPriceWithTax(p, pct ?? 0) : null;
    const total = withTax != null && qty != null ? calcTotalWithTax(withTax, qty) : null;
    return { withTax, total };
  }, [watched]);

  const submit = async () => {
    const values = await form.validateFields();
    setSaving(true);
    try {
      if (editing) {
        // 乐观锁：编辑态必须回传 version，否则后端 assertVersion 抛 409
        await contractMaterialApi.update(editing.id, { ...values, version: (editing as any).version });
      } else {
        if (!picked) return message.warning('请先从物资基础库中选择物资');
        await contractMaterialApi.create({ ...values, contractId: s.contractId, materialBaseId: picked.id });
      }
      message.success('保存成功');
      editorTab.closeEditor();
    } finally {
      setSaving(false);
    }
  };

  return (
    <EditorTabPage
      listPath={LIST_PATH}
      title={editing ? '编辑清单行' : '添加清单行'}
      saving={saving}
      dirty={dirty}
      onSave={submit}
    >
      <Form form={form} layout="vertical" onValuesChange={() => setDirty(true)}>
        <Form.Item label="物资（来自基础库，只读）" required>
          {picked ? (
            <Space wrap>
              <Tag color="blue">{picked.name}</Tag>
              <span>规格：{picked.spec}</span>
              {!editing && <Button size="small" onClick={() => { loadBases(''); setPickerOpen(true); }}>重新选择</Button>}
            </Space>
          ) : (
            <Button type="primary" ghost onClick={() => { loadBases(''); setPickerOpen(true); }}>从物资基础库选择</Button>
          )}
        </Form.Item>
        <Space size={16} wrap>
          <Form.Item name="unit" label="计量单位" rules={[{ required: true, message: '如 吨/台/米' }]} style={{ width: 140 }}>
            <Input placeholder="吨/台/米" />
          </Form.Item>
          <Form.Item name="qty" label="暂定数量" style={{ width: 160 }}>
            <InputNumber style={{ width: '100%' }} min={0} precision={4} />
          </Form.Item>
          <Form.Item name="priceBeforeTax" label="税前单价" style={{ width: 160 }}>
            <InputNumber style={{ width: '100%' }} min={0} precision={4} />
          </Form.Item>
          <Form.Item name="taxRatePct" label="税率 (%，留空继承合同税率)" style={{ width: 200 }}>
            <InputNumber style={{ width: '100%' }} min={0} max={100} precision={2} placeholder="留空自动继承" />
          </Form.Item>
          <Form.Item name="sortOrder" label="序号" style={{ width: 120 }}>
            <InputNumber style={{ width: '100%' }} precision={0} />
          </Form.Item>
        </Space>
        <Form.Item name="remark" label="备注"><Input.TextArea rows={2} /></Form.Item>
        <Alert
          type="info"
          showIcon={false}
          message={
            <span>
              实时计算预览：含税单价 <b>{fmtNum(preview.withTax, 2)}</b>，
              暂定含税合价 <b>{fmtNum(preview.total, 2)}</b>（保存时以服务端计算为准）
            </span>
          }
        />
      </Form>

      {/* 选料弹窗（单个） */}
      <Modal
        title="从物资基础库选择物资"
        open={pickerOpen}
        onCancel={() => setPickerOpen(false)}
        footer={null}
        width={760}
        destroyOnHidden
      >
        <Input.Search
          placeholder="搜索物资名称/规格/MDM/DSC编码"
          allowClear
          enterButton
          onSearch={(v) => loadBases(v)}
          onChange={(e) => { if (e.target.value) return; loadBases(''); }}
          style={{ marginBottom: 12 }}
        />
        <Space direction="vertical" style={{ width: '100%' }}>
          <TableInline baseList={baseList} baseLoading={baseLoading} onPick={(m) => { setPicked(m); setPickerOpen(false); }} />
          {baseList.length === 0 && !baseLoading && (
            <Alert type="warning" showIcon message="基础库中未找到匹配物资，请先到「物资基础库」页面维护。" />
          )}
        </Space>
      </Modal>
    </EditorTabPage>
  );
}

