/** 状态标签（需求修正6：待签章-蓝 / 已签章-绿；历史空状态与 COMPLETED 数据按待签章展示） */
function StatusTag({ status }: { status?: string | null }) {
  if (status === 'SIGNED') return <Tag color="green">已签章</Tag>;
  if (status === 'DRAFT') return <Tag color="default">草稿中</Tag>;
  return <Tag color="blue">待签章</Tag>;
}

const ACCEPT = '.pdf,.jpg,.jpeg,.png,.docx';
const MAX_SIZE = 20 * 1024 * 1024;

/**
 * 合同查询（需求 2.2 / 需求修正4/5/6；问题四：统一标准列表页规约）
 * - 展示待签章/已签章的正式合同（起草发布后自动流转至此）
 * - 筛选区：合同编号/名称关键词、供应商、签订日期范围
 * - 行操作：查看（详情抽屉）+ 更多 → 合同签章 / 新增补充协议 / 导出Word / 下载签章合同
 * - 需求 2.1：合同类型只读（后端同步校验，发布后不可修改）
 * - 需求 2.2：导出 Word 仅草稿中不可用，待签章/已签章均可导出
 * - 需求 2.3：签章时选择的签订日期覆盖合同主表签订日期
 */
export default function ContractQuery() {
  const [rows, setRows] = useState<any[]>([]);
  const [suppliers, setSuppliers] = useState<any[]>([]);
  const [listRefresh, setListRefresh] = useState(0);
  const refreshList = useCallback(() => setListRefresh((k) => k + 1), []);

  // 详情抽屉
  const [detail, setDetail] = useState<any>(null);
  const [detailOpen, setDetailOpen] = useState(false);

  // 新增补充协议抽屉
  const [suppOpen, setSuppOpen] = useState(false);
  const [suppParent, setSuppParent] = useState<any>(null);

  // 合同签章弹窗
  const [signOpen, setSignOpen] = useState(false);
  const [signTarget, setSignTarget] = useState<any>(null);
  const [signFile, setSignFile] = useState<File | null>(null);
  const [signing, setSigning] = useState(false);
  const [signForm] = Form.useForm();

  // 合同归档（单向，业务 2026-10-18）：先检查下游完整性，再确认归档
  const [archiveOpen, setArchiveOpen] = useState(false);
  const [archiveTarget, setArchiveTarget] = useState<any>(null);
  const [archiveCheckData, setArchiveCheckData] = useState<any>(null);
  const [archiving, setArchiving] = useState(false);

  /** 标准列表数据源：签订日期区间从 ${key}From/${key}To（ISO）映射为后端 signDateStart/signDateEnd */
  const fetcher = useCallback(async (params: Record<string, any>) => {
    const req: any = {
      page: params.page,
      pageSize: params.pageSize,
      keyword: params.keyword || undefined,
      supplierId: params.supplierId || undefined,
    };
    if (params.signDateFrom) req.signDateStart = String(params.signDateFrom).slice(0, 10);
    if (params.signDateTo) req.signDateEnd = String(params.signDateTo).slice(0, 10);
    const res: any = await contractApi.published(req);
    const data = res?.data ?? res;
    const list = Array.isArray(data) ? data : data?.list || [];
    setRows(list);
    return { list, total: Array.isArray(data) ? list.length : data?.total ?? list.length };
  }, []);

  useEffect(() => {
    supplierApi.options().then((res: any) => setSuppliers(res || []));
  }, []);

  const openDetail = async (id: string) => {
    const d: any = await contractApi.detail(id);
    setDetail(d);
    setDetailOpen(true);
  };

  /** 需求 2.2：草稿中不可导出 Word，待签章 / 已签章均可导出 */
  const canExportWord = (row: any) => row?.status !== 'DRAFT';

  const handleExport = (row: any) => {
    if (!canExportWord(row)) {
      message.warning('草稿中的合同不可导出，请先发布后再导出 Word 文件');
      return;
    }
    if (!row.templateId) {
      message.warning('该合同未关联合同模板，无法导出');
      return;
    }
    window.open(withToken(contractApi.exportWordUrl(row.id)));
  };

  const openSign = (row: any) => {
    setSignTarget(row);
    setSignFile(null);
    signForm.resetFields();
    // 需求 2.3：签订日期优先取合同主表 signDate，兼容历史签章记录 signedDate
    const prev = row.signDate || row.signedDate;
    signForm.setFieldsValue({
      signDate: prev ? dayjs(prev) : undefined,
      remark: row.signedRemark || '',
    });
    setSignOpen(true);
  };

  const beforeUpload = (file: File) => {
    const ok = /\.(pdf|jpe?g|png|docx)$/i.test(file.name);
    if (!ok) {
      message.error('仅支持 PDF/JPG/PNG/DOCX 格式文件');
      return Upload.LIST_IGNORE;
    }
    if (file.size > MAX_SIZE) {
      message.error('文件大小不能超过 20MB');
      return Upload.LIST_IGNORE;
    }
    setSignFile(file);
    return false; // 手动上传
  };

  const handleSign = async () => {
    if (!signTarget) return;
    const values = await signForm.validateFields();
    if (!signFile && !signTarget.signedFilePath) {
      message.warning('请上传签章合同文件');
      return;
    }
    setSigning(true);
    try {
      const fd = new FormData();
      if (signFile) fd.append('file', signFile);
      fd.append('signDate', values.signDate.format('YYYY-MM-DD'));
      fd.append('remark', values.remark || '');
      await contractApi.sign(signTarget.id, fd);
      message.success('签章信息已保存，签订日期已更新，合同状态：已签章');
      setSignOpen(false);
      setSignTarget(null);
      setSignFile(null);
      refreshList();
    } finally {
      setSigning(false);
    }
  };

  /** 任务 7：合同签章驳回 → 回退到「合同起草」（纯状态回退） */
  const handleReject = (row: any) => {
    Modal.confirm({
      title: '驳回合同签章',
      content: '确认将该合同从「待签章/已签章」驳回回「合同起草」吗？驳回后需重新发布与签章。',
      okText: '确认驳回',
      okButtonProps: { danger: true },
      cancelText: '取消',
      onOk: async () => {
        try {
          await contractApi.rejectToDraft(row.id);
          message.success('已驳回，合同回到「合同起草」');
          refreshList();
        } catch (e: any) {
          message.error(e?.message || '驳回失败');
        }
      },
    });
  };

  /** 归档前检查：拉取阻断项/提示项后再让用户确认（业务口径 2026-10-18，单向归档） */
  const openArchive = async (row: any) => {
    try {
      const check: any = await contractApi.archiveCheck(row.id);
      setArchiveTarget(row);
      setArchiveCheckData(check);
      setArchiveOpen(true);
    } catch (e: any) {
      message.error(e?.message || '归档检查失败');
    }
  };

  const handleArchive = async () => {
    if (!archiveTarget) return;
    setArchiving(true);
    try {
      await contractApi.archive(archiveTarget.id);
      message.success('合同已归档（单向归档，不提供解除归档）');
      setArchiveOpen(false);
      setArchiveTarget(null);
      setArchiveCheckData(null);
      refreshList();
    } catch (e: any) {
      message.error(e?.message || '归档失败');
    } finally {
      setArchiving(false);
    }
  };

  /** 筛选项（问题四：标准筛选区） */
  const extraFilters: ModuleListFilterField[] = [
    { key: 'keyword', label: '合同编号 / 名称', control: 'input', placeholder: '请输入关键词' },
    {
      key: 'supplierId',
      label: '供应商',
      control: 'select',
      options: suppliers.map((s: any) => ({ value: s.id, label: s.name })),
    },
    { key: 'signDate', label: '签订日期', control: 'dateRange' },
  ];

  /** 表格列（问题四：generic 模式完整列定义） */
  const extraColumns: any[] = [
    { title: '合同编号', dataIndex: 'code', width: 200, fixed: 'left' },
    { title: '合同名称', dataIndex: 'name', width: 220, ellipsis: true },
    {
      title: '供应商',
      dataIndex: ['supplier', 'name'],
      width: 170,
      ellipsis: true,
      render: (v: any) => v || '-',
    },
    {
      title: '合同类型',
      dataIndex: 'typeCode',
      width: 120,
      // 需求 2.1：合同类型只读展示（发布后不可修改）
      render: (v: any) => (v ? <DictTag typeCode="contract_type" value={v} /> : '-'),
    },
    { title: '合同金额', dataIndex: 'amount', width: 140, align: 'right' as const, render: money },
    {
      title: '签订日期',
      dataIndex: 'signDate',
      width: 120,
      // 需求 2.3：优先展示合同主表签订日期，兼容历史签章记录
      render: (v: any, row: any) => {
        const d = v || row.signedDate;
        return d ? String(d).slice(0, 10) : '-';
      },
    },
    {
      title: '状态',
      dataIndex: 'status',
      width: 100,
      render: (v: any, row: any) =>
        row.archivedAt ? <Tag color="default">已归档</Tag> : <StatusTag status={v} />,
    },
  ];

  return (
    <>
      <ModuleListPage
        mode="generic"
        columnConfigKey="contract.query"
        fetcher={fetcher}
        extraFilters={extraFilters}
        extraColumns={extraColumns}
        refreshKey={listRefresh}
        emptyText="暂无合同数据"
        editPermission="contract:edit"
        onView={(row) => openDetail(row.id)}
        rowMenuItems={(row: ModuleListRow, { canEdit }) => {
          const r = row as any;
          // 归档合同是单向终态：签章/驳回/补充协议/归档入口全部隐藏（读取/导出仍可用）；
          // 无 contract:edit 的只读用户同样不显示这些写操作
          const locked = !!r.archivedAt || !canEdit;
          return [
          ...(!locked
            ? [
                {
                  key: 'sign',
                  label: (
                    <span>
                      <FileProtectOutlined /> {row.status === 'SIGNED' ? '重新签章' : '合同签章'}
                    </span>
                  ),
                  onClick: () => openSign(row),
                },
              ]
            : []),
          // 任务 7：仅「待签章 / 已签章」可驳回回合同起草
          ...(!locked && (r.status === 'APPROVING' || r.status === 'SIGNED')
            ? [
                {
                  key: 'reject',
                  label: (
                    <span>
                      <RollbackOutlined /> 驳回回合同起草
                    </span>
                  ),
                  onClick: () => handleReject(r),
                },
              ]
            : []),
          ...(!locked
            ? [
                {
                  key: 'supplement',
                  label: (
                    <span>
                      <PlusSquareOutlined /> 新增补充协议
                    </span>
                  ),
                  onClick: () => { setSuppParent(row); setSuppOpen(true); },
                },
              ]
            : []),
          {
            key: 'exportWord',
            label: (
              <span>
                <FileWordOutlined /> 导出Word
              </span>
            ),
            disabled: !canExportWord(r) || !r.templateId,
            onClick: () => handleExport(r),
          },
          ...(r.signedFilePath
            ? [
                {
                  key: 'downloadSigned',
                  label: (
                    <span>
                      <ExportOutlined /> 下载签章合同
                    </span>
                  ),
                  onClick: () => window.open(withToken(contractApi.signedFileUrl(row.id))),
                },
              ]
            : []),
          // 归档（单向）：已归档合同不再显示入口
          ...(!r.archivedAt
            ? [
                {
                  key: 'archive',
                  label: (
                    <span>
                      <FileProtectOutlined /> 归档合同
                    </span>
                  ),
                  onClick: () => openArchive(r),
                },
              ]
            : []),
          ];
        }}
      />

      {/* ==================== 合同签章弹窗（需求修正4） ==================== */}
      <Modal
        title={
          <Space>
            <FileProtectOutlined />
            <span>合同签章</span>
            {signTarget?.status === 'SIGNED' && <Tag color="green">已签章 · 可重新上传覆盖</Tag>}
          </Space>
        }
        open={signOpen}
        onCancel={() => { setSignOpen(false); setSignTarget(null); setSignFile(null); }}
        onOk={handleSign}
        confirmLoading={signing}
        okText="保存签章信息"
        width={560}
        destroyOnHidden
      >
        <Form form={signForm} layout="vertical">
          <Form.Item label="合同编号">
            <Input value={signTarget?.code} disabled />
          </Form.Item>
          <Form.Item label="合同名称">
            <Input value={signTarget?.name} disabled />
          </Form.Item>
          <Form.Item
            name="signDate"
            label="签订日期"
            rules={[{ required: true, message: '请选择签订日期' }]}
            extra="保存后将以本次选择的日期覆盖该合同的签订日期"
          >
            <DatePicker format="YYYY-MM-DD" style={{ width: '100%' }} placeholder="YYYY-MM-DD" />
          </Form.Item>
          <Form.Item
            label="签章合同文件"
            required={!signTarget?.signedFilePath}
            extra="支持 PDF / JPG / PNG / DOCX，单个文件不超过 20MB；已签章的合同可重新上传覆盖"
          >
            <Upload.Dragger
              accept={ACCEPT}
              maxCount={1}
              beforeUpload={beforeUpload}
              onRemove={() => setSignFile(null)}
              fileList={signFile ? [{ uid: '-1', name: signFile.name, status: 'done' }] as any : []}
            >
              <p className="ant-upload-drag-icon">
                <UploadOutlined />
              </p>
              <p className="ant-upload-text">点击或拖拽文件到此处上传</p>
            </Upload.Dragger>
          </Form.Item>
          {(signTarget?.signDate || signTarget?.signedDate) && (
            <Form.Item label="当前签章信息">
              <Space wrap>
                <Tag color="green">
                  签订日期：{String(signTarget.signDate || signTarget.signedDate).slice(0, 10)}
                </Tag>
                {signTarget.signedAt && (
                  <Tag>签章时间：{String(signTarget.signedAt).slice(0, 19).replace('T', ' ')}</Tag>
                )}
                {signTarget.signedFileName && <Tag>{signTarget.signedFileName}</Tag>}
              </Space>
            </Form.Item>
          )}
          <Form.Item name="remark" label="备注">
            <Input.TextArea rows={2} placeholder="选填" />
          </Form.Item>
        </Form>
      </Modal>

      {/* 合同归档（单向，业务口径 2026-10-18） */}
      <Modal
        title={
          <Space>
            <FileProtectOutlined />
            <span>归档合同</span>
            {archiveTarget?.code && <Tag color="geekblue">{archiveTarget.code}</Tag>}
          </Space>
        }
        open={archiveOpen}
        onCancel={() => { setArchiveOpen(false); setArchiveTarget(null); setArchiveCheckData(null); }}
        onOk={handleArchive}
        confirmLoading={archiving}
        okText="确认归档"
        okButtonProps={{ danger: true, disabled: !archiveCheckData?.canArchive }}
        width={560}
        destroyOnHidden
      >
        {archiveCheckData?.canArchive ? (
          <Alert
            type="warning"
            showIcon
            message="归档后不可解除"
            description="归档将锁定合同、收领单、结算与总结算的写操作；发票与付款仍可补录，读取/导出不受影响。"
          />
        ) : (
          <Alert
            type="error"
            showIcon
            message="存在未完成事项，暂不能归档"
            description={
              <ul style={{ margin: 0, paddingLeft: 18 }}>
                {(archiveCheckData?.blockers || []).map((b: string, i: number) => (
                  <li key={i}>{b}</li>
                ))}
              </ul>
            }
          />
        )}
        {!!archiveCheckData?.warnings?.length && (
          <Alert
            type="info"
            showIcon
            style={{ marginTop: 12 }}
            message="提示（不阻断归档）"
            description={
              <ul style={{ margin: 0, paddingLeft: 18 }}>
                {archiveCheckData.warnings.map((w: string, i: number) => (
                  <li key={i}>{w}</li>
                ))}
              </ul>
            }
          />
        )}
      </Modal>

      {/* 合同详情（问题三：居中弹窗） */}
      <Modal
        title={
          <Space>
            <span>合同详情</span>
            {detail?.code && <Tag color="geekblue">{detail.code}</Tag>}
            {detail && <StatusTag status={detail.status} />}
          </Space>
        }
        width={640}
        centered
        open={detailOpen}
        onCancel={() => setDetailOpen(false)}
        footer={null}
        styles={{ body: { maxHeight: 'calc(100vh - 220px)', overflowY: 'auto' } }}
      >
        {detail && (
          <Space direction="vertical" size={12} style={{ width: '100%' }}>
            <Space>
              {!detail.archivedAt && (
                <Button icon={<FileProtectOutlined />} size="small" onClick={() => { setDetailOpen(false); openSign(detail); }}>
                  合同签章
                </Button>
              )}
              {detail && canExportWord(detail) && (
                <Button icon={<ExportOutlined />} size="small" onClick={() => handleExport(detail)}>
                  导出Word
                </Button>
              )}
            </Space>
            <ContractQueryDetailBody detail={detail} />
          </Space>
        )}
      </Modal>

      <SupplementDraft
        parent={suppParent}
        open={suppOpen}
        onClose={() => setSuppOpen(false)}
        onDone={() => { setSuppOpen(false); refreshList(); }}
      />
    </>
  );
}

/** 详情弹窗正文：列数按弹窗容器宽度降级（DESIGN.md §10.2；窄容器单列） */
function ContractQueryDetailBody({ detail }: { detail: any }) {
  const { ref, size } = useContainerWidth<HTMLDivElement>();
  /** 履约进度（零表派生；取数失败不阻断详情展示） */
  const [fulfillment, setFulfillment] = useState<any>(null);
  useEffect(() => {
    let alive = true;
    contractApi
      .fulfillment(detail.id)
      .then((d: any) => alive && setFulfillment(d))
      .catch(() => {});
    return () => {
      alive = false;
    };
  }, [detail.id]);

  const pct = (v: number | null | undefined) =>
    v == null ? '-' : `${(v * 100).toFixed(1)}%`;
  const qty = (v: number | null | undefined) =>
    v == null ? '-' : Number(v).toLocaleString('zh-CN', { maximumFractionDigits: 4 });

  return (
    <div ref={ref} className="cq" style={{ width: '100%' }}>
      {detail.archivedAt && (
        <Alert
          type="warning"
          showIcon
          style={{ marginBottom: 12 }}
          message={`该合同已归档（${detail.archivedBy || '—'} · ${String(detail.archivedAt).slice(0, 10)}），业务单据已锁定；发票/付款仍可补录`}
        />
      )}
      <Card size="small" title="履约进度（派生）" style={{ marginBottom: 12 }}>
        {fulfillment ? (
          <>
            <Descriptions column={size.isNarrow ? 1 : 2} size="small">
              <Descriptions.Item label="合同当前金额">
                {money(fulfillment.currentAmount)}
              </Descriptions.Item>
              <Descriptions.Item label="已收数量">
                {qty(fulfillment.receivedQty)} / {qty(fulfillment.orderedQty)}
              </Descriptions.Item>
              <Descriptions.Item label="已结金额">
                {money(fulfillment.settledAmount)}（{pct(fulfillment.settledRatio)}）
              </Descriptions.Item>
              <Descriptions.Item label="已付金额">
                {money(fulfillment.paidAmount)}（占已结 {pct(fulfillment.paidVsSettledRatio)} / 占合同{' '}
                {pct(fulfillment.paidVsContractRatio)}）
              </Descriptions.Item>
              <Descriptions.Item label="已开票金额">
                {money(fulfillment.invoicedAmount)}（{pct(fulfillment.invoiceRatio)}）
              </Descriptions.Item>
              <Descriptions.Item label="未收数量 / 待结 / 未付">
                {qty(fulfillment.remainingToReceiveQty)} / {money(fulfillment.remainingToSettleAmount)} /{' '}
                {money(fulfillment.unpaidAmount)}
              </Descriptions.Item>
            </Descriptions>
            {fulfillment.receivedRatio != null && (
              <Progress
                style={{ marginTop: 8 }}
                percent={Math.min(100, Number((fulfillment.receivedRatio * 100).toFixed(1)))}
                format={() => `收货 ${pct(fulfillment.receivedRatio)}`}
              />
            )}
            {fulfillment.hasReceiptNoSettlement && (
              <Alert type="warning" showIcon style={{ marginTop: 8 }} message="已有收货但尚无结算，请检查是否漏生成结算单" />
            )}
            {fulfillment.hasSettlementNoPayment && (
              <Alert type="warning" showIcon style={{ marginTop: 8 }} message="已有结算但尚无付款" />
            )}
          </>
        ) : (
          <span>加载中…</span>
        )}
      </Card>
      <MilestoneCard contractId={detail.id} archived={!!detail.archivedAt} />

      <Descriptions column={size.isNarrow ? 1 : 2} size="small" bordered>
        <Descriptions.Item label="合同编号">{detail.code}</Descriptions.Item>
        <Descriptions.Item label="合同名称">{detail.name}</Descriptions.Item>
        <Descriptions.Item label="供应商">{detail.supplier?.name || '-'}</Descriptions.Item>
        <Descriptions.Item label="合同类型（只读）">
          {detail.typeCode ? <DictTag typeCode="contract_type" value={detail.typeCode} /> : '-'}
        </Descriptions.Item>
        <Descriptions.Item label="签订日期">
          {detail.signDate || detail.signedDate
            ? String(detail.signDate || detail.signedDate).slice(0, 10)
            : '未签订'}
        </Descriptions.Item>
        {detail.signedAt && (
          <Descriptions.Item label="签章操作时间">
            {String(detail.signedAt).slice(0, 19).replace('T', ' ')}
          </Descriptions.Item>
        )}
        <Descriptions.Item label="合同金额">{money(detail.amount)}</Descriptions.Item>
        <Descriptions.Item label="执行状态">
          {detail.execStatus ? <DictTag typeCode="contract_execution_status" value={detail.execStatus} /> : '-'}
        </Descriptions.Item>
        <Descriptions.Item label="关联合同模板">{detail.templateId || '未关联'}</Descriptions.Item>
        <Descriptions.Item label="签章文件">
          {detail.signedFilePath ? (
            <a onClick={() => window.open(withToken(contractApi.signedFileUrl(detail.id)))}>
              {detail.signedFileName || '下载签章合同'}
            </a>
          ) : (
            '未上传'
          )}
        </Descriptions.Item>
        {detail.signedRemark && (
          <Descriptions.Item label="签章备注">{detail.signedRemark}</Descriptions.Item>
        )}
        <Descriptions.Item label="创建时间">
          {detail.createdAt ? String(detail.createdAt).slice(0, 19).replace('T', ' ') : '-'}
        </Descriptions.Item>
        <Descriptions.Item label="备注">{detail.remark || '-'}</Descriptions.Item>
      </Descriptions>
    </div>
  );
}


/** 履约节点（四域扩展按需项 2026-10-18）：计划 vs 实际时间线；逾期派生标红 */
function MilestoneCard({ contractId, archived }: { contractId: string; archived: boolean }) {
  const canEdit = usePermission('contract:edit') && !archived;
  const [rows, setRows] = useState<any[] | null>(null);
  const [editing, setEditing] = useState(false);
  const [form] = Form.useForm();

  const load = useCallback(() => {
    contractApi
      .milestones(contractId)
      .then((d: any) => setRows(d || []))
      .catch(() => setRows([]));
  }, [contractId]);
  useEffect(() => load(), [load]);

  const submit = async () => {
    const values = await form.validateFields();
    try {
      await contractApi.createMilestone(contractId, {
        ...values,
        planDate: values.planDate ? values.planDate.format('YYYY-MM-DD') : null,
        actualDate: values.actualDate ? values.actualDate.format('YYYY-MM-DD') : null,
      });
      message.success('已添加履约节点');
      setEditing(false);
      form.resetFields();
      load();
    } catch (e: any) {
      message.error(e?.message || '保存失败');
    }
  };

  const markDone = async (m: any) => {
    try {
      await contractApi.updateMilestone(contractId, m.id, {
        statusCode: 'DONE',
        actualDate: dayjs().format('YYYY-MM-DD'),
        version: m.version,
      });
      load();
    } catch (e: any) {
      message.error(e?.message || '操作失败');
    }
  };

  /** 节点不再可能发生（计划取消等）→ 标记跳过；SKIPPED 不参与逾期派生 */
  const markSkipped = async (m: any) => {
    try {
      await contractApi.updateMilestone(contractId, m.id, { statusCode: 'SKIPPED', version: m.version });
      load();
    } catch (e: any) {
      message.error(e?.message || '操作失败');
    }
  };

  /** 编辑节点名/计划日期/责任人（此前只有「标记完成」，计划日期填错无法修正） */
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editForm] = Form.useForm();
  const startEdit = (m: any) => {
    setEditingId(m.id);
    editForm.setFieldsValue({
      name: m.name,
      planDate: m.planDate ? dayjs(m.planDate) : undefined,
      owner: m.owner,
    });
  };
  const submitEdit = async () => {
    if (!editingId) return;
    let values: any;
    try {
      values = await editForm.validateFields();
    } catch {
      return; // 行内校验错误已由表单展示
    }
    const m = (rows || []).find((x) => x.id === editingId);
    try {
      await contractApi.updateMilestone(contractId, editingId, {
        name: values.name,
        planDate: values.planDate ? values.planDate.format('YYYY-MM-DD') : null,
        owner: values.owner ?? null,
        version: m?.version,
      });
      message.success('已更新履约节点');
      setEditingId(null);
      load();
    } catch (e: any) {
      message.error(e?.message || '保存失败');
    }
  };

  const remove = (m: any) => {
    Modal.confirm({
      title: '删除履约节点',
      content: `确认删除「${m.name}」吗？`,
      okType: 'danger',
      onOk: async () => {
        await contractApi.removeMilestone(contractId, m.id);
        message.success('已删除');
        load();
      },
    });
  };

  const colorOf = (m: any) => (m.overdue ? 'red' : m.statusCode === 'DONE' ? 'green' : 'blue');

  return (
    <Card
      size="small"
      title="履约节点"
      style={{ marginBottom: 12 }}
      extra={
        canEdit && !editing ? (
          <Button size="small" type="link" onClick={() => setEditing(true)}>
            添加节点
          </Button>
        ) : undefined
      }
    >
      {editing && (
        <Form form={form} layout="inline" style={{ marginBottom: 12, rowGap: 8 }} onFinish={submit}>
          <Form.Item name="name" rules={[{ required: true, message: '请输入节点名' }]}>
            <Input placeholder="节点名" style={{ width: 140 }} />
          </Form.Item>
          <Form.Item name="planDate">
            <DatePicker placeholder="计划日期" style={{ width: 130 }} />
          </Form.Item>
          <Form.Item name="owner">
            <Input placeholder="责任人" style={{ width: 110 }} />
          </Form.Item>
          <Button type="primary" htmlType="submit" size="small">
            保存
          </Button>
          <Button size="small" onClick={() => setEditing(false)}>
            取消
          </Button>
        </Form>
      )}
      {rows === null ? (
        <span>加载中…</span>
      ) : rows.length === 0 ? (
        <span>暂无履约节点</span>
      ) : (
        <Timeline
          items={rows.map((m) => ({
            color: colorOf(m),
            children: editingId === m.id ? (
              <Form form={editForm} layout="inline" style={{ rowGap: 4 }} onFinish={submitEdit}>
                <Form.Item name="name" rules={[{ required: true, message: '请输入节点名' }]}>
                  <Input placeholder="节点名" style={{ width: 130 }} size="small" />
                </Form.Item>
                <Form.Item name="planDate">
                  <DatePicker placeholder="计划日期" style={{ width: 130 }} size="small" />
                </Form.Item>
                <Form.Item name="owner">
                  <Input placeholder="责任人" style={{ width: 100 }} size="small" />
                </Form.Item>
                <Button type="primary" htmlType="submit" size="small">保存</Button>
                <Button size="small" onClick={() => setEditingId(null)}>取消</Button>
              </Form>
            ) : (
              <Space size={8} wrap>
                <span>{m.name}</span>
                {m.planDate && <span>计划 {String(m.planDate).slice(0, 10)}</span>}
                {m.actualDate && <span>实际 {String(m.actualDate).slice(0, 10)}</span>}
                {m.owner && <span>{m.owner}</span>}
                {m.overdue && <Tag color="red">逾期</Tag>}
                {m.statusCode === 'SKIPPED' && <Tag>已跳过</Tag>}
                {canEdit && m.statusCode !== 'DONE' && m.statusCode !== 'SKIPPED' && (
                  <>
                    <a onClick={() => markDone(m)}>标记完成</a>
                    <a onClick={() => markSkipped(m)}>跳过</a>
                  </>
                )}
                {canEdit && editingId !== m.id && <a onClick={() => startEdit(m)}>编辑</a>}
                {canEdit && <a onClick={() => remove(m)}>删除</a>}
              </Space>
            ),
          }))}
        />
      )}
    </Card>
  );
}

import { useEffect, useMemo, useState } from 'react';
import { Button, Input, InputNumber, Modal, Select, Space, Table, message } from 'antd';
import { DownloadOutlined, PlusOutlined, ReloadOutlined } from '@ant-design/icons';
import { costApi } from '@/api/modules';
import ModuleListPage, { type ModuleListFilterField, type ModuleListRow } from '@/components/procurement/ModuleListPage';
import EditorTabPage from '@/components/editor/EditorTabPage';
import { useEditorTab, useTabRefresh } from '@/hooks/useTabs';
import { usePermission } from '@/hooks/usePermission';
import { withToken } from '@/utils/download';

/**
 * 成本管理 · 月度盈亏分析（附件需求 2026-10-17 第三批；替换原手工台账）。
 * **一个月一条记录**：新建时选结算期 → 服务端把当期各分包单位「甲供材节超分析」行快照成明细；
 * 快照的单价/数量冻结（只读），只有责任人/劳务计价已扣/备注可手改；「重新抓取」重算快照
 * （手填项按 分包单位+材料+规格 回填）。
 * 导出 xlsx 三 sheet：封面 / 明细表 / 汇总表（按材料跨队加权汇总）。
 */
const LIST_PATH = '/cost/profit-loss';

const money = (v: any) => (v == null ? '-' : Number(v).toLocaleString('zh-CN', { minimumFractionDigits: 2 }));
const qty = (v: any) => (v == null ? '-' : Number(v).toLocaleString('zh-CN', { maximumFractionDigits: 3 }));

export default function CostProfitLoss() {
  const editorTab = useEditorTab(LIST_PATH);
  if (editorTab.isEditor && editorTab.editorId && editorTab.editorId !== 'new') {
    return <ProfitEditor id={editorTab.editorId} />;
  }
  return <ProfitList />;
}

function ProfitList() {
  const editorTab = useEditorTab(LIST_PATH);
  const canEdit = usePermission('cost:edit');
  const tabRefresh = useTabRefresh(LIST_PATH);
  const [listRefresh, setListRefresh] = useState(0);
  const [creating, setCreating] = useState(false);
  const refreshList = () => setListRefresh((k) => k + 1);

  const handleRemove = (row: ModuleListRow) => {
    Modal.confirm({
      title: `确认删除该盈亏分析记录？（明细一并删除）`,
      okText: '确认删除',
      okType: 'danger',
      onOk: async () => {
        await costApi.monthlyProfitLoss.remove(row.id);
        message.success('已删除');
        refreshList();
      },
    });
  };

  const extraFilters: ModuleListFilterField[] = [
    { key: 'period', label: '结算期', control: 'input', placeholder: '如 2026-10' },
  ];

  const extraColumns: any[] = [
    { title: '结算期', dataIndex: 'period', width: 110, fixed: 'left' as const },
    { title: '明细行数', dataIndex: 'detailCount', width: 90, align: 'right' as const },
    {
      title: '六项降本创效金额',
      dataIndex: 'sixSavingsAmount',
      width: 140,
      align: 'right' as const,
      className: 'col-secondary',
      render: (v: any) => (v == null ? '-' : money(v)),
    },
    {
      title: '劳务计价累计扣款',
      dataIndex: 'totalDeductAmount',
      width: 140,
      align: 'right' as const,
      className: 'col-secondary',
      render: (v: any) => (v == null ? '-' : money(v)),
    },
    { title: '备注', dataIndex: 'remark', width: 160, ellipsis: true, render: (v: any) => v || '-' },
  ];

  return (
    <ModuleListPage
      mode="generic"
      columnConfigKey="cost.monthlyProfitLoss"
      fetcher={(params) => costApi.monthlyProfitLoss.list(params)}
      extraFilters={extraFilters}
      extraColumns={extraColumns}
      refreshKey={listRefresh + tabRefresh}
      emptyText="暂无月度盈亏分析记录"
      editPermission="cost:edit"
      onEdit={(row) => editorTab.openEdit(row.id, row)}
      onDelete={handleRemove}
      toolbarLeft={
        canEdit ? (
          <CreateButton
            creating={creating}
            setCreating={setCreating}
            onCreated={(id, seed) => {
              refreshList();
              editorTab.openEdit(id, seed);
            }}
          />
        ) : null
      }
    />
  );
}

/** 新建：选结算期（只列尚无记录的期），确定即创建并生成快照 */
function CreateButton({
  creating,
  setCreating,
  onCreated,
}: {
  creating: boolean;
  setCreating: (v: boolean) => void;
  onCreated: (id: string, seed: any) => void;
}) {
  const [open, setOpen] = useState(false);
  const [periods, setPeriods] = useState<string[]>([]);
  const [period, setPeriod] = useState<string>();
  const [saving, setSaving] = useState(false);

  const openDialog = async () => {
    setOpen(true);
    setPeriod(undefined);
    const [opts, list]: any[] = await Promise.all([
      costApi.laborReceiving.options(),
      costApi.monthlyProfitLoss.list({ pageSize: 500 }),
    ]);
    const existing = new Set((list?.list || []).map((r: any) => r.period));
    setPeriods((opts?.periods || []).filter((p: string) => !existing.has(p)));
  };

  const doCreate = async () => {
    if (!period) return;
    setSaving(true);
    try {
      const created: any = await costApi.monthlyProfitLoss.create({ period });
      message.success('已生成当期快照');
      setOpen(false);
      onCreated(created.id, created);
    } finally {
      setSaving(false);
    }
  };

  return (
    <>
      <Button type="primary" icon={<PlusOutlined />} loading={creating} onClick={openDialog}>
        新增月度分析
      </Button>
      <Modal
        title="新增月度盈亏分析"
        open={open}
        onCancel={() => setOpen(false)}
        onOk={doCreate}
        okButtonProps={{ disabled: !period, loading: saving }}
        okText="生成快照"
      >
        <Space direction="vertical" style={{ width: '100%', marginTop: 8 }}>
          <Select
            showSearch
            style={{ width: '100%' }}
            placeholder="选择结算期（来自分包单位领用汇总已有期间）"
            value={period}
            options={periods.map((p) => ({ value: p, label: p }))}
            onChange={setPeriod}
          />
          {periods.length === 0 && (
            <span>没有可用的结算期——请先在「分包单位领用汇总」里选择分包单位与账期生成数据。</span>
          )}
        </Space>
      </Modal>
    </>
  );
}

function ProfitEditor({ id }: { id: string }) {
  const [rec, setRec] = useState<any>(null);
  const [details, setDetails] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [dirty, setDirty] = useState(false);

  const load = async () => {
    setLoading(true);
    try {
      const res: any = await costApi.monthlyProfitLoss.detail(id);
      setRec(res);
      setDetails(res.details || []);
      setDirty(false);
    } finally {
      setLoading(false);
    }
  };
  useEffect(() => {
    if (id) load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  const patchDetail = (did: string, patch: any) => {
    setDetails((prev) => prev.map((d) => (d.id === did ? { ...d, ...patch, _dirty: true } : d)));
    setDirty(true);
  };

  const save = async () => {
    setSaving(true);
    try {
      const changed = details.filter((d: any) => d._dirty);
      const res: any = await costApi.monthlyProfitLoss.update(id, {
        sixSavingsAmount: rec?.sixSavingsAmount,
        totalDeductAmount: rec?.totalDeductAmount,
        remark: rec?.remark,
        version: rec?.version,
        details: changed.map((d: any) => ({ ...d, _dirty: undefined })),
      });
      setRec(res);
      setDetails(res.details || []);
      setDirty(false);
      message.success('保存成功');
    } finally {
      setSaving(false);
    }
  };

  const doReSnapshot = () => {
    Modal.confirm({
      title: '重新抓取当期快照？',
      content: '手填项（责任人/劳务计价已扣/备注）按 分包单位+材料+规格 自动回填，快照列以当期最新数据重算。',
      onOk: async () => {
        const res: any = await costApi.monthlyProfitLoss.reSnapshot(id);
        setRec(res);
        setDetails(res.details || []);
        setDirty(false);
        message.success('已重新抓取');
      },
    });
  };

  const columns = useMemo(
    () => [
      { title: '序号', width: 55, render: (_: any, __: any, i: number) => i + 1 },
      { title: '材料名称', dataIndex: 'materialName', width: 130, fixed: 'left' as const },
      { title: '规格型号', dataIndex: 'spec', width: 130, render: (v: string) => v || '-' },
      { title: '单位', dataIndex: 'unit', width: 65, render: (v: string) => v || '-' },
      {
        title: '单价',
        dataIndex: 'unitPrice',
        width: 110,
        render: (v: number | null) => money(v),
      },
      {
        title: '进场量',
        dataIndex: 'entryQty',
        width: 100,
        align: 'right' as const,
        render: qty,
      },
      { title: '进场金额', dataIndex: 'entryAmount', width: 110, align: 'right' as const, className: 'col-secondary', render: (v: any, d: any) => money(d.entryQty != null && d.unitPrice != null ? d.entryQty * d.unitPrice : null) },
      {
        title: '设计量',
        dataIndex: 'designQty',
        width: 100,
        align: 'right' as const,
        render: qty,
      },
      {
        title: '损耗率%',
        dataIndex: 'lossRate',
        width: 95,
        align: 'right' as const,
        className: 'col-secondary',
      },
      { title: '理论消耗量', dataIndex: 'theoryUseQty', width: 110, align: 'right' as const, render: qty },
      {
        title: '实际消耗量',
        dataIndex: 'actualUseQty',
        width: 110,
        align: 'right' as const,
        render: qty,
      },
      {
        title: '库存量',
        dataIndex: 'stockQty',
        width: 100,
        align: 'right' as const,
        render: qty,
      },
      {
        title: '盈(+)/亏(-)',
        dataIndex: 'saveOverQty',
        width: 110,
        align: 'right' as const,
        render: (v: number | null) => (v == null ? '-' : v.toFixed(3)),
      },
      { title: '盈亏金额', dataIndex: 'saveOverAmount', width: 110, align: 'right' as const, render: money },
      {
        title: '节超率',
        dataIndex: 'saveRate',
        width: 90,
        align: 'right' as const,
        className: 'col-secondary',
        render: (v: any) => (v == null ? '-' : `${(Number(v) * 100).toFixed(2)}%`),
      },
      { title: '劳务队名称', dataIndex: 'laborTeamName', width: 150 },
      {
        title: '责任人',
        dataIndex: 'owner',
        width: 110,
        render: (v: string, d: any) => (
          <Input size="small" value={v} onChange={(e) => patchDetail(d.id, { owner: e.target.value })} />
        ),
      },
      {
        title: '劳务计价已扣',
        dataIndex: 'deductAmount',
        width: 120,
        render: (v: number | null, d: any) => (
          <InputNumber size="small" style={{ width: '100%' }} value={v} onChange={(val) => patchDetail(d.id, { deductAmount: val })} />
        ),
      },
      {
        title: '备注',
        dataIndex: 'remark',
        width: 150,
        render: (v: string, d: any) => (
          <Input size="small" value={v} onChange={(e) => patchDetail(d.id, { remark: e.target.value })} />
        ),
      },
    ],
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [details],
  );

  return (
    <EditorTabPage
      listPath={LIST_PATH}
      title={rec ? `月度盈亏分析 · ${rec.period}` : '月度盈亏分析'}
      saving={saving}
      dirty={dirty}
      closeOnSave={false}
      onSave={save}
      footerExtra={
        <Space wrap>
          <Button icon={<ReloadOutlined />} onClick={doReSnapshot} disabled={!rec}>
            重新抓取
          </Button>
          <Button
            icon={<DownloadOutlined />}
            disabled={!rec}
            onClick={() => window.open(withToken(costApi.monthlyProfitLoss.exportUrl(id)))}
          >
            导出 Excel（封面/明细/汇总）
          </Button>
        </Space>
      }
    >
      {rec && (
        <Space wrap style={{ marginBottom: 12 }}>
          <label>
            六项降本创效金额：
            <InputNumber
              style={{ width: 160 }}
              value={rec.sixSavingsAmount}
              onChange={(v) => {
                setRec({ ...rec, sixSavingsAmount: v });
                setDirty(true);
              }}
            />
          </label>
          <label>
            劳务计价累计扣款金额：
            <InputNumber
              style={{ width: 160 }}
              value={rec.totalDeductAmount}
              onChange={(v) => {
                setRec({ ...rec, totalDeductAmount: v });
                setDirty(true);
              }}
            />
          </label>
          <Input
            style={{ width: 240 }}
            placeholder="备注"
            value={rec.remark}
            onChange={(e) => {
              setRec({ ...rec, remark: e.target.value });
              setDirty(true);
            }}
          />
        </Space>
      )}
      <Table
        rowKey="id"
        size="small"
        loading={loading}
        columns={columns}
        dataSource={details}
        pagination={false}
        scroll={{ x: 2200 }}
        locale={{ emptyText: '当期没有节超数据（先在「分包单位领用汇总」填好当期数据，或点「重新抓取」）' }}
      />
    </EditorTabPage>
  );
}

import { useEffect, useState } from 'react';
import { message } from 'antd';
import { useNavigate } from 'react-router-dom';
import { Button, Card, Col, Row, Space, Statistic, List, Tag, Spin } from 'antd';
import { FileTextOutlined, AccountBookOutlined, WalletOutlined } from '@ant-design/icons';
import ReactECharts from 'echarts-for-react';
import { dashboardApi } from '@/api/modules';
import { useDictStore } from '@/store/dict';
import { chartPalette } from '@/theme';
import { useContainerWidth } from '@/hooks/useContainerWidth';
import { useTabRefresh } from '@/hooks/useTabs';
import { LIST_PATHS } from '@/constants/listPaths';
import EmptyState from '@/components/EmptyState';
import { TodoCard, DashboardNoticeModal } from './dashboardTodo';

const money = (v: number) => `¥${(v || 0).toLocaleString('zh-CN', { maximumFractionDigits: 2 })}`;

export default function Dashboard() {
  const navigate = useNavigate();
  const [overview, setOverview] = useState<any>({});
  const [trend, setTrend] = useState<any[]>([]);
  const [typeStat, setTypeStat] = useState<any[]>([]);
  const [reminders, setReminders] = useState<any>({});
  /** 我的待办聚合数据（TodoCard 与"当天首次浮窗"共用，避免两份请求） */
  const [todoData, setTodoData] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const label = useDictStore((s) => s.label);
  const ensure = useDictStore((s) => s.ensure);
  /** 发票作废/红冲等跨标签动作会 bump 本路径：缓存页不会重挂载，靠令牌重新取数 */
  const tabRefresh = useTabRefresh(LIST_PATHS.dashboard);

  useEffect(() => {
    ensure(['contract_type']);
    Promise.all([
      dashboardApi.overview(),
      dashboardApi.trend(),
      dashboardApi.contractType(),
      dashboardApi.reminders(),
      dashboardApi.todos(),
    ])
      .then(([o, t, c, r, td]) => {
        setOverview(o || {});
        setTrend((t as any[]) || []);
        setTypeStat((c as any[]) || []);
        setReminders((r as any) || {});
        setTodoData(td || { groups: [], total: 0 });
      })
      /**
       * 第 8 轮审计：原来没有 catch —— 任一接口失败（比如 todos 500）整段 then 都不执行，
       * finally 照样把 loading 关掉，于是 KPI/趋势/待办全渲染成 0 与空图，
       * 用户分不清「没有数据」和「取数失败」，控制台还留一条 unhandled rejection。
       */
      .catch((e: any) => {
        message.error(e?.message ? `工作台数据加载失败：${e.message}` : '工作台数据加载失败，请稍后重试');
      })
      .finally(() => setLoading(false));
  }, [tabRefresh]);

  const { ref: trendRef, size: trendSize } = useContainerWidth<HTMLDivElement>();
  const { ref: pieRef, size: pieSize } = useContainerWidth<HTMLDivElement>();

  /**
   * 图表按**自身容器宽度**降级（DESIGN.md §10.2）：ECharts 的图例/标签/边距都是 JS 选项，
   * CSS 的 `@container` 驱动不了 —— 图表的"响应式"必须落在 JS，故这里用 `useContainerWidth()`，
   * 且量的是**卡片**宽度而不是视口：`lg=8` 侧列卡片只有 ~380px，按视口它会以为自己在大屏上。
   */
  const trendOption = {
    tooltip: { trigger: 'axis' },
    legend: {
      data: ['结算金额', '付款金额'],
      ...(trendSize.isNarrow ? { itemWidth: 14, itemHeight: 8, textStyle: { fontSize: 11 } } : {}),
    },
    // 窄容器里默认的左 60 / 右 20 边距会吃掉本就不多的绘图区
    grid: trendSize.isNarrow
      ? { left: 44, right: 8, top: 34, bottom: 26 }
      : { left: 60, right: 20, top: 40, bottom: 30 },
    xAxis: { type: 'category', data: trend.map((t) => t.month) },
    yAxis: { type: 'value' },
    series: [
      { name: '结算金额', type: 'line', smooth: true, data: trend.map((t) => t.settleAmount), itemStyle: { color: chartPalette[0] } },
      { name: '付款金额', type: 'bar', data: trend.map((t) => t.paidAmount), itemStyle: { color: chartPalette[1] } },
    ],
  };

  const typeOption = {
    tooltip: { trigger: 'item' },
    legend: {
      bottom: 0,
      ...(pieSize.isNarrow ? { itemWidth: 10, itemHeight: 8, textStyle: { fontSize: 11 } } : {}),
    },
    // 系列配色统一取 theme 的 chartPalette（珊瑚 → 青 → 琥珀 → 绿 → 深墨 → 红）
    color: [...chartPalette],
    series: [
      {
        type: 'pie',
        radius: ['40%', '70%'],
        // 窄容器：扇形上的标签会互相压字 → 关掉标签、把识别交给图例与 tooltip
        label: pieSize.isNarrow ? { show: false } : undefined,
        labelLine: pieSize.isNarrow ? { show: false } : undefined,
        data: typeStat.map((t) => ({ name: label('contract_type', t.typeCode), value: t.amount })),
      },
    ],
  };

  /** 金额预警（业务口径 2026-10-15）：红/黄分级由后端按合同当前金额与补充协议占比算好 */
  const alertList: any[] = reminders.amountAlerts || [];
  /** 付款超比例预警（业务口径 2026-10-16）与上面的金额预警是**两个信号**，分列展示 */
  const payAlertList: any[] = reminders.paymentRatioAlerts || [];
  const alertRed = alertList.filter((a: any) => a.level === 'RED').length;
  const alertYellow = alertList.filter((a: any) => a.level === 'YELLOW').length;

  if (loading) return <Spin style={{ width: '100%', marginTop: 80 }} />;

  return (
    <>
      {/* 超时草稿提醒已并入「我的待办 · 合同起草」分类（避免同一信息两处提示） */}
      <DashboardNoticeModal data={todoData} loading={loading} />
      <Row gutter={[16, 16]}>
        <Col xs={24} sm={12} lg={6}>
          {/* 每张统计卡自己声明容器：卡只有 1/4 宽，字号要按**卡**宽收敛（见 containers.css §4）；
              `stat-card` 只加"悬停加深一档阴影"（业务要求，见 DESIGN.md §5） */}
          <Card className="cq stat-card"><Statistic title="合同数量" value={overview.contractCount || 0} prefix={<FileTextOutlined />} /></Card>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <Card className="cq stat-card"><Statistic title="合同总额" value={overview.contractAmount || 0} precision={2} prefix="¥" /></Card>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <Card className="cq stat-card"><Statistic title="累计结算额" value={overview.settleAmount || 0} precision={2} prefix={<AccountBookOutlined />} /></Card>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <Card className="cq stat-card"><Statistic title="累计付款额" value={overview.paidAmount || 0} precision={2} prefix={<WalletOutlined />} /></Card>
        </Col>
      </Row>

      <Row gutter={[16, 16]} style={{ marginTop: 16 }}>
        <Col xs={24} lg={16}>
          <Card className="cq" ref={trendRef} title="近 12 个月结算 / 付款趋势">
            <ReactECharts option={trendOption} style={{ height: 300 }} />
          </Card>
        </Col>
        <Col xs={24} lg={8}>
          <Card className="cq" ref={pieRef} title="合同类型金额分布">
            <ReactECharts option={typeOption} style={{ height: 300 }} />
          </Card>
        </Col>
      </Row>

      <Row gutter={[16, 16]} style={{ marginTop: 16 }}>
        <Col xs={24}>
          <TodoCard />
        </Col>
      </Row>

      <Row gutter={[16, 16]} style={{ marginTop: 16 }}>
        <Col xs={24}>
          <Card
            title="合同金额预警"
            extra={
              <Space size={8}>
                {alertRed > 0 && <Tag color="error">红 {alertRed}</Tag>}
                {alertYellow > 0 && <Tag color="warning">黄 {alertYellow}</Tag>}
              </Space>
            }
          >
            <List
              dataSource={alertList}
              locale={{ emptyText: <EmptyState compact description="暂无金额预警" /> }}
              renderItem={(a: any) => (
                <List.Item>
                  <List.Item.Meta
                    title={
                      <Space size={8} wrap>
                        <Tag color={a.level === 'RED' ? 'error' : 'warning'}>
                          {a.level === 'RED' ? '红' : '黄'}
                        </Tag>
                        <Button type="link" size="small" style={{ padding: 0 }} onClick={() => navigate('/ledger')}>
                          {a.code}
                        </Button>
                        <span>{a.name}</span>
                      </Space>
                    }
                    description={(a.reasons || []).join('；')}
                  />
                </List.Item>
              )}
            />
            {reminders.amountAlertTotal > alertList.length && (
              <div className="cms-hint">仅显示前 {alertList.length} 条，共 {reminders.amountAlertTotal} 条</div>
            )}
          </Card>
        </Col>
      </Row>

      <Row gutter={[16, 16]} style={{ marginTop: 16 }}>
        <Col xs={24}>
          <Card
            title="付款超比例预警"
            extra={<Tag color="warning">{reminders.paymentRatioAlertTotal || 0}</Tag>}
          >
            {/* 单级预警（业务只给了"超过就预警"一个口径）：不冒充红/黄，避免暗示不存在的分级阈值 */}
            <List
              dataSource={payAlertList}
              locale={{ emptyText: <EmptyState compact description="暂无付款超比例预警" /> }}
              renderItem={(a: any) => (
                <List.Item>
                  <List.Item.Meta
                    title={
                      <Space size={8} wrap>
                        <Tag color="warning">付款超比例</Tag>
                        <Button
                          type="link"
                          size="small"
                          style={{ padding: 0 }}
                          onClick={() => navigate('/settlement/payment')}
                        >
                          {a.code}
                        </Button>
                        <span>{a.name}</span>
                      </Space>
                    }
                    description={a.reason}
                  />
                </List.Item>
              )}
            />
            {reminders.paymentRatioAlertTotal > payAlertList.length && (
              <div className="cms-hint">
                仅显示前 {payAlertList.length} 条，共 {reminders.paymentRatioAlertTotal} 条
              </div>
            )}
          </Card>
        </Col>
      </Row>

      <Row gutter={[16, 16]} style={{ marginTop: 16 }}>
        <Col xs={24}>
          <Card title="待查验发票" extra={<Tag color="red">{reminders.pendingInvoices?.length || 0}</Tag>}>
            <List
              dataSource={reminders.pendingInvoices || []}
              locale={{
                emptyText: (
                  <EmptyState compact description="暂无待查验发票" actionText="前往发票管理" onAction={() => navigate('/invoice')} />
                ),
              }}
              renderItem={(item: any) => (
                <List.Item>
                  <List.Item.Meta
                    title={item.issuer || '-'}
                    description={`发票号码 ${item.invoiceNo || '-'} · 开票日期 ${item.invoiceDate?.slice(0, 10) || '-'}`}
                  />
                  <span style={{ color: 'var(--cms-error)' }}>{money(item.amountWithTax)}</span>
                </List.Item>
              )}
            />
          </Card>
        </Col>
      </Row>
    </>
  );
}

import { useEffect, useMemo, useState } from 'react';
import { withToken } from '../utils/download';
import {
  Row, Col, Card, Table, Button, Input, Space, Modal, Form, Tag, message, Popconfirm,
  InputNumber, Select, Tooltip, Upload, Descriptions,
} from 'antd';
import { PlusOutlined, ExportOutlined, ImportOutlined, ReloadOutlined, ArrowLeftOutlined } from '@ant-design/icons';
import { dictApi } from '@/api/dict';
import { useDictStore } from '@/store/dict';
import { useContainerWidth } from '@/hooks/useContainerWidth';
import { usePermission } from '@/hooks/usePermission';
import Can from '@/components/Can';

const COLORS = ['blue', 'green', 'red', 'orange', 'gold', 'cyan', 'purple', 'magenta', 'volcano', 'geekblue', 'default'];

export default function Dict() {
  /** 字典写入：后端是 `dict:edit` **或** `system:config` 任一即可（OR 语义，见 dict.controller） */
  const canEdit = usePermission(['dict:edit', 'system:config']);
  const [types, setTypes] = useState<any[]>([]);
  const [typeKeyword, setTypeKeyword] = useState('');
  const [currentType, setCurrentType] = useState<any>(null);
  const [items, setItems] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [typeModal, setTypeModal] = useState(false);
  const [itemModal, setItemModal] = useState(false);
  const [editingItem, setEditingItem] = useState<any>(null);
  const [editingType, setEditingType] = useState<any>(null);
  const [typeForm] = Form.useForm();
  const [itemForm] = Form.useForm();
  const invalidate = useDictStore((s) => s.invalidate);
  /**
   * 窄容器主从降级：`xs=24` 会让「类型列表」与「字典项」上下堆叠，
   * 选一个类型后要往下滚很久才看得到明细（375px 实测：列表高约 1.5 屏）。
   * 窄容器改成「列表 → 点进明细」单栏切换，宽容器两栏并存不受影响。
   * 判定用**容器宽度**（`useContainerWidth`，行内注释见 DESIGN.md §10.2）——
   * 视口值只归页面外壳使用，本页两栏形态由自己所在容器决定。
   */
  const { ref: cqRef, size: containerSize } = useContainerWidth<HTMLDivElement>();
  const isNarrow = containerSize.isNarrow;
  const [mobileDetail, setMobileDetail] = useState(false);
  /**
   * 窄容器下**只隐藏另一栏是不够的，还要把可见栏拉满整行**：
   * `Col` 的 `lg={7}`/`lg={17}` 按**视口**断点生效，当视口 ≥1200 而容器 <720
   * （分屏 / 嵌入等窄容器场景）时，剩下的那一栏仍只占 7/24 或 17/24 的宽度——
   * 500px 容器里只剩 ~146px，标题与「新增」按钮重叠、搜索框被压成一条。
   * 容器级响应式的判定与宽度必须同源，故这里用容器档位直接覆盖 flex 宽度。
   */
  const colStyle = (hidden: boolean) =>
    isNarrow
      ? { display: hidden ? ('none' as const) : undefined, flex: '0 0 100%', maxWidth: '100%' }
      : undefined;

  const loadTypes = async (keyword = '') => {
    const res: any = await dictApi.types({ keyword, pageSize: 500 });
    setTypes(res.list || []);
    if (!currentType && res.list?.length) setCurrentType(res.list[0]);
  };

  const loadItems = async (typeCode: string) => {
    if (!typeCode) return;
    setLoading(true);
    try {
      const res: any = await dictApi.items({ typeCode, pageSize: 500 });
      setItems(res || []);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadTypes();
  }, []);

  useEffect(() => {
    if (currentType) loadItems(currentType.code);
  }, [currentType?.code]);

  const filteredTypes = useMemo(
    () => types.filter((t) => !typeKeyword || t.code.includes(typeKeyword) || t.name.includes(typeKeyword)),
    [types, typeKeyword],
  );

  const submitType = async () => {
    const values = await typeForm.validateFields();
    if (editingType) await dictApi.updateType(editingType.id, values);
    else await dictApi.createType(values);
    message.success('保存成功');
    setTypeModal(false);
    typeForm.resetFields();
    setEditingType(null);
    loadTypes(typeKeyword);
    invalidate();
  };

  const submitItem = async () => {
    const values = await itemForm.validateFields();
    const payload = { ...values, typeCode: currentType.code };
    if (editingItem) await dictApi.updateItem(editingItem.id, payload);
    else await dictApi.createItem(payload);
    message.success('保存成功');
    setItemModal(false);
    itemForm.resetFields();
    setEditingItem(null);
    loadItems(currentType.code);
    invalidate(currentType.code);
  };

  const removeItem = async (row: any) => {
    await dictApi.removeItem(row.id);
    message.success('删除成功');
    loadItems(currentType.code);
    invalidate(currentType.code);
  };

  const toggleItem = async (row: any) => {
    await dictApi.toggleItem(row.id);
    loadItems(currentType.code);
    invalidate(currentType.code);
  };

  const move = async (row: any, dir: -1 | 1) => {
    const idx = items.findIndex((i) => i.id === row.id);
    const target = idx + dir;
    if (target < 0 || target >= items.length) return;
    const ids = items.map((i) => i.id);
    [ids[idx], ids[target]] = [ids[target], ids[idx]];
    await dictApi.sortItems(currentType.code, ids);
    loadItems(currentType.code);
    invalidate(currentType.code);
  };

  return (
    <Row gutter={16} ref={cqRef} className="cq">
      <Col xs={24} lg={7} style={colStyle(mobileDetail)}>
        <Card
          title="字典类型"
          extra={
            canEdit ? (
              <Button
                type="primary"
                size="small"
                icon={<PlusOutlined />}
                onClick={() => {
                  setEditingType(null);
                  typeForm.resetFields();
                  setTypeModal(true);
                }}
              >
                新增
              </Button>
            ) : null
          }
        >
          <Input.Search placeholder="搜索编码/名称" allowClear onSearch={loadTypes} onChange={(e) => setTypeKeyword(e.target.value)} style={{ marginBottom: 12 }} />
          <div style={{ maxHeight: 'calc(100vh - 260px)', overflow: 'auto' }}>
            {filteredTypes.map((t) => (
              <div
                key={t.id}
                onClick={() => { setCurrentType(t); setMobileDetail(true); }}
                style={{
                  padding: '8px 12px',
                  cursor: 'pointer',
                  borderRadius: 6,
                  marginBottom: 4,
                  background: currentType?.id === t.id ? 'var(--cms-surface-card)' : 'transparent',
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center',
                }}
              >
                <Tooltip title={t.remark}>
                  <span>
                    {t.name} <span style={{ color: 'var(--cms-muted-soft)', fontSize: 12 }}>{t.code}</span>
                  </span>
                </Tooltip>
                <Space size={4}>
                  <Tag>{t.itemCount ?? 0}</Tag>
                  <Can code={['dict:edit', 'system:config']}>
                    <Button
                      type="link"
                      size="small"
                      onClick={(e) => {
                        e.stopPropagation();
                        setEditingType(t);
                        typeForm.setFieldsValue(t);
                        setTypeModal(true);
                      }}
                    >
                      编辑
                    </Button>
                  </Can>
                </Space>
              </div>
            ))}
          </div>
        </Card>
      </Col>

      <Col xs={24} lg={17} style={colStyle(!mobileDetail)}>
        <Card
          title={
            isNarrow ? (
              <Space size={4}>
                <Button type="text" size="small" icon={<ArrowLeftOutlined />} onClick={() => setMobileDetail(false)}>
                  字典类型
                </Button>
                {currentType && <span>· {currentType.name}</span>}
              </Space>
            ) : currentType ? `字典项 · ${currentType.name}` : '字典项'
          }
          extra={
            <Space>
              <Button icon={<ReloadOutlined />} onClick={() => currentType && loadItems(currentType.code)} disabled={!currentType}>
                刷新
              </Button>
              <Can code={['dict:edit', 'system:config']}>
              <Button
                icon={<ImportOutlined />}
                disabled={!currentType}
                onClick={() => {
                  const input = document.createElement('input');
                  input.type = 'file';
                  input.accept = '.xlsx,.xls';
                  input.onchange = async () => {
                    const file = input.files?.[0];
                    if (!file) return;
                    const fd = new FormData();
                    fd.append('file', file);
                    const token = localStorage.getItem('cms_token');
                    // 预校验：不写库，全部通过后再导入
                    const vRes = await fetch(dictApi.validateUrl(currentType.code), {
                      method: 'POST',
                      headers: {
                        Authorization: `Bearer ${token}`,
                        'x-project-id': localStorage.getItem('cms_project_id') || '',
                      },
                      body: fd,
                    });
                    const vBody = await vRes.json();
                    if (vBody.code !== 0) { message.error(vBody.message); return; }
                    const vErrors = vBody.data?.errors || [];
                    if (vBody.data?.valid === false || vErrors.length) {
                      Modal.error({
                        title: `预校验未通过：${vErrors.length} 行存在问题，未写入任何数据`,
                        width: 560,
                        content: (
                          <ul style={{ maxHeight: 300, overflowY: 'auto', paddingLeft: 18 }}>
                            {vErrors.map((e: any, i: number) => (
                              <li key={i} style={{ color: 'var(--cms-error)' }}>
                                {e.row ? `第 ${e.row} 行` : ''}{e.field ? `【${e.field}】` : ''}：{e.message}
                              </li>
                            ))}
                          </ul>
                        ),
                      });
                      return;
                    }
                    const res = await fetch(dictApi.importUrl(currentType.code), {
                      method: 'POST',
                      headers: {
                        Authorization: `Bearer ${token}`,
                        'x-project-id': localStorage.getItem('cms_project_id') || '',
                      },
                      body: fd,
                    });
                    const body = await res.json();
                    if (body.code === 0) {
                      message.success(`导入完成：新增 ${body.data.created}，更新 ${body.data.updated}`);
                      loadItems(currentType.code);
                      invalidate(currentType.code);
                    } else message.error(body.message);
                  };
                  input.click();
                }}
              >
                导入
              </Button>
              </Can>
              <Button
                icon={<ExportOutlined />}
                disabled={!currentType}
                onClick={() => window.open(withToken(dictApi.exportUrl(currentType.code)))}
              >
                导出
              </Button>
              <Can code={['dict:edit', 'system:config']}>
                <Button
                  type="primary"
                  icon={<PlusOutlined />}
                  disabled={!currentType}
                  onClick={() => {
                    setEditingItem(null);
                    itemForm.resetFields();
                    itemForm.setFieldsValue({ status: 1, sortOrder: items.length + 1 });
                    setItemModal(true);
                  }}
                >
                  新增字典项
                </Button>
              </Can>
            </Space>
          }
        >
          {currentType?.remark && (
            <Descriptions size="small" column={1} style={{ marginBottom: 12 }}>
              <Descriptions.Item label="说明">{currentType.remark}</Descriptions.Item>
            </Descriptions>
          )}
          <Table
            rowKey="id"
            size="small"
            loading={loading}
            dataSource={items}
            scroll={{ x: 900 }}
            pagination={false}
            columns={[
              { title: '排序', dataIndex: 'sortOrder', width: 70 },
              { title: '字典项编码', dataIndex: 'itemCode', width: 150 },
              { title: '字典项名称', dataIndex: 'itemName', width: 160 },
              {
                title: '标签颜色',
                dataIndex: 'color',
                width: 110,
                render: (c: string) => (c ? <Tag color={c}>{c}</Tag> : '-'),
              },
              { title: '扩展字段1', dataIndex: 'extField1', width: 130, render: (v: string) => v || '-' },
              {
                title: '状态',
                dataIndex: 'status',
                width: 90,
                render: (s: number) => (s === 1 ? <Tag color="green">启用</Tag> : <Tag>停用</Tag>),
              },
              { title: '备注', dataIndex: 'remark', render: (v: string) => v || '-' },
              {
                title: '操作',
                // 5 个 small 按钮实测共 236px（编辑/停用/上移/下移/删除 各 44 + 间距），
                // 原 210 会把「删除」裁在固定列右缘外（桌面与手机都点不到）。留 16px 内边距余量。
                width: 260,
                fixed: 'right',
                render: (_: any, row: any) =>
                  canEdit ? (
                    <Space size={4} wrap>
                      <Button type="link" size="small" onClick={() => { setEditingItem(row); itemForm.setFieldsValue(row); setItemModal(true); }}>
                        编辑
                      </Button>
                      <Button type="link" size="small" onClick={() => toggleItem(row)}>
                        {row.status === 1 ? '停用' : '启用'}
                      </Button>
                      <Button type="link" size="small" onClick={() => move(row, -1)}>
                        上移
                      </Button>
                      <Button type="link" size="small" onClick={() => move(row, 1)}>
                        下移
                      </Button>
                      <Popconfirm
                        title="确认删除该字典项？被业务数据引用时不可删除"
                        onConfirm={() => removeItem(row)}
                      >
                        <Button type="link" size="small" danger>
                          删除
                        </Button>
                      </Popconfirm>
                    </Space>
                  ) : null,
              },
            ]}
          />
        </Card>
      </Col>

      <Modal
        title={editingType ? '编辑字典类型' : '新增字典类型'}
        open={typeModal}
        onOk={submitType}
        onCancel={() => setTypeModal(false)}
        destroyOnHidden
      >
        <Form form={typeForm} layout="vertical">
          <Form.Item name="code" label="字典类型编码" rules={[{ required: true }]}>
            <Input placeholder="如 contract_type" disabled={!!editingType} />
          </Form.Item>
          <Form.Item name="name" label="字典类型名称" rules={[{ required: true }]}>
            <Input />
          </Form.Item>
          <Form.Item name="sort" label="排序号">
            <InputNumber style={{ width: '100%' }} />
          </Form.Item>
          <Form.Item name="status" label="状态">
            <Select options={[{ value: 1, label: '启用' }, { value: 0, label: '停用' }]} />
          </Form.Item>
          <Form.Item name="remark" label="备注">
            <Input.TextArea rows={2} />
          </Form.Item>
        </Form>
      </Modal>

      <Modal
        title={editingItem ? '编辑字典项' : '新增字典项'}
        open={itemModal}
        onOk={submitItem}
        onCancel={() => setItemModal(false)}
        destroyOnHidden
      >
        <Form form={itemForm} layout="vertical">
          <Form.Item name="itemCode" label="字典项编码" rules={[{ required: true }]}>
            <Input placeholder="如 FRAMEWORK" disabled={!!editingItem} />
          </Form.Item>
          <Form.Item name="itemName" label="字典项名称" rules={[{ required: true }]}>
            <Input />
          </Form.Item>
          <Form.Item name="sortOrder" label="排序号">
            <InputNumber style={{ width: '100%' }} />
          </Form.Item>
          <Form.Item name="color" label="标签颜色（用于 Tag 展示）">
            <Select allowClear options={COLORS.map((c) => ({ value: c, label: c }))} />
          </Form.Item>
          <Form.Item name="extField1" label="扩展字段1（如关联材料类别编码）">
            <Input />
          </Form.Item>
          <Form.Item name="status" label="状态">
            <Select options={[{ value: 1, label: '启用' }, { value: 0, label: '停用' }]} />
          </Form.Item>
          <Form.Item name="remark" label="备注">
            <Input.TextArea rows={2} />
          </Form.Item>
        </Form>
      </Modal>
    </Row>
  );
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  Alert, Button, Card, Col, Descriptions, Form, Image, Input, Modal,
  Popconfirm, Row, Select, Space, Table, Tag, Upload, message,
} from 'antd';
import type { UploadFile } from 'antd';
import {
  ArrowLeftOutlined, DownloadOutlined, EyeOutlined, FilePdfOutlined, PlusOutlined,
  ReloadOutlined, SaveOutlined, SearchOutlined, UploadOutlined,
} from '@ant-design/icons';
import dayjs from 'dayjs';
import { withToken } from '../utils/download';
import { contractApi, laborApi } from '@/api/business';
import { fileApi } from '@/api/auth';
import { useTable } from '@/hooks/useTable';
import { useEditorTab, useTabRefresh } from '@/hooks/useTabs';
import { useContainerWidth } from '@/hooks/useContainerWidth';
import EditorTabPage from '@/components/editor/EditorTabPage';
