import { LIST_PATHS } from '@/constants/listPaths';
import { useDictStore } from '@/store/dict';

const money = (v: any) =>
  v == null ? '-' : '¥' + Number(v).toLocaleString('zh-CN', { maximumFractionDigits: 2 });

const COMPLIANCE_OPTIONS = [
  '无问题',
  '未招标进场',
  '未定标进场',
  '未签合同进场',
  '未签合同先进场',
  '时间数据不完整',
];

const renderYearMap = (v: any) => {
  if (!v || typeof v !== 'object') return '-';
  return Object.entries(v)
    .map(([y, a]) => `${y}: ${money(a as any)}`)
    .join('  ');
};

const renderCompliance = (v: any) => {
  if (!v || v === '无问题') return <span style={{ color: 'var(--cms-success)' }}>无问题</span>;
  if (v === '时间数据不完整') return <span style={{ color: 'var(--cms-warning)' }}>时间数据不完整</span>;
  return <span style={{ color: 'var(--cms-error)' }}>{v}</span>;
};

/** 小数比例列（如付款比例 0.65）：页面乘 100 显示为 65.00%，与导出 `0.00%` 格式一致 */
const pct = (v: any) => (v == null || v === '' ? '-' : `${(Number(v) * 100).toFixed(2)}%`);
/** 百分数口径列（税率 13 = 13%）：单轨后直接拼 %，不再乘 100 */
const pctVal = (v: any) => (v == null || v === '' ? '-' : `${Number(v).toFixed(2)}%`);

const renderCell = (key: string, v: any) => {
  if (key === 'taxRate' || key === 'taxRatePct') return pctVal(v);
  if (key === 'currentPayRatio') return pct(v);
  if (/amount$/i.test(key) || /debt/i.test(key) || key === 'amount') return money(v);
  if (key === 'yearSettle' || key === 'yearPaid') return renderYearMap(v);
  if (key === 'compliance') return renderCompliance(v);
  return v == null || v === '' ? '-' : v;
};

/**
 * 合同台账（问题四：统一标准列表页规约）
 * - 顶部统计卡片 + 标准筛选区/工具栏/表格/分页
 * - 动态列由服务端返回（含列可见性配置），「列设置」保存后刷新
 * - **同时承载合同主数据维护**（业务 2026-11-14 合并「合同台账 + 合同台账维护」）：
 *   行操作「查看/编辑/删除」、工具栏「新建/导入」，编辑器走同一路径的 `?editor=new|<id>`。
 *   签章/驳回/归档等**工作流动作仍只在「合同查询」**，不在本页。
 *   台账仍包含草稿合同（`/ledger/contracts` 的 where 只有 projectId），与合并前口径一致。
 */
export default function Ledger() {
  const editorTab = useEditorTab(LIST_PATHS.contractLedger);
  if (editorTab.isEditor) {
    return <ContractEditor seed={editorTab.seed} />;
  }
  return <LedgerList />;
}

function LedgerList() {
  const ensure = useDictStore((s) => s.ensure);
  const editorTab = useEditorTab(LIST_PATHS.contractLedger);
  const [detailId, setDetailId] = useState<string | null>(null);
  /** 发票作废/红冲等跨标签动作会 bump 本路径，缓存页必须重新取数（含顶部统计） */
  const tabRefresh = useTabRefresh(LIST_PATHS.contractLedger);
  const [suppliers, setSuppliers] = useState<any[]>([]);
  const [columns, setColumns] = useState<any[]>([]);
  const [summary, setSummary] = useState<any>(null);
  const [colModal, setColModal] = useState(false);
  const [colChecked, setColChecked] = useState<string[]>([]);
  const [listRefresh, setListRefresh] = useState(0);


  /** 标准列表数据源：台账接口返回 { list, total, columns }，columns 用于动态列渲染 */
  const fetcher = useMemo(
    () => async (params: Record<string, any>) => {
      const res: any = await ledgerApi.contracts(params);
      if (res?.columns) setColumns(res.columns);
      return res;
    },
    [],
  );

  /** 顶部统计卡（不走列表接口，增删改后需单独重取） */
  const loadSummary = useCallback(() => {
    ledgerApi.summary().then((res: any) => setSummary(res)).catch(() => setSummary(null));
  }, []);

  useEffect(() => {
    ensure(['contract_type', 'contract_execution_status', 'supplier_category']);
    supplierApi.options().then((res: any) => setSuppliers(res || []));
    loadSummary();
  }, [tabRefresh, loadSummary]);

  /**
   * 大宽表冻结列（DESIGN.md §10.2）：**张数随容器宽度收敛**——
   * 宽容器冻结「序号 + 合同编号」（横向滚动时保持可见）；窄容器只冻结**合同编号**：
   * 序号是装饰性的，窄容器里留着它只会白占可视区，而合同编号才是识别行的那一列。
   * 行高不在这里管：它由 `ModuleListPage` 按同一个容器宽度给 `size`。
   * 列宽由后端 `/ledger/contracts` 返回，已是**像素**宽（后端把 Excel 字符宽统一换算过）。
   */
  const { ref: cqRef, size: containerSize } = useContainerWidth<HTMLDivElement>();
  const frozenLeftKeys = useMemo(
    () => (containerSize.isNarrow ? ['contractCode'] : ['index', 'contractCode']),
    [containerSize.isNarrow],
  );

  const buildColumns = useCallback(
    (cols: any[]) =>
      cols
        .filter((c) => c.visible)
        .map((c) => ({
          title: c.title,
          dataIndex: c.key,
          key: c.key,
          width: c.width || 140,
          ...(frozenLeftKeys.includes(c.key) ? { fixed: 'left' as const } : {}),
          render: (v: any) => renderCell(c.key, v),
        })),
    [frozenLeftKeys],
  );

  const tableColumns = useMemo(() => buildColumns(columns), [buildColumns, columns]);

  const openColModal = () => {
    setColChecked(columns.filter((c) => c.visible).map((c) => c.key));
    setColModal(true);
  };

  const saveCols = async () => {
    const config: Record<string, boolean> = {};
    columns.forEach((c) => {
      config[c.key] = colChecked.includes(c.key);
    });
    await ledgerApi.saveColumns(config);
    message.success('列设置已保存');
    setColModal(false);
    setListRefresh((k) => k + 1);
  };

  /** 台账行增删改后：列表与顶部统计卡都要重取（统计卡不走列表接口） */
  const refreshAll = useCallback(() => {
    setListRefresh((k) => k + 1);
    loadSummary();
  }, [loadSummary]);

  const openDetail = (row: any) => {
    setDetailId(row.id);
  };

  /** 编辑取全量（含 ext / version）；列表 DTO 是拍平的展示字段，不参与保存 */
  const openEdit = async (row: any) => {
    const res: any = await contractApi.detail(row.id);
    editorTab.openEdit(row.id, res);
  };

  const confirmRemove = (row: any) => {
    Modal.confirm({
      title: '确认删除该合同？',
      content: '存在下游单据或补充协议时会被服务端拒绝，请改为归档；仅物资清单等随合同级联删除。',
      okText: '删除',
      okButtonProps: { danger: true },
      cancelText: '取消',
      onOk: async () => {
        await contractApi.remove(row.id);
        message.success('已删除');
        refreshAll();
      },
    });
  };

  /** 筛选项（问题四：标准筛选区） */
  const extraFilters: ModuleListFilterField[] = [
    { key: 'code', label: '合同编号', control: 'input' },
    {
      key: 'supplierId',
      label: '供应商',
      control: 'select',
      options: suppliers.map((s) => ({ value: s.id, label: s.name })),
      placeholder: '全部',
    },
    { key: 'type', label: '合同类型', control: 'input', render: () => <DictSelect typeCode="contract_type" placeholder="全部" /> },
    { key: 'executionStatus', label: '合同执行情况', control: 'input', render: () => <DictSelect typeCode="contract_execution_status" placeholder="全部" /> },
    { key: 'compliance', label: '合规性问题', control: 'select', options: COMPLIANCE_OPTIONS.map((o) => ({ value: o, label: o })) },
    { key: 'category', label: '分供方类别', control: 'input', render: () => <DictSelect typeCode="supplier_category" placeholder="全部" /> },
    { key: 'keyword', label: '关键词', control: 'input' },
  ];

  return (
    <Space ref={cqRef} className="cq" direction="vertical" size={16} style={{ width: '100%' }}>
      {summary && (
        <Row gutter={16}>
          <Col xs={12} md={8} lg={4}>
            <Card size="small" className="stat-card"><Statistic title="合同数量" value={summary.contractCount ?? 0} /></Card>
          </Col>
          <Col xs={12} md={8} lg={4}>
            <Card size="small" className="stat-card">
              <Statistic title="合同总额" value={money(summary.contractAmount)} />
              {/* 未填金额的合同按 0 参与求和（金额未知）——不说出来，总额会看起来是完整的 */}
              {summary.amountMissingCount > 0 && (
                <div className="cms-hint" style={{ marginTop: 4 }}>
                  另有 {summary.amountMissingCount} 份未填金额
                </div>
              )}
            </Card>
          </Col>
          <Col xs={12} md={8} lg={4}>
            <Card size="small" className="stat-card"><Statistic title="开累结算" value={money(summary.settleAmount)} /></Card>
          </Col>
          <Col xs={12} md={8} lg={4}>
            <Card size="small" className="stat-card"><Statistic title="开累付款" value={money(summary.paidAmount)} /></Card>
          </Col>
          <Col xs={12} md={8} lg={4}>
            <Card size="small" className="stat-card"><Statistic title="应付款" value={money(summary.payableAmount)} /></Card>
          </Col>
          <Col xs={12} md={8} lg={4}>
            <Card size="small" className="stat-card"><Statistic title="100%欠款" value={money(summary.debt100)} /></Card>
          </Col>
          <Col xs={12} md={8} lg={4}>
            <Card size="small" className="stat-card"><Statistic title="合规问题数" value={summary.complianceIssues ?? 0} /></Card>
          </Col>
        </Row>
      )}

      <ModuleListPage
        mode="generic"
        fetcher={fetcher}
        extraFilters={extraFilters}
        extraColumns={tableColumns as any}
        refreshKey={listRefresh + tabRefresh}
        onView={(row) => openDetail(row as any)}
        editPermission="contract:edit"
        rowMenuItems={(row: ModuleListRow, ctx) => {
          const r = row as any;
          // 写操作统一用组件给出的 canEdit（与 editPermission 同源），避免页面另起一套门禁
          if (!ctx.canEdit) return [];
          // 归档是单向终态：编辑/删除都禁用，与合并前的维护页口径一致
          const archived = !!r.archivedAt;
          return [
            {
              key: 'edit',
              label: '编辑',
              disabled: archived,
              onClick: () => openEdit(r),
            },
            {
              key: 'remove',
              label: '删除',
              danger: true,
              disabled: archived,
              onClick: () => confirmRemove(r),
            },
          ];
        }}
        /* 手机端（窄容器）：只留「编号 / 名称 / 供应商 / 金额 / 执行情况」，并用卡片展示 */
        mobileDefaultKeys={['contractCode', 'contractName', 'supplierName', 'currentAmount', 'execStatus']}
        mobileCards
        emptyText="暂无合同台账数据"
        toolbarLeft={
          <Space wrap size={8}>
            <Can code="contract:edit">
              <Button type="primary" icon={<PlusOutlined />} onClick={() => editorTab.openCreate()}>
                新建合同
              </Button>
            </Can>
            <Can code="contract:edit">
              <ImportButton
                moduleName="合同台账"
                templateUrl={contractApi.templateUrl()}
                uploadUrl={contractApi.importUrl()}
                validateUrl={contractApi.validateUrl()}
                onDone={refreshAll}
              />
            </Can>
            <Button icon={<ExportOutlined />} onClick={() => window.open(withToken(ledgerApi.exportUrl()))}>
              导出
            </Button>
            <Button icon={<SettingOutlined />} onClick={openColModal}>
              列设置
            </Button>
          </Space>
        }
      />

      <ContractDetailModal
        contractId={detailId}
        onClose={() => setDetailId(null)}
        onChanged={refreshAll}
      />

      <Modal
        title="列设置"
        open={colModal}
        onOk={saveCols}
        onCancel={() => setColModal(false)}
        destroyOnHidden
      >
        <Checkbox.Group
          value={colChecked}
          onChange={(vals) => setColChecked(vals as string[])}
          style={{ display: 'flex', flexDirection: 'column', gap: 8 }}
        >
          {columns.map((c) => (
            <Checkbox key={c.key} value={c.key}>
              {c.title}
            </Checkbox>
          ))}
        </Checkbox.Group>
      </Modal>
    </Space>
  );
}

import { useEffect, useState } from 'react';
import { withToken } from '../utils/download';
import { Card, Table, Button, Form, Input, Space, Modal, Popconfirm, message, Tag, Select, Radio, Tooltip } from 'antd';
import { PlusOutlined, SearchOutlined, ExportOutlined, StopOutlined, CheckCircleOutlined, LockOutlined } from '@ant-design/icons';
import { materialApi } from '@/api/modules';
import { dictApi } from '@/api/dict';
import { useTable } from '@/hooks/useTable';
import { useEditorTab, useTabRefresh } from '@/hooks/useTabs';
import { usePermission } from '@/hooks/usePermission';
import EditorTabPage from '@/components/editor/EditorTabPage';
import ImportButton from '@/components/ImportButton';
import Can from '@/components/Can';

const YES_NO = [
  { label: '是', value: true },
  { label: '否', value: false },
];

/** 列表与「新增/编辑」是同一路由的两种形态（`?editor=new|<id>`） */
const LIST_PATH = '/base/material';

export default function Materials() {
  const editorTab = useEditorTab(LIST_PATH);
  if (editorTab.isEditor) {
    return <MaterialEditor seed={editorTab.seed} />;
  }
  return <MaterialList />;
}

function MaterialList() {
  const editorTab = useEditorTab(LIST_PATH);
  const tabRefresh = useTabRefresh(LIST_PATH);
  const { loading, list, params, search, reload, pagination } = useTable<any>((p) => materialApi.list(p));
  const canEdit = usePermission('material:edit');
  // 物资一二级分类（需求 2.2）：一级 material_category、二级 material_type（extField1 关联一级 code）
  const [catL1, setCatL1] = useState<any[]>([]);
  const [catL2, setCatL2] = useState<any[]>([]);

  useEffect(() => {
    dictApi.options('material_category').then((r) => setCatL1(r || [])).catch(() => undefined);
    dictApi.options('material_type').then((r) => setCatL2(r || [])).catch(() => undefined);
  }, []);

  // 编辑器标签保存后 bump 令牌 → 本（被缓存的）列表标签重新取数
  useEffect(() => {
    if (tabRefresh) reload();
  }, [tabRefresh, reload]);

  return (
    <Card
      title="物资基础库"
      extra={
        <Space>
          <Can code="material:edit">
            <ImportButton moduleName="物资基础库" templateUrl={materialApi.templateUrl()} uploadUrl={materialApi.importUrl()} validateUrl={materialApi.validateUrl()} onDone={reload} />
          </Can>
          <Button icon={<ExportOutlined />} onClick={() => window.open(withToken(materialApi.exportUrl()))}>导出</Button>
          <Can code="material:edit">
            <Button type="primary" icon={<PlusOutlined />} onClick={() => editorTab.openCreate()}>新增物资</Button>
          </Can>
        </Space>
      }
    >
      <Form layout="inline" style={{ marginBottom: 16, rowGap: 8 }} onFinish={(v) => search(v)}>
        <Form.Item name="keyword">
          <Input placeholder="物资名称/规格/MDM/DSC编码" allowClear prefix={<SearchOutlined />} style={{ width: 260 }} />
        </Form.Item>
        <Form.Item name="categoryLevel1">
          <Select
            allowClear
            placeholder="一级分类"
            style={{ width: 140 }}
            options={catL1.map((i: any) => ({ value: i.label ?? i.name, label: i.label ?? i.name }))}
          />
        </Form.Item>
        <Form.Item name="categoryLevel2">
          <Select
            allowClear
            placeholder="二级分类"
            style={{ width: 160 }}
            options={catL2.map((i: any) => ({ value: i.label ?? i.name, label: i.label ?? i.name }))}
          />
        </Form.Item>
        <Form.Item><Button type="primary" htmlType="submit">查询</Button></Form.Item>
      </Form>

      <Table
        rowKey="id"
        loading={loading}
        dataSource={list}
        pagination={pagination}
        scroll={{ x: 1450 }}
        columns={[
          { title: '物资名称', dataIndex: 'name', width: 220, render: (v, row) => (
            <Space>{v}{row.status === 0 && <Tag color="default">已停用</Tag>}</Space>
          ) },
          { title: '规格型号', dataIndex: 'spec', width: 180 },
          { title: '一级分类', dataIndex: 'categoryLevel1', width: 130, render: (v) => v || '-' },
          { title: '二级分类', dataIndex: 'categoryLevel2', width: 130, render: (v) => v || '-' },
          { title: '计量单位', dataIndex: 'unit', width: 110, render: (v) => v || '-' },
          {
            title: '是否资产',
            dataIndex: 'isAsset',
            width: 100,
            render: (v) => (v ? <Tag color="blue">是</Tag> : <Tag>否</Tag>),
          },
          {
            title: '是否安全物资',
            dataIndex: 'isSafetyMaterial',
            width: 130,
            render: (v) => (v ? <Tag color="green">是</Tag> : <Tag>否</Tag>),
          },
          { title: 'MDM编码', dataIndex: 'mdmCode', width: 160, render: (v) => v || '-' },
          { title: 'DSC编码', dataIndex: 'dscCode', width: 160, render: (v) => v || '-' },
          { title: '被引用次数', dataIndex: 'refCount', width: 110, render: (v) => (v > 0 ? <Tag color="blue">{v} 条</Tag> : '-') },
          { title: '备注', dataIndex: 'remark', width: 200, ellipsis: true, render: (v) => v || '-' },
          {
            title: '操作',
            width: 220,
            fixed: 'right',
            render: (_, row) =>
              canEdit ? (
                <Space size={4}>
                  <Button type="link" size="small" onClick={() => editorTab.openEdit(row.id, row)}>编辑</Button>
                  <Popconfirm
                    title={row.refCount > 0 ? `该物资已被 ${row.refCount} 条合同清单引用，删除会破坏历史合同数据，建议改为停用。仍要删除吗？` : '确认删除该物资？'}
                    okButtonProps={{ danger: row.refCount > 0 }}
                    onConfirm={async () => {
                      try {
                        await materialApi.remove(row.id);
                        message.success('已删除');
                        reload();
                      } catch { /* 后端已提示引用阻止 */ }
                    }}
                  >
                    <Button type="link" size="small" danger>删除</Button>
                  </Popconfirm>
                  <Button
                    type="link"
                    size="small"
                    icon={row.status === 1 ? <StopOutlined /> : <CheckCircleOutlined />}
                    onClick={async () => {
                      await materialApi.toggle(row.id);
                      message.success(row.status === 1 ? '已停用（历史合同数据保留）' : '已启用');
                      reload();
                    }}
                  >
                    {row.status === 1 ? '停用' : '启用'}
                  </Button>
                </Space>
              ) : null,
          },
        ]}
      />
    </Card>
  );
}

function MaterialEditor({ seed }: { seed: unknown }) {
  const editorTab = useEditorTab(LIST_PATH);
  const [form] = Form.useForm();
  const [saving, setSaving] = useState(false);
  const [dirty, setDirty] = useState(false);
  const editing = seed as any | undefined;
  // 物资一二级分类（需求 2.2）
  const [catL1, setCatL1] = useState<any[]>([]);
  const [catL2, setCatL2] = useState<any[]>([]);
  // 需求 2.3.1：计量单位只能取自字典「measurement_unit」
  const [units, setUnits] = useState<any[]>([]);
  const watchCatL1 = Form.useWatch('categoryLevel1', form);
  // 需求 2.3.1：计量单位创建后不可修改
  const unitLocked = !!editing?.unit;

  useEffect(() => {
    dictApi.options('material_category').then((r) => setCatL1(r || [])).catch(() => undefined);
    dictApi.options('material_type').then((r) => setCatL2(r || [])).catch(() => undefined);
    dictApi.options('measurement_unit').then((r) => setUnits(r || [])).catch(() => undefined);
  }, []);

  useEffect(() => {
    form.resetFields();
    // 需求 2.1.1：两个属性必填，默认「否」
    if (editing) form.setFieldsValue(editing);
    else form.setFieldsValue({ isAsset: false, isSafetyMaterial: false });
    setDirty(false);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [editing]);

  // 二级分类按所选一级过滤（extField1 === 一级 value）；未选一级时展示全部
  const l2Options = catL2
    .filter((i: any) => !watchCatL1 || !i.extField1 || i.extField1 === catL1.find((x: any) => x.label === watchCatL1)?.value)
    .map((i: any) => ({ value: i.label ?? i.name, label: i.label ?? i.name }));

  const submit = async () => {
    const values = await form.validateFields();
    setSaving(true);
    try {
      if (editing) await materialApi.update(editing.id, { ...values, version: editing.version });
      else await materialApi.create(values);
      message.success('保存成功');
      editorTab.closeEditor();
    } finally {
      setSaving(false);
    }
  };

  return (
    <EditorTabPage
      listPath={LIST_PATH}
      title={editing ? '编辑物资' : '新增物资'}
      saving={saving}
      dirty={dirty}
      onSave={submit}
    >
      <Form form={form} layout="vertical" onValuesChange={() => setDirty(true)}>
        <Form.Item name="name" label="物资名称" rules={[{ required: true, message: '请输入物资名称' }]}>
          <Input placeholder="如：螺纹钢" />
        </Form.Item>
        <Form.Item name="spec" label="规格型号" rules={[{ required: true, message: '请输入规格型号' }]}>
          <Input placeholder="如：HRB400E Φ12" />
        </Form.Item>
        <Form.Item name="categoryLevel1" label="一级分类">
          <Select
            allowClear
            placeholder="请选择一级分类"
            options={catL1.map((i: any) => ({ value: i.label ?? i.name, label: i.label ?? i.name }))}
            onChange={() => form.setFieldValue('categoryLevel2', undefined)}
          />
        </Form.Item>
        <Form.Item name="categoryLevel2" label="二级分类">
          <Select allowClear placeholder="请选择二级分类" options={l2Options} />
        </Form.Item>
        {/* 需求 2.3.1：计量单位只能从字典选择；创建后不可修改 */}
        <Form.Item
          name="unit"
          label="计量单位"
          rules={[{ required: true, message: '请选择计量单位' }]}
          extra={unitLocked ? '计量单位创建后不可修改；如需新单位请先在【系统管理 → 字典管理】中添加' : '只能从字典「计量单位」中选择'}
        >
          <Select
            showSearch
            optionFilterProp="label"
            disabled={unitLocked}
            placeholder="请选择计量单位"
            options={units.map((u) => ({ value: u.label, label: u.label }))}
            notFoundContent="字典中暂无计量单位，请先在【系统管理 → 字典管理】中添加"
            suffixIcon={unitLocked ? <LockOutlined /> : undefined}
          />
        </Form.Item>
        {/* 需求 2.1.1：是否资产 / 是否安全物资 由物资基础库统一维护（必填） */}
        <Form.Item name="isAsset" label="是否资产" rules={[{ required: true, message: '请选择是否资产' }]}>
          <Radio.Group options={YES_NO} optionType="button" buttonStyle="solid" />
        </Form.Item>
        <Form.Item
          name="isSafetyMaterial"
          label="是否安全物资"
          rules={[{ required: true, message: '请选择是否安全物资' }]}
        >
          <Radio.Group options={YES_NO} optionType="button" buttonStyle="solid" />
        </Form.Item>
        <Form.Item name="mdmCode" label="MDM编码（可空）"><Input /></Form.Item>
        <Form.Item name="dscCode" label="DSC编码（可空）"><Input /></Form.Item>
        <Form.Item name="remark" label="备注"><Input.TextArea rows={2} /></Form.Item>
      </Form>
    </EditorTabPage>
  );
}

