      }
    | null;
}

const EMPTY_FORM: DocumentForm = {
  procurementTime: null,
  responseDeposit: null,
  quoteDescription: '',
};

/** 补充二/补充四：将采购发起填写的技术质量/验收/付款标准注入合同模板 HTML（替换占位符，无占位符时在末尾追加章节） */
function injectContractThreeFields(
  content: string,
  techQuality: string,
  acceptanceMethod: string,
  paymentMethod: string,
): string {
  let html = content || '';
  const map: Record<string, string> = {
    技术质量标准: techQuality,
    验收方式: acceptanceMethod,
    付款方式: paymentMethod,
  };
  for (const [k, v] of Object.entries(map)) {
    html = html.split(`{{${k}}}`).join(v || '');
  }
  // 模板未含对应占位符时，追加三字段章节，确保技术质量/验收/付款标准随合同模板导出（补充二）
  if (!html.includes('技术质量标准') && (techQuality || acceptanceMethod || paymentMethod)) {
    html +=
      '<h2>技术质量标准、验收方式与付款方式</h2>' +
      `<p><strong>技术质量标准：</strong></p>${techQuality || ''}` +
      `<p><strong>验收方式：</strong></p>${acceptanceMethod || ''}` +
      `<p><strong>付款方式：</strong></p>${paymentMethod || ''}`;
  }
  return html;
}

export default function Document() {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const currentProjectId = useAuthStore((s) => s.currentProjectId);

  /**
   * 列表与「编辑」是同一路由的两种形态（`?editor=<taskId>`），见 `useEditorTab` 的注释。
   * 编辑态原本是弹窗，现改为编辑器页签（底部操作栏 sticky，长表单不再把按钮滚出视口）。
   */
  const editorTab = useEditorTab(LIST_PATH);
  const tabRefresh = useTabRefresh(LIST_PATH);
  const taskId = editorTab.editorId === 'new' ? null : editorTab.editorId;
  /** 兼容旧深链 `?taskId=xxx`：归一成编辑器页签 */
  useEffect(() => {
    const legacy = searchParams.get('taskId');
    if (legacy && !editorTab.isEditor) navigate(editorTabKey(LIST_PATH, legacy), { replace: true });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  /** 列表刷新键：编辑器页签关闭后由 closeEditor 的 bump 触发；本键用于页内（删除等） */
  const [listRefresh, setListRefresh] = useState(0);
  /** 问题二：删除模块记录并回退流程 */
  const handleDeleteModule = useModuleDelete('DOCUMENT', () => setListRefresh((k) => k + 1));

  const [detail, setDetail] = useState<DocumentDetail | null>(null);
  const [detailLoading, setDetailLoading] = useState(false);

  const [form, setForm] = useState<DocumentForm>(EMPTY_FORM);
  const [saving, setSaving] = useState(false);
  const [publishing, setPublishing] = useState(false);
  /** 发布后默认只读；点「重新编辑」解锁 */
  const [reEditing, setReEditing] = useState(false);
  /** 统一预览/发布弹窗（批次四 · 任务 4.2）：publish=发布前确认；preview=纯预览 */
  const [modalMode, setModalMode] = useState<'preview' | 'publish' | null>(null);
  /** 未保存改动（关闭编辑器页签前确认） */
  const [dirty, setDirty] = useState(false);
  /** 任务查看弹窗（问题一：已完成行「查看」→ 任务信息+采购明细+Word 文档） */
  const [viewRow, setViewRow] = useState<ModuleListRow | null>(null);
  /** 重新编辑标记：loadDetail 完成后按此恢复可编辑（已发布行「重新编辑」） */
  const reEditRef = useRef(false);
  /** 补充四：合同模板预览 */
  const [contractPreviewOpen, setContractPreviewOpen] = useState(false);
  const [contractHtml, setContractHtml] = useState('');

  const [project, setProject] = useState<{
    name?: string;
    nameAbbr?: string;
    undertaker?: string;
    provinceCity?: string;
    siteLocation?: string;
    projectAddress?: string;
  }>({});

  const currentTask = detail?.task ?? null;
  /** 当前是否可编辑：采购文件编制中，或已发布后主动点「重新编辑」 */
  const editable = !!detail && (detail.editable || (detail.published && reEditing));
  /** 采购内容（默认取采购公告内容 / 采购任务内容） */
  const content = detail?.notice?.content || currentTask?.content || '';

  /** 采购清单（只读） */
  const purchaseItems = useMemo(() => detail?.purchaseItems ?? [], [detail]);

  useEffect(() => {
    if (!currentProjectId) return;
    projectApi
      .detail(currentProjectId)
      .then((res: any) => setProject(res ?? {}))
      .catch(() => setProject({}));
  }, [currentProjectId]);

  const loadDetail = useCallback((id: string) => {
    setDetailLoading(true);
    procurementTaskApi
      .document(id)
      .then((res: any) => {
        const d: DocumentDetail = res; // 响应拦截器已解开 body.data，res 即完整 payload（含 task 与 data 记录）
        setDetail(d);
        const data = (d?.data ?? {}) as NonNullable<DocumentDetail['data']>;
        setForm({
          procurementTime: data.procurementTime
            ? dayjs(data.procurementTime).format('YYYY-MM-DD')
            : null,
          responseDeposit: data.responseDeposit ?? null,
          quoteDescription: data.quoteDescription ?? '',
        });
        setReEditing(reEditRef.current && !!d.published);
        reEditRef.current = false;
      })
      .catch(() => {
        setDetail(null);
        setForm(EMPTY_FORM);
      })
      .finally(() => setDetailLoading(false));
  }, []);

  /** 列表行操作（问题一）：已完成行 → 任务查看弹窗；未填写/编辑中 → 直接进入编辑界面 */
  const handleViewRow = (row: ModuleListRow) => {
    if (moduleStatusOf(row).value === 'PUBLISHED') setViewRow(row);
    else editRow(row);
  };
  /** 列表行操作：编辑（reEdit=true 为已发布后的重新编辑）—— 打开编辑器页签，reEdit 随种子递过去 */
  const editRow = (row: ModuleListRow, reEdit = false) => {
    editorTab.openEdit(row.id, { reEdit });
  };
  /** 编辑器页签挂载时：按种子里的 reEdit 决定初始是否可编辑，并拉详情 */
  useEffect(() => {
    if (!taskId) return;
    reEditRef.current = !!(editorTab.seed as { reEdit?: boolean } | undefined)?.reEdit;
    loadDetail(taskId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [taskId]);

  /** 行「更多 → 导出Word」（问题二）：按任务直接构建并导出本模块文档 */
  const handleRowExport = async (row: ModuleListRow) => {
    try {
      const filename = await exportTaskModuleWord(MODULE_TYPE, row.id);
      message.success(`已导出：${filename}`);
    } catch (e: any) {
      message.error(e?.message || '导出失败，请稍后重试');
    }
  };

  const patchForm = (patch: Partial<DocumentForm>) => {
    setForm((f) => ({ ...f, ...patch }));
    setDirty(true);
  };

  /* ---------------- 保存 / 发布 / 导出 ---------------- */

  const buildSavePayload = () => ({
    procurementTime: form.procurementTime || null,
    responseDeposit: form.responseDeposit,
    quoteDescription: form.quoteDescription,
  });

  const handleSave = async () => {
    if (!taskId) return;
    setSaving(true);
    try {
      await procurementTaskApi.saveDocument(taskId, buildSavePayload());
      message.success('已保存');
      // 编辑器页签形态下「保存」不关标签，就地重载详情与列表
      loadDetail(taskId);
      setDirty(false);
      setListRefresh((x) => x + 1);
    } finally {
      setSaving(false);
    }
  };

  /** 发布流程第 1 步：校验必填 → 打开「发布前预览」 */
  const openPublishPreview = () => {
    if (!form.procurementTime) {
      message.warning('请先选择「采购时间」再发布');
      return;
    }
    if (form.responseDeposit == null) {
      message.warning('请先填写「响应保证金」再发布');
      return;
    }
    setModalMode('publish');
  };

  /** 发布流程第 2 步：确认发布（先落库当前编辑内容） */
  const handlePublish = async () => {
    if (!taskId) return;
    setPublishing(true);
    try {
      await procurementTaskApi.saveDocument(taskId, buildSavePayload());
      await procurementTaskApi.publish(taskId);
      message.success('已发布，采购文件状态变更为「已完成」');
      setModalMode(null);
      setDirty(false);
      // 发布即完成本模块 → 关掉编辑器页签并让列表重新取数
      editorTab.closeEditor();
    } finally {
      setPublishing(false);
    }
  };

  const docData = useMemo<DocumentData>(
    () => ({
      procurementTime: form.procurementTime,
      responseDeposit: form.responseDeposit,
      quoteDescription: form.quoteDescription,
      purchaseItems,
    }),
    [form, purchaseItems],
  );

  const docCtx = useMemo(
    () => ({
      projectName: project.name,
      projectAbbr: project.nameAbbr,
      undertaker: project.undertaker,
      provinceCity: project.provinceCity,
      siteLocation: project.siteLocation,
      projectAddress: project.projectAddress,
      content,
      procurementNo: detail?.notice?.procurementNo,
      techQuality: detail?.notice?.techQuality,
      acceptanceMethod: detail?.notice?.acceptanceMethod,
      paymentMethod: detail?.notice?.paymentMethod,
    }),
    [project, content, detail],
  );

  /** 模块内置文档 HTML（含 {{占位符}}，未替换；统一管线内完成模板优先与变量替换） */
  const rawDocHtml = useMemo(() => {
    if (!currentTask) return '';
    const title = `${project.nameAbbr || project.name || ''}-${content}-采购文件`;
    return buildDocumentDocHtml(docData, docCtx, title);
  }, [docData, docCtx, currentTask, project, content]);

  /** 变量取值（统一预览 / 导出共用） */
  const varValues = useMemo(
    () => buildDocumentVariableValues(docData, docCtx),
    [docData, docCtx],
  );

  const exportFilename = `${project.nameAbbr || project.name || '项目'}-${content}-采购文件.docx`;

  const handleExport = async () => {
    if (!currentTask) return;
    await exportProcurementWord({
      moduleType: MODULE_TYPE,
      taskId: taskId ?? undefined,
      docHtml: rawDocHtml,
      values: varValues,
      filename: exportFilename,
    });
    message.success(`已导出：${exportFilename}`);
  };

  /**
   * 补充四：拉取「与采购文件关联的合同模板」内容，并把采购发起填写的
   * 技术质量/验收/付款标准注入（替换占位符或追加章节），返回注入后 HTML 与导出文件名。
   */
  const getContractTemplateHtml = useCallback(async (): Promise<{ html: string; filename: string }> => {
    if (!taskId) return { html: '', filename: '' };
    const res: any = await procurementTaskApi.contractTemplate(taskId);
    const ct = res?.data ?? res ?? {};
    const injected = injectContractThreeFields(
      ct?.content || '',
      ct?.techQuality || '',
      ct?.acceptanceMethod || '',
      ct?.paymentMethod || '',
    );
    const tmplName = ct?.templateName || '合同模板';
    const filename = `${project.nameAbbr || project.name || '项目'}-${content}-${tmplName}.docx`;
    return { html: injected, filename };
  }, [taskId, project.nameAbbr, project.name, content]);

  /** 补充四：预览采购合同模板（注入三标准后渲染） */
  const handlePreviewContractTemplate = async () => {
    if (!taskId) return;
    try {
      const { html } = await getContractTemplateHtml();
      const built = await buildProcurementDoc(
        { moduleType: CONTRACT_TPL_MODULE, docHtml: html, values: {} },
        { inlineImages: false },
      );
      setContractHtml(built.html || html);
      setContractPreviewOpen(true);
    } catch (e: any) {
      message.error(e?.message || '合同模板预览失败');
    }
  };

  /** 补充四：导出采购合同模板 Word（注入三标准后导出） */
  const handleExportContractTemplate = async () => {
    if (!taskId) return;
    try {
      const { html, filename } = await getContractTemplateHtml();
      await exportProcurementWord({
        moduleType: CONTRACT_TPL_MODULE,
        docHtml: html,
        values: {},
        filename,
      });
      message.success(`已导出：${filename}`);
    } catch (e: any) {
      message.error(e?.message || '合同模板导出失败');
    }
  };

  /* ---------------- 采购清单（只读）列 ---------------- */

  /** 价格类列由投标方填写，系统内留空 */
  const priceCell = (v: number | null | undefined) => (v == null ? '-' : fmtAmount(v));

  const purchaseColumns: ColumnsType<DocumentPurchaseItem> = [
    { title: '序号', width: 56, render: (_v, _r, i) => i + 1 },
    { title: '物资名称', dataIndex: 'materialName', render: (v: string | null) => v || '-' },
    { title: '规格型号', dataIndex: 'spec', render: (v: string | null) => v || '-' },
    { title: '计量单位', dataIndex: 'unit', width: 90, render: (v: string | null) => v || '-' },
    {
      title: '暂定数量',
      dataIndex: 'qty',
      width: 100,
      render: (v: number | null) => (v != null ? Number(v).toLocaleString('zh-CN') : '-'),
    },
    // 以下四列留空（由投标方填写）
    { title: '税前单价', dataIndex: 'preTaxPrice', width: 100, render: priceCell },
    { title: '税率', dataIndex: 'taxRate', width: 80, render: priceCell },
    { title: '综合单价', dataIndex: 'unitPrice', width: 100, render: priceCell },
    { title: '合价', dataIndex: 'amount', width: 110, render: priceCell },
    { title: '备注', dataIndex: 'remark', width: 140, render: (v: string | null) => v || '-' },
  ];

  /* ---------------- 渲染 ---------------- */

  /** 采购文件模块特有筛选项 */
  const extraFilters: ModuleListFilterField[] = [{ key: 'procTime', label: '采购时间', control: 'dateRange' }];

  /** 采购文件模块特有表格列 */
  const extraColumns: ColumnsType<ModuleListRow> = [
    {
      title: '采购时间',
      key: 'procurementTime',
      width: 120,
      render: (_v, row) =>
        row.module?.procurementTime ? dayjs(row.module.procurementTime).format('YYYY-MM-DD') : '-',
    },
    {
      title: '响应保证金（元）',
      key: 'responseDeposit',
      width: 140,
      render: (_v, row) =>
        row.module?.responseDeposit != null
          ? Number(row.module.responseDeposit).toLocaleString('zh-CN')
          : '-',
    },
  ];

  return (
    <Space direction="vertical" size={12} style={{ width: '100%' }}>
      {/* 标准列表页（批次五）：筛选区 + 工具栏 + 数据表格 */}
      <ModuleListPage
        moduleKey="DOCUMENT"
        baseParams={{ type: 'SINGLE' }}
        extraFilters={extraFilters}
        extraColumns={extraColumns}
        toolbarLeft={
          <span style={{ color: 'var(--cms-muted-soft)', fontSize: 13 }}>
            仅显示单项采购类型的任务；编辑与发布以任务所处阶段为准（需先完成采购公告）
          </span>
        }
        refreshKey={listRefresh + tabRefresh}
        editPermission="procurement:edit"
        onView={handleViewRow}
        onEdit={editRow}
        onDelete={handleDeleteModule}
        rowMenuItems={(row, { canEdit }) => {
          const published = moduleStatusOf(row).value === 'PUBLISHED';
          return published
            ? [
                {
                  key: 'exportWord',
                  label: (
                    <span>
                      <FileWordOutlined /> 导出Word
                    </span>
                  ),
                  onClick: () => handleRowExport(row),
                },
                ...(canEdit ? [{ key: 'reEdit', label: '重新编辑', onClick: () => editRow(row, true) }] : []),
              ]
            : [];
        }}
      />

      {/* 任务查看弹窗（问题一：已完成行「查看」→ 居中弹窗：任务信息+采购明细+Word 文档） */}
      <TaskViewModal task={viewRow} open={!!viewRow} onClose={() => setViewRow(null)} />

      {/* 编辑弹窗（问题一：未填写/编辑中行「编辑」直接进入；问题三：居中弹窗） */}
      {/* 编辑器页签（未填写/编辑中行「编辑」直接进入；底部操作栏 sticky） */}
      {taskId && (
        <EditorTabPage
          listPath={LIST_PATH}
          title={`采购文件 · 编辑${currentTask ? ` · ${currentTask.taskNo}` : ''}`}
          saving={saving}
          saveText="保 存"
          onSave={editable ? handleSave : undefined}
          // 本页有独立的「发布」流程，保存不关标签
          closeOnSave={false}
          dirty={dirty}
          footerLeft={
            <Space wrap size={8}>
              {currentTask && (
                <Button icon={<EyeOutlined />} onClick={() => setModalMode('preview')}>
                  预览采购文件
                </Button>
              )}
              {currentTask && (
                <Button icon={<FileWordOutlined />} onClick={handleExport}>
                  导出采购文件
                </Button>
              )}
              {currentTask && (
                <Button icon={<EyeOutlined />} onClick={handlePreviewContractTemplate}>
                  预览合同模板
                </Button>
              )}
              {currentTask && (
                <Button icon={<FileWordOutlined />} onClick={handleExportContractTemplate}>
                  导出合同模板
                </Button>
              )}
            </Space>
          }
          footerExtra={
            detail && !detail.published && editable ? (
              <Button type="primary" icon={<SendOutlined />} onClick={openPublishPreview}>
                发布
              </Button>
            ) : null
          }
        >
        <Spin spinning={detailLoading}>
          {!currentTask && !detailLoading && (
            <Alert type="warning" showIcon message="任务详情加载失败，请关闭后重试。" />
          )}
          {currentTask && (
            <Space direction="vertical" size={12} style={{ width: '100%' }}>
              {detail && !detail.reached && (
                <Alert
                  type="info"
                  showIcon
                  message="该采购任务尚未进入采购文件阶段（需先完成采购公告）。"
                />
              )}
              {detail?.published && editable && (
                <Alert
                  type="warning"
                  showIcon
                  message="重新编辑模式：修改后请保存，发布状态保持「已完成」。"
                />
              )}

            {/* 展示信息 */}
            <Card size="small" title="展示信息">
              <Descriptions column={3} size="small" bordered>
                <Descriptions.Item label="采购内容">{content || '-'}</Descriptions.Item>
                <Descriptions.Item label="采购编号">
                  {detail?.notice?.procurementNo || '-'}
                </Descriptions.Item>
                <Descriptions.Item label="采购时间">{form.procurementTime || '-'}</Descriptions.Item>
                <Descriptions.Item label="采购类型">
                  {taskTypeLabel(currentTask.type)}
                </Descriptions.Item>
                <Descriptions.Item label="任务状态">
                  {taskStatusLabel(currentTask.status)}
                </Descriptions.Item>
                <Descriptions.Item label="发布时间">
                  {detail?.data?.publishedAt
                    ? dayjs(detail.data.publishedAt).format('YYYY-MM-DD HH:mm')
                    : '-'}
                </Descriptions.Item>
              </Descriptions>
            </Card>

            {/* 一、采购文件基本信息 */}
            <Card size="small" title="一、采购文件基本信息">
              <Row gutter={[16, 16]}>
                <Col xs={24} md={8}>
                  <div style={{ color: 'var(--cms-muted-soft)', fontSize: 12, marginBottom: 4 }}>采购时间</div>
                  {editable ? (
                    <DatePicker
                      style={{ width: '100%' }}
                      value={form.procurementTime ? dayjs(form.procurementTime) : null}
                      onChange={(d) =>
                        patchForm({ procurementTime: d ? d.format('YYYY-MM-DD') : null })
                      }
                    />
                  ) : (
                    <div style={{ minHeight: 22 }}>{form.procurementTime || '-'}</div>
                  )}
                </Col>
                <Col xs={24} md={8}>
                  <div style={{ color: 'var(--cms-muted-soft)', fontSize: 12, marginBottom: 4 }}>
                    响应保证金（元）
                  </div>
                  {editable ? (
                    <InputNumber
                      style={{ width: '100%' }}
                      min={0}
                      precision={2}
                      placeholder="请输入响应保证金金额"
                      value={form.responseDeposit}
                      onChange={(v) => patchForm({ responseDeposit: v ?? null })}
                    />
                  ) : (
                    <div style={{ minHeight: 22 }}>
                      {form.responseDeposit == null ? '-' : `${fmtAmount(form.responseDeposit)} 元`}
                    </div>
                  )}
                </Col>
                <Col xs={24} md={8}>
                  <div style={{ color: 'var(--cms-muted-soft)', fontSize: 12, marginBottom: 4 }}>采购编号</div>
                  <div style={{ minHeight: 22 }}>{detail?.notice?.procurementNo || '-'}</div>
                </Col>
              </Row>
            </Card>

            {/* 二、采购清单（只读，来自总采购清单） */}
            <Card
              size="small"
              title="二、采购清单"
              extra={
                <span style={{ color: 'var(--cms-muted-soft)', fontSize: 12 }}>
                  数据来自总采购清单，不可编辑；价格列由投标方填写
                </span>
              }
            >
              <Table
                size="small"
                rowKey={(_r, i) => String(i)}
                columns={purchaseColumns}
                dataSource={purchaseItems}
                pagination={false}
                scroll={{ x: 1100 }}
                locale={{ emptyText: '暂无数据（总采购清单为空或尚未编制）' }}
                summary={() =>
                  purchaseItems.length ? (
                    <>
                      <Table.Summary.Row>
                        <Table.Summary.Cell index={0} colSpan={8} align="center">
                          <strong>合价合计</strong>
                        </Table.Summary.Cell>
                        <Table.Summary.Cell index={8}>
                          <strong>{sumAmount(purchaseItems) || '-'}</strong>
                        </Table.Summary.Cell>
                        <Table.Summary.Cell index={9} />
                      </Table.Summary.Row>
                      <Table.Summary.Row>
                        <Table.Summary.Cell index={0} colSpan={2} align="center">
                          <strong>报价说明</strong>
                        </Table.Summary.Cell>
                        <Table.Summary.Cell index={2} colSpan={8}>
                          {stripHtml(form.quoteDescription) || '-'}
                        </Table.Summary.Cell>
                      </Table.Summary.Row>
                    </>
                  ) : null
                }
              />
            </Card>

            {/* 三、报价说明（富文本） */}
            <Card size="small" title="三、报价说明">
              <RichTextEditor
                value={form.quoteDescription}
                onChange={(html) => patchForm({ quoteDescription: html })}
                variableGroups={getProcurementVariableGroups(MODULE_TYPE)}
                variableScope="procurement"
                disabled={!editable}
                minHeight={200}
                placeholder="请填写报价说明"
              />
            </Card>

          </Space>
          )}
        </Spin>
        </EditorTabPage>
      )}

      {/* 统一预览 / 发布流程（批次四 · 任务 4.2）：发布前确认与发布后预览共用 */}
      <PreviewPublishModal
        open={modalMode !== null}
        mode={modalMode ?? 'preview'}
        moduleType={MODULE_TYPE}
        taskId={taskId ?? undefined}
        docHtml={rawDocHtml}
        values={varValues}
        publishing={publishing}
        filename={exportFilename}
        projectAbbr={project.nameAbbr}
        content={content}
        confirmTitle="确认发布采购文件？"
        confirmDescription="发布前将自动保存当前内容；发布后状态变更为「已完成」，任务状态流转到下一阶段。"
        tipMessage="请核对采购文件内容与采购清单，确认无误后点击「确认发布」。"
        onPublish={handlePublish}
        onClose={() => setModalMode(null)}
      />

      {/* 补充四：合同模板预览（注入技术质量/验收/付款标准后渲染，与导出所见即所得） */}
      <Modal
        title={`合同模板 · 预览${currentTask ? ` · ${currentTask.taskNo}` : ''}`}
        width={1000}
        centered
        open={contractPreviewOpen}
        onCancel={() => setContractPreviewOpen(false)}
        styles={{ body: { maxHeight: 'calc(100vh - 220px)', overflowY: 'auto' } }}
        footer={
          <Space style={{ float: 'right' }}>
            <Button onClick={() => setContractPreviewOpen(false)}>关闭</Button>
            <Button icon={<FileWordOutlined />} onClick={handleExportContractTemplate}>
              导出合同模板
            </Button>
          </Space>
        }
      >
        {/* 容器标记：预览区按**弹窗自身宽度**降级（DESIGN.md §10.2） */}
        <div className="cq">
          <div
            className="doc-preview"
            style={{
              maxHeight: '60vh',
              minHeight: 120,
              overflow: 'auto',
              border: '1px solid var(--cms-hairline-soft)',
              // padding 交由 .doc-preview 做容器级收敛（DESIGN.md §10.2）
            }}
            dangerouslySetInnerHTML={{
              __html: sanitizeHtml(highlightPlaceholders(contractHtml)) || '<p style="color:var(--cms-muted-soft)">暂无内容</p>',
            }}
          />
        </div>
      </Modal>
    </Space>
  );
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import {
  Alert,
  Button,
  Card,
  Input,
  InputNumber,
  Modal,
  Popconfirm,
  Select,
  Space,
  Spin,
  Table,
  Tooltip,
  Upload,
  message,
} from 'antd';
import type { ColumnsType } from 'antd/es/table';
import type { UploadFile } from 'antd/es/upload/interface';
import {
  DeleteOutlined,
  EyeOutlined,
  FileWordOutlined,
  PlusOutlined,
  SaveOutlined,
  SendOutlined,
} from '@ant-design/icons';
import http from '@/api/http';
import { procurementTaskApi } from '@/api/modules';
import { projectApi } from '@/api/business';
import { useAuthStore } from '@/store/auth';
import PreviewPublishModal from '@/components/PreviewPublishModal';
import TaskViewModal from '@/components/procurement/TaskViewModal';
import ModuleListPage, {
  moduleStatusOf,
  type ModuleListFilterField,
  type ModuleListRow,
  useModuleDelete,
} from '@/components/procurement/ModuleListPage';
import { exportProcurementWord } from '@/utils/procurementExport';
import { exportTaskModuleWord } from '@/utils/procurementTaskDocs';
import EditorTabPage from '@/components/editor/EditorTabPage';
import { useEditorTab, useTabRefresh } from '@/hooks/useTabs';
import { editorTabKey } from '@/utils/tabs';

/** 列表与编辑器是同一路由的两种形态（`?editor=<taskId>`），见 `useEditorTab` 的注释 */
const LIST_PATH = '/procurement/framework';
import {
  buildExplanationDocHtml,
  buildExplanationVariableValues,
  type CostRow,
  type InquiryRow,
  type PriceCompareRow,
} from '@/utils/frameworkExplanation';
// 询价最低价规则收敛到统一引擎（前后端单一实现，避免前端 Math.min 与服务端口径漂移）
import { lowestPriceSuppliers } from '../../../../server/src/common/calc/procurement.ts';

/** 采购任务行（列表精简） */
interface TaskRow {
  id: string;
  taskNo: string;
  type: string;
  content: string;
  status: string;
  stage: number;
}

/** 可编辑行：带前端 key 供 Table 渲染（保存时剔除） */
type Keyed<T> = T & { key: string };

/** 问题五：引用供应商及金额（可从询价情况自动填充最低价单位） */
export interface ReferenceSupplier {
  supplier: string;
  amount: number | null;
}

interface ExplanationForm {
  frameworkIntro: string;
  negotiation: string;
  inquiryRows: Keyed<InquiryRow>[];
  priceCompareRows: Keyed<PriceCompareRow>[];
  execution: string;
  costRows: Keyed<CostRow>[];
  referenceSuppliers: Keyed<ReferenceSupplier>[];
}

interface ExplanationDetail {
  task: TaskRow;
  editable: boolean;
  published: boolean;
  status: string;
  statusLabel: string;
  data: {
    frameworkIntro?: string;
    negotiation?: string;
    inquiryRows?: InquiryRow[];
    priceCompareRows?: PriceCompareRow[];
    execution?: string;
    costRows?: CostRow[];
    referenceSuppliers?: ReferenceSupplier[];
    attachments?: { fileName?: string; url?: string; size?: number | null }[];
    publishedAt?: string | null;
  } | null;
}

let rowSeq = 0;
const nextKey = (): string => {
  rowSeq += 1;
  return `row-${Date.now()}-${rowSeq}`;
};
const withKeys = <T,>(rows: T[] = []): Keyed<T>[] => rows.map((r) => ({ ...r, key: nextKey() }));
const stripKey = <T,>(row: Keyed<T>): T => {
  const { key: _key, ...rest } = row;
  return rest as unknown as T;
};

const EMPTY_FORM: ExplanationForm = {
  frameworkIntro: '',
  negotiation: '',
  inquiryRows: [],
  priceCompareRows: [],
  execution: '',
  costRows: [],
  referenceSuppliers: [],
};

export default function FrameworkExplanation() {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const currentProjectId = useAuthStore((s) => s.currentProjectId);

  /**
   * 列表与「编辑」是同一路由的两种形态（`?editor=<taskId>`），见 `useEditorTab` 的注释。
   * 编辑态原本是弹窗，现改为编辑器页签（底部操作栏 sticky，长表单不再把按钮滚出视口）。
   */
  const editorTab = useEditorTab(LIST_PATH);
  const tabRefresh = useTabRefresh(LIST_PATH);
  const taskId = editorTab.editorId === 'new' ? null : editorTab.editorId;
  /** 兼容旧深链 `?taskId=xxx`：归一成编辑器页签 */
  useEffect(() => {
    const legacy = searchParams.get('taskId');
    if (legacy && !editorTab.isEditor) navigate(editorTabKey(LIST_PATH, legacy), { replace: true });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  /** 列表刷新键：编辑器页签关闭后由 closeEditor 的 bump 触发；本键用于页内（删除等） */
  const [listRefresh, setListRefresh] = useState(0);
  /** 问题二：删除模块记录并回退流程 */
  const handleDeleteModule = useModuleDelete('FRAMEWORK_EXPLANATION', () => setListRefresh((k) => k + 1));

  const [detail, setDetail] = useState<ExplanationDetail | null>(null);
  const [detailLoading, setDetailLoading] = useState(false);

  const [form, setForm] = useState<ExplanationForm>(EMPTY_FORM);
  const [fileList, setFileList] = useState<UploadFile[]>([]);
  const [saving, setSaving] = useState(false);
  const [publishing, setPublishing] = useState(false);
  /** 从采购价格对比表导入「价格对比表」明细 */
  const [importing, setImporting] = useState(false);
  /** 发布后默认预览（只读）；点「重新编辑」解锁 */
  const [reEditing, setReEditing] = useState(false);
  /** 统一预览/发布弹窗（批次四 · 任务 4.2）：publish=发布前确认；preview=纯预览 */
  const [modalMode, setModalMode] = useState<'preview' | 'publish' | null>(null);
  /** 未保存改动（关闭编辑器页签前确认） */
  const [dirty, setDirty] = useState(false);
  /** 任务查看弹窗（问题一：已完成行「查看」→ 任务信息+采购明细+Word 文档） */
  const [viewRow, setViewRow] = useState<ModuleListRow | null>(null);
  /** 重新编辑标记：loadDetail 完成后按此恢复可编辑（已发布行「重新编辑」） */
  const reEditRef = useRef(false);

  const [project, setProject] = useState<{
    name?: string;
    nameAbbr?: string;
    undertaker?: string;
    provinceCity?: string;
    siteLocation?: string;
    projectAddress?: string;
  }>({});

  const currentTask = detail?.task ?? null;
  /** 当前是否可编辑：编辑中阶段，或已发布后主动点「重新编辑」 */
  const editable = !!detail && (detail.editable || (detail.published && reEditing));

  useEffect(() => {
    if (!currentProjectId) return;
    projectApi
      .detail(currentProjectId)
      .then((res: any) => setProject(res ?? {}))
      .catch(() => setProject({}));
  }, [currentProjectId]);

  const loadDetail = useCallback((id: string) => {
    setDetailLoading(true);
    procurementTaskApi
      .frameworkExplanation(id)
      .then((res: any) => {
        const d: ExplanationDetail = res; // 响应拦截器已解开 body.data，res 即完整 payload（含 task 与 data 记录）
        setDetail(d);
        const data = d?.data ?? {};
        setForm({
          frameworkIntro: data.frameworkIntro ?? '',
          negotiation: data.negotiation ?? '',
          inquiryRows: withKeys(data.inquiryRows ?? []),
          priceCompareRows: withKeys(data.priceCompareRows ?? []),
          execution: data.execution ?? '',
          costRows: withKeys(data.costRows ?? []),
          referenceSuppliers: withKeys(data.referenceSuppliers ?? []),
        });
        setFileList(
          (data.attachments ?? []).map((f, i) => ({
            uid: f.url || `att-${i}`,
            name: f.fileName || `附件${i + 1}`,
            status: 'done' as const,
            response: f,
          })),
        );
        setReEditing(reEditRef.current && !!d.published);
        reEditRef.current = false;
      })
      .catch(() => {
        setDetail(null);
        setForm(EMPTY_FORM);
      })
      .finally(() => setDetailLoading(false));
  }, []);

  /** 列表行操作（问题一）：已完成行 → 任务查看弹窗；未填写/编辑中 → 直接进入编辑界面 */
  const handleViewRow = (row: ModuleListRow) => {
    if (moduleStatusOf(row).value === 'PUBLISHED') setViewRow(row);
    else editRow(row);
  };
  /** 列表行操作：编辑（reEdit=true 为已发布后的重新编辑）—— 打开编辑器页签，reEdit 随种子递过去 */
  const editRow = (row: ModuleListRow, reEdit = false) => {
    editorTab.openEdit(row.id, { reEdit });
  };
  /** 编辑器页签挂载时：按种子里的 reEdit 决定初始是否可编辑，并拉详情 */
  useEffect(() => {
    if (!taskId) return;
    reEditRef.current = !!(editorTab.seed as { reEdit?: boolean } | undefined)?.reEdit;
    loadDetail(taskId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [taskId]);

  /** 关闭编辑器页签（发布后回到列表，并让列表重新取数） */
  const closeEdit = () => {
    setDirty(false);
    editorTab.closeEditor();
  };

  /** 行「更多 → 导出Word」（问题二）：按任务直接构建并导出本模块文档 */
  const handleRowExport = async (row: ModuleListRow) => {
    try {
      const filename = await exportTaskModuleWord('FRAMEWORK', row.id);
      message.success(`已导出：${filename}`);
    } catch (e: any) {
      message.error(e?.message || '导出失败，请稍后重试');
    }
  };

  const patchForm = (patch: Partial<ExplanationForm>) => {
    setForm((f) => ({ ...f, ...patch }));
    setDirty(true);
  };

  const updateRow = (
    field: 'inquiryRows' | 'priceCompareRows' | 'costRows' | 'referenceSuppliers',
    key: string,
    patch: Record<string, unknown>,
  ) => {
    setForm((f) => ({
      ...f,
      [field]: (f[field] as Keyed<unknown>[]).map((r) => (r.key === key ? { ...r, ...patch } : r)),
    }));
  };
  const removeRow = (
    field: 'inquiryRows' | 'priceCompareRows' | 'costRows' | 'referenceSuppliers',
    key: string,
  ) => {
    setForm((f) => ({
      ...f,
      [field]: (f[field] as Keyed<unknown>[]).filter((r) => r.key !== key),
    }));
  };

  /** 附表：Upload fileList 中的成功响应即附件元数据 */
  const attachmentsFromList = (list: UploadFile[]) =>
    list
      .map((f) => f.response as { fileName?: string; url?: string; size?: number | null } | undefined)
      .filter((f): f is { fileName?: string; url?: string; size?: number | null } => !!f?.url);

  const buildSavePayload = () => ({
    frameworkIntro: form.frameworkIntro,
    negotiation: form.negotiation,
    inquiryRows: form.inquiryRows.map(stripKey),
    priceCompareRows: form.priceCompareRows.map(stripKey),
    execution: form.execution,
    costRows: form.costRows.map(stripKey),
    referenceSuppliers: form.referenceSuppliers
      .map(stripKey)
      .filter((r) => String(r.supplier ?? '').trim()),
    attachments: attachmentsFromList(fileList),
  });

  const handleSave = async () => {
    if (!taskId) return;
    setSaving(true);
    try {
      await procurementTaskApi.saveFrameworkExplanation(taskId, buildSavePayload());
      message.success('已保存');
      // 编辑器页签形态下「保存」不关标签，就地重载详情与列表
      loadDetail(taskId);
      setDirty(false);
      setListRefresh((x) => x + 1);
    } finally {
      setSaving(false);
    }
  };

  /** 从采购价格对比表导入「价格对比表」明细（任务 3.6；幂等覆盖本表） */
  const handleImportPriceCompare = async () => {
    if (!taskId) return;
    setImporting(true);
    try {
      const res: any = await procurementTaskApi.importPriceCompare(taskId);
      setForm((f) => ({
        ...f,
        priceCompareRows: withKeys(res?.priceCompareRows ?? []),
      }));
      message.success('已从「采购价格对比表」导入价格对比表明细，可继续调整');
    } catch (e: any) {
      message.error(e?.message || '导入失败，请确认采购价格对比表已录入明细');
    } finally {
      setImporting(false);
    }
  };

  /** 发布流程第 1 步：校验必填 → 打开「发布前预览」（统一预览发布流程） */
  const openPublishPreview = () => {
    if (!taskId) return;
    if (!String(form.frameworkIntro ?? '').trim()) {
      message.warning('请先填写「框架简介」再发布');
      return;
    }
    // 需求：框架协议事前说明未勾选/未填写「单位」则无法发起（引用供应商及金额为必填，至少一家）
    const hasUnit = form.referenceSuppliers.some((r) =>
      String(r?.supplier ?? '').trim().length > 0,
    );
    if (!hasUnit) {
      message.warning('请先在「引用供应商及金额」中填写至少一家单位，再发布框架协议事前说明');
      return;
    }
    setModalMode('publish');
  };

  /** 发布流程第 2 步：确认发布（先落库当前编辑内容） */
  const handlePublish = async () => {
    if (!taskId) return;
    setPublishing(true);
    try {
      await procurementTaskApi.saveFrameworkExplanation(taskId, buildSavePayload());
      await procurementTaskApi.publish(taskId);
      message.success('已发布，框架协议事前说明状态变更为「已完成」');
      setModalMode(null);
      closeEdit();
    } finally {
      setPublishing(false);
    }
  };

  /** 模块内置文档 HTML（含 {{占位符}}，未替换；统一管线内完成模板优先与变量替换） */
  const rawDocHtml = useMemo(() => {
    if (!currentTask) return '';
    const ctx = {
      projectName: project.name,
      projectAbbr: project.nameAbbr,
      undertaker: project.undertaker,
      provinceCity: project.provinceCity,
      siteLocation: project.siteLocation,
      projectAddress: project.projectAddress,
      content: currentTask.content,
    };
    const title = `${project.nameAbbr || project.name || ''}-${currentTask.content}-框架协议事前说明`;
    return buildExplanationDocHtml(form, ctx, title);
  }, [form, currentTask, project]);

  /** 变量取值（统一预览 / 导出共用） */
  const varValues = useMemo(() => {
    const ctx = {
      projectName: project.name,
      projectAbbr: project.nameAbbr,
      undertaker: project.undertaker,
      provinceCity: project.provinceCity,
      siteLocation: project.siteLocation,
      projectAddress: project.projectAddress,
      content: currentTask?.content,
    };
    return buildExplanationVariableValues(form, ctx);
  }, [form, currentTask]);

  const exportFilename = `${
    project.nameAbbr || project.name || '项目'
  }-${currentTask?.content || '采购'}-框架协议事前说明.docx`;

  const handleExport = async () => {
    if (!currentTask) return;
    await exportProcurementWord({
      moduleType: 'FRAMEWORK',
      taskId: taskId ?? undefined,
      docHtml: rawDocHtml,
      values: varValues,
      filename: exportFilename,
    });
    message.success(`已导出：${exportFilename}`);
  };

  /** 只读详情文档（模板优先 + 变量替换，需求修正 · 修改二） */
  /** ---------- 表格编辑渲染 ---------- */
  const numberCell = (
    value: number | null | undefined,
    onChange: (v: number | null) => void,
    suffix?: string,
  ) => (
    <InputNumber
      size="small"
      style={{ width: '100%' }}
      min={0}
      precision={2}
      addonAfter={suffix}
      value={value ?? undefined}
      disabled={!editable}
      onChange={(v) => onChange(typeof v === 'number' ? v : null)}
    />
  );
  const textCell = (value: string | null | undefined, onChange: (v: string) => void) =>
    editable ? (
      <Input size="small" value={value ?? undefined} onChange={(e) => onChange(e.target.value)} />
    ) : (
      value ?? '-'
    );

  const opColumn = <T,>(field: 'inquiryRows' | 'priceCompareRows' | 'costRows' | 'referenceSuppliers') =>
    editable
      ? [
          {
            title: '',
            key: 'op',
            width: 50,
            render: (_: unknown, row: Keyed<T>) => (
              <Button
                type="link"
                size="small"
                danger
                icon={<DeleteOutlined />}
                onClick={() => removeRow(field, row.key)}
              />
            ),
          },
        ]
      : [];

  const inquiryColumns: ColumnsType<Keyed<InquiryRow>> = [
    {
      title: '排名',
      dataIndex: 'rank',
      width: 90,
      render: (v: string | null, row) => textCell(v, (val) => updateRow('inquiryRows', row.key, { rank: val })),
    },
    {
      title: '单位',
      dataIndex: 'unit',
      render: (v: string | null, row) => textCell(v, (val) => updateRow('inquiryRows', row.key, { unit: val })),
    },
    {
      title: '总价（元）',
      dataIndex: 'totalPrice',
      width: 150,
      render: (v: number | null, row) =>
        editable
          ? numberCell(v, (n) => updateRow('inquiryRows', row.key, { totalPrice: n }))
          : v != null
            ? v.toLocaleString('zh-CN')
            : '-',
    },
    {
      title: '含税',
      dataIndex: 'taxIncluded',
      width: 120,
      render: (v: string | null, row) =>
        editable ? (
          <Select
            size="small"
            style={{ width: '100%' }}
            value={v ?? undefined}
            allowClear
            placeholder="—"
            options={[
              { value: '含税', label: '含税' },
              { value: '不含税', label: '不含税' },
            ]}
            onChange={(val) => updateRow('inquiryRows', row.key, { taxIncluded: val ?? null })}
          />
        ) : (
          v ?? '-'
        ),
    },
    {
      title: '类型',
      dataIndex: 'type',
      width: 130,
      render: (v: string | null, row) => textCell(v, (val) => updateRow('inquiryRows', row.key, { type: val })),
    },
    ...opColumn<InquiryRow>('inquiryRows'),
  ];

  const priceColumns: ColumnsType<Keyed<PriceCompareRow>> = [
    { title: '序号', width: 60, render: (_v, _r, i) => i + 1 },
    {
      title: '单位',
      dataIndex: 'unit',
      render: (v: string | null, row) => textCell(v, (val) => updateRow('priceCompareRows', row.key, { unit: val })),
    },
    {
      title: '合同内容',
      dataIndex: 'content',
      render: (v: string | null, row) => textCell(v, (val) => updateRow('priceCompareRows', row.key, { content: val })),
    },
    {
      title: '执行合同价（元）',
      dataIndex: 'execPrice',
      width: 160,
      render: (v: number | null, row) =>
        editable
          ? numberCell(v, (n) => updateRow('priceCompareRows', row.key, { execPrice: n }))
          : v != null
            ? v.toLocaleString('zh-CN')
            : '-',
    },
    {
      title: '备注',
      dataIndex: 'note',
      render: (v: string | null, row) => textCell(v, (val) => updateRow('priceCompareRows', row.key, { note: val })),
    },
    ...opColumn<PriceCompareRow>('priceCompareRows'),
  ];

  const costColumns: ColumnsType<Keyed<CostRow>> = [
    {
      title: '成本项目',
      dataIndex: 'item',
      render: (v: string | null, row) => textCell(v, (val) => updateRow('costRows', row.key, { item: val })),
    },
    {
      title: '金额（万元）',
      dataIndex: 'amount',
      width: 140,
      render: (v: number | null, row) =>
        editable
          ? numberCell(v, (n) => updateRow('costRows', row.key, { amount: n }))
          : v != null
            ? v.toLocaleString('zh-CN')
            : '-',
    },
    {
      title: '占比（%）',
      dataIndex: 'ratio',
      width: 120,
      render: (v: number | null, row) =>
        editable
          ? numberCell(v, (n) => updateRow('costRows', row.key, { ratio: n }), '%')
          : v != null
            ? `${v}%`
            : '-',
    },
    {
      title: '备注',
      dataIndex: 'note',
      render: (v: string | null, row) => textCell(v, (val) => updateRow('costRows', row.key, { note: val })),
    },
    ...opColumn<CostRow>('costRows'),
  ];

  const addRow = (field: 'inquiryRows' | 'priceCompareRows' | 'costRows' | 'referenceSuppliers') => {
    setForm((f) => {
      if (field === 'inquiryRows') {
        const blank: Keyed<InquiryRow> = {
          key: nextKey(),
          rank: String(f.inquiryRows.length + 1),
          unit: '',
          totalPrice: null,
          taxIncluded: '含税',
          type: '',
        };
        return { ...f, inquiryRows: [...f.inquiryRows, blank] };
      }
      if (field === 'priceCompareRows') {
        const blank: Keyed<PriceCompareRow> = { key: nextKey(), unit: '', content: '', execPrice: null, note: '' };
        return { ...f, priceCompareRows: [...f.priceCompareRows, blank] };
      }
      if (field === 'referenceSuppliers') {
        const blank: Keyed<ReferenceSupplier> = { key: nextKey(), supplier: '', amount: null };
        return { ...f, referenceSuppliers: [...f.referenceSuppliers, blank] };
      }
      const blank: Keyed<CostRow> = { key: nextKey(), item: '', amount: null, ratio: null, note: '' };
      return { ...f, costRows: [...f.costRows, blank] };
    });
  };

  /** ---------- 引用供应商及金额（问题五） ---------- */

  const refSupplierColumns: ColumnsType<Keyed<ReferenceSupplier>> = [
    {
      title: '供应商',
      dataIndex: 'supplier',
      render: (v: string | null, row) => textCell(v, (val) => updateRow('referenceSuppliers', row.key, { supplier: val })),
    },
    {
      title: '引用金额（元）',
      dataIndex: 'amount',
      width: 160,
      render: (v: number | null, row) =>
        editable
          ? numberCell(v, (n) => updateRow('referenceSuppliers', row.key, { amount: n }))
          : v != null
            ? v.toLocaleString('zh-CN')
            : '-',
    },
    ...opColumn<ReferenceSupplier>('referenceSuppliers'),
  ];

  /** 自动填充：从询价情况表取报价最低的单位与金额（规则走统一引擎，可多行手动增改） */
  const autoFillRefSuppliers = () => {
    const winners = lowestPriceSuppliers(form.inquiryRows);
    if (!winners.length) {
      message.warning('询价情况表中暂无有效报价（单位 + 总价），无法自动填充');
      return;
    }
    setForm((f) => ({
      ...f,
      referenceSuppliers: winners.map((r) => ({ key: nextKey(), supplier: r.supplier, amount: r.amount })),
    }));
    message.success(
      `已自动填充询价最低价供应商 ${winners.length} 家（最低价 ${winners[0].amount.toLocaleString('zh-CN')} 元），可继续手动增改`,
    );
  };

  const refSupplierSection = (
    <Card
      size="small"
      title="引用供应商及金额"
      extra={
        editable && (
          <Space size={8}>
            <Button size="small" onClick={autoFillRefSuppliers}>
              自动填充最低价
            </Button>
            <Button size="small" icon={<PlusOutlined />} onClick={() => addRow('referenceSuppliers')}>
              添加行
            </Button>
          </Space>
        )
      }
    >
      <Table
        size="small"
        rowKey="key"
        columns={refSupplierColumns}
        dataSource={form.referenceSuppliers as unknown as any[]}
        scroll={{ x: 'max-content' }}
        pagination={false}
        locale={{ emptyText: '暂无数据（可点击「自动填充最低价」从询价情况带出，或手动添加行）' }}
      />
    </Card>
  );

  /** ---------- 渲染 ---------- */
  const textSection = (
    label: string,
    field: 'frameworkIntro' | 'negotiation' | 'execution',
    rows = 5,
  ) => (
    <Card size="small" title={label}>
      {editable ? (
        <Input.TextArea
          rows={rows}
          value={form[field]}
          maxLength={5000}
          placeholder={`请填写${label}`}
          onChange={(e) => patchForm({ [field]: e.target.value } as Partial<ExplanationForm>)}
        />
      ) : (
        <div style={{ whiteSpace: 'pre-wrap', color: form[field] ? undefined : 'var(--cms-muted-soft)' }}>
          {form[field] || '（待填写）'}
        </div>
      )}
    </Card>
  );

  const tableSection = (
    label: string,
    field: 'inquiryRows' | 'priceCompareRows' | 'costRows',
    columns: ColumnsType<any>,
  ) => (
    <Card
      size="small"
      title={label}
      extra={
        editable && (
          <Button size="small" icon={<PlusOutlined />} onClick={() => addRow(field)}>
            添加行
          </Button>
        )
      }
    >
      <Table
        size="small"
        rowKey="key"
        columns={columns}
        dataSource={form[field] as unknown as any[]}
        scroll={{ x: 'max-content' }}
        pagination={false}
        locale={{ emptyText: '暂无数据' }}
      />
    </Card>
  );

  /* ---------------- 渲染 ---------------- */

  /** 问题五：模块特有筛选（采购内容为公共筛选，这里补「供应商」） */
  const extraFilters: ModuleListFilterField[] = [
    { key: 'supplier', label: '供应商', control: 'input', placeholder: '请输入供应商' },
  ];

  /** 问题五：模块特有表格列（采购内容后：供应商 / 引用金额） */
  const extraColumns: ColumnsType<ModuleListRow> = [
    {
      title: '供应商',
      key: 'supplier',
      width: 200,
      ellipsis: { showTitle: true },
      render: (_v, row) => {
        const names: string[] = (row.module?.referenceSuppliers ?? [])
          .map((r: any) => String(r?.supplier ?? '').trim())
          .filter(Boolean);
        return names.length ? names.join('、') : '-';
      },
    },
    {
      title: '引用金额（元）',
      key: 'refAmount',
      width: 150,
      align: 'right',
      render: (_v, row) => {
        const list: any[] = row.module?.referenceSuppliers ?? [];
        if (!list.length) return '-';
        const sum = list.reduce((s, r) => s + (Number(r?.amount) || 0), 0);
        return sum.toLocaleString('zh-CN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
      },
    },
  ];

  return (
    <Space direction="vertical" size={12} style={{ width: '100%' }}>
      {/* 标准列表页（批次五）：筛选区 + 工具栏 + 数据表格（无模块特有列/筛选项） */}
      <ModuleListPage
        moduleKey="FRAMEWORK_EXPLANATION"
        baseParams={{ type: 'FRAMEWORK' }}
        extraFilters={extraFilters}
        extraColumns={extraColumns}
        toolbarLeft={
          <span style={{ color: 'var(--cms-muted-soft)', fontSize: 13 }}>
            仅显示引用框架协议类型的任务；编辑与发布以任务所处阶段为准
          </span>
        }
        refreshKey={listRefresh + tabRefresh}
        editPermission="procurement:edit"
        onView={handleViewRow}
        onEdit={editRow}
        onDelete={handleDeleteModule}
        emptyText="暂无数据（仅「引用框架协议」类型的采购任务可使用框架协议事前说明模块）"
        rowMenuItems={(row, { canEdit }) => {
          const published = moduleStatusOf(row).value === 'PUBLISHED';
          return published
            ? [
                {
                  key: 'exportWord',
                  label: (
                    <span>
                      <FileWordOutlined /> 导出Word
                    </span>
                  ),
                  onClick: () => handleRowExport(row),
                },
                ...(canEdit ? [{ key: 'reEdit', label: '重新编辑', onClick: () => editRow(row, true) }] : []),
              ]
            : [];
        }}
      />

      {/* 任务查看弹窗（问题一：已完成行「查看」→ 居中弹窗：任务信息+采购明细+Word 文档） */}
      <TaskViewModal task={viewRow} open={!!viewRow} onClose={() => setViewRow(null)} />

      {/* 编辑弹窗（问题一：未填写/编辑中行「编辑」直接进入；问题三：居中弹窗） */}
      {/* 编辑器页签（未填写/编辑中行「编辑」直接进入；底部操作栏 sticky） */}
      {taskId && (
        <EditorTabPage
          listPath={LIST_PATH}
          title={`框架协议事前说明 · 编辑${currentTask ? ` · ${currentTask.taskNo}` : ''}`}
          saving={saving}
          saveText="保 存"
          onSave={editable ? handleSave : undefined}
          // 本页有独立的「发布」流程，保存不关标签
          closeOnSave={false}
          dirty={dirty}
          footerLeft={
            <Space wrap size={8}>
              {currentTask && (
                <Button icon={<EyeOutlined />} onClick={() => setModalMode('preview')}>
                  预览
                </Button>
              )}
              {currentTask && (
                <Button icon={<FileWordOutlined />} onClick={handleExport}>
                  导出Word
                </Button>
              )}
            </Space>
          }
          footerExtra={
            detail && !detail.published && editable ? (
              <Button type="primary" icon={<SendOutlined />} onClick={openPublishPreview}>
                发布
              </Button>
            ) : null
          }
        >
        <Spin spinning={detailLoading}>
          {!currentTask && !detailLoading && (
            <Alert type="warning" showIcon message="任务详情加载失败，请关闭后重试。" />
          )}
          {currentTask && (
            <Space direction="vertical" size={12} style={{ width: '100%' }}>
            {editable && detail?.published && (
              <Alert
                type="warning"
                showIcon
                message="重新编辑模式：修改后请保存，发布状态保持「已完成」。"
              />
            )}

            {textSection('一、框架简介', 'frameworkIntro', 6)}
            {textSection('二、谈判情况', 'negotiation')}
            {tableSection('三、询价情况', 'inquiryRows', inquiryColumns)}
            {refSupplierSection}
            {/* 四、价格对比表：支持从采购价格对比表一键导入（任务 3.6） */}
            <Card
              size="small"
              title="四、同城/相邻城市局其他单位执行合同价"
              extra={
                editable && (
                  <Space size={8}>
                    <Button
                      size="small"
                      loading={importing}
                      onClick={handleImportPriceCompare}
                      title="从本任务的「采购价格对比表」导入明细"
                    >
                      从价格对比表导入
                    </Button>
                    <Button size="small" icon={<PlusOutlined />} onClick={() => addRow('priceCompareRows')}>
                      添加行
                    </Button>
                  </Space>
                )
              }
            >
              <Table
                size="small"
                rowKey="key"
                columns={priceColumns}
                dataSource={form.priceCompareRows as unknown as any[]}
                scroll={{ x: 'max-content' }}
                pagination={false}
                locale={{ emptyText: '暂无数据，可点击「从价格对比表导入」带出，或手动添加行' }}
              />
            </Card>
            {textSection('五、执行情况', 'execution')}
            {tableSection('六、成本分析', 'costRows', costColumns)}

            <Card
              size="small"
              title="七、附表"
              extra={
                editable && (
                  <Upload
                    name="files"
                    multiple
                    showUploadList={false}
                    customRequest={async (options: any) => {
                      try {
                        const fd = new FormData();
                        fd.append('files', options.file);
                        const res: any = await http.post('/files/upload', fd);
                        const arr = Array.isArray(res) ? res : res?.data ?? [];
                        options.onSuccess?.(arr[0]);
                      } catch (e) {
                        options.onError?.(e);
                      }
                    }}
                    onChange={(info) => {
                      const list = info.fileList.filter((f) => f.status !== 'removed');
                      setFileList(list);
                      if (info.file.status === 'done') message.success(`「${info.file.name}」上传成功`);
                      if (info.file.status === 'error') message.error(`「${info.file.name}」上传失败`);
                    }}
                  >
                    <Button size="small" icon={<PlusOutlined />}>
                      上传附件
                    </Button>
                  </Upload>
                )
              }
            >
              {fileList.length === 0 ? (
                <span style={{ color: 'var(--cms-muted-soft)' }}>（无附表）</span>
              ) : (
                <Space direction="vertical" size={4}>
                  {fileList.map((f) => (
                    <Space key={f.uid}>
                      <FileWordOutlined />
                      <span>{f.name}</span>
                      {editable && (
                        <Button
                          type="link"
                          size="small"
                          danger
                          icon={<DeleteOutlined />}
                          onClick={() => setFileList((l) => l.filter((x) => x.uid !== f.uid))}
                        >
                          移除
                        </Button>
                      )}
                    </Space>
                  ))}
                </Space>
              )}
            </Card>
          </Space>
          )}
        </Spin>
        </EditorTabPage>
      )}

      {/* 统一预览 / 发布流程（批次四 · 任务 4.2）：发布前确认与发布后预览共用 */}
      <PreviewPublishModal
        open={modalMode !== null}
        mode={modalMode ?? 'preview'}
        moduleType="FRAMEWORK"
        taskId={taskId ?? undefined}
        docHtml={rawDocHtml}
        values={varValues}
        publishing={publishing}
        filename={exportFilename}
        projectAbbr={project.nameAbbr}
        content={currentTask?.content}
        confirmTitle="确认发布框架协议事前说明？"
        confirmDescription="发布前将自动保存当前内容；发布后状态变更为「已完成」，仍可预览与重新编辑。"
        onPublish={handlePublish}
        onClose={() => setModalMode(null)}
      />
    </Space>
  );
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import {
  Alert,
  Button,
  Card,
  Col,
  DatePicker,
  Descriptions,
  Input,
  Modal,
  Popconfirm,
  Row,
  Space,
  Spin,
  Table,
  Tooltip,
  message,
} from 'antd';
import type { ColumnsType } from 'antd/es/table';
import {
  DeleteOutlined,
  EyeOutlined,
  FileWordOutlined,
  PlusOutlined,
  SaveOutlined,
  SendOutlined,
} from '@ant-design/icons';
import dayjs from 'dayjs';
import { procurementTaskApi } from '@/api/modules';
import { projectApi } from '@/api/business';
import { useAuthStore } from '@/store/auth';
import { taskStatusLabel, taskTypeLabel } from '@/constants/procurementWorkflow';
import RichTextEditor from '@/components/RichTextEditor';
import PreviewPublishModal from '@/components/PreviewPublishModal';
import TaskViewModal from '@/components/procurement/TaskViewModal';
import ModuleListPage, {
  moduleStatusOf,
  type ModuleListFilterField,
  type ModuleListRow,
  useModuleDelete,
} from '@/components/procurement/ModuleListPage';
import { exportProcurementWord } from '@/utils/procurementExport';
import { exportTaskModuleWord } from '@/utils/procurementTaskDocs';
import EditorTabPage from '@/components/editor/EditorTabPage';
import { useEditorTab, useTabRefresh } from '@/hooks/useTabs';
import { editorTabKey } from '@/utils/tabs';

/** 列表与编辑器是同一路由的两种形态（`?editor=<taskId>`），见 `useEditorTab` 的注释 */
const LIST_PATH = '/procurement/notice';
import {
  buildNoticeDocHtml,
  buildNoticeVariableValues,
  contactEntries,
  type NoticeData,
  type NoticePurchaseItem,
} from '@/utils/procurementNotice';

/** 模块类型（与采购模板 moduleType、变量占位符前缀一致） */
const MODULE_TYPE = 'NOTICE';

/** 采购任务行（列表精简） */
interface TaskRow {
  id: string;
  taskNo: string;
  type: string;
  content: string;
  status: string;
  stage: number;
  preMeetingRequired: boolean;
  /** 补充二：采购发起填写、随任务下发的三个标准（公告/文件/合同模板只读引用） */
  techQuality?: string;
  acceptanceMethod?: string;
  paymentMethod?: string;
}

/** 可编辑行：带前端 key 供 Table 渲染（保存时剔除） */
type Keyed<T> = T & { key: string };

/** 联系人 / 联系电话（成对动态增加，按位置自动编号 联系人1 / 联系电话1） */
interface ContactRow {
  name: string;
  phone: string;
}

interface NoticeForm {
  procurementNo: string;
  procurementTime: string | null;
  content: string;
  contacts: Keyed<ContactRow>[];
}

interface NoticeDetail {
  task: TaskRow;
  /** 公告阶段在阶段链中的下标 */
  stageIndex: number;
  /** 是否已进入或完成公告阶段 */
  reached: boolean;
  editable: boolean;
  published: boolean;
  status: string;
  statusLabel: string;
  /** 采购清单（只读，来自总采购清单） */
  purchaseItems: NoticePurchaseItem[];
  data:
    | (Omit<NoticeForm, 'contacts'> & {
        id?: string;
        contacts?: string[];
        contactPhones?: string[];
        publishedAt?: string | null;
      })
    | null;
}

let rowSeq = 0;
const nextKey = (): string => {
  rowSeq += 1;
  return `row-${Date.now()}-${rowSeq}`;
};
const withKeys = <T,>(rows: T[] = []): Keyed<T>[] => rows.map((r) => ({ ...r, key: nextKey() }));
const stripKey = <T,>(row: Keyed<T>): T => {
  const { key: _key, ...rest } = row;
  return rest as unknown as T;
};
/** 联系人列表至少保留一行，便于直接录入 */
const normalizeContacts = (rows: Keyed<ContactRow>[]): Keyed<ContactRow>[] =>
  rows.length ? rows : withKeys<ContactRow>([{ name: '', phone: '' }]);

const EMPTY_FORM: NoticeForm = {
  procurementNo: '',
  procurementTime: null,
  content: '',
  contacts: withKeys<ContactRow>([{ name: '', phone: '' }]),
};

/** 带标签的表单块（只读时降级为文本） */
function Field({
  label,
  value,
  editable,
  onChange,
  placeholder,
}: {
  label: string;
  value: string;
  editable: boolean;
  onChange: (v: string) => void;
  placeholder?: string;
}) {
  return (
    <div>
      <div style={{ color: 'var(--cms-muted-soft)', fontSize: 12, marginBottom: 4 }}>{label}</div>
      {editable ? (
        <Input value={value} placeholder={placeholder ?? `请填写${label}`} onChange={(e) => onChange(e.target.value)} />
      ) : (
        <div style={{ minHeight: 22 }}>{value || '-'}</div>
      )}
    </div>
  );
}

export default function Notice() {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const currentProjectId = useAuthStore((s) => s.currentProjectId);

  /**
   * 列表与「编辑」是同一路由的两种形态（`?editor=<taskId>`），见 `useEditorTab` 的注释。
   * 编辑态原本是弹窗，现改为编辑器页签（底部操作栏 sticky，长表单不再把按钮滚出视口）。
   */
  const editorTab = useEditorTab(LIST_PATH);
  const tabRefresh = useTabRefresh(LIST_PATH);
  const taskId = editorTab.editorId === 'new' ? null : editorTab.editorId;
  /** 兼容旧深链 `?taskId=xxx`：归一成编辑器页签 */
  useEffect(() => {
    const legacy = searchParams.get('taskId');
    if (legacy && !editorTab.isEditor) navigate(editorTabKey(LIST_PATH, legacy), { replace: true });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  /** 列表刷新键：编辑器页签关闭后由 closeEditor 的 bump 触发；本键用于页内（删除等） */
  const [listRefresh, setListRefresh] = useState(0);
  /** 问题二：删除模块记录并回退流程 */
  const handleDeleteModule = useModuleDelete('NOTICE', () => setListRefresh((k) => k + 1));

  const [detail, setDetail] = useState<NoticeDetail | null>(null);
  const [detailLoading, setDetailLoading] = useState(false);

  const [form, setForm] = useState<NoticeForm>(EMPTY_FORM);
  const [saving, setSaving] = useState(false);
  const [publishing, setPublishing] = useState(false);
  /** 发布后默认只读；点「重新编辑」解锁 */
  const [reEditing, setReEditing] = useState(false);
  /** 统一预览/发布弹窗（批次四 · 任务 4.2）：publish=发布前确认；preview=纯预览 */
  const [modalMode, setModalMode] = useState<'preview' | 'publish' | null>(null);
  /** 未保存改动（关闭编辑器页签前确认） */
  const [dirty, setDirty] = useState(false);
  /** 任务查看弹窗（问题一：已完成行「查看」→ 任务信息+采购明细+Word 文档） */
  const [viewRow, setViewRow] = useState<ModuleListRow | null>(null);
  /** 重新编辑标记：loadDetail 完成后按此恢复可编辑（已发布行「重新编辑」） */
  const reEditRef = useRef(false);

  const [project, setProject] = useState<{
    name?: string;
    nameAbbr?: string;
    undertaker?: string;
    provinceCity?: string;
    siteLocation?: string;
    projectAddress?: string;
  }>({});

  const currentTask = detail?.task ?? null;
  /** 当前是否可编辑：公告编制中，或已发布后主动点「重新编辑」 */
  const editable = !!detail && (detail.editable || (detail.published && reEditing));

  useEffect(() => {
    if (!currentProjectId) return;
    projectApi
      .detail(currentProjectId)
      .then((res: any) => setProject(res ?? {}))
      .catch(() => setProject({}));
  }, [currentProjectId]);

  const loadDetail = useCallback((id: string) => {
    setDetailLoading(true);
    procurementTaskApi
      .notice(id)
      .then((res: any) => {
        const d: NoticeDetail = res; // 响应拦截器已解开 body.data，res 即完整 payload（含 task 与 data 记录）
        setDetail(d);
        const data = (d?.data ?? {}) as NonNullable<NoticeDetail['data']>;
        setForm({
          procurementNo: data.procurementNo || String(d?.task?.taskNo ?? ''),
          procurementTime: data.procurementTime ? dayjs(data.procurementTime).format('YYYY-MM-DD') : null,
          // 采购内容默认带出采购任务内容
          content: data.content || String(d?.task?.content ?? ''),
          contacts: normalizeContacts(
            withKeys(contactEntries(data.contacts ?? [], data.contactPhones ?? [])),
          ),
        });
        setReEditing(reEditRef.current && !!d.published);
        reEditRef.current = false;
      })
      .catch(() => {
        setDetail(null);
        setForm(EMPTY_FORM);
      })
      .finally(() => setDetailLoading(false));
  }, []);

  /** 列表行操作（问题一）：已完成行 → 任务查看弹窗；未填写/编辑中 → 直接进入编辑界面 */
  const handleViewRow = (row: ModuleListRow) => {
    if (moduleStatusOf(row).value === 'PUBLISHED') setViewRow(row);
    else editRow(row);
  };
  /** 列表行操作：编辑（reEdit=true 为已发布后的重新编辑）—— 打开编辑器页签，reEdit 随种子递过去 */
  const editRow = (row: ModuleListRow, reEdit = false) => {
    editorTab.openEdit(row.id, { reEdit });
  };
  /** 编辑器页签挂载时：按种子里的 reEdit 决定初始是否可编辑，并拉详情 */
  useEffect(() => {
    if (!taskId) return;
    reEditRef.current = !!(editorTab.seed as { reEdit?: boolean } | undefined)?.reEdit;
    loadDetail(taskId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [taskId]);

  /** 行「更多 → 导出Word」（问题二）：按任务直接构建并导出本模块文档 */
  const handleRowExport = async (row: ModuleListRow) => {
    try {
      const filename = await exportTaskModuleWord(MODULE_TYPE, row.id);
      message.success(`已导出：${filename}`);
    } catch (e: any) {
      message.error(e?.message || '导出失败，请稍后重试');
    }
  };

  const patchForm = (patch: Partial<NoticeForm>) => {
    setForm((f) => ({ ...f, ...patch }));
    setDirty(true);
  };

  /* ---------------- 联系人 / 联系电话（动态增加） ---------------- */

  const updateContact = (key: string, patch: Partial<ContactRow>) =>
    setForm((f) => ({
      ...f,
      contacts: f.contacts.map((r) => (r.key === key ? { ...r, ...patch } : r)),
    }));

  const addContact = () =>
    setForm((f) => ({ ...f, contacts: [...f.contacts, { key: nextKey(), name: '', phone: '' }] }));

  const removeContact = (key: string) =>
    setForm((f) => ({ ...f, contacts: normalizeContacts(f.contacts.filter((r) => r.key !== key)) }));

  /* ---------------- 保存 / 发布 / 导出 ---------------- */

  const buildSavePayload = () => ({
    procurementNo: form.procurementNo,
    procurementTime: form.procurementTime || null,
    content: form.content,
    contacts: form.contacts.map((r) => String(r.name ?? '').trim()),
    contactPhones: form.contacts.map((r) => String(r.phone ?? '').trim()),
  });

  const handleSave = async () => {
    if (!taskId) return;
    setSaving(true);
    try {
      await procurementTaskApi.saveNotice(taskId, buildSavePayload());
      message.success('已保存');
      // 编辑器页签形态下「保存」不关标签，就地重载详情与列表
      loadDetail(taskId);
      setDirty(false);
      setListRefresh((x) => x + 1);
    } finally {
      setSaving(false);
    }
  };

  /** 发布流程第 1 步：校验必填 → 打开「发布前预览」 */
  const openPublishPreview = () => {
    if (!String(form.procurementNo ?? '').trim()) {
      message.warning('请先填写「采购编号」再发布');
      return;
    }
    if (!form.procurementTime) {
      message.warning('请先选择「采购时间」再发布');
      return;
    }
    if (!String(form.content ?? '').trim()) {
      message.warning('请先填写「采购内容」再发布');
      return;
    }
    setModalMode('publish');
  };

  /** 发布流程第 2 步：确认发布（先落库当前编辑内容，避免「发布的内容 ≠ 已保存的内容」） */
  const handlePublish = async () => {
    if (!taskId) return;
    setPublishing(true);
    try {
      await procurementTaskApi.saveNotice(taskId, buildSavePayload());
      await procurementTaskApi.publish(taskId);
      message.success('已发布，采购公告状态变更为「已完成」');
      setModalMode(null);
      setDirty(false);
      // 发布即完成本模块 → 关掉编辑器页签并让列表重新取数
      editorTab.closeEditor();
    } finally {
      setPublishing(false);
    }
  };

  /** 文档数据（联系人转事件对数组） */
  const docData = useMemo<NoticeData>(
    () => ({
      procurementNo: form.procurementNo,
      procurementTime: form.procurementTime,
      content: form.content,
      // 补充二：技术质量/验收/付款标准取自采购发起填写的任务三字段（只读）
      techQuality: currentTask?.techQuality ?? '',
      acceptanceMethod: currentTask?.acceptanceMethod ?? '',
      paymentMethod: currentTask?.paymentMethod ?? '',
      contacts: form.contacts.map((r) => String(r.name ?? '').trim()),
      contactPhones: form.contacts.map((r) => String(r.phone ?? '').trim()),
      purchaseItems: detail?.purchaseItems ?? [],
    }),
    [form, detail],
  );

  const docCtx = useMemo(
    () => ({
      projectName: project.name,
      projectAbbr: project.nameAbbr,
      undertaker: project.undertaker,
      provinceCity: project.provinceCity,
      siteLocation: project.siteLocation,
      projectAddress: project.projectAddress,
      content: currentTask?.content,
    }),
    [project, currentTask],
  );

  /** 模块内置文档 HTML（含 {{占位符}}，未替换；统一管线内完成模板优先与变量替换） */
  const rawDocHtml = useMemo(() => {
    if (!currentTask) return '';
    const content = docData.content || currentTask.content;
    const title = `${project.nameAbbr || project.name || ''}-${content}-采购公告`;
    // {{采购公告-采购清单}} / {{采购编号}} / {{采购时间}} / {{联系人1}} / {{联系电话1}} 等
    return buildNoticeDocHtml(docData, docCtx, title);
  }, [docData, docCtx, currentTask, project]);

  /** 变量取值（统一预览 / 导出共用） */
  const varValues = useMemo(
    () => buildNoticeVariableValues(docData, docCtx),
    [docData, docCtx],
  );

  const exportFilename = `${
    project.nameAbbr || project.name || '项目'
  }-${form.content || currentTask?.content || '采购'}-采购公告.docx`;

  const handleExport = async () => {
    if (!currentTask) return;
    await exportProcurementWord({
      moduleType: MODULE_TYPE,
      taskId: taskId ?? undefined,
      docHtml: rawDocHtml,
      values: varValues,
      filename: exportFilename,
    });
    message.success(`已导出：${exportFilename}`);
  };

  /* ---------------- 采购清单（只读）列 ---------------- */

  const purchaseColumns: ColumnsType<NoticePurchaseItem> = [
    { title: '序号', width: 60, render: (_v, _r, i) => i + 1 },
    { title: '物资名称', dataIndex: 'materialName', render: (v: string | null) => v || '-' },
    { title: '规格型号', dataIndex: 'spec', render: (v: string | null) => v || '-' },
    { title: '计量单位', dataIndex: 'unit', width: 110, render: (v: string | null) => v || '-' },
    {
      title: '暂定数量',
      dataIndex: 'qty',
      width: 130,
      render: (v: number | null) => (v != null ? Number(v).toLocaleString('zh-CN') : '-'),
    },
    { title: '备注', dataIndex: 'remark', width: 160, render: (v: string | null) => v || '-' },
  ];

  /* ---------------- 渲染 ---------------- */

  const richSection = (
    label: string,
    field: 'techQuality' | 'acceptanceMethod' | 'paymentMethod',
  ) => (
    <Card
      size="small"
      title={label}
      extra={<span style={{ color: 'var(--cms-muted-soft)', fontSize: 12 }}>取自采购发起填写的标准（只读）</span>}
    >
      <RichTextEditor
        value={currentTask?.[field] ?? ''}
        disabled
        minHeight={180}
        placeholder="（采购发起未填写技术质量/验收/付款标准）"
      />
    </Card>
  );

  /** 公告模块特有筛选项 */
  const extraFilters: ModuleListFilterField[] = [
    { key: 'procTime', label: '采购时间', control: 'dateRange' },
    { key: 'contact', label: '联系人', control: 'input' },
  ];

  /** 公告模块特有表格列 */
  const extraColumns: ColumnsType<ModuleListRow> = [
    {
      title: '采购时间',
      key: 'procurementTime',
      width: 120,
      render: (_v, row) =>
        row.module?.procurementTime ? dayjs(row.module.procurementTime).format('YYYY-MM-DD') : '-',
    },
    {
      title: '联系人',
      key: 'contacts',
      width: 150,
      ellipsis: { showTitle: true },
      render: (_v, row) =>
        Array.isArray(row.module?.contacts) && row.module.contacts.length
          ? row.module.contacts.join('、')
          : '-',
    },
  ];

  return (
    <Space direction="vertical" size={12} style={{ width: '100%' }}>
      {/* 标准列表页（批次五）：筛选区 + 工具栏 + 数据表格 */}
      <ModuleListPage
        moduleKey="NOTICE"
        baseParams={{ type: 'SINGLE' }}
        extraFilters={extraFilters}
        extraColumns={extraColumns}
        toolbarLeft={
          <span style={{ color: 'var(--cms-muted-soft)', fontSize: 13 }}>
            仅显示单项采购类型的任务；编辑与发布以任务所处阶段为准
          </span>
        }
        refreshKey={listRefresh + tabRefresh}
        editPermission="procurement:edit"
        onView={handleViewRow}
        onEdit={editRow}
        onDelete={handleDeleteModule}
        rowMenuItems={(row, { canEdit }) => {
          const published = moduleStatusOf(row).value === 'PUBLISHED';
          return published
            ? [
                {
                  key: 'exportWord',
                  label: (
                    <span>
                      <FileWordOutlined /> 导出Word
                    </span>
                  ),
                  onClick: () => handleRowExport(row),
                },
                ...(canEdit ? [{ key: 'reEdit', label: '重新编辑', onClick: () => editRow(row, true) }] : []),
              ]
            : [];
        }}
      />

      {/* 任务查看弹窗（问题一：已完成行「查看」→ 居中弹窗：任务信息+采购明细+Word 文档） */}
      <TaskViewModal task={viewRow} open={!!viewRow} onClose={() => setViewRow(null)} />

      {/* 编辑弹窗（问题一：未填写/编辑中行「编辑」直接进入；问题三：居中弹窗） */}
      {/* 编辑器页签（未填写/编辑中行「编辑」直接进入；底部操作栏 sticky） */}
      {taskId && (
        <EditorTabPage
          listPath={LIST_PATH}
          title={`采购公告 · 编辑${currentTask ? ` · ${currentTask.taskNo}` : ''}`}
          saving={saving}
          saveText="保 存"
          onSave={editable ? handleSave : undefined}
          // 本页有独立的「发布」流程，保存不关标签
          closeOnSave={false}
          dirty={dirty}
          footerLeft={
            <Space wrap size={8}>
              {currentTask && (
                <Button icon={<EyeOutlined />} onClick={() => setModalMode('preview')}>
                  预览
                </Button>
              )}
              {currentTask && (
                <Button icon={<FileWordOutlined />} onClick={handleExport}>
                  导出Word
                </Button>
              )}
            </Space>
          }
          footerExtra={
            detail && !detail.published && editable ? (
              <Button type="primary" icon={<SendOutlined />} onClick={openPublishPreview}>
                发布
              </Button>
            ) : null
          }
        >
        <Spin spinning={detailLoading}>
          {!currentTask && !detailLoading && (
            <Alert type="warning" showIcon message="任务详情加载失败，请关闭后重试。" />
          )}
          {currentTask && (
            <Space direction="vertical" size={12} style={{ width: '100%' }}>
              {detail && !detail.reached && (
                <Alert
                  type="info"
                  showIcon
                  message="该采购任务尚未进入采购公告阶段（需先发布总采购清单，如有采前会会议纪要亦需先发布）。"
                />
              )}
              {detail?.published && editable && (
                <Alert
                  type="warning"
                  showIcon
                  message="重新编辑模式：修改后请保存，发布状态保持「已完成」。"
                />
              )}

            {/* 展示信息 */}
            <Card size="small" title="展示信息">
              <Descriptions column={3} size="small" bordered>
                <Descriptions.Item label="采购内容">{form.content || currentTask.content}</Descriptions.Item>
                <Descriptions.Item label="采购编号">{form.procurementNo || '-'}</Descriptions.Item>
                <Descriptions.Item label="采购时间">{form.procurementTime || '-'}</Descriptions.Item>
                <Descriptions.Item label="采购类型">{taskTypeLabel(currentTask.type)}</Descriptions.Item>
                <Descriptions.Item label="任务状态">{taskStatusLabel(currentTask.status)}</Descriptions.Item>
                <Descriptions.Item label="发布时间">
                  {detail?.data?.publishedAt ? dayjs(detail.data.publishedAt).format('YYYY-MM-DD HH:mm') : '-'}
                </Descriptions.Item>
              </Descriptions>
            </Card>

            {/* 一、公告基本信息 */}
            <Card size="small" title="一、公告基本信息">
              <Row gutter={[16, 16]}>
                <Col xs={24} md={8}>
                  <Field
                    label="采购编号"
                    value={form.procurementNo}
                    editable={editable}
                    onChange={(v) => patchForm({ procurementNo: v })}
                  />
                </Col>
                <Col xs={24} md={8}>
                  <div style={{ color: 'var(--cms-muted-soft)', fontSize: 12, marginBottom: 4 }}>采购时间</div>
                  {editable ? (
                    <DatePicker
                      style={{ width: '100%' }}
                      value={form.procurementTime ? dayjs(form.procurementTime) : null}
                      onChange={(d) => patchForm({ procurementTime: d ? d.format('YYYY-MM-DD') : null })}
                    />
                  ) : (
                    <div style={{ minHeight: 22 }}>{form.procurementTime || '-'}</div>
                  )}
                </Col>
                <Col xs={24} md={8}>
                  <Field
                    label="采购内容"
                    value={form.content}
                    editable={editable}
                    onChange={(v) => patchForm({ content: v })}
                  />
                </Col>
                <Col xs={24}>
                  <div style={{ color: 'var(--cms-muted-soft)', fontSize: 12, marginBottom: 8 }}>
                    联系人 / 联系电话（可动态增加，多个时自动编号 联系人1、联系人2… / 联系电话1、联系电话2…）
                  </div>
                  <Space direction="vertical" size={8} style={{ width: '100%' }}>
                    {form.contacts.map((row, idx) => (
                      <Row gutter={8} key={row.key} align="middle">
                        <Col xs={24} md={9}>
                          {editable ? (
                            <Input
                              addonBefore={`联系人${idx + 1}`}
                              value={row.name}
                              placeholder="请输入联系人姓名"
                              onChange={(e) => updateContact(row.key, { name: e.target.value })}
                            />
                          ) : (
                            <div>
                              联系人{idx + 1}：{row.name || '-'}
                            </div>
                          )}
                        </Col>
                        <Col xs={24} md={12}>
                          {editable ? (
                            <Input
                              addonBefore={`联系电话${idx + 1}`}
                              value={row.phone}
                              placeholder="请输入联系电话"
                              onChange={(e) => updateContact(row.key, { phone: e.target.value })}
                            />
                          ) : (
                            <div>
                              联系电话{idx + 1}：{row.phone || '-'}
                            </div>
                          )}
                        </Col>
                        <Col xs={24} md={3}>
                          {editable && form.contacts.length > 1 && (
                            <Button
                              type="link"
                              danger
                              size="small"
                              icon={<DeleteOutlined />}
                              onClick={() => removeContact(row.key)}
                            />
                          )}
                        </Col>
                      </Row>
                    ))}
                  </Space>
                  {editable && (
                    <Button style={{ marginTop: 8 }} size="small" icon={<PlusOutlined />} onClick={addContact}>
                      添加联系人
                    </Button>
                  )}
                </Col>
              </Row>
            </Card>

            {/* 二、采购清单（只读，来自总采购清单） */}
            <Card
              size="small"
              title="二、采购清单"
              extra={<span style={{ color: 'var(--cms-muted-soft)', fontSize: 12 }}>数据来自总采购清单，不可编辑</span>}
            >
              <Table
                size="small"
                rowKey={(_r, i) => String(i)}
                columns={purchaseColumns}
                dataSource={detail?.purchaseItems ?? []}
                scroll={{ x: 'max-content' }}
                pagination={false}
                locale={{ emptyText: '暂无数据（总采购清单为空或尚未编制）' }}
              />
            </Card>

            {richSection('三、技术质量标准', 'techQuality')}
            {richSection('四、验收方式', 'acceptanceMethod')}
            {richSection('五、付款方式', 'paymentMethod')}
          </Space>
          )}
        </Spin>
        </EditorTabPage>
      )}

      {/* 统一预览 / 发布流程（批次四 · 任务 4.2）：发布前确认与发布后预览共用 */}
      <PreviewPublishModal
        open={modalMode !== null}
        mode={modalMode ?? 'preview'}
        moduleType={MODULE_TYPE}
        taskId={taskId ?? undefined}
        docHtml={rawDocHtml}
        values={varValues}
        publishing={publishing}
        filename={exportFilename}
        projectAbbr={project.nameAbbr}
        content={form.content || currentTask?.content}
        confirmTitle="确认发布采购公告？"
        confirmDescription="发布前将自动保存当前内容；发布后状态变更为「已完成」，任务状态流转到下一阶段。"
        tipMessage="请核对公告内容与采购清单，确认无误后点击「确认发布」。"
        onPublish={handlePublish}
        onClose={() => setModalMode(null)}
      />
    </Space>
  );
}

