/** 列表与编辑器是同一路由的两种形态（`?editor=<taskId>`），见 `useEditorTab` 的注释 */
const LIST_PATH = '/procurement/pre-meeting';
import {
  buildPreMeetingDocHtml,
  buildPreMeetingVariableValues,
  costRowsFromTotalList,
  deriveCostRow,
  fmtRate,
  fmtWan,
  summarizeCost,
  type CostAnalysisRow,
  type PreMeetingData,
  type PurchaseItemRow,
} from '@/utils/preMeetingMinutes';

/** 模块类型（与采购模板 moduleType、变量占位符前缀一致） */
const MODULE_TYPE = 'PRE_MEETING';

/** 采购任务行（列表精简） */
interface TaskRow {
  id: string;
  taskNo: string;
  type: string;
  content: string;
  status: string;
  stage: number;
  preMeetingRequired: boolean;
  estimatedAmountWan?: number;
}

/** 可编辑行：带前端 key 供 Table 渲染（保存时剔除） */
type Keyed<T> = T & { key: string };

interface MinutesForm {
  meetingTime: string | null;
  content: string;
  host: string;
  attendees: string;
  writer: string;
  reviewer: string;
  purchaseItems: Keyed<PurchaseItemRow>[];
  techQuality: string;
  acceptance: string;
  paymentTerms: string;
  costRows: Keyed<CostAnalysisRow>[];
}

interface MinutesDetail {
  task: TaskRow;
  /** 是否生成采前会会议纪要模块（单项采购且预计采购金额 ≥ 100 万） */
  generated: boolean;
  thresholdWan: number;
  estimatedAmountWan: number;
  editable: boolean;
  published: boolean;
  status: string;
  statusLabel: string;
  data:
    | (Omit<MinutesForm, 'purchaseItems' | 'costRows'> & {
        id?: string;
        purchaseItems?: PurchaseItemRow[];
        costRows?: CostAnalysisRow[];
        inquirySheets?: { fileName?: string; url?: string; size?: number | null }[];
        publishedAt?: string | null;
      })
    | null;
}

let rowSeq = 0;
const nextKey = (): string => {
  rowSeq += 1;
  return `row-${Date.now()}-${rowSeq}`;
};
const withKeys = <T,>(rows: T[] = []): Keyed<T>[] => rows.map((r) => ({ ...r, key: nextKey() }));
const stripKey = <T,>(row: Keyed<T>): T => {
  const { key: _key, ...rest } = row;
  return rest as unknown as T;
};

const EMPTY_FORM: MinutesForm = {
  meetingTime: null,
  content: '',
  host: '',
  attendees: '',
  writer: '',
  reviewer: '',
  purchaseItems: [],
  techQuality: '',
  acceptance: '',
  paymentTerms: '',
  costRows: [],
};

/** 带标签的表单块（只读时降级为文本） */
function Field({
  label,
  value,
  editable,
  onChange,
  placeholder,
}: {
  label: string;
  value: string;
  editable: boolean;
  onChange: (v: string) => void;
  placeholder?: string;
}) {
  return (
    <div>
      <div style={{ color: 'var(--cms-muted-soft)', fontSize: 12, marginBottom: 4 }}>{label}</div>
      {editable ? (
        <Input value={value} placeholder={placeholder ?? `请填写${label}`} onChange={(e) => onChange(e.target.value)} />
      ) : (
        <div style={{ minHeight: 22 }}>{value || '-'}</div>
      )}
    </div>
  );
}

export default function PreMeetingMinutes() {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const currentProjectId = useAuthStore((s) => s.currentProjectId);

  /**
   * 列表与「编辑」是同一路由的两种形态（`?editor=<taskId>`），见 `useEditorTab` 的注释。
   * 编辑态原本是弹窗，现改为编辑器页签（底部操作栏 sticky，长表单不再把按钮滚出视口）。
   */
  const editorTab = useEditorTab(LIST_PATH);
  const tabRefresh = useTabRefresh(LIST_PATH);
  const taskId = editorTab.editorId === 'new' ? null : editorTab.editorId;
  /** 兼容旧深链 `?taskId=xxx`：归一成编辑器页签 */
  useEffect(() => {
    const legacy = searchParams.get('taskId');
    if (legacy && !editorTab.isEditor) navigate(editorTabKey(LIST_PATH, legacy), { replace: true });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  /** 列表刷新键：编辑器页签关闭后由 closeEditor 的 bump 触发；本键用于页内（删除等） */
  const [listRefresh, setListRefresh] = useState(0);
  /** 问题二：删除模块记录并回退流程 */
  const handleDeleteModule = useModuleDelete('PRE_MEETING', () => setListRefresh((k) => k + 1));

  const [detail, setDetail] = useState<MinutesDetail | null>(null);
  const [detailLoading, setDetailLoading] = useState(false);

  const [form, setForm] = useState<MinutesForm>(EMPTY_FORM);
  const [fileList, setFileList] = useState<UploadFile[]>([]);
  const [saving, setSaving] = useState(false);
  const [publishing, setPublishing] = useState(false);
  /** 发布后默认预览（只读）；点「重新编辑」解锁 */
  const [reEditing, setReEditing] = useState(false);
  /** 统一预览/发布弹窗（批次四 · 任务 4.2）：publish=发布前确认；preview=纯预览 */
  const [modalMode, setModalMode] = useState<'preview' | 'publish' | null>(null);
  /** 未保存改动（关闭编辑器页签前确认） */
  const [dirty, setDirty] = useState(false);
  /** 任务查看弹窗（问题一：已完成行「查看」→ 任务信息+采购明细+Word 文档） */
  const [viewRow, setViewRow] = useState<ModuleListRow | null>(null);
  /** 重新编辑标记：loadDetail 完成后按此恢复可编辑（已发布行「重新编辑」） */
  const reEditRef = useRef(false);
  const [imgPreview, setImgPreview] = useState<string | null>(null);
  const [importing, setImporting] = useState(false);

  const [project, setProject] = useState<{
    name?: string;
    nameAbbr?: string;
    undertaker?: string;
    provinceCity?: string;
    siteLocation?: string;
    projectAddress?: string;
  }>({});

  const currentTask = detail?.task ?? null;
  /** 当前是否可编辑：编辑中阶段，或已发布后主动点「重新编辑」 */
  const editable = !!detail && (detail.editable || (detail.published && reEditing));

  useEffect(() => {
    if (!currentProjectId) return;
    projectApi
      .detail(currentProjectId)
      .then((res: any) => setProject(res ?? {}))
      .catch(() => setProject({}));
  }, [currentProjectId]);

  const loadDetail = useCallback((id: string) => {
    setDetailLoading(true);
    procurementTaskApi
      .preMeetingMinutes(id)
      .then((res: any) => {
        const d: MinutesDetail = res; // 响应拦截器已解开 body.data，res 即完整 payload（含 task 与 data 记录）
        setDetail(d);
        const data = (d?.data ?? {}) as NonNullable<MinutesDetail['data']>;
        setForm({
          meetingTime: data.meetingTime ? dayjs(data.meetingTime).format('YYYY-MM-DD') : null,
          // 采购内容默认带出采购任务内容
          content: data.content || String(d?.task?.content ?? ''),
          host: data.host ?? '',
          attendees: data.attendees ?? '',
          writer: data.writer ?? '',
          reviewer: data.reviewer ?? '',
          purchaseItems: withKeys(data.purchaseItems ?? []),
          techQuality: data.techQuality ?? '',
          acceptance: data.acceptance ?? '',
          paymentTerms: data.paymentTerms ?? '',
          costRows: withKeys(data.costRows ?? []),
        });
        setFileList(
          (data.inquirySheets ?? []).map((f, i) => ({
            uid: f.url || `sheet-${i}`,
            name: f.fileName || `询价单${i + 1}`,
            status: 'done' as const,
            url: f.url,
            response: f,
          })),
        );
        setReEditing(reEditRef.current && !!d.published);
        reEditRef.current = false;
        // 首次进入（尚未保存过）时，采购清单与成本分析表自动从总采购清单带出
        const empty = (data.purchaseItems ?? []).length === 0 && (data.costRows ?? []).length === 0;
        if (empty && d?.editable) void importFromTotalList(id, { silent: true });
      })
      .catch(() => {
        setDetail(null);
        setForm(EMPTY_FORM);
        setFileList([]);
      })
      .finally(() => setDetailLoading(false));
    // importFromTotalList 为稳定引用（依赖 setState），此处不纳入依赖
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  /** 列表行操作（问题一）：已完成行 → 任务查看弹窗；未填写/编辑中 → 直接进入编辑界面 */
  const handleViewRow = (row: ModuleListRow) => {
    if (moduleStatusOf(row).value === 'PUBLISHED') setViewRow(row);
    else editRow(row);
  };
  /** 列表行操作：编辑（reEdit=true 为已发布后的重新编辑）—— 打开编辑器页签，reEdit 随种子递过去 */
  const editRow = (row: ModuleListRow, reEdit = false) => {
    editorTab.openEdit(row.id, { reEdit });
  };
  /** 编辑器页签挂载时：按种子里的 reEdit 决定初始是否可编辑，并拉详情 */
  useEffect(() => {
    if (!taskId) return;
    reEditRef.current = !!(editorTab.seed as { reEdit?: boolean } | undefined)?.reEdit;
    loadDetail(taskId);
    // taskId 变化即换记录；loadDetail 为稳定引用
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [taskId]);

  /** 行「更多 → 导出Word」（问题二）：按任务直接构建并导出本模块文档 */
  const handleRowExport = async (row: ModuleListRow) => {
    try {
      const filename = await exportTaskModuleWord(MODULE_TYPE, row.id);
      message.success(`已导出：${filename}`);
    } catch (e: any) {
      message.error(e?.message || '导出失败，请稍后重试');
    }
  };

  const patchForm = (patch: Partial<MinutesForm>) => {
    setForm((f) => ({ ...f, ...patch }));
    setDirty(true);
  };

  const updateRow = (
    field: 'purchaseItems' | 'costRows',
    key: string,
    patch: Record<string, unknown>,
  ) => {
    setForm((f) => ({
      ...f,
      [field]: (f[field] as Keyed<unknown>[]).map((r) => (r.key === key ? { ...r, ...patch } : r)),
    }));
  };
  const removeRow = (field: 'purchaseItems' | 'costRows', key: string) => {
    setForm((f) => ({
      ...f,
      [field]: (f[field] as Keyed<unknown>[]).filter((r) => r.key !== key),
    }));
  };

  /** 询价单：Upload fileList 中的成功响应即图片元数据 */
  const sheetsFromList = (list: UploadFile[]) =>
    list
      .map((f) => f.response as { fileName?: string; url?: string; size?: number | null } | undefined)
      .filter((f): f is { fileName?: string; url?: string; size?: number | null } => !!f?.url);

  /** 从「总采购清单」导入采购清单 / 成本分析表初始值 */
  const importFromTotalList = useCallback(
    async (id: string, opts: { silent?: boolean } = {}) => {
      setImporting(true);
      try {
        const res: any = await procurementTaskApi.totalList(id);
        const items: any[] = res?.data?.items ?? res?.items ?? [];
        if (!items.length) {
          if (!opts.silent) {
            message.warning('总采购清单暂无明细，请先在「采购发起 → 总采购清单」中编制并发布');
          }
          return;
        }
        setForm((f) => ({
          ...f,
          purchaseItems: withKeys(
            items.map((i) => ({
              materialName: i.materialName ?? '',
              spec: i.spec ?? '',
              unit: i.unit ?? '',
              qty: i.qty ?? null,
            })),
          ),
          costRows: withKeys(costRowsFromTotalList(items)),
        }));
        if (!opts.silent) message.success(`已从总采购清单导入 ${items.length} 条明细（收入/成本按万元换算）`);
      } catch {
        if (!opts.silent) message.error('导入总采购清单失败');
      } finally {
        setImporting(false);
      }
    },
    [],
  );

  const buildSavePayload = () => ({
    meetingTime: form.meetingTime || null,
    content: form.content,
    host: form.host,
    attendees: form.attendees,
    writer: form.writer,
    reviewer: form.reviewer,
    purchaseItems: form.purchaseItems.map(stripKey),
    techQuality: form.techQuality,
    acceptance: form.acceptance,
    paymentTerms: form.paymentTerms,
    costRows: form.costRows.map(stripKey),
    inquirySheets: sheetsFromList(fileList),
  });

  const handleSave = async () => {
    if (!taskId) return;
    setSaving(true);
    try {
      await procurementTaskApi.savePreMeetingMinutes(taskId, buildSavePayload());
      message.success('已保存');
      // 编辑器页签形态下「保存」不关标签，就地重载详情与列表
      loadDetail(taskId);
      setDirty(false);
      setListRefresh((x) => x + 1);
    } finally {
      setSaving(false);
    }
  };

  /** 发布流程第 1 步：校验必填 → 打开「发布前预览」（统一预览发布流程） */
  const openPublishPreview = () => {
    if (!taskId) return;
    if (!form.meetingTime || !String(form.content ?? '').trim()) {
      message.warning('请先填写「会议时间」与「采购内容」再发布');
      return;
    }
    setModalMode('publish');
  };

  /** 发布流程第 2 步：确认发布（先落库当前编辑内容） */
  const handlePublish = async () => {
    if (!taskId) return;
    setPublishing(true);
    try {
      await procurementTaskApi.savePreMeetingMinutes(taskId, buildSavePayload());
      await procurementTaskApi.publish(taskId);
      message.success('已发布，采前会会议纪要状态变更为「已完成」');
      setModalMode(null);
      setDirty(false);
      // 发布即完成本模块 → 关掉编辑器页签并让列表重新取数
      editorTab.closeEditor();
    } finally {
      setPublishing(false);
    }
  };

  /** 文档数据（Dayjs → Date；剔除表格 key） */
  const docData = useMemo<PreMeetingData>(
    () => ({
      ...form,
      meetingTime: form.meetingTime,
      purchaseItems: form.purchaseItems.map(stripKey),
      costRows: form.costRows.map(stripKey),
    }),
    [form],
  );

  const docCtx = useMemo(
    () => ({
      projectName: project.name,
      projectAbbr: project.nameAbbr,
      undertaker: project.undertaker,
      provinceCity: project.provinceCity,
      siteLocation: project.siteLocation,
      projectAddress: project.projectAddress,
      content: currentTask?.content,
      estimatedAmountWan: detail?.estimatedAmountWan ?? null,
    }),
    [project, currentTask, detail],
  );

  /** 模块内置文档 HTML（含 {{占位符}}，未替换；统一管线内完成模板优先与变量替换） */
  const rawDocHtml = useMemo(() => {
    if (!currentTask) return '';
    const content = docData.content || currentTask.content;
    const title = `${project.nameAbbr || project.name || ''}-${content}-采前会会议纪要`;
    // {{采前会-采购清单}} / {{采前会-采购成本分析表}} / {{会议时间}} / {{主持人}} / {{参会人员}} 等
    return buildPreMeetingDocHtml(docData, docCtx, title);
  }, [docData, docCtx, currentTask, project]);

  /** 变量取值（统一预览 / 导出共用） */
  const varValues = useMemo(
    () => buildPreMeetingVariableValues(docData, docCtx),
    [docData, docCtx],
  );

  const exportFilename = `${
    project.nameAbbr || project.name || '项目'
  }-${form.content || currentTask?.content || '采购'}-采前会会议纪要.docx`;

  const handleExport = async () => {
    if (!currentTask) return;
    await exportProcurementWord({
      moduleType: MODULE_TYPE,
      taskId: taskId ?? undefined,
      docHtml: rawDocHtml,
      values: varValues,
      filename: exportFilename,
    });
    message.success(`已导出：${exportFilename}`);
  };

  /** 只读详情文档（模板优先 + 变量替换，需求修正 · 修改二） */
  /* ---------------- 表格列 ---------------- */

  const textCell = (value: string | null | undefined, onChange: (v: string) => void) =>
    editable ? (
      <Input size="small" value={value ?? undefined} onChange={(e) => onChange(e.target.value)} />
    ) : (
      value ?? '-'
    );

  const numberCell = (
    value: number | null | undefined,
    onChange: (v: number | null) => void,
    opts: { precision?: number; suffix?: string; min?: number } = {},
  ) => (
    <InputNumber
      size="small"
      style={{ width: '100%' }}
      min={opts.min ?? 0}
      precision={opts.precision ?? 2}
      addonAfter={opts.suffix}
      value={value ?? undefined}
      disabled={!editable}
      onChange={(v) => onChange(typeof v === 'number' ? v : null)}
    />
  );

  const opColumn = (field: 'purchaseItems' | 'costRows') =>
    editable
      ? [
          {
            title: '',
            key: 'op',
            width: 50,
            render: (_: unknown, row: Keyed<unknown>) => (
              <Button
                type="link"
                size="small"
                danger
                icon={<DeleteOutlined />}
                onClick={() => removeRow(field, row.key)}
              />
            ),
          },
        ]
      : [];

  const purchaseColumns: ColumnsType<Keyed<PurchaseItemRow>> = [
    { title: '序号', width: 60, render: (_v, _r, i) => i + 1 },
    {
      title: '物资名称',
      dataIndex: 'materialName',
      render: (v: string | null, row) =>
        textCell(v, (val) => updateRow('purchaseItems', row.key, { materialName: val })),
    },
    {
      title: '规格型号',
      dataIndex: 'spec',
      render: (v: string | null, row) => textCell(v, (val) => updateRow('purchaseItems', row.key, { spec: val })),
    },
    {
      title: '计量单位',
      dataIndex: 'unit',
      width: 120,
      render: (v: string | null, row) => textCell(v, (val) => updateRow('purchaseItems', row.key, { unit: val })),
    },
    {
      title: '暂定数量',
      dataIndex: 'qty',
      width: 140,
      render: (v: number | null, row) =>
        editable
          ? numberCell(v, (n) => updateRow('purchaseItems', row.key, { qty: n }), { precision: 3 })
          : v != null
            ? v.toLocaleString('zh-CN')
            : '-',
    },
    ...opColumn('purchaseItems'),
  ];

  const costColumns: ColumnsType<Keyed<CostAnalysisRow>> = [
    { title: '序号', width: 56, render: (_v, _r, i) => i + 1 },
    {
      title: '物资名称',
      dataIndex: 'materialName',
      render: (v: string | null, row) => textCell(v, (val) => updateRow('costRows', row.key, { materialName: val })),
    },
    {
      title: '规格型号',
      dataIndex: 'spec',
      render: (v: string | null, row) => textCell(v, (val) => updateRow('costRows', row.key, { spec: val })),
    },
    {
      title: '清单收入（万元）',
      dataIndex: 'income',
      width: 150,
      render: (v: number | null, row) =>
        editable
          ? numberCell(v, (n) => updateRow('costRows', row.key, { income: n ?? 0 }), { suffix: '万元' })
          : fmtWan(v),
    },
    {
      title: '预计采购成本（万元）',
      dataIndex: 'cost',
      width: 170,
      render: (v: number | null, row) =>
        editable
          ? numberCell(v, (n) => updateRow('costRows', row.key, { cost: n ?? 0 }), { suffix: '万元' })
          : fmtWan(v),
    },
    {
      title: '预计效益额（万元）',
      key: 'benefit',
      width: 150,
      render: (_v, row) => fmtWan(deriveCostRow(row).benefit),
    },
    {
      title: '效益率',
      key: 'rate',
      width: 110,
      render: (_v, row) => fmtRate(deriveCostRow(row).rate),
    },
    ...opColumn('costRows'),
  ];

  const addRow = (field: 'purchaseItems' | 'costRows') => {
    setForm((f) => {
      if (field === 'purchaseItems') {
        const blank: Keyed<PurchaseItemRow> = { key: nextKey(), materialName: '', spec: '', unit: '', qty: null };
        return { ...f, purchaseItems: [...f.purchaseItems, blank] };
      }
      const blank: Keyed<CostAnalysisRow> = { key: nextKey(), materialName: '', spec: '', income: 0, cost: 0 };
      return { ...f, costRows: [...f.costRows, blank] };
    });
  };

  /* ---------------- 渲染 ---------------- */

  const richSection = (
    label: string,
    field: 'techQuality' | 'acceptance' | 'paymentTerms',
    tip?: string,
  ) => (
    <Card size="small" title={label}>
      {tip && <div style={{ color: 'var(--cms-muted-soft)', fontSize: 12, marginBottom: 8 }}>{tip}</div>}
      <RichTextEditor
        value={form[field]}
        onChange={(html) => patchForm({ [field]: html } as Partial<MinutesForm>)}
        variableGroups={getProcurementVariableGroups(MODULE_TYPE)}
        variableScope="procurement"
        disabled={!editable}
        minHeight={180}
        placeholder={`请填写${label}`}
      />
    </Card>
  );

  const totals = useMemo(() => summarizeCost(form.costRows.map(stripKey)), [form.costRows]);

  /** 采前会模块特有筛选项 */
  const extraFilters: ModuleListFilterField[] = [
    { key: 'meeting', label: '会议时间', control: 'dateRange' },
    { key: 'host', label: '主持人', control: 'input' },
  ];

  /** 采前会模块特有表格列 */
  const extraColumns: ColumnsType<ModuleListRow> = [
    {
      title: '会议时间',
      key: 'meetingTime',
      width: 120,
      render: (_v, row) =>
        row.module?.meetingTime ? dayjs(row.module.meetingTime).format('YYYY-MM-DD') : '-',
    },
    { title: '主持人', key: 'host', width: 120, ellipsis: { showTitle: true }, render: (_v, row) => row.module?.host || '-' },
    { title: '编写人', key: 'writer', width: 120, ellipsis: { showTitle: true }, render: (_v, row) => row.module?.writer || '-' },
  ];

  return (
    <Space direction="vertical" size={12} style={{ width: '100%' }}>
      {/* 标准列表页（批次五）：筛选区 + 工具栏 + 数据表格 */}
      <ModuleListPage
        moduleKey="PRE_MEETING"
        baseParams={{ type: 'SINGLE', preMeetingRequired: 'true' }}
        extraFilters={extraFilters}
        extraColumns={extraColumns}
        toolbarLeft={
          <span style={{ color: 'var(--cms-muted-soft)', fontSize: 13 }}>
            仅显示单项采购且需要采前会（预计采购金额 ≥ 100 万）的任务
          </span>
        }
        refreshKey={listRefresh + tabRefresh}
        editPermission="procurement:edit"
        onView={handleViewRow}
        onEdit={editRow}
        onDelete={handleDeleteModule}
        emptyText="暂无数据（仅「单项采购」类型且预计采购金额 ≥ 100 万元的采购任务才生成采前会会议纪要）"
        rowMenuItems={(row, { canEdit }) => {
          const published = moduleStatusOf(row).value === 'PUBLISHED';
          return published
            ? [
                {
                  key: 'exportWord',
                  label: (
                    <span>
                      <FileWordOutlined /> 导出Word
                    </span>
                  ),
                  onClick: () => handleRowExport(row),
                },
                ...(canEdit ? [{ key: 'reEdit', label: '重新编辑', onClick: () => editRow(row, true) }] : []),
              ]
            : [];
        }}
      />

      {/* 任务查看弹窗（问题一：已完成行「查看」→ 居中弹窗：任务信息+采购明细+Word 文档） */}
      <TaskViewModal task={viewRow} open={!!viewRow} onClose={() => setViewRow(null)} />

      {/* 编辑器页签（未填写/编辑中行「编辑」直接进入；底部操作栏 sticky） */}
      {taskId && (
        <EditorTabPage
          listPath={LIST_PATH}
          title={`采前会会议纪要 · 编辑${currentTask ? ` · ${currentTask.taskNo}` : ''}`}
          saving={saving}
          saveText="保 存"
          onSave={editable ? handleSave : undefined}
          // 本页有独立的「发布」流程，保存不关标签
          closeOnSave={false}
          dirty={dirty}
          footerLeft={
            <Space wrap size={8}>
              {currentTask && (
                <Button icon={<EyeOutlined />} onClick={() => setModalMode('preview')}>
                  预览
                </Button>
              )}
              {currentTask && (
                <Button icon={<FileWordOutlined />} onClick={handleExport}>
                  导出Word
                </Button>
              )}
            </Space>
          }
          footerExtra={
            detail && !detail.published && editable ? (
              <Button type="primary" icon={<SendOutlined />} onClick={openPublishPreview}>
                发布
              </Button>
            ) : null
          }
        >
        <Spin spinning={detailLoading}>
          {!currentTask && !detailLoading && (
            <Alert type="warning" showIcon message="任务详情加载失败，请关闭后重试。" />
          )}
          {currentTask && (
            <Space direction="vertical" size={12} style={{ width: '100%' }}>
            {editable && detail?.published && (
              <Alert
                type="warning"
                showIcon
                message="重新编辑模式：修改后请保存，发布状态保持「已完成」。"
              />
            )}

            {/* 展示信息 */}
            <Card size="small" title="展示信息">
              <Descriptions column={2} size="small" bordered>
                <Descriptions.Item label="采购内容">{form.content || currentTask.content}</Descriptions.Item>
                <Descriptions.Item label="预计采购金额">
                  {fmtWan(detail?.estimatedAmountWan ?? 0)} 万元
                </Descriptions.Item>
                <Descriptions.Item label="会议时间">{form.meetingTime || '-'}</Descriptions.Item>
                <Descriptions.Item label="发布时间">
                  {detail?.data?.publishedAt ? dayjs(detail.data.publishedAt).format('YYYY-MM-DD HH:mm') : '-'}
                </Descriptions.Item>
              </Descriptions>
            </Card>

            {/* 基本信息 */}
            <Card size="small" title="一、会议基本信息">
              <Row gutter={[16, 16]}>
                <Col xs={24} md={8}>
                  <div style={{ color: 'var(--cms-muted-soft)', fontSize: 12, marginBottom: 4 }}>项目名称（自动带出）</div>
                  <Input value={project.name ?? ''} disabled placeholder="（项目名称）" />
                </Col>
                <Col xs={24} md={8}>
                  <div style={{ color: 'var(--cms-muted-soft)', fontSize: 12, marginBottom: 4 }}>会议时间</div>
                  {editable ? (
                    <DatePicker
                      style={{ width: '100%' }}
                      value={form.meetingTime ? dayjs(form.meetingTime) : null}
                      onChange={(d) => patchForm({ meetingTime: d ? d.format('YYYY-MM-DD') : null })}
                    />
                  ) : (
                    <div style={{ minHeight: 22 }}>{form.meetingTime || '-'}</div>
                  )}
                </Col>
                <Col xs={24} md={8}>
                  <Field
                    label="采购内容"
                    value={form.content}
                    editable={editable}
                    onChange={(v) => patchForm({ content: v })}
                  />
                </Col>
                <Col xs={24} md={6}>
                  <Field label="主持人" value={form.host} editable={editable} onChange={(v) => patchForm({ host: v })} />
                </Col>
                <Col xs={24} md={6}>
                  <Field
                    label="参会人员"
                    value={form.attendees}
                    editable={editable}
                    onChange={(v) => patchForm({ attendees: v })}
                  />
                </Col>
                <Col xs={24} md={6}>
                  <Field
                    label="会议纪要编写人"
                    value={form.writer}
                    editable={editable}
                    onChange={(v) => patchForm({ writer: v })}
                  />
                </Col>
                <Col xs={24} md={6}>
                  <Field
                    label="审核人"
                    value={form.reviewer}
                    editable={editable}
                    onChange={(v) => patchForm({ reviewer: v })}
                  />
                </Col>
              </Row>
            </Card>

            {/* 采购清单 */}
            <Card
              size="small"
              title="二、采购清单"
              extra={
                editable && (
                  <Space>
                    <Button
                      size="small"
                      icon={<ImportOutlined />}
                      loading={importing}
                      onClick={() => taskId && importFromTotalList(taskId)}
                    >
                      从总采购清单导入
                    </Button>
                    <Button size="small" icon={<PlusOutlined />} onClick={() => addRow('purchaseItems')}>
                      添加行
                    </Button>
                  </Space>
                )
              }
            >
              <Table
                size="small"
                rowKey="key"
                columns={purchaseColumns}
                dataSource={form.purchaseItems as unknown as Keyed<PurchaseItemRow>[]}
                scroll={{ x: 'max-content' }}
                pagination={false}
                locale={{ emptyText: '暂无数据（可点击「从总采购清单导入」自动带出）' }}
              />
            </Card>

            {richSection('三、技术质量要求', 'techQuality')}
            {richSection('四、验收标准', 'acceptance')}
            {richSection('五、付款条件', 'paymentTerms')}

            {/* 采购成本分析表 */}
            <Card
              size="small"
              title="六、采购成本分析表"
              extra={
                editable && (
                  <Space>
                    <Button
                      size="small"
                      icon={<ImportOutlined />}
                      loading={importing}
                      onClick={() => taskId && importFromTotalList(taskId)}
                    >
                      从总采购清单导入
                    </Button>
                    <Button size="small" icon={<PlusOutlined />} onClick={() => addRow('costRows')}>
                      添加行
                    </Button>
                  </Space>
                )
              }
            >
              <Alert
                type="info"
                showIcon
                style={{ marginBottom: 12 }}
                message="计算规则：清单收入 = 收入单价 × 暂定数量；预计采购成本 = 控制价 × 暂定数量；预计效益额 = 清单收入 − 预计采购成本；效益率 = 预计效益额 ÷ 清单收入。金额按万元保留 2 位小数，效益率按百分比保留 2 位小数。"
              />
              <Table
                size="small"
                rowKey="key"
                columns={costColumns}
                dataSource={form.costRows as unknown as Keyed<CostAnalysisRow>[]}
                scroll={{ x: 'max-content' }}
                pagination={false}
                locale={{ emptyText: '暂无数据（可点击「从总采购清单导入」自动带出）' }}
                summary={() => (
                  <Table.Summary.Row style={{ background: 'var(--cms-surface-soft)', fontWeight: 600 }}>
                    <Table.Summary.Cell index={0} colSpan={3}>
                      合计
                    </Table.Summary.Cell>
                    <Table.Summary.Cell index={3}>{fmtWan(totals.income)}</Table.Summary.Cell>
                    <Table.Summary.Cell index={4}>{fmtWan(totals.cost)}</Table.Summary.Cell>
                    <Table.Summary.Cell index={5}>{fmtWan(totals.benefit)}</Table.Summary.Cell>
                    <Table.Summary.Cell index={6}>{fmtRate(totals.rate)}</Table.Summary.Cell>
                    <Table.Summary.Cell index={7} />
                  </Table.Summary.Row>
                )}
              />
            </Card>

            {/* 询价单 */}
            <Card size="small" title="七、询价单（图片，支持多张）">
              <Upload
                listType="picture-card"
                accept="image/*"
                multiple
                disabled={!editable}
                fileList={fileList}
                onPreview={(file) => setImgPreview(file.url || (file.response as any)?.url || null)}
                customRequest={async (options: any) => {
                  try {
                    const fd = new FormData();
                    fd.append('files', options.file);
                    const res: any = await http.post('/files/upload', fd);
                    const arr = Array.isArray(res) ? res : res?.data ?? [];
                    options.onSuccess?.(arr[0]);
                  } catch (e) {
                    options.onError?.(e);
                  }
                }}
                onChange={(info) => {
                  const list = info.fileList.filter((f) => f.status !== 'removed');
                  setFileList(list);
                  if (info.file.status === 'done') message.success(`「${info.file.name}」上传成功`);
                  if (info.file.status === 'error') message.error(`「${info.file.name}」上传失败`);
                }}
              >
                {editable && (
                  <div>
                    <PlusOutlined />
                    <div style={{ marginTop: 8 }}>上传询价单</div>
                  </div>
                )}
              </Upload>
              {fileList.length === 0 && <div style={{ color: 'var(--cms-muted-soft)' }}>（暂无询价单）</div>}
            </Card>

            {/* 操作 */}
          </Space>
          )}
        </Spin>
        </EditorTabPage>
      )}

      {/* 统一预览 / 发布流程（批次四 · 任务 4.2）：发布前确认与发布后预览共用 */}
      <PreviewPublishModal
        open={modalMode !== null}
        mode={modalMode ?? 'preview'}
        moduleType={MODULE_TYPE}
        taskId={taskId ?? undefined}
        docHtml={rawDocHtml}
        values={varValues}
        publishing={publishing}
        filename={exportFilename}
        projectAbbr={project.nameAbbr}
        content={form.content || currentTask?.content}
        confirmTitle="确认发布采前会会议纪要？"
        confirmDescription="发布前将自动保存当前内容；发布后状态变更为「已完成」，仍可预览与重新编辑。"
        onPublish={handlePublish}
        onClose={() => setModalMode(null)}
      />

      <Modal
        title="询价单预览"
        open={!!imgPreview}
        footer={null}
        width={720}
        onCancel={() => setImgPreview(null)}
      >
        {imgPreview && <img src={imgPreview} style={{ width: '100%' }} alt="询价单" />}
      </Modal>

      <style>{`
        .ant-table-summary { font-weight: 600; }
      `}</style>
    </Space>
  );
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import {
  Alert,
  Button,
  Card,
  Col,
  Descriptions,
  Input,
  InputNumber,
  Modal,
  Popconfirm,
  Row,
  Select,
  Space,
  Spin,
  Table,
  Tooltip,
  message,
} from 'antd';
import type { ColumnsType } from 'antd/es/table';
import { EyeOutlined, FileWordOutlined, SaveOutlined, SendOutlined } from '@ant-design/icons';
import dayjs from 'dayjs';
import { procurementTaskApi } from '@/api/modules';
import { projectApi } from '@/api/business';
import { useAuthStore } from '@/store/auth';
import { taskStatusLabel, taskTypeLabel } from '@/constants/procurementWorkflow';
import {
  getProcurementVariableGroups,
  replaceProcurementVariables,
} from '@/constants/procurementVariables';
import RichTextEditor from '@/components/RichTextEditor';
import PreviewPublishModal from '@/components/PreviewPublishModal';
import TaskViewModal from '@/components/procurement/TaskViewModal';
import ModuleListPage, {
  moduleStatusOf,
  type ModuleListFilterField,
  type ModuleListRow,
  useModuleDelete,
} from '@/components/procurement/ModuleListPage';
import { exportProcurementWord } from '@/utils/procurementExport';
import { exportTaskModuleWord } from '@/utils/procurementTaskDocs';
import EditorTabPage from '@/components/editor/EditorTabPage';
import { useEditorTab, useTabRefresh } from '@/hooks/useTabs';
import { editorTabKey } from '@/utils/tabs';

/** 列表与编辑器是同一路由的两种形态（`?editor=<taskId>`），见 `useEditorTab` 的注释 */
const LIST_PATH = '/procurement/price-compare';
import {
  buildPriceCompareDocHtml,
  buildPriceCompareVariableValues,
  deriveRow,
  fmtAmount,
  fmtQty,
  fmtRate,
  PRICING_METHODS,
  pricingMethodLabel,
  summarizePriceCompare,
  type PriceCompareItemRow,
} from '@/utils/procurementPriceCompare';

/** 模块类型（与采购模板 moduleType、变量占位符前缀一致） */
const MODULE_TYPE = 'PRICE_COMPARE';

interface TaskRow {
  id: string;
  taskNo: string;
  type: string;
  content: string;
  status: string;
  stage: number;
  preMeetingRequired: boolean;
}

/** 明细行（表格需要 key） */
interface KeyedRow extends PriceCompareItemRow {
  key: string;
  materialBaseId: string;
}

interface PriceForm {
  pricingMethod: string;
  benefitAnalysis: string;
}

interface PriceDetail {
  task: TaskRow;
  stageIndex: number;
  resultReportStageIndex: number;
  /** 成交报告是否已完成（本模块入口条件） */
  resultReportCompleted: boolean;
  reached: boolean;
  editable: boolean;
  published: boolean;
  status: string;
  statusLabel: string;
  content: string;
  /** 明细行（总采购清单派生 + 已保存的成交价/备注） */
  items: PriceCompareItemRow[];
  data:
    | {
        id?: string;
        pricingMethod?: string;
        benefitAnalysis?: string;
        publishedAt?: string | null;
        items?: PriceCompareItemRow[];
      }
    | null;
}

const EMPTY_FORM: PriceForm = { pricingMethod: '', benefitAnalysis: '' };

export default function PriceCompare() {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const currentProjectId = useAuthStore((s) => s.currentProjectId);

  /**
   * 列表与「编辑」是同一路由的两种形态（`?editor=<taskId>`），见 `useEditorTab` 的注释。
   * 编辑态原本是弹窗，现改为编辑器页签（底部操作栏 sticky，长表单不再把按钮滚出视口）。
   */
  const editorTab = useEditorTab(LIST_PATH);
  const tabRefresh = useTabRefresh(LIST_PATH);
  const taskId = editorTab.editorId === 'new' ? null : editorTab.editorId;
  /** 兼容旧深链 `?taskId=xxx`：归一成编辑器页签 */
  useEffect(() => {
    const legacy = searchParams.get('taskId');
    if (legacy && !editorTab.isEditor) navigate(editorTabKey(LIST_PATH, legacy), { replace: true });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  /** 列表刷新键：编辑器页签关闭后由 closeEditor 的 bump 触发；本键用于页内（删除等） */
  const [listRefresh, setListRefresh] = useState(0);
  /** 问题二：删除模块记录并回退流程 */
  const handleDeleteModule = useModuleDelete('PRICE_COMPARE', () => setListRefresh((k) => k + 1));

  const [detail, setDetail] = useState<PriceDetail | null>(null);
  const [detailLoading, setDetailLoading] = useState(false);

  const [form, setForm] = useState<PriceForm>(EMPTY_FORM);
  const [rows, setRows] = useState<KeyedRow[]>([]);

  const [saving, setSaving] = useState(false);
  const [publishing, setPublishing] = useState(false);
  const [reEditing, setReEditing] = useState(false);
  /** 统一预览/发布弹窗（批次四 · 任务 4.2）：publish=发布前确认；preview=纯预览 */
  const [modalMode, setModalMode] = useState<'preview' | 'publish' | null>(null);
  /** 未保存改动（关闭编辑器页签前确认） */
  const [dirty, setDirty] = useState(false);
  /** 任务查看弹窗（问题一：已完成行「查看」→ 任务信息+采购明细+Word 文档） */
  const [viewRow, setViewRow] = useState<ModuleListRow | null>(null);
  /** 重新编辑标记：loadDetail 完成后按此恢复可编辑（已发布行「重新编辑」） */
  const reEditRef = useRef(false);

  const [project, setProject] = useState<{
    name?: string;
    code?: string;
    nameAbbr?: string;
    undertaker?: string;
    provinceCity?: string;
    siteLocation?: string;
    projectAddress?: string;
  }>({});

  const currentTask = detail?.task ?? null;
  const editable = !!detail && (detail.editable || (detail.published && reEditing));
  const content = detail?.content || currentTask?.content || '';

  /** 表底汇总（清单收入总金额 / 标准成本总金额 / 采购效益率 / 采购成本降低率） */
  const summary = useMemo(() => summarizePriceCompare(rows), [rows]);

  useEffect(() => {
    if (!currentProjectId) return;
    projectApi
      .detail(currentProjectId)
      .then((res: any) => setProject(res ?? {}))
      .catch(() => setProject({}));
  }, [currentProjectId]);

  const loadDetail = useCallback((id: string) => {
    setDetailLoading(true);
    procurementTaskApi
      .priceCompare(id)
      .then((res: any) => {
        const d: PriceDetail = res; // 响应拦截器已解开 body.data，res 即完整 payload（含 task 与 data 记录）
        setDetail(d);
        const data = (d?.data ?? {}) as NonNullable<PriceDetail['data']>;
        setForm({
          pricingMethod: data.pricingMethod ?? '',
          benefitAnalysis: data.benefitAnalysis ?? '',
        });
        const list = Array.isArray(d?.items) ? d.items : [];
        setRows(
          list.map((r, i) => ({
            ...r,
            key: r.materialBaseId ? String(r.materialBaseId) : `row-${i}`,
            materialBaseId: String(r.materialBaseId ?? ''),
            dealPrice: r.dealPrice ?? null,
            remark: r.remark ?? '',
          })),
        );
        setReEditing(reEditRef.current && !!d.published);
        reEditRef.current = false;
      })
      .catch(() => {
        setDetail(null);
        setForm(EMPTY_FORM);
        setRows([]);
      })
      .finally(() => setDetailLoading(false));
  }, []);

  /** 列表行操作（问题一）：已完成行 → 任务查看弹窗；未填写/编辑中 → 直接进入编辑界面 */
  const handleViewRow = (row: ModuleListRow) => {
    if (moduleStatusOf(row).value === 'PUBLISHED') setViewRow(row);
    else editRow(row);
  };
  /** 列表行操作：编辑（reEdit=true 为已发布后的重新编辑）—— 打开编辑器页签，reEdit 随种子递过去 */
  const editRow = (row: ModuleListRow, reEdit = false) => {
    editorTab.openEdit(row.id, { reEdit });
  };
  /** 编辑器页签挂载时：按种子里的 reEdit 决定初始是否可编辑，并拉详情 */
  useEffect(() => {
    if (!taskId) return;
    reEditRef.current = !!(editorTab.seed as { reEdit?: boolean } | undefined)?.reEdit;
    loadDetail(taskId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [taskId]);

  /** 关闭编辑器页签（发布后回到列表，并让列表重新取数） */
  const closeEdit = () => {
    setDirty(false);
    editorTab.closeEditor();
  };

  /** 行「更多 → 导出Word」（问题二）：按任务直接构建并导出本模块文档 */
  const handleRowExport = async (row: ModuleListRow) => {
    try {
      const filename = await exportTaskModuleWord(MODULE_TYPE, row.id);
      message.success(`已导出：${filename}`);
    } catch (e: any) {
      message.error(e?.message || '导出失败，请稍后重试');
    }
  };

  const patchRow = (key: string, patch: Partial<KeyedRow>) => {
    setRows((prev) => prev.map((r) => (r.key === key ? { ...r, ...patch } : r)));
    setDirty(true);
  };

  /* ---------------- 保存 / 发布 / 导出 ---------------- */

  const buildSavePayload = () => ({
    pricingMethod: form.pricingMethod,
    benefitAnalysis: form.benefitAnalysis,
    // 仅提交用户录入的两列，其余列由后端按总采购清单回填
    items: rows.map((r) => ({
      materialBaseId: r.materialBaseId,
      dealPrice: r.dealPrice ?? null,
      remark: r.remark ?? '',
    })),
  });

  const handleSave = async () => {
    if (!taskId) return;
    setSaving(true);
    try {
      await procurementTaskApi.savePriceCompare(taskId, buildSavePayload());
      message.success('已保存');
      // 编辑器页签形态下「保存」不关标签，就地重载详情与列表
      loadDetail(taskId);
      setDirty(false);
      setListRefresh((x) => x + 1);
    } finally {
      setSaving(false);
    }
  };

  const openPublishPreview = () => {
    if (!form.pricingMethod) {
      message.warning('请先选择「计价方式」再发布');
      return;
    }
    if (!form.benefitAnalysis.trim() || form.benefitAnalysis === '<p><br></p>') {
      message.warning('请先填写「采购效益分析说明」再发布');
      return;
    }
    setModalMode('publish');
  };

  const handlePublish = async () => {
    if (!taskId) return;
    setPublishing(true);
    try {
      await procurementTaskApi.savePriceCompare(taskId, buildSavePayload());
      await procurementTaskApi.publish(taskId);
      message.success('已发布，采购价格对比表状态变更为「已完成」');
      setModalMode(null);
      closeEdit();
    } finally {
      setPublishing(false);
    }
  };

  const priceData = useMemo(
    () => ({
      pricingMethod: form.pricingMethod,
      benefitAnalysis: form.benefitAnalysis,
      items: rows,
    }),
    [form, rows],
  );

  const priceCtx = useMemo(
    () => ({
      projectName: project.name,
      projectCode: project.code,
      projectAbbr: project.nameAbbr,
      undertaker: project.undertaker,
      provinceCity: project.provinceCity,
      siteLocation: project.siteLocation,
      projectAddress: project.projectAddress,
      content,
    }),
    [project, content],
  );

  /** 模块内置文档 HTML（含 {{占位符}}，未替换；统一管线内完成模板优先与变量替换） */
  const rawDocHtml = useMemo(() => {
    if (!currentTask) return '';
    const title = `${project.nameAbbr || project.name || ''}-${content}-采购价格对比表`;
    return buildPriceCompareDocHtml(priceData, priceCtx, title);
  }, [priceData, priceCtx, currentTask, project, content]);

  /** 变量取值（统一预览 / 导出共用） */
  const varValues = useMemo(
    () => buildPriceCompareVariableValues(priceData, priceCtx),
    [priceData, priceCtx],
  );

  const exportFilename = `${
    project.nameAbbr || project.name || '项目'
  }-${content}-采购价格对比表.docx`;

  const handleExport = async () => {
    if (!currentTask) return;
    await exportProcurementWord({
      moduleType: MODULE_TYPE,
      taskId: taskId ?? undefined,
      docHtml: rawDocHtml,
      values: varValues,
      filename: exportFilename,
    });
    message.success(`已导出：${exportFilename}`);
  };

  /** 只读详情文档（模板优先 + 变量替换，需求修正 · 修改二） */
  /* ---------------- 表格列（18 列） ---------------- */

  const columns: ColumnsType<KeyedRow> = [
    { title: '序号', width: 56, fixed: 'left', render: (_v, _r, i) => i + 1 },
    {
      title: '采购名称',
      dataIndex: 'materialName',
      width: 160,
      fixed: 'left',
      render: (v: string | null | undefined) => v || '-',
    },
    { title: '规格型号', dataIndex: 'spec', width: 130, render: (v) => v || '-' },
    { title: '单位', dataIndex: 'unit', width: 70, render: (v) => v || '-' },
    {
      title: '数量',
      dataIndex: 'qty',
      width: 90,
      align: 'right',
      render: (v) => fmtQty(v) || '-',
    },
    {
      title: '清单收入\n不含税单价',
      dataIndex: 'incomePrice',
      width: 120,
      align: 'right',
      render: (v) => fmtAmount(v) || '-',
    },
    {
      title: '清单收入\n不含税合价',
      width: 130,
      align: 'right',
      render: (_v, r) => fmtAmount(deriveRow(r).incomeAmount) || '-',
    },
    {
      title: '标准成本\n不含税单价',
      dataIndex: 'stdCost',
      width: 120,
      align: 'right',
      render: (v) => fmtAmount(v) || '-',
    },
    {
      title: '标准成本\n不含税合价',
      width: 130,
      align: 'right',
      render: (_v, r) => fmtAmount(deriveRow(r).stdAmount) || '-',
    },
    {
      title: '控制价\n不含税单价',
      dataIndex: 'planPrice',
      width: 120,
      align: 'right',
      render: (v) => fmtAmount(v) || '-',
    },
    {
      title: '信息价\n不含税单价',
      dataIndex: 'infoPrice',
      width: 120,
      align: 'right',
      render: (v) => fmtAmount(v) || '-',
    },
    {
      title: '信息价\n不含税合价',
      width: 130,
      align: 'right',
      render: (_v, r) => fmtAmount(deriveRow(r).infoAmount) || '-',
    },
    {
      title: '成交价\n不含税单价',
      width: 140,
      align: 'right',
      render: (v: number | null | undefined, r) =>
        editable ? (
          <InputNumber
            size="small"
            style={{ width: '100%' }}
            min={0}
            precision={2}
            value={v ?? null}
            placeholder="录入成交价"
            onChange={(val) => patchRow(r.key, { dealPrice: val ?? null })}
          />
        ) : (
          fmtAmount(v) || '-'
        ),
    },
    {
      title: '成交价\n不含税合价',
      width: 130,
      align: 'right',
      render: (_v, r) => fmtAmount(deriveRow(r).dealAmount) || '-',
    },
    {
      title: '采购成本降低率',
      width: 130,
      align: 'right',
      render: (_v, r) => fmtRate(deriveRow(r).costReduceRate) || '-',
    },
    {
      title: '采购成交价下浮率',
      width: 140,
      align: 'right',
      render: (_v, r) => fmtRate(deriveRow(r).dealDiscountRate) || '-',
    },
    {
      title: '信息价下浮率',
      width: 120,
      align: 'right',
      render: (_v, r) => fmtRate(deriveRow(r).infoDiscountRate) || '-',
    },
    {
      title: '备注',
      width: 180,
      render: (v: string | null | undefined, r) =>
        editable ? (
          <Input
            size="small"
            value={v ?? ''}
            placeholder="请输入"
            onChange={(e) => patchRow(r.key, { remark: e.target.value })}
          />
        ) : (
          v || '-'
        ),
    },
  ];

  /* ---------------- 渲染 ---------------- */

  /** 计价方式展示名 */
  const pricingMethodLabel = (v: string | null | undefined) =>
    v === 'FIXED' ? '固定价' : v === 'FLOATING' ? '浮动价' : '-';

  /** 价格对比表模块特有筛选项 */
  const extraFilters: ModuleListFilterField[] = [
    {
      key: 'pricingMethod',
      label: '计价方式',
      control: 'select',
      options: [
        { label: '全部', value: '' },
        { label: '固定价', value: 'FIXED' },
        { label: '浮动价', value: 'FLOATING' },
      ],
    },
  ];

  /** 价格对比表模块特有表格列 */
  const extraColumns: ColumnsType<ModuleListRow> = [
    {
      title: '计价方式',
      key: 'pricingMethod',
      width: 110,
      render: (_v, row) => pricingMethodLabel(row.module?.pricingMethod),
    },
  ];

  return (
    <Space direction="vertical" size={12} style={{ width: '100%' }}>
      {/* 标准列表页（批次五）：筛选区 + 工具栏 + 数据表格 */}
      <ModuleListPage
        moduleKey="PRICE_COMPARE"
        extraFilters={extraFilters}
        extraColumns={extraColumns}
        toolbarLeft={
          <span style={{ color: 'var(--cms-muted-soft)', fontSize: 13 }}>
            显示「单项采购 / 引用框架协议」中已到达本阶段的任务；编辑与发布以任务所处阶段为准（单项采购需先完成成交报告，框架协议需先发布总清单）
          </span>
        }
        refreshKey={listRefresh + tabRefresh}
        editPermission="procurement:edit"
        onView={handleViewRow}
        onEdit={editRow}
        onDelete={handleDeleteModule}
        rowMenuItems={(row, { canEdit }) => {
          const published = moduleStatusOf(row).value === 'PUBLISHED';
          return published
            ? [
                {
                  key: 'exportWord',
                  label: (
                    <span>
                      <FileWordOutlined /> 导出Word
                    </span>
                  ),
                  onClick: () => handleRowExport(row),
                },
                ...(canEdit ? [{ key: 'reEdit', label: '重新编辑', onClick: () => editRow(row, true) }] : []),
              ]
            : [];
        }}
      />

      {/* 任务查看弹窗（问题一：已完成行「查看」→ 居中弹窗：任务信息+采购明细+Word 文档） */}
      <TaskViewModal task={viewRow} open={!!viewRow} onClose={() => setViewRow(null)} />

      {/* 编辑弹窗（问题一：未填写/编辑中行「编辑」直接进入；问题三：居中弹窗） */}
      {/* 编辑器页签（未填写/编辑中行「编辑」直接进入；底部操作栏 sticky） */}
      {taskId && (
        <EditorTabPage
          listPath={LIST_PATH}
          title={`采购价格对比表 · 编辑${currentTask ? ` · ${currentTask.taskNo}` : ''}`}
          saving={saving}
          saveText="保 存"
          onSave={editable ? handleSave : undefined}
          // 本页有独立的「发布」流程，保存不关标签
          closeOnSave={false}
          dirty={dirty}
          footerLeft={
            <Space wrap size={8}>
              {currentTask && (
                <Button icon={<EyeOutlined />} onClick={() => setModalMode('preview')}>
                  预览
                </Button>
              )}
              {currentTask && (
                <Button icon={<FileWordOutlined />} onClick={handleExport}>
                  导出Word
                </Button>
              )}
            </Space>
          }
          footerExtra={
            detail && !detail.published && editable ? (
              <Button type="primary" icon={<SendOutlined />} onClick={openPublishPreview}>
                发布
              </Button>
            ) : null
          }
        >
        <Spin spinning={detailLoading}>
          {!currentTask && !detailLoading && (
            <Alert type="warning" showIcon message="任务详情加载失败，请关闭后重试。" />
          )}
          {currentTask && (
            <Space direction="vertical" size={12} style={{ width: '100%' }}>
              {detail && !detail.reached && (
                <Alert
                  type="info"
                  showIcon
                  message={
                    currentTask?.type === 'FRAMEWORK'
                      ? '该采购任务尚未进入采购价格对比表阶段（需先发布总采购清单）。'
                      : '该采购任务尚未进入采购价格对比表阶段（需先完成成交报告）。'
                  }
                />
              )}
              {detail?.published && editable && (
                <Alert
                  type="warning"
                  showIcon
                  message="重新编辑模式：修改后请保存，发布状态保持「已完成」。"
                />
              )}

            {/* 展示信息 */}
            <Card size="small" title="展示信息">
              <Descriptions column={3} size="small" bordered>
                <Descriptions.Item label="项目名称及编码">
                  {[project.name, project.code ? `（${project.code}）` : ''].join('') || '-'}
                </Descriptions.Item>
                <Descriptions.Item label="采购内容">{content || '-'}</Descriptions.Item>
                <Descriptions.Item label="计价方式">
                  {pricingMethodLabel(form.pricingMethod) || '-'}
                </Descriptions.Item>
                <Descriptions.Item label="采购类型">
                  {taskTypeLabel(currentTask.type)}
                </Descriptions.Item>
                <Descriptions.Item label="任务状态">
                  {taskStatusLabel(currentTask.status)}
                </Descriptions.Item>
                <Descriptions.Item label="发布时间">
                  {detail?.data?.publishedAt
                    ? dayjs(detail.data.publishedAt).format('YYYY-MM-DD HH:mm')
                    : '-'}
                </Descriptions.Item>
              </Descriptions>
            </Card>

            {/* 一、项目基本情况 */}
            <Card size="small" title="一、项目基本情况">
              <Row gutter={[16, 16]}>
                <Col xs={24} md={12}>
                  <div style={{ color: 'var(--cms-muted-soft)', fontSize: 12, marginBottom: 4 }}>
                    项目名称及编码
                  </div>
                  <div style={{ minHeight: 32, lineHeight: '32px' }}>
                    {project.name || '-'}
                    {project.code ? `（${project.code}）` : ''}
                  </div>
                </Col>
                <Col xs={24} md={12}>
                  <div style={{ color: 'var(--cms-muted-soft)', fontSize: 12, marginBottom: 4 }}>计价方式</div>
                  {editable ? (
                    <Select
                      style={{ width: '100%' }}
                      placeholder="请选择计价方式"
                      value={form.pricingMethod || undefined}
                      options={PRICING_METHODS.map((m) => ({ value: m.value, label: m.label }))}
                      onChange={(v) => setForm((f) => ({ ...f, pricingMethod: v }))}
                    />
                  ) : (
                    <div style={{ minHeight: 32, lineHeight: '32px' }}>
                      {pricingMethodLabel(form.pricingMethod) || '-'}
                    </div>
                  )}
                </Col>
              </Row>
            </Card>

            {/* 二、采购效益分析说明 */}
            <Card size="small" title="二、采购效益分析说明">
              <RichTextEditor
                value={form.benefitAnalysis}
                onChange={(html) => setForm((f) => ({ ...f, benefitAnalysis: html }))}
                variableGroups={getProcurementVariableGroups(MODULE_TYPE)}
                variableScope="procurement"
                disabled={!editable}
                minHeight={180}
                placeholder="请填写采购效益分析说明（可插入变量占位符）"
              />
            </Card>

            {/* 三、采购价格对比明细表 */}
            <Card
              size="small"
              title="三、采购价格对比明细表"
              extra={
                <span style={{ color: 'var(--cms-muted-soft)', fontSize: 12 }}>
                  采购名称/规格/单位/数量/清单收入/标准成本/控制价/信息价来自总采购清单（只读）；成交价与备注由人工录入
                </span>
              }
            >
              <Table<KeyedRow>
                size="small"
                rowKey="key"
                columns={columns}
                dataSource={rows}
                pagination={false}
                scroll={{ x: 2450 }}
                locale={{ emptyText: '暂无明细（请先编制并发布总采购清单）' }}
              />
              <Descriptions
                style={{ marginTop: 12 }}
                size="small"
                bordered
                column={4}
                title="表底汇总"
              >
                <Descriptions.Item label="清单收入不含税总金额">
                  {fmtAmount(summary.incomeAmount) || '0.00'} 元
                </Descriptions.Item>
                <Descriptions.Item label="标准成本不含税总金额">
                  {fmtAmount(summary.stdAmount) || '0.00'} 元
                </Descriptions.Item>
                <Descriptions.Item label="采购效益率">
                  {fmtRate(summary.benefitRate) || '-'}
                </Descriptions.Item>
                <Descriptions.Item label="采购成本降低率">
                  {fmtRate(summary.costReduceRate) || '-'}
                </Descriptions.Item>
              </Descriptions>
              <div style={{ color: 'var(--cms-muted-soft)', fontSize: 12, marginTop: 8 }}>
                计算规则：利润额 = 清单收入 − 成交价；采购效益率 = 利润额 ÷ 清单收入；
                采购成本降低率 =（标准成本 − 成交价）÷ 标准成本；信息价下浮率 =（信息价 − 成交价）÷ 信息价。
              </div>
            </Card>

          </Space>
          )}
        </Spin>
        </EditorTabPage>
      )}

      {/* 统一预览 / 发布流程（批次四 · 任务 4.2）：发布前确认与发布后预览共用 */}
      <PreviewPublishModal
        open={modalMode !== null}
        mode={modalMode ?? 'preview'}
        moduleType={MODULE_TYPE}
        taskId={taskId ?? undefined}
        docHtml={rawDocHtml}
        values={varValues}
        publishing={publishing}
        filename={exportFilename}
        projectAbbr={project.nameAbbr}
        content={content}
        confirmTitle="确认发布采购价格对比表？"
        confirmDescription="发布前将自动保存当前内容；发布后状态变更为「已完成」，任务状态流转到下一阶段。"
        tipMessage="请核对明细表与表底汇总数据，确认无误后点击「确认发布」。"
        onPublish={handlePublish}
        onClose={() => setModalMode(null)}
      />
    </Space>
  );
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import {
  Alert,
  Button,
  Card,
  Checkbox,
  Col,
  DatePicker,
  Descriptions,
  Input,
  InputNumber,
  Modal,
  Popconfirm,
  Row,
  Space,
  Spin,
  Table,
  Tag,
  Tooltip,
  message,
} from 'antd';
import type { ColumnsType } from 'antd/es/table';
import { EyeOutlined, FileWordOutlined, SaveOutlined, SendOutlined, RollbackOutlined } from '@ant-design/icons';
import dayjs from 'dayjs';
import { procurementTaskApi } from '@/api/modules';
import { projectApi } from '@/api/business';
import { useAuthStore } from '@/store/auth';
import { taskStatusLabel, taskTypeLabel } from '@/constants/procurementWorkflow';
import {
  getProcurementVariableGroups,
  replaceProcurementVariables,
} from '@/constants/procurementVariables';
import ImportButton from '@/components/ImportButton';
import PreviewPublishModal from '@/components/PreviewPublishModal';
import BidderPanel from '@/components/procurement/BidderPanel';
import TaskViewModal from '@/components/procurement/TaskViewModal';
import ModuleListPage, {
  moduleStatusOf,
  type ModuleListFilterField,
  type ModuleListRow,
  useModuleDelete,
} from '@/components/procurement/ModuleListPage';
import { exportProcurementWord } from '@/utils/procurementExport';
import { exportTaskModuleWord } from '@/utils/procurementTaskDocs';
import EditorTabPage from '@/components/editor/EditorTabPage';
import { useEditorTab, useTabRefresh } from '@/hooks/useTabs';
import { editorTabKey } from '@/utils/tabs';

/** 列表与编辑器是同一路由的两种形态（`?editor=<taskId>`），见 `useEditorTab` 的注释 */
const LIST_PATH = '/procurement/result-report';
import {
  buildResultReportDocHtml,
  buildResultReportVariableValues,
  defaultFinalPrice,
  fmtAmount,
  rankByFirstRound,
  rankBySecondRound,
  type RankedSupplier,
  type ResultCandidate,
  type ResultReportData,
  type ResultSupplier,
} from '@/utils/procurementResultReport';

/** 模块类型（与采购模板 moduleType、变量占位符前缀一致） */
const MODULE_TYPE = 'RESULT_REPORT';

interface TaskRow {
  id: string;
  taskNo: string;
  type: string;
  content: string;
  status: string;
  stage: number;
  preMeetingRequired: boolean;
}

/** 成交报告 8 个编辑字段 */
interface ResultForm {
  unitCount: number | null;
  openTime: string | null;
  openPlace: string;
  reviewMembers: string;
  approvedCount: number | null;
  participantCount: number | null;
  abstainCount: number | null;
  validFileCount: number | null;
}

interface ResultDetail {
  task: TaskRow;
  stageIndex: number;
  documentStageIndex: number;
  /** 采购文件是否已完成（本模块入口条件） */
  documentCompleted: boolean;
  reached: boolean;
  editable: boolean;
  published: boolean;
  status: string;
  statusLabel: string;
  /** 采购内容 */
  content: string;
  /** 预计采购金额（元，来自总采购清单） */
  estimatedAmount: number | null;
  /** 响应单位明细（导入） */
  suppliers: ResultSupplier[];
  /** 拟推荐成交候选人（勾选） */
  candidates: ResultCandidate[];
  data:
    | {
        id?: string;
        unitCount?: number | null;
        openTime?: string | null;
        openPlace?: string;
        reviewMembers?: string;
        approvedCount?: number | null;
        participantCount?: number | null;
        abstainCount?: number | null;
        validFileCount?: number | null;
        publishedAt?: string | null;
      }
    | null;
}

const EMPTY_FORM: ResultForm = {
  unitCount: null,
  openTime: null,
  openPlace: '',
  reviewMembers: '',
  approvedCount: null,
  participantCount: null,
  abstainCount: null,
  validFileCount: null,
};

export default function ResultReport() {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const currentProjectId = useAuthStore((s) => s.currentProjectId);

  /**
   * 列表与「编辑」是同一路由的两种形态（`?editor=<taskId>`），见 `useEditorTab` 的注释。
   * 编辑态原本是弹窗，现改为编辑器页签（底部操作栏 sticky，长表单不再把按钮滚出视口）。
   */
  const editorTab = useEditorTab(LIST_PATH);
  const tabRefresh = useTabRefresh(LIST_PATH);
  const taskId = editorTab.editorId === 'new' ? null : editorTab.editorId;
  /** 兼容旧深链 `?taskId=xxx`：归一成编辑器页签 */
  useEffect(() => {
    const legacy = searchParams.get('taskId');
    if (legacy && !editorTab.isEditor) navigate(editorTabKey(LIST_PATH, legacy), { replace: true });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  /** 列表刷新键：编辑器页签关闭后由 closeEditor 的 bump 触发；本键用于页内（删除等） */
  const [listRefresh, setListRefresh] = useState(0);
  /** 问题二：删除模块记录并回退流程 */
  const handleDeleteModule = useModuleDelete('RESULT_REPORT', () => setListRefresh((k) => k + 1));

  const [detail, setDetail] = useState<ResultDetail | null>(null);
  const [detailLoading, setDetailLoading] = useState(false);

  const [form, setForm] = useState<ResultForm>(EMPTY_FORM);
  const [suppliers, setSuppliers] = useState<ResultSupplier[]>([]);
  const [candidates, setCandidates] = useState<ResultCandidate[]>([]);

  const [saving, setSaving] = useState(false);
  const [publishing, setPublishing] = useState(false);
  const [reEditing, setReEditing] = useState(false);
  /** 统一预览/发布弹窗（批次四 · 任务 4.2）：publish=发布前确认；preview=纯预览 */
  const [modalMode, setModalMode] = useState<'preview' | 'publish' | null>(null);
  /** 未保存改动（关闭编辑器页签前确认） */
  const [dirty, setDirty] = useState(false);
  /** 任务查看弹窗（问题一：已完成行「查看」→ 任务信息+采购明细+Word 文档） */
  const [viewRow, setViewRow] = useState<ModuleListRow | null>(null);
  /** 重新编辑标记：loadDetail 完成后按此恢复可编辑（已发布行「重新编辑」） */
  const reEditRef = useRef(false);

  const [project, setProject] = useState<{
    name?: string;
    nameAbbr?: string;
    undertaker?: string;
    provinceCity?: string;
    siteLocation?: string;
    projectAddress?: string;
  }>({});

  const currentTask = detail?.task ?? null;
  const editable = !!detail && (detail.editable || (detail.published && reEditing));
  const content = detail?.content || currentTask?.content || '';

  /** 开启报价情况表（第一轮报价不含税总额升序） */
  const firstRoundRows = useMemo(() => rankByFirstRound(suppliers), [suppliers]);
  /** 第二轮报价情况表（仅「通过第一轮报价=是」，第二轮报价不含税总额升序） */
  const secondRoundRows = useMemo(() => rankBySecondRound(suppliers), [suppliers]);

  useEffect(() => {
    if (!currentProjectId) return;
    projectApi
      .detail(currentProjectId)
      .then((res: any) => setProject(res ?? {}))
      .catch(() => setProject({}));
  }, [currentProjectId]);

  const loadDetail = useCallback((id: string) => {
    setDetailLoading(true);
    procurementTaskApi
      .resultReport(id)
      .then((res: any) => {
        const d: ResultDetail = res; // 响应拦截器已解开 body.data，res 即完整 payload（含 task 与 data 记录）
        setDetail(d);
        const data = (d?.data ?? {}) as NonNullable<ResultDetail['data']>;
        setForm({
          unitCount: data.unitCount ?? null,
          openTime: data.openTime ? dayjs(data.openTime).format('YYYY-MM-DD') : null,
          openPlace: data.openPlace ?? '',
          reviewMembers: data.reviewMembers ?? '',
          approvedCount: data.approvedCount ?? null,
          participantCount: data.participantCount ?? null,
          abstainCount: data.abstainCount ?? null,
          validFileCount: data.validFileCount ?? null,
        });
        setSuppliers(Array.isArray(d?.suppliers) ? d.suppliers : []);
        setCandidates(Array.isArray(d?.candidates) ? d.candidates : []);
        setReEditing(reEditRef.current && !!d.published);
        reEditRef.current = false;
      })
      .catch(() => {
        setDetail(null);
        setForm(EMPTY_FORM);
        setSuppliers([]);
        setCandidates([]);
      })
      .finally(() => setDetailLoading(false));
  }, []);

  /** 列表行操作（问题一）：已完成行 → 任务查看弹窗；未填写/编辑中 → 直接进入编辑界面 */
  const handleViewRow = (row: ModuleListRow) => {
    if (moduleStatusOf(row).value === 'PUBLISHED') setViewRow(row);
    else editRow(row);
  };
  /** 列表行操作：编辑（reEdit=true 为已发布后的重新编辑）—— 打开编辑器页签，reEdit 随种子递过去 */
  const editRow = (row: ModuleListRow, reEdit = false) => {
    editorTab.openEdit(row.id, { reEdit });
  };
  /** 编辑器页签挂载时：按种子里的 reEdit 决定初始是否可编辑，并拉详情 */
  useEffect(() => {
    if (!taskId) return;
    reEditRef.current = !!(editorTab.seed as { reEdit?: boolean } | undefined)?.reEdit;
    loadDetail(taskId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [taskId]);
  /** 关闭编辑弹窗后刷新列表（反映保存/发布后的最新模块状态） */
  /** 关闭编辑器页签（发布 / 退回后都回到列表，并让列表重新取数） */
  const closeEdit = () => {
    setDirty(false);
    editorTab.closeEditor();
  };

  /** 行「更多 → 导出Word」（问题二）：按任务直接构建并导出本模块文档 */
  const handleRowExport = async (row: ModuleListRow) => {
    try {
      const filename = await exportTaskModuleWord(MODULE_TYPE, row.id);
      message.success(`已导出：${filename}`);
    } catch (e: any) {
      message.error(e?.message || '导出失败，请稍后重试');
    }
  };

  const patchForm = (patch: Partial<ResultForm>) => {
    setForm((f) => ({ ...f, ...patch }));
    setDirty(true);
  };

  /* ---------------- 候选人勾选（第二轮报价表） ---------------- */

  const isChecked = (index: number) => candidates.some((c) => c.supplierIndex === index);

  const toggleCandidate = (row: RankedSupplier, checked: boolean) => {
    setCandidates((list) => {
      if (checked) {
        if (list.some((c) => c.supplierIndex === row.index)) return list;
        return [
          ...list,
          {
            supplierIndex: row.index,
            name: String(row.supplier.name ?? ''),
            // 最终确认不含税价格默认取第二轮报价（未通过第一轮时回退第一轮）
            finalPreTaxPrice: defaultFinalPrice(row.supplier),
            remark: String(row.supplier.remark ?? ''),
          },
        ];
      }
      return list.filter((c) => c.supplierIndex !== row.index);
    });
  };

  const patchCandidate = (index: number, patch: Partial<ResultCandidate>) =>
    setCandidates((list) => list.map((c, i) => (i === index ? { ...c, ...patch } : c)));

  /* ---------------- 保存 / 发布 / 导出 ---------------- */

  const buildSavePayload = () => ({
    unitCount: form.unitCount,
    openTime: form.openTime || null,
    openPlace: form.openPlace,
    reviewMembers: form.reviewMembers,
    approvedCount: form.approvedCount,
    participantCount: form.participantCount,
    abstainCount: form.abstainCount,
    validFileCount: form.validFileCount,
    candidates,
  });

  const handleSave = async () => {
    if (!taskId) return;
    setSaving(true);
    try {
      await procurementTaskApi.saveResultReport(taskId, buildSavePayload());
      message.success('已保存');
      // 编辑器页签形态下「保存」不关标签，就地重载详情与列表
      loadDetail(taskId);
      setDirty(false);
      setListRefresh((x) => x + 1);
    } finally {
      setSaving(false);
    }
  };

  const openPublishPreview = () => {
    if (!form.openTime) {
      message.warning('请先选择「采购开启时间」再发布');
      return;
    }
    if (!suppliers.length) {
      message.warning('请先导入「响应单位情况汇总表」再发布');
      return;
    }
    setModalMode('publish');
  };

  const handlePublish = async () => {
    if (!taskId) return;
    setPublishing(true);
    try {
      await procurementTaskApi.saveResultReport(taskId, buildSavePayload());
      await procurementTaskApi.publish(taskId);
      message.success('已发布，成交报告状态变更为「已完成」');
      setModalMode(null);
      closeEdit();
    } finally {
      setPublishing(false);
    }
  };

  /** 任务 7：成交报告「退回 → 重发」（纯状态回退；若下游合同已签章则禁止） */
  const handleRejectResultReport = async () => {
    if (!taskId) return;
    Modal.confirm({
      title: '成交报告退回重发',
      content:
        '确认退回成交报告吗？退回后报告恢复为「编制中」可重新编辑并再次发布（重发），已自动生成的合同草稿将被清理。',
      okText: '确认退回',
      okButtonProps: { danger: true },
      cancelText: '取消',
      onOk: async () => {
        try {
          await procurementTaskApi.rejectResultReport(taskId);
          message.success('已退回，成交报告恢复编制中，可重新发布');
          setModalMode(null);
          closeEdit();
        } catch (e: any) {
          message.error(e?.message || '退回失败');
        }
      },
    });
  };

  const reportData = useMemo<ResultReportData>(
    () => ({
      unitCount: form.unitCount,
      openTime: form.openTime,
      openPlace: form.openPlace,
      reviewMembers: form.reviewMembers,
      approvedCount: form.approvedCount,
      participantCount: form.participantCount,
      abstainCount: form.abstainCount,
      validFileCount: form.validFileCount,
      suppliers,
      candidates,
    }),
    [form, suppliers, candidates],
  );

  const reportCtx = useMemo(
    () => ({
      projectName: project.name,
      projectAbbr: project.nameAbbr,
      undertaker: project.undertaker,
      provinceCity: project.provinceCity,
      siteLocation: project.siteLocation,
      projectAddress: project.projectAddress,
      content,
      estimatedAmount: detail?.estimatedAmount ?? null,
    }),
    [project, content, detail],
  );

  /** 模块内置文档 HTML（含 {{占位符}}，未替换；统一管线内完成模板优先与变量替换） */
  const rawDocHtml = useMemo(() => {
    if (!currentTask) return '';
    const title = `${project.nameAbbr || project.name || ''}-${content}-成交报告`;
    return buildResultReportDocHtml(reportData, reportCtx, title);
  }, [reportData, reportCtx, currentTask, project, content]);

  /** 变量取值（统一预览 / 导出共用） */
  const varValues = useMemo(
    () => buildResultReportVariableValues(reportData, reportCtx),
    [reportData, reportCtx],
  );

  const exportFilename = `${project.nameAbbr || project.name || '项目'}-${content}-成交报告.docx`;

  const handleExport = async () => {
    if (!currentTask) return;
    await exportProcurementWord({
      moduleType: MODULE_TYPE,
      taskId: taskId ?? undefined,
      docHtml: rawDocHtml,
      values: varValues,
      filename: exportFilename,
    });
    message.success(`已导出：${exportFilename}`);
  };

  /* ---------------- 表格列 ---------------- */

  const estAmount = fmtAmount(detail?.estimatedAmount) || '-';

  const summaryColumns: ColumnsType<ResultSupplier> = [
    { title: '序号', width: 60, render: (_v, _r, i) => i + 1 },
    { title: '参与响应单位', dataIndex: 'name', render: (v: string | null) => v || '-' },
    { title: '响应保证金是否缴纳', dataIndex: 'depositPaid', width: 160, render: (v: string | null) => v || '-' },
    { title: '响应文件密封是否完整', dataIndex: 'sealed', width: 180, render: (v: string | null) => v || '-' },
    { title: '备注', dataIndex: 'remark', width: 160, render: (v: string | null) => v || '-' },
  ];

  const firstRoundColumns: ColumnsType<RankedSupplier> = [
    { title: '排名', dataIndex: 'rank', width: 70, render: (v: number) => <Tag color="blue">{v}</Tag> },
    { title: '参与响应单位', width: 220, render: (_v, r) => r.supplier.name || '-' },
    {
      title: '第一次报价不含税总额',
      width: 190,
      align: 'right',
      render: (_v, r) => fmtAmount(r.supplier.firstPreTaxTotal) || '-',
    },
    { title: '预计采购金额', width: 150, align: 'right', render: () => estAmount },
    {
      title: '第一轮报价税金',
      width: 140,
      align: 'right',
      render: (_v, r) => fmtAmount(r.supplier.firstTax) || '-',
    },
  ];

  const secondRoundColumns: ColumnsType<RankedSupplier> = [
    {
      title: '拟推荐',
      width: 80,
      align: 'center',
      render: (_v, r) => (
        <Tooltip title="勾选后自动填入「拟推荐成交候选人表」">
          <Checkbox
            disabled={!editable}
            checked={isChecked(r.index)}
            onChange={(e) => toggleCandidate(r, e.target.checked)}
          />
        </Tooltip>
      ),
    },
    { title: '排名', dataIndex: 'rank', width: 70, render: (v: number) => <Tag color="blue">{v}</Tag> },
    { title: '参与响应单位', width: 220, render: (_v, r) => r.supplier.name || '-' },
    {
      title: '第二次报价不含税总额',
      width: 190,
      align: 'right',
      render: (_v, r) => fmtAmount(r.supplier.secondPreTaxTotal) || '-',
    },
    { title: '预计采购金额', width: 150, align: 'right', render: () => estAmount },
    {
      title: '第二轮报价税金',
      width: 140,
      align: 'right',
      render: (_v, r) => fmtAmount(r.supplier.secondTax) || '-',
    },
  ];

  const candidateColumns: ColumnsType<ResultCandidate> = [
    { title: '序号', width: 60, render: (_v, _r, i) => i + 1 },
    { title: '拟推荐成交候选人', dataIndex: 'name', render: (v: string) => v || '-' },
    {
      title: '最终确认不含税价格',
      dataIndex: 'finalPreTaxPrice',
      width: 220,
      render: (v: number | null | undefined, _r, i) =>
        editable ? (
          <InputNumber
            style={{ width: '100%' }}
            min={0}
            precision={2}
            value={typeof v === 'number' ? v : null}
            placeholder="请输入"
            onChange={(val) => patchCandidate(i, { finalPreTaxPrice: val ?? null })}
          />
        ) : (
          fmtAmount(v) || '-'
        ),
    },
    {
      title: '备注',
      dataIndex: 'remark',
      width: 220,
      render: (v: string | null | undefined, _r, i) =>
        editable ? (
          <Input
            value={typeof v === 'string' ? v : ''}
            placeholder="请输入"
            onChange={(e) => patchCandidate(i, { remark: e.target.value })}
          />
        ) : (
          v || '-'
        ),
    },
    {
      title: '操作',
      width: 90,
      fixed: 'right',
      render: (_v, r) => (
        <Button
          type="link"
          size="small"
          danger
          disabled={!editable}
          onClick={() =>
            setCandidates((list) => list.filter((c) => c.supplierIndex !== r.supplierIndex))
          }
        >
          移除
        </Button>
      ),
    },
  ];

  /* ---------------- 渲染 ---------------- */

  /** 成交报告模块特有筛选项 */
  const extraFilters: ModuleListFilterField[] = [
    { key: 'open', label: '开启时间', control: 'dateRange' },
    // 问题五：按成交供应商（拟推荐成交候选人）筛选
    { key: 'winner', label: '成交供应商', control: 'input', placeholder: '请输入成交供应商' },
  ];

  /** 成交报告模块特有表格列 */
  const extraColumns: ColumnsType<ModuleListRow> = [
    {
      // 问题五：成交供应商 = 拟推荐成交候选人（candidates）
      title: '成交供应商',
      key: 'winner',
      width: 180,
      ellipsis: { showTitle: true },
      render: (_v, row) => {
        const names: string[] = (row.module?.candidates ?? [])
          .map((c: any) => String(c?.name ?? c?.unit ?? '').trim())
          .filter(Boolean);
        return names.length ? names.join('、') : '-';
      },
    },
    {
      title: '开启时间',
      key: 'openTime',
      width: 120,
      render: (_v, row) =>
        row.module?.openTime ? dayjs(row.module.openTime).format('YYYY-MM-DD') : '-',
    },
    {
      title: '成交单位数量',
      key: 'unitCount',
      width: 120,
      render: (_v, row) => row.module?.unitCount ?? '-',
    },
    {
      title: '通过单位数',
      key: 'approvedCount',
      width: 110,
      render: (_v, row) => row.module?.approvedCount ?? '-',
    },
  ];

  return (
    <Space direction="vertical" size={12} style={{ width: '100%' }}>
      {/* 标准列表页（批次五）：筛选区 + 工具栏 + 数据表格 */}
      <ModuleListPage
        moduleKey="RESULT_REPORT"
        baseParams={{ type: 'SINGLE' }}
        extraFilters={extraFilters}
        extraColumns={extraColumns}
        toolbarLeft={
          <span style={{ color: 'var(--cms-muted-soft)', fontSize: 13 }}>
            仅显示单项采购类型的任务；编辑与发布以任务所处阶段为准（需先完成采购文件）
          </span>
        }
        refreshKey={listRefresh + tabRefresh}
        editPermission="procurement:edit"
        onView={handleViewRow}
        onEdit={editRow}
        onDelete={handleDeleteModule}
        rowMenuItems={(row, { canEdit }) => {
          const published = moduleStatusOf(row).value === 'PUBLISHED';
          return published
            ? [
                {
                  key: 'exportWord',
                  label: (
                    <span>
                      <FileWordOutlined /> 导出Word
                    </span>
                  ),
                  onClick: () => handleRowExport(row),
                },
                ...(canEdit ? [{ key: 'reEdit', label: '重新编辑', onClick: () => editRow(row, true) }] : []),
              ]
            : [];
        }}
      />

      {/* 任务查看弹窗（问题一：已完成行「查看」→ 居中弹窗：任务信息+采购明细+Word 文档） */}
      <TaskViewModal task={viewRow} open={!!viewRow} onClose={() => setViewRow(null)} />

      {/* 编辑弹窗（问题一：未填写/编辑中行「编辑」直接进入；问题三：居中弹窗） */}
      {/* 编辑器页签（未填写/编辑中行「编辑」直接进入；底部操作栏 sticky） */}
      {taskId && (
        <EditorTabPage
          listPath={LIST_PATH}
          title={`成交报告 · 编辑${currentTask ? ` · ${currentTask.taskNo}` : ''}`}
          saving={saving}
          saveText="保 存"
          onSave={editable ? handleSave : undefined}
          // 本页有独立的「发布 / 退回重发」流程，保存不关标签
          closeOnSave={false}
          dirty={dirty}
          footerLeft={
            <Space wrap size={8}>
              {currentTask && (
                <Button icon={<EyeOutlined />} onClick={() => setModalMode('preview')}>
                  预览
                </Button>
              )}
              {currentTask && (
                <Button icon={<FileWordOutlined />} onClick={handleExport}>
                  导出Word
                </Button>
              )}
              {/* 任务 7：成交报告「退回 → 重发」（仅已发布且单项采购类型） */}
              {detail?.published && currentTask?.type === 'SINGLE' && (
                <Button danger icon={<RollbackOutlined />} onClick={handleRejectResultReport}>
                  退回重发
                </Button>
              )}
            </Space>
          }
          footerExtra={
            detail && !detail.published && editable ? (
              <Button type="primary" icon={<SendOutlined />} onClick={openPublishPreview}>
                发布
              </Button>
            ) : null
          }
        >
        <Spin spinning={detailLoading}>
          {!currentTask && !detailLoading && (
            <Alert type="warning" showIcon message="任务详情加载失败，请关闭后重试。" />
          )}
          {currentTask && (
            <Space direction="vertical" size={12} style={{ width: '100%' }}>
