import { useEffect, useMemo, useState } from 'react';
import {
  Card,
  Table,
  Button,
  Form,
  Input,
  Select,
  Tree,
  Space,
  Modal,
  Popconfirm,
  Tag,
  Row,
  Col,
  message,
} from 'antd';
import { PlusOutlined, ReloadOutlined, DeleteOutlined } from '@ant-design/icons';
import { systemApi } from '@/api/auth';
import { useTable } from '@/hooks/useTable';

const STATUS_TAG = (v: any) => (v === 1 || v === '1' ? <Tag color="green">启用</Tag> : <Tag>停用</Tag>);

/* ---------------- 用户管理 ---------------- */
function UsersTab() {
  const { loading, list, pagination, reload } = useTable<any>((p) => systemApi.users(p));
  const [roles, setRoles] = useState<any[]>([]);
  const [modal, setModal] = useState(false);
  const [editing, setEditing] = useState<any>(null);
  const [pwdModal, setPwdModal] = useState(false);
  const [pwdUser, setPwdUser] = useState<any>(null);
  const [pwd, setPwd] = useState('');
  const [form] = Form.useForm();

  useEffect(() => {
    systemApi.roles().then((r: any) => setRoles(r || []));
  }, []);

  const openCreate = () => {
    setEditing(null);
    form.resetFields();
    form.setFieldsValue({ status: 1 });
    setModal(true);
  };

  const openEdit = (row: any) => {
    setEditing(row);
    form.resetFields();
    form.setFieldsValue({
      ...row,
      /**
       * 后端返回的 `roles` 是 `UserRole[]`（{ roleId, role }），而角色下拉的 value 是**角色 id**。
       * 直接回填对象会让 Select 显示成无匹配项，且保存时被原样提交——后端只认 `roleIds`，角色变更静默丢失。
       */
      roles: (Array.isArray(row.roles) ? row.roles : [])
        .map((r: any) => (typeof r === 'string' ? r : r?.roleId || r?.role?.id))
        .filter(Boolean),
    });
    setModal(true);
  };

  const submit = async () => {
    const values: any = await form.validateFields();
    // 服务端写入字段是 roleIds（updateUser 在事务里整体替换 userRole）；roles 只是本页 SELECT 的字段名
    const { roles, ...rest } = values;
    const payload = { ...rest, roleIds: roles || [] };
    if (editing) await systemApi.updateUser(editing.id, payload);
    else await systemApi.createUser(payload);
    message.success('保存成功');
    setModal(false);
    reload();
  };

  const openReset = (row: any) => {
    setPwdUser(row);
    setPwd('');
    setPwdModal(true);
  };

  const submitReset = async () => {
    await systemApi.resetPassword(pwdUser.id, pwd);
    message.success('密码已重置');
    setPwdModal(false);
  };

  return (
    <Card
      title="用户管理"
      extra={<Button type="primary" icon={<PlusOutlined />} onClick={openCreate}>新增用户</Button>}
    >
      <Table
        rowKey="id"
        loading={loading}
        dataSource={list}
        pagination={pagination}
        scroll={{ x: 1400 }}
        columns={[
          { title: '用户名', dataIndex: 'username', width: 160 },
          { title: '姓名', dataIndex: 'realName', width: 120 },
          { title: '手机', dataIndex: 'phone', width: 140 },
          { title: '邮箱', dataIndex: 'email', width: 200, ellipsis: true },
          { title: '状态', dataIndex: 'status', width: 90, render: STATUS_TAG },
          {
            title: '角色',
            width: 220,
            ellipsis: true,
            // 后端没有 roleNames 字段（返回的是 roles[{ roleId, role }]），原来该列永远是空白
            render: (_: any, row: any) =>
              (Array.isArray(row.roles) ? row.roles : [])
                .map((r: any) => r?.role?.name || r?.name || '')
                .filter(Boolean)
                .join('、') || '-',
          },
          {
            title: '操作',
            width: 220,
            fixed: 'right',
            render: (_: any, row: any) => (
              <Space size={4}>
                <Button type="link" size="small" onClick={() => openEdit(row)}>编辑</Button>
                <Button type="link" size="small" icon={<ReloadOutlined />} onClick={() => openReset(row)}>重置密码</Button>
                <Popconfirm title="确认删除该用户？" onConfirm={async () => { await systemApi.removeUser(row.id); message.success('已删除'); reload(); }}>
                  <Button type="link" size="small" danger>删除</Button>
                </Popconfirm>
              </Space>
            ),
          },
        ]}
      />

      <Modal title={editing ? '编辑用户' : '新增用户'} open={modal} onOk={submit} onCancel={() => setModal(false)} width={640} destroyOnHidden>
        <Form form={form} layout="vertical">
          <Form.Item name="username" label="用户名" rules={[{ required: true }]}>
            <Input disabled={!!editing} />
          </Form.Item>
          {!editing && (
            <Form.Item name="password" label="密码" rules={[{ required: true }]}>
              <Input.Password />
            </Form.Item>
          )}
          <Form.Item name="realName" label="姓名" rules={[{ required: true }]}>
            <Input />
          </Form.Item>
          <Form.Item name="phone" label="手机"><Input /></Form.Item>
          <Form.Item name="email" label="邮箱"><Input /></Form.Item>
          <Form.Item name="status" label="状态" rules={[{ required: true }]}>
            <Select options={[{ value: 1, label: '启用' }, { value: 0, label: '停用' }]} />
          </Form.Item>
          <Form.Item name="roles" label="角色">
            <Select
              mode="multiple"
              allowClear
              placeholder="请选择角色"
              options={roles.map((r) => ({ value: r.id, label: r.name }))}
            />
          </Form.Item>
        </Form>
      </Modal>

      <Modal title={`重置密码 - ${pwdUser?.realName || pwdUser?.username}`} open={pwdModal} onOk={submitReset} onCancel={() => setPwdModal(false)} okText="确认重置">
        <Input.Password placeholder="请输入新密码" value={pwd} onChange={(e) => setPwd(e.target.value)} />
      </Modal>
    </Card>
  );
}

/* ---------------- 角色管理 ---------------- */
function RolesTab() {
  const [roles, setRoles] = useState<any[]>([]);
  const [permissions, setPermissions] = useState<any[]>([]);
  const [modal, setModal] = useState(false);
  const [editing, setEditing] = useState<any>(null);
  const [form] = Form.useForm();
  const [checkedKeys, setCheckedKeys] = useState<any[]>([]);

  const load = () => systemApi.roles().then((r: any) => setRoles(r || []));
  useEffect(() => {
    load();
    systemApi.permissions().then((r: any) => setPermissions(r || []));
  }, []);

  const treeData = permissions.map((p) => ({
    title: p.module,
    key: p.module,
    selectable: false,
    children: (p.items || []).map((i: any) => ({ title: i.name, key: i.id })),
  }));

  const openCreate = () => {
    setEditing(null);
    form.resetFields();
    setCheckedKeys([]);
    setModal(true);
  };

  const openEdit = (row: any) => {
    setEditing(row);
    form.resetFields();
    form.setFieldsValue({ code: row.code, name: row.name, remark: row.remark });
    /**
     * 后端返回的是 `permissions: [{ permissionId, permission }]`，**没有** `permissionIds`。
     * 原来读 `row.permissionIds || []` 会让树全部不勾选；保存时提交空数组 → 该角色权限被整体清空。
     */
    setCheckedKeys(
      (Array.isArray(row.permissions) ? row.permissions : [])
        .map((p: any) => p?.permissionId || p?.permission?.id)
        .filter(Boolean),
    );
    setModal(true);
  };

  const submit = async () => {
    const values: any = await form.validateFields();
    /**
     * 树的分组节点 key 是**模块编码**（如 `contract`），只有叶子才是权限 id。
     * 勾选叶子时 antd 会把父节点一并计入 checkedKeys —— 直接提交会拿模块编码当 permissionId
     * 写关联表（外键失败 → 保存必报错）。这里只保留权限 id。
     */
    const validIds = new Set<string>(
      permissions.flatMap((p: any) => (p.items || []).map((i: any) => String(i.id))),
    );
    const permissionIds = (checkedKeys as any[]).map((k) => String(k)).filter((k) => validIds.has(k));
    const payload = { ...values, permissionIds };
    if (editing) await systemApi.updateRole(editing.id, payload);
    else await systemApi.createRole(payload);
    message.success('保存成功');
    setModal(false);
    load();
  };

  return (
    <Card title="角色管理" extra={<Button type="primary" icon={<PlusOutlined />} onClick={openCreate}>新增角色</Button>}>
      <Table
      scroll={{ x: 'max-content' }}
        rowKey="id"
        dataSource={roles}
        pagination={false}
        columns={[
          { title: '角色编码', dataIndex: 'code', width: 180 },
          { title: '名称', dataIndex: 'name', width: 180 },
          { title: '备注', dataIndex: 'remark', ellipsis: true },
          {
            title: '权限数',
            width: 100,
            // 后端没有 permissionCount 字段，按关联行计算（原来的 fallback 读的是 editing，行与行之间会串）
            render: (_: any, row: any) => (Array.isArray(row.permissions) ? row.permissions.length : 0),
          },
          {
            title: '操作',
            width: 160,
            fixed: 'right',
            render: (_: any, row: any) => (
              <Space size={4}>
                <Button type="link" size="small" onClick={() => openEdit(row)}>编辑</Button>
                <Popconfirm title="确认删除该角色？" onConfirm={async () => { await systemApi.removeRole(row.id); message.success('已删除'); load(); }}>
                  <Button type="link" size="small" danger>删除</Button>
                </Popconfirm>
              </Space>
            ),
          },
        ]}
      />
      <Modal title={editing ? '编辑角色' : '新增角色'} open={modal} onOk={submit} onCancel={() => setModal(false)} width={560} destroyOnHidden>
        <Form form={form} layout="vertical">
          <Form.Item name="code" label="角色编码" rules={[{ required: true }]}><Input disabled={!!editing} /></Form.Item>
          <Form.Item name="name" label="名称" rules={[{ required: true }]}><Input /></Form.Item>
          <Form.Item name="remark" label="备注"><Input.TextArea rows={2} /></Form.Item>
          <Form.Item label="权限">
            <Tree
              checkable
              treeData={treeData}
              checkedKeys={checkedKeys}
              onCheck={(keys) => setCheckedKeys(keys as any[])}
            />
          </Form.Item>
        </Form>
      </Modal>
    </Card>
  );
}

