/** JSON 映射表编辑器（名称 ↔ 编码段，支持增删改） */
function MappingEditor({ value, onChange }: { value: string; onChange: (v: string) => void }) {
  let entries: [string, string][] = [];
  try {
    entries = Object.entries(JSON.parse(value || '{}'));
  } catch {
    /* JSON 损坏时视为空，保存后修复 */
  }
  const update = (list: [string, string][]) => {
    const out: Record<string, string> = {};
    list.forEach(([k, v]) => {
      if (k.trim()) out[k.trim()] = v.trim();
    });
    onChange(JSON.stringify(out));
  };
  return (
    <div>
      {entries.map(([k, v], i) => (
        <Space.Compact key={i} style={{ marginBottom: 4, display: 'flex' }}>
          <Input
            style={{ width: 150 }}
            value={k}
            placeholder="字典项名称"
            onChange={(e) => {
              const list = [...entries];
              list[i] = [e.target.value, v];
              update(list);
            }}
          />
          <Input
            style={{ width: 100 }}
            value={v}
            placeholder="编码段"
            onChange={(e) => {
              const list = [...entries];
              list[i] = [k, e.target.value];
              update(list);
            }}
          />
          <Button size="small" type="text" danger icon={<DeleteOutlined />} onClick={() => update(entries.filter((_, j) => j !== i))} />
        </Space.Compact>
      ))}
      <Button size="small" icon={<PlusOutlined />} onClick={() => update([...entries, ['', '']] as [string, string][])}>
        添加映射
      </Button>
    </div>
  );
}

function ParamsTab() {
  const [params, setParams] = useState<any[]>([]);
  const [groupKeyword, setGroupKeyword] = useState('');
  const [currentGroup, setCurrentGroup] = useState<string | null>(null);

  const load = () => systemApi.params().then((r: any) => setParams(r || []));
  useEffect(() => { load(); }, []);

  /** 分组名映射：参数键首段 → 中文名 */
  const GROUP_LABELS: Record<string, string> = {
    contract: '合同参数',
    supplier: '供应商参数',
    repayment: '还款协议',
    multi: '项目模式',
  };

  /** 按参数键首段分组 */
  const groups = useMemo(() => {
    const map: Record<string, number> = {};
    params.forEach((p) => {
      const g = String(p.key).split('.')[0];
      map[g] = (map[g] || 0) + 1;
    });
    return Object.entries(map)
      .map(([code, count]) => ({ code, label: GROUP_LABELS[code] || code, count }))
      .filter((g) => !groupKeyword || g.label.includes(groupKeyword) || g.code.includes(groupKeyword))
      .sort((a, b) => a.code.localeCompare(b.code));
  }, [params, groupKeyword]);

  useEffect(() => {
    if (!currentGroup && groups.length) setCurrentGroup(groups[0].code);
  }, [groups, currentGroup]);

  const groupParams = params.filter((p) => String(p.key).split('.')[0] === currentGroup);

  const onChangeValue = (key: string, v: string) =>
    setParams((ps) => ps.map((p) => (p.key === key ? { ...p, value: v } : p)));

  const save = async () => {
    await systemApi.saveParams(params.map((p) => ({ key: p.key, value: p.value })));
    message.success('参数已保存');
    load();
  };

  const currentLabel = GROUP_LABELS[currentGroup || ''] || currentGroup || '';

  return (
    <Row gutter={16}>
      <Col xs={24} lg={7}>
        <Card title="参数分组">
          <Input.Search
            placeholder="搜索分组"
            allowClear
            onSearch={() => undefined}
            onChange={(e) => setGroupKeyword(e.target.value)}
            style={{ marginBottom: 12 }}
          />
          <div style={{ maxHeight: 'calc(100vh - 260px)', overflow: 'auto' }}>
            {groups.map((g) => (
              <div
                key={g.code}
                onClick={() => setCurrentGroup(g.code)}
                style={{
                  padding: '8px 12px',
                  cursor: 'pointer',
                  borderRadius: 6,
                  marginBottom: 4,
                  background: currentGroup === g.code ? 'var(--cms-surface-card)' : 'transparent',
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center',
                }}
              >
                <span>
                  {g.label} <span style={{ color: 'var(--cms-muted-soft)', fontSize: 12 }}>{g.code}</span>
                </span>
                <Tag>{g.count}</Tag>
              </div>
            ))}
            {!groups.length && <div style={{ color: 'var(--cms-muted-soft)', padding: '8px 12px' }}>暂无匹配分组</div>}
          </div>
        </Card>
      </Col>

      <Col xs={24} lg={17}>
        <Card
          title={`参数明细${currentLabel ? ` · ${currentLabel}` : ''}`}
          extra={
            <Space>
              <Button icon={<ReloadOutlined />} onClick={load}>刷新</Button>
              <Button type="primary" onClick={save}>保存</Button>
            </Space>
          }
        >
          <Table
          scroll={{ x: 'max-content' }}
            rowKey="key"
            dataSource={groupParams}
            pagination={false}
            columns={[
              { title: '参数键', dataIndex: 'key', width: 240 },
              {
                title: '参数值',
                dataIndex: 'value',
                width: 340,
                render: (v: any, row: any) =>
                  row.key.endsWith('_mapping') ? (
                    <MappingEditor value={v} onChange={(nv) => onChangeValue(row.key, nv)} />
                  ) : (
                    <Input value={v} onChange={(e) => onChangeValue(row.key, e.target.value)} />
                  ),
              },
              {
                title: '说明',
                dataIndex: 'remark',
                ellipsis: true,
                className: 'col-secondary',
                render: (v: any, row: any) => v || PARAM_REMARK[row.key] || '-',
              },
            ]}
          />
        </Card>
      </Col>
    </Row>
  );
}

