/** 尝试把 JSON 字符串格式化展示，失败原样输出 */
function tryPretty(v: any): string {
  if (!v) return '-';
  try {
    return JSON.stringify(JSON.parse(v), null, 2);
  } catch {
    return String(v);
  }
}

