import { useEffect, useState } from 'react';
import {
  Card, Table, Button, Form, Input, Space, Modal, Popconfirm, message, Tag, Select,
  Checkbox,
} from 'antd';
import type { ColumnsType } from 'antd/es/table';
import {
  PlusOutlined, SearchOutlined, HistoryOutlined, ReloadOutlined, EditOutlined, DeleteOutlined,
} from '@ant-design/icons';
import { templateApi } from '@/api/business';
import { useTable } from '@/hooks/useTable';
import DictSelect, { DictTag } from '@/components/DictSelect';
import RichTextEditor from '@/components/RichTextEditor';
import EmptyState from '@/components/EmptyState';
import VersionHistoryModal from '@/components/templates/VersionHistoryModal';
import Can from '@/components/Can';
import { checkPlaceholders } from '@/utils/placeholderCheck';
import { VARIABLE_GROUPS } from './Clauses';

interface ContractTemplateRow {
  id: string;
  name: string;
  categoryCode?: string;
  tags?: string;
  status: number;
  version: number;
  content?: string;
  pageSetup?: string;
  createdAt?: string;
}

export default function Templates() {
  const { loading, list, params, search, reload, pagination } = useTable<ContractTemplateRow>(
    // includeHistory 由 useTable 的 params 合并进 p（不要直接引用 `params`，那会变成自引用 → 隐式 any）
    (p: any) => templateApi.list({ ...p, includeHistory: p.includeHistory }),
  );
  const [form] = Form.useForm();
  const [filterForm] = Form.useForm();
  const [modal, setModal] = useState(false);
  const [editing, setEditing] = useState<ContractTemplateRow | null>(null);
  const [saving, setSaving] = useState(false);

  const [includeHistory, setIncludeHistory] = useState(false);

  // 页面设置（页边距/页眉/页脚页码），以 JSON 存入模板 pageSetup 字段
  const [ps, setPs] = useState<any>({ margin: 'normal', header: '', footerFormat: 'xofy', footerAlign: 'center' });
  const syncPs = (next: any) => {
    const merged = { ...ps, ...next };
    setPs(merged);
    form.setFieldValue('pageSetup', JSON.stringify(merged));
  };

  // 版本历史（共享弹窗：合同/采购视觉与列一致，不显示修改人）
  const [versionOpen, setVersionOpen] = useState(false);
  const [versionRow, setVersionRow] = useState<ContractTemplateRow | null>(null);
  const [versions, setVersions] = useState<any[]>([]);
  const [versionLoading, setVersionLoading] = useState(false);

  useEffect(() => {
    if (!versionOpen || !versionRow) return;
    setVersionLoading(true);
    templateApi
      .versions(versionRow.id)
      .then((res: any) => setVersions(res?.list || res || []))
      .finally(() => setVersionLoading(false));
  }, [versionOpen, versionRow]);

  const openEdit = (row?: ContractTemplateRow) => {
    setEditing(row || null);
    form.resetFields();
    form.setFieldsValue(row ? { ...row } : { status: 1 });
    try {
      setPs(row?.pageSetup ? JSON.parse(row.pageSetup) : { margin: 'normal', header: '', footerFormat: 'xofy', footerAlign: 'center' });
    } catch {
      setPs({ margin: 'normal', header: '', footerFormat: 'xofy', footerAlign: 'center' });
    }
    setModal(true);
  };

  const submit = async () => {
    const values = await form.validateFields();
    const problems = checkPlaceholders(values.content);
    const doSave = async () => {
      setSaving(true);
      try {
        if (editing) await templateApi.update(editing.id, { ...values, version: editing.version });
        else await templateApi.create(values);
        message.success('保存成功');
        setModal(false);
        setEditing(null);
        reload();
      } finally {
        setSaving(false);
      }
    };
    if (problems.length) {
      Modal.confirm({
        title: '占位符写法警告',
        width: 520,
        content: (
          <div>
            <p>以下写法会导致变量或清单表格无法替换（生成合同后残留占位符）：</p>
            <ul style={{ paddingLeft: 20 }}>
              {problems.map((p) => (
                <li key={p} style={{ marginBottom: 4 }}>{p}</li>
              ))}
            </ul>
            <p>仍要保存吗？</p>
          </div>
        ),
        onOk: doSave,
      });
      return;
    }
    await doSave();
  };

  const openVersions = (row: ContractTemplateRow) => {
    setVersionRow(row);
    setVersionOpen(true);
  };

  const rollback = async (targetId: string) => {
    if (!versionRow) return;
    await templateApi.rollback(versionRow.id, targetId);
    message.success('已回滚到该版本');
    setVersionOpen(false);
    setVersionRow(null);
    reload();
  };

  const toggleHistory = (checked: boolean) => {
    setIncludeHistory(checked);
    search({ includeHistory: checked });
  };

  const columns: ColumnsType<ContractTemplateRow> = [
    { title: '模板名称', dataIndex: 'name', ellipsis: true },
    {
      title: '模板分类',
      dataIndex: 'categoryCode',
      width: 140,
      render: (v) => <DictTag typeCode="contract_template_category" value={v} />,
    },
    {
      title: '标签',
      dataIndex: 'tags',
      width: 160,
      render: (v) => (v ? v.split(',').filter(Boolean).map((t: string) => <Tag key={t}>{t}</Tag>) : '-'),
    },
    { title: '版本号', dataIndex: 'version', width: 90, render: (v) => <Tag color="blue">v{v ?? 1}</Tag> },
    {
      title: '状态',
      dataIndex: 'status',
      width: 90,
      // 状态列是 Int（1/0）；yes_no 字典是 Y/N，用 DictTag 会显示成 "1"
      render: (v: number) => (v === 0 ? <Tag>停用</Tag> : <Tag color="green">启用</Tag>),
    },
    { title: '创建时间', dataIndex: 'createdAt', width: 180, render: (v) => v?.slice(0, 19).replace('T', ' ') },
    {
      title: '操作',
      width: 230,
      fixed: 'right',
      render: (_, row) => (
        <Space size={4}>
          <Button type="link" size="small" icon={<HistoryOutlined />} onClick={() => openVersions(row)}>版本</Button>
          <Can code="template:edit">
            <>
              <Button type="link" size="small" icon={<EditOutlined />} onClick={() => openEdit(row)}>编辑</Button>
              <Popconfirm title="删除后该模板所有版本将被移除" onConfirm={async () => { await templateApi.remove(row.id); message.success('已删除'); reload(); }}>
                <Button type="link" size="small" danger icon={<DeleteOutlined />}>删除</Button>
              </Popconfirm>
            </>
          </Can>
        </Space>
      ),
    },
  ];

  return (
    <Card
      title="合同模板"
      extra={
        <Space>
          <Button icon={<ReloadOutlined />} onClick={reload}>刷新</Button>
          <Can code="template:edit">
            <Button type="primary" icon={<PlusOutlined />} onClick={() => openEdit()}>新增模板</Button>
          </Can>
        </Space>
      }
    >
      <Form
        form={filterForm}
        layout="inline"
        style={{ marginBottom: 16, rowGap: 8 }}
        onFinish={(v) => search({ keyword: v.keyword || undefined, categoryCode: v.categoryCode || undefined })}
      >
        <Form.Item name="keyword">
          <Input placeholder="模板名称 / 标签关键词" allowClear prefix={<SearchOutlined />} />
        </Form.Item>
        <Form.Item name="categoryCode">
          <DictSelect typeCode="contract_template_category" placeholder="模板分类" />
        </Form.Item>
        <Form.Item>
          <Checkbox checked={includeHistory} onChange={(e) => toggleHistory(e.target.checked)}>
            显示历史版本
          </Checkbox>
        </Form.Item>
        <Form.Item>
          <Space>
            <Button type="primary" htmlType="submit">查询</Button>
            <Button
              onClick={() => {
                filterForm.resetFields();
                if (includeHistory) toggleHistory(false);
                search({ keyword: undefined, categoryCode: undefined });
              }}
            >
              重置
            </Button>
          </Space>
        </Form.Item>
      </Form>

      <Table<ContractTemplateRow>
        rowKey="id"
        loading={loading}
        dataSource={list}
        pagination={pagination}
        scroll={{ x: 'max-content' }}
        columns={columns}
        locale={{ emptyText: <EmptyState compact description="暂无合同模板，点击右上角「新增模板」创建" /> }}
      />

      {/* 新增/编辑模板 */}
      <Modal
        title={editing ? '编辑合同模板' : '新增合同模板'}
        open={modal}
        onOk={submit}
        onCancel={() => setModal(false)}
        okText="保存"
        confirmLoading={saving}
        width={960}
        destroyOnHidden
      >
        <Form form={form} layout="vertical">
          <Space size={16} style={{ display: 'flex', flexWrap: 'wrap' }}>
            <Form.Item name="name" label="模板名称" rules={[{ required: true }]} style={{ minWidth: 280 }}>
              <Input placeholder="如 采购合同模板" maxLength={100} />
            </Form.Item>
            <Form.Item name="categoryCode" label="模板分类" rules={[{ required: true }]} style={{ minWidth: 240 }}>
              <DictSelect typeCode="contract_template_category" />
            </Form.Item>
            <Form.Item name="tags" label="标签" style={{ minWidth: 180 }}>
              <Input placeholder="多个标签用逗号分隔" maxLength={100} />
            </Form.Item>
            <Form.Item name="status" label="状态" initialValue={1} style={{ minWidth: 110 }}>
              <Select
                options={[
                  { value: 1, label: '启用' },
                  { value: 0, label: '停用' },
                ]}
              />
            </Form.Item>
          </Space>
          <Form.Item name="content" label="模板内容" rules={[{ required: true, message: '请填写模板内容' }]}>
            <RichTextEditor
              variableGroups={VARIABLE_GROUPS}
              variableScope="contract"
              minHeight={380}
              placeholder="在此编辑合同正文，可点击「插入变量」把占位符插入到光标处（占位符语法：{{变量名}}，单花括号不生效）"
            />
          </Form.Item>
          <Form.Item label="页面设置（生成 Word 时生效）" style={{ marginBottom: 4 }}>
            <Card size="small" title="页边距 / 页眉 / 页码" extra={
              <Select
                style={{ width: 140 }}
                value={ps.margin}
                onChange={(v) => syncPs({ margin: v })}
                options={[
                  { label: '普通（上下2.54/左右2cm）', value: 'normal' },
                  { label: '窄（1.27cm）', value: 'narrow' },
                  { label: '适中（上下2.54/左右1.9cm）', value: 'moderate' },
                  { label: '宽（3.18cm）', value: 'wide' },
                ]}
              />
            }>
              <Space direction="vertical" style={{ width: '100%' }}>
                <Input
                  addonBefore="页眉"
                  placeholder="如：合同编号：{{合同编号}}    项目名称：{{项目名称}}"
                  value={ps.header}
                  onChange={(e) => syncPs({ header: e.target.value })}
                />
                <Space wrap>
                  <Select
                    style={{ width: 200 }}
                    value={ps.footerFormat}
                    onChange={(v) => syncPs({ footerFormat: v })}
                    options={[
                      { label: '页脚：第 X 页 / 共 Y 页', value: 'xofy' },
                      { label: '页脚：X / Y', value: 'xy' },
                      { label: '页脚：- X -', value: 'dash' },
                    ]}
                  />
                  <Select
                    style={{ width: 140 }}
                    value={ps.footerAlign}
                    onChange={(v) => syncPs({ footerAlign: v })}
                    options={[
                      { label: '页码居中', value: 'center' },
                      { label: '页码居右', value: 'right' },
                      { label: '页码居左', value: 'left' },
                    ]}
                  />
                </Space>
              </Space>
            </Card>
          </Form.Item>
          <Form.Item name="pageSetup" hidden><Input /></Form.Item>
          {editing && (
            <div style={{ color: 'var(--cms-muted-soft)' }}>
              提示：每次保存会生成新版本，旧版本可在「版本」里回滚；删除会把该模板所有版本一并移除。
            </div>
          )}
        </Form>
      </Modal>

      <VersionHistoryModal
        open={versionOpen}
        versions={versions}
        loading={versionLoading}
        emptyText="该模板还没有历史版本（每次编辑会自动保存一份）"
        onClose={() => { setVersionOpen(false); setVersionRow(null); }}
        onRollback={rollback}
      />
    </Card>
  );
}

import { useCallback, useEffect, useState, type KeyboardEvent, type MouseEvent } from 'react';
import { useNavigate } from 'react-router-dom';
import { Badge, Button, Card, List, Modal, Space, Tabs, Tag, Tooltip } from 'antd';
import { DeleteOutlined, RightOutlined } from '@ant-design/icons';
import dayjs from 'dayjs';
import { dashboardApi } from '@/api/modules';
import { useAuthStore } from '@/store/auth';
import { useTabActivate } from '@/hooks/useTabs';
import { DASHBOARD_TODO_TABS } from '@/constants/dashboardTodoTabs';
import EmptyState from '@/components/EmptyState';

/* ==================== 我的待办（业务口径 2026-10-16） ==================== */

/**
 * 「消除提醒 / 当天首次浮窗」的本地状态：`localStorage` 按 **用户 + 日期** 记录已处理的待办 key。
 *
 * 取舍（有意为之）：**不落库** —— 换来零后端改动；代价是跨设备/跨浏览器不同步。
 * key 里带日期，隔天自动失效（新的一天待办重新出现，正好符合"今天的待办"语义）。
 *
 * ⚠️ **两份存储，刻意分开**：
 * - `scm_dashboard_seen_<u>`：浮窗的"已看过"——浮窗弹出即写入（否则每次进工作台都弹）；
 * - `scm_dashboard_dismissed_<u>`：列表里的「消除提醒」——只隐藏用户**显式**赶走的那几条。
 * 共用一份是错的：浮窗一弹就把全部待办标为"已消除"，列表里会一条都不剩（实测踩到）。
 */
const seenStoreKey = (userId: string) => `scm_dashboard_seen_${userId}`;
const dismissedStoreKey = (userId: string) => `scm_dashboard_dismissed_${userId}`;

interface NoticeState {
  date: string;
  seenKeys: string[];
}

function readKeys(storeKey: (u: string) => string, userId: string): NoticeState | null {
  try {
    const raw = localStorage.getItem(storeKey(userId));
    return raw ? (JSON.parse(raw) as NoticeState) : null;
  } catch {
    return null;
  }
}

function writeKeys(storeKey: (u: string) => string, userId: string, state: NoticeState): void {
  try {
    localStorage.setItem(storeKey(userId), JSON.stringify(state));
  } catch {
    /* 存储不可用时静默降级（刷新后提醒会再出现，不算错） */
  }
}

const noticeToday = () => dayjs().format('YYYY-MM-DD');

/** 级别 → Tag 色 */
const LEVEL_TONE: Record<string, string> = { RED: 'error', AMBER: 'warning', INFO: 'default' };

/**
 * 我的待办卡片：
 * - 分类 Tab **常驻**（0 条的分类也在，= "为每个模块都预留一个待办卡片的位置"）；
 * - **点击分类 Tab 直接跳转**对应模块（用户 2026-10-17：不要「前往处理」按钮——
 *   Tab 本身就是入口；有 count > 0 时点击先跳转，Tab 切换交给默认行为即可，
 *   跳转后回来标签仍在）；行内保留「消除提醒」。
 */

/** 分类 key → 模块落地路径（Tab 点击跳转；与后端 target.path 的"模块列表"一致） */
const TODO_TAB_TARGET: Record<string, string> = {
  CONTRACT_DRAFT: '/contract/draft',
  CONTRACT_SIGN: '/contract/query',
  SETTLEMENT_DRAFT: '/settlement/order',
  FINAL_SETTLEMENT: '/settlement/final-settlement',
  PAYMENT_PROCEDURE: '/settlement/payment-procedure',
  INVOICE_VERIFY: '/invoice',
  OVERDUE_INTEREST: '/settlement/overdue',
  PROCUREMENT_TODO: '/procurement/initiate',
  OVERDUE_MILESTONE: '/contract/query',
};

export function TodoCard() {
  const navigate = useNavigate();
  const userId = useAuthStore((s) => s.user?.id || '');
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<string>(DASHBOARD_TODO_TABS[0]?.key ?? '');
  /** 已消除的待办 key（当天有效） */
  const [dismissed, setDismissed] = useState<string[]>([]);

  const load = useCallback(() => {
    dashboardApi
      .todos()
      .then((res: any) => setData(res))
      .finally(() => setLoading(false));
  }, []);

  useEffect(() => {
    load();
    const timer = window.setInterval(load, 5 * 60 * 1000);
    return () => window.clearInterval(timer);
  }, [load]);

  useEffect(() => {
    if (userId) setDismissed(readKeys(dismissedStoreKey, userId)?.seenKeys ?? []);
  }, [userId]);

  /** 标签被缓存后不会重新挂载 —— 数据复检必须挂在"重新激活"上（见 useTabActivate 注释） */
  useTabActivate('/dashboard', () => {
    load();
    if (userId) setDismissed(readKeys(dismissedStoreKey, userId)?.seenKeys ?? []);
  });

  const groups: any[] = (data?.groups ?? []).map((g: any) => ({
    ...g,
    visibleItems: (g.items ?? []).filter((i: any) => !dismissed.includes(i.key)),
  }));

  const dismiss = (key: string) => {
    if (!userId) return;
    const next = Array.from(new Set([...dismissed, key]));
    setDismissed(next);
    writeKeys(dismissedStoreKey, userId, { date: noticeToday(), seenKeys: next });
  };

  const tabItems = groups.map((g) => ({
    key: g.key,
    label: (
      <Badge count={g.visibleItems.length} size="small" offset={[8, 0]}>
        {DASHBOARD_TODO_TABS.find((t) => t.key === g.key)?.label ?? g.label}
      </Badge>
    ),
    children: (
      <List
        loading={loading}
        dataSource={g.visibleItems}
        locale={{
          emptyText: <EmptyState compact description="暂无待办——点击上方分类标签前往对应模块处理" />,
        }}
        renderItem={(item: any) => (
          <List.Item
            actions={[
              <Tooltip key="dismiss" title="今天不再提醒（隔天恢复）">
                <Button
                  type="link"
                  size="small"
                  icon={<DeleteOutlined />}
                  onClick={() => dismiss(item.key)}
                />
              </Tooltip>,
            ]}
          >
            <List.Item.Meta
              title={
                <Space size={8} wrap>
                  <Tag color={LEVEL_TONE[item.level] ?? 'default'}>{item.level}</Tag>
                  {item.code && <span style={{ color: 'var(--cms-muted)' }}>{item.code}</span>}
                  <span>{item.title}</span>
                </Space>
              }
              description={item.hint}
            />
          </List.Item>
        )}
      />
    ),
  }));

  /** 点分类 Tab：先切 Tab（看明细），再跳对应模块——两个动作都要，跳转后回来 Tab 还停在原位 */
  // 直接对齐 antd 的 TabsProps['onTabClick']：键盘触发时事件是 KeyboardEvent，
  // 自己写 MouseEvent 会在 strict 下类型不兼容（原实现只用到 preventDefault，两者都有）
  const handleTabClick = (key: string, e: MouseEvent<Element> | KeyboardEvent<Element>) => {
    setActiveTab(key);
    const target = TODO_TAB_TARGET[key];
    if (target) {
      e.preventDefault();
      navigate(target);
    }
  };

  return (
    <Card
      title="我的待办"
      extra={
        <span className="cms-hint">
          共 {data?.total ?? 0} 条{activeTab === 'OVERDUE_MILESTONE' ? ' · 点击具体条目可打开对应合同' : ''}
        </span>
      }
    >
      <Tabs
        activeKey={activeTab}
        onTabClick={handleTabClick}
        items={tabItems}
      />
      {groups.map((g) => {
        const shown = g.items?.length ?? 0;
        return g.count > shown ? (
          <div key={g.key} className="cms-hint">
            {DASHBOARD_TODO_TABS.find((t) => t.key === g.key)?.label}：仅显示前 {shown} 条，共 {g.count} 条
          </div>
        ) : null;
      })}
    </Card>
  );
}

/**
 * 当天首次进入工作台的待办汇总浮窗（需求 4）。
 *
 * 判定（按 用户 + 日期 存 localStorage）：
 * ① 记录的 date ≠ 今天 → 弹，并把 date 置为今天、seenKeys 置为当前全部 key；
 * ② date 是今天，但存在新 key ∉ seenKeys（= 关闭后又来了新待办）→ 弹，并把新 key 并入；
 * ③ 否则不弹。
 * 关闭即写回 —— "除非再次发生新待办且我再次进入工作台，当天不再显示"。
 */
export function DashboardNoticeModal({ data, loading }: { data: any; loading: boolean }) {
  const userId = useAuthStore((s) => s.user?.id || '');
  const [open, setOpen] = useState(false);
  const navigate = useNavigate();

  const groups: any[] = data?.groups ?? [];
  const total: number = data?.total ?? 0;

  const check = useCallback(() => {
    if (loading || !userId || !groups.length) return;
    // ⚠️ 只看**分类级**信号（是否有 count>0 的分类没提示过），不看单条 key——
    // 否则用户「消除提醒」/处理掉一条后，"新 key"判定会让浮窗再次弹出（实测踩到）。
    const allKeys = groups.filter((g) => (g.items ?? []).length > 0).map((g) => `group:${g.key}`);
    const prev = readKeys(seenStoreKey, userId);
    const isNewDay = !prev || prev.date !== noticeToday();
    const hasNew = allKeys.some((k) => !prev?.seenKeys.includes(k));
    if (isNewDay || hasNew) {
      // 弹出即视为"已看过"：当天不再弹，除非又出现新的**有待办的分类**
      const base = prev?.date === noticeToday() ? prev!.seenKeys : [];
      writeKeys(seenStoreKey, userId, { date: noticeToday(), seenKeys: Array.from(new Set([...base, ...allKeys])) });
      setOpen(true);
    }
  }, [groups, loading, userId]);

  // 挂载后首检 + 标签重新激活时复检（缓存页不会重新挂载）。
  // ⚠️ 浮窗只在**首次挂载**时判定一次：切回来不算"再次进入"（当天首弹后写 seen，
  // 复检会因"无新分类"而不再弹；但 StrictMode 下 effect 双跑 + 激活信号会反复 setOpen(true)）。
  useEffect(() => {
    const id = window.setTimeout(check, 0);
    return () => window.clearTimeout(id);
  }, [check]);

  const goTarget = (item: any) => {
    setOpen(false);
    const t = item.target ?? {};
    navigate(t.editor ? `${t.path}?editor=${t.editor}` : t.path);
  };

  return (
    <Modal
      title={`今日待办（${total} 条）`}
      open={open}
      onCancel={() => setOpen(false)}
      footer={<Button onClick={() => setOpen(false)}>知道了</Button>}
      width={520}
    >
      {groups.map((g) =>
        (g.items ?? []).length ? (
          <div key={g.key} style={{ marginBottom: 12 }}>
            <div style={{ fontWeight: 600, marginBottom: 4 }}>
              {DASHBOARD_TODO_TABS.find((t) => t.key === g.key)?.label ?? g.label}
              <Tag style={{ marginLeft: 8 }}>{g.count}</Tag>
            </div>
            {(g.items ?? []).slice(0, 3).map((item: any) => (
              <div key={item.key} style={{ display: 'flex', justifyContent: 'space-between', gap: 8 }}>
                <span>
                  {item.code && <span className="cms-hint">{item.code} </span>}
                  {item.title}
                </span>
                <Button type="link" size="small" icon={<RightOutlined />} onClick={() => goTarget(item)}>
                  处理
                </Button>
              </div>
            ))}
          </div>
        ) : null,
      )}
    </Modal>
  );
}
